        end)
    end

    Window:SetBackgroundImage(WindowInfo.BackgroundImage or "")
    if WindowInfo.AutoShow then task.spawn(Library.Toggle) end

    Window.Holder = Outer
    Library.Window = Window
    Library.Tabs = Window.Tabs

    return Window
end

local function OnPlayerChange()
    if Library.Unloaded then
        return
    end

    local PlayerList, ExcludedPlayerList = GetPlayers(false, true), GetPlayers(true, true)
    local StringPlayerList, StringExcludedPlayerList = GetPlayers(false, false), GetPlayers(true, false)

    for _, Value in next, Options do
        if Value.SetValues and Value.Type == "Dropdown" and Value.SpecialType == "Player" then
            Value:SetValues(
                if Value.ReturnInstanceInstead then
                    (if Value.ExcludeLocalPlayer then ExcludedPlayerList else PlayerList)
                else
                    (if Value.ExcludeLocalPlayer then StringExcludedPlayerList else StringPlayerList)
            )
        end
    end
end

local function OnTeamChange()
    if Library.Unloaded then
        return
    end
    
    local TeamList = GetTeams(false)
    local StringTeamList = GetTeams(true)

    for _, Value in next, Options do
        if Value.SetValues and Value.Type == "Dropdown" and Value.SpecialType == "Team" then
            Value:SetValues(if Value.ReturnInstanceInstead then TeamList else StringTeamList)
        end
    end
end

Library:GiveSignal(Players.PlayerAdded:Connect(OnPlayerChange))
Library:GiveSignal(Players.PlayerRemoving:Connect(OnPlayerChange))

Library:GiveSignal(Teams.ChildAdded:Connect(OnTeamChange))
Library:GiveSignal(Teams.ChildRemoved:Connect(OnTeamChange))

--// Rainbow Handler \\--
local RainbowStep = 0
local Hue = 0

Library:GiveSignal(RunService.RenderStepped:Connect(function(Delta)
    if Library.Unloaded then
        return
    end

    RainbowStep = RainbowStep + Delta
    if RainbowStep >= (1 / 60) then
        RainbowStep = 0

        Hue = Hue + (1 / 400)

        if Hue > 1 then
            Hue = 0
        end

        Library.CurrentRainbowHue = Hue
        Library.CurrentRainbowColor = Color3.fromHSV(Hue, 0.8, 1)
    end
end))

----
getgenv().Linoria = Library
if getgenv().skip_getgenv_linoria ~= true then getgenv().Library = Library end
Library.Scheme = setmetatable({}, {
    __index = function(_, key) return Library[key] end,
    __newindex = function(_, key, value) Library[key] = value end,
})
return Library

end

__evilrollerplayers_hook_shared.config_manager = function()
-- Vendored from Obsidian b4523805727561499b5b8206e14590371923f343; inline type annotations removed.
local cloneref = (cloneref or clonereference or function(instance)
    return instance
end)
local clonefunction = (clonefunction or copyfunction or function(func)
    return func
end)

local HttpService = cloneref(game:GetService("HttpService"))
local isfolder, isfile, listfiles = isfolder, isfile, listfiles

if typeof(clonefunction) == "function" then
    -- Fix is_____ functions for shitsploits, those functions should never error, only return a boolean.

    local
        isfolder_copy,
        isfile_copy,
        listfiles_copy = clonefunction(isfolder), clonefunction(isfile), clonefunction(listfiles)

    local isfolder_success, isfolder_error = pcall(function()
        return isfolder_copy("test" .. tostring(math.random(1000000, 9999999)))
    end)

    if isfolder_success == false or typeof(isfolder_error) ~= "boolean" then
        isfolder = function(folder)
            local success, data = pcall(isfolder_copy, folder)
            return (if success then data else false)
        end

        isfile = function(file)
            local success, data = pcall(isfile_copy, file)
            return (if success then data else false)
        end

        listfiles = function(folder)
            local success, data = pcall(listfiles_copy, folder)
            return (if success then data else {})
        end
    end
end

local SaveManager = {
    Library = nil,

    Folder = "ObsidianLibSettings",
    SubFolder = "",

    Ignore = {},
    LoadingOrder = {},
    UseLoadingOrder = false,

    AutoloadConfig = nil
}

function SaveManager:SetLibrary(Library)
    SaveManager.Library = Library
end

--// Element Parser \\--
local SpecialValueParser = {
    UDim2 = {
        Encode = function(Value)
            return {
                X = { Scale = Value.X.Scale, Offset = Value.X.Offset },
                Y = { Scale = Value.Y.Scale, Offset = Value.Y.Offset }
            }
        end,

        Decode = function(Data)
            local DataType = typeof(Data)
            if DataType == "table" then
                return UDim2.new(Data.X.Scale, Data.X.Offset, Data.Y.Scale, Data.Y.Offset)
            elseif DataType == "UDim2" then
                return Data
            end

            return nil
        end
    }
}

local ElementParser = {}; do
    local function CreateParser(
        ElementType,
        LibaryIndex,

        Save,
        Load,
        CustomElementFetcher
    )
        ElementParser[ElementType] = {
            Save = function(Index, Element, ...)
                local Data = Save(Index, Element, ...)
                Data.type = ElementType
                Data.idx = Index

                return Data
            end,

            Load = function(Index, Data)
                if CustomElementFetcher == true then
                    return Load(nil, Data)
                end

                local Elements = SaveManager.Library and SaveManager.Library[LibaryIndex]
                local Element = Elements and Elements[Index]
                return Load(Element, Data)
            end
        }
    end

    CreateParser(
        "Toggle", "Toggles",
        function(Index, Toggle)
            return { value = Toggle.Value }
        end,
        function(Element, Data)
            if not Element then return end
            if Element.Value == Data.value then
                Element:RunChanged()
                return
            end

            Element:SetValue(Data.value)
        end
    )

    CreateParser(
        "Slider", "Options",
        function(Index, Slider)
            return { value = tostring(Slider.Value) }
        end,
        function(Element, Data)
            if not Element then return end
            if Element.Value == Data.value then
                Element:RunChanged()
                return
            end

            Element:SetValue(Data.value)
        end
    )

    CreateParser(
        "Dropdown", "Options",
        function(Index, Dropdown)
            return { value = Dropdown.Value, multi = Dropdown.Multi }
        end,
        function(Element, Data)
            if not Element then return end
            if Element.Value == Data.value then
                Element:RunChanged()
                return
            end

            Element:SetValue(Data.value)
        end
    )

    CreateParser(
        "ColorPicker", "Options",
        function(Index, ColorPicker)
            return { value = ColorPicker.Value:ToHex(), transparency = ColorPicker.Transparency }
        end,
        function(Element, Data)
            if not Element then return end

            Element:SetValueRGB(Color3.fromHex(Data.value), Data.transparency)
        end
    )

    CreateParser(
        "KeyPicker", "Options",
        function(Index, KeyPicker)
            return { mode = KeyPicker.Mode, key = KeyPicker.Value, modifiers = KeyPicker.Modifiers, toggled = KeyPicker.Toggled }
        end,
        function(Element, Data)
            if not Element then return end

            Element:SetValue({ Data.key, Data.mode, Data.modifiers })
            if Data.mode == "Toggle" and Data.toggled ~= nil then
                Element.Toggled = Data.toggled
                Element:Update()
            end
        end
    )

    CreateParser(
        "Input", "Options",
        function(Index, Input)
            return { text = Input.Value }
        end,
        function(Element, Data)
            if not Element then return end
            if typeof(Data.text) ~= "string" then return end

            if Element.Value == Data.text then
                Element:RunChanged()
                return
            end

            Element:SetValue(Data.text)
        end
    )

    CreateParser(
        "Groupbox", "Tabs",
        function(Index, Groupbox, TabIndex)
            return { collapsed = Groupbox.Collapsed, tabIdx = TabIndex }
        end,
        function(_, Data)
            local TabIndex, Index = Data.tabIdx, Data.idx
            if typeof(TabIndex) ~= "string" or typeof(Index) ~= "string" then return end

            local Tabs = SaveManager.Library and SaveManager.Library.Tabs
            local Tab = Tabs and Tabs[TabIndex]
            if not Tab then return end

            local Groupbox = Tab.Groupboxes[Index]
            if not Groupbox or Groupbox.Collapsed == Data.collapsed then return end

            if type(Groupbox.SetCollapsed) == "function" then Groupbox:SetCollapsed(Data.collapsed == true) end
        end,
        true
    )
end

--// Helpers \\--
local function Trim(Text)
    return Text:match("^%s*(.-)%s*$")
end

local function IsStringEmpty(String)
    return if typeof(String) == "string" then Trim(String) == "" else true
end

local function IsValidFolderPath(Name)
    return typeof(Name) == "string" and (
        Trim(Name) ~= "" and
        not Name:match("^%s*$") and
        not Name:find('[<>:"|%?%*%z]')
    )
end

--// Folder helper \\--
local function SplitPath(Path)
	local Result = {}
	local Current = ""

	for Part in string.gmatch(Path, "[^/]+") do
		Current = if Current == "" then Part else (Current .. "/" .. Part)
		table.insert(Result, Current)
	end

	return Result
end

local function GetFolderPath()
    if IsStringEmpty(SaveManager.Folder) then
        return false
    end

    return string.format("%s/settings", SaveManager.Folder)
end

local function GetSubFolderPath()
    if IsStringEmpty(SaveManager.Folder) or IsStringEmpty(SaveManager.SubFolder) then
        return false
    end

    return string.format("%s/settings/%s", SaveManager.Folder, SaveManager.SubFolder)
end

local function GetCurrentSettingsPath()
    local SubFolderPath = GetSubFolderPath()
    return if SubFolderPath == false then GetFolderPath() else SubFolderPath
end

--// Files helper \\--
local function GetConfigPath(ConfigName)
    local CurrentSettingsPath = GetCurrentSettingsPath()
    return if CurrentSettingsPath == false then false else string.format("%s/%s.json", CurrentSettingsPath, ConfigName)
end

local function DoesConfigExist(ConfigName)
    local ConfigPath = GetConfigPath(ConfigName)
    return if ConfigPath == false then false else isfile(ConfigPath)
end

local function GetAutoloadPath()
    local CurrentSettingsPath = GetCurrentSettingsPath()
    return if CurrentSettingsPath == false then false else string.format("%s/autoload.txt", CurrentSettingsPath)
end

--// Indexes \\--
function SaveManager:SetLoadingOrder(Enabled, Order)
    SaveManager.UseLoadingOrder = Enabled == true
    SaveManager.LoadingOrder = typeof(Order) == "table" and Order or SaveManager.LoadingOrder
end

function SaveManager:SetIgnoreIndexes(Indexes)
    assert(typeof(Indexes) == "table", "Expected table, got " .. typeof(Indexes))

    for _, Index in Indexes do
        SaveManager.Ignore[Index] = true
    end
end

function SaveManager:IgnoreThemeSettings()
    SaveManager:SetIgnoreIndexes({
        "BackgroundColor", "MainColor", "AccentColor", "OutlineColor", "FontColor", "FontFace", "BackgroundImage",
        "ThemeManager_ThemeList", "ThemeManager_CustomThemeList", "ThemeManager_CustomThemeName"
    })
end

--// Folders \\--
function SaveManager:GetPaths()
    local SubFolderPath = GetSubFolderPath()
    if SubFolderPath == false then
        local FolderPath = GetFolderPath()
        return if FolderPath == false then {} else SplitPath(FolderPath)
    end

    return SplitPath(SubFolderPath)
end

function SaveManager:BuildFolderTree(SkipWhenCreated)
    local Paths = SaveManager:GetPaths()
    if #Paths == 0 then
        return false
    end

    if SkipWhenCreated == true then
        if isfolder(Paths[1]) then
            return true
        end
    end

    for _, Path in Paths do
        if isfolder(Path) then continue end

        makefolder(Path)
    end

    return true
end

function SaveManager:CheckFolderTree()
    return SaveManager:BuildFolderTree(true)
end

function SaveManager:CheckSubFolder(CreateFolder)
    local SubFolderPath = GetSubFolderPath()
    if SubFolderPath == false then
        return false
    end

    local FolderExists = isfolder(SubFolderPath)
    if not CreateFolder then
        return FolderExists
    end

    makefolder(SubFolderPath)
    return true
end

function SaveManager:SetFolder(Folder)
    assert(IsValidFolderPath(Folder), "Invalid path provided")

    SaveManager.Folder = Folder
    SaveManager:BuildFolderTree()
end

function SaveManager:SetSubFolder(SubFolder)
    assert(IsValidFolderPath(SubFolder), "Invalid path provided")

    SaveManager.SubFolder = SubFolder
    SaveManager:BuildFolderTree()
end

--// Config Management \\--
function SaveManager:RefreshConfigList()
    local SettingsPath = GetCurrentSettingsPath()
    if SettingsPath == false then
        return {}
    end

    local SuccessList, Files = pcall(listfiles, SettingsPath)
    if not (SuccessList and typeof(Files) == "table") then
        SaveManager.Library:Notify(string.format("Failed to load config list: %s", tostring(Files)))
        return {}
    end

    local FileNames = {}
    for _, FilePath in Files do
        local RawFileName = FilePath:match("(.+)%..+$")
        if not RawFileName then continue end

        local Position = RawFileName:gsub("\\", "/"):find("/[^/]*$")
        local FileName = Position and RawFileName:sub(Position + 1) or RawFileName
        if not FileName or FileName == "autoload" then continue end

        table.insert(FileNames, FileName)
    end

    return FileNames
end

function SaveManager:Save(ConfigName)
    if IsStringEmpty(ConfigName) then
        return false, "Invalid config name provided"
    end

    if string.lower(ConfigName) == "autoload" then
        return false, "Invalid config name provided"
    end

    local ConfigPath = GetConfigPath(ConfigName)
    if ConfigPath == false then
        return false, "Invalid config name provided"
    end

    SaveManager:CheckFolderTree()

    local Library = SaveManager.Library
    local IgnoreIndexes = SaveManager.Ignore
    local CurrentData = {
        timestamp = os.date("%d.%m.%Y %H:%M:%S"),
        name = ConfigName,

        objects = {},
        keybindMenu = if Library.KeybindFrame then {
            visible = Library.KeybindFrame.Visible,
            position = SpecialValueParser.UDim2.Encode(Library.KeybindFrame.Position)
        } else nil
    }

    --// Toggles
    for Index, Toggle in Library.Toggles do
        if not Toggle.Type then continue end
        if IgnoreIndexes[Index] then continue end

        local Parser = ElementParser[Toggle.Type]
        if not Parser then continue end

        table.insert(CurrentData.objects, Parser.Save(Index, Toggle))
    end

    --// Options
    for Index, Option in Library.Options do
        if not Option.Type then continue end
        if IgnoreIndexes[Index] then continue end

        local Parser = ElementParser[Option.Type]
        if not Parser then continue end

        table.insert(CurrentData.objects, Parser.Save(Index, Option))
    end

    --// Groupboxes
    for TabIndex, Tab in Library.Tabs do
        if not Tab.Groupboxes then continue end

        for Index, Groupbox in Tab.Groupboxes do
            if IgnoreIndexes[Index] then continue end

            local Parser = ElementParser.Groupbox
            if not Parser then continue end

            table.insert(CurrentData.objects, Parser.Save(Index, Groupbox, TabIndex))
        end
    end

    local SuccessEncode, EncodedData = pcall(HttpService.JSONEncode, HttpService, CurrentData)
    if not SuccessEncode then
        return false, "Failed to encode data"
    end

    local SuccessWrite, ErrorMessage = pcall(writefile, ConfigPath, EncodedData)
    if not SuccessWrite then
        return false, "Failed to write config file: " .. tostring(ErrorMessage)
    end

    return true
end

function SaveManager:Load(ConfigName)
    if IsStringEmpty(ConfigName) then
        return false, "No config is selected"
    end

    local ConfigPath = GetConfigPath(ConfigName)
    if ConfigPath == false or not isfile(ConfigPath) then
        return false, "Config file does not exist"
    end

    local SuccessRead, Content = pcall(readfile, ConfigPath)
    if not SuccessRead then
        return false, "Failed to read config file"
    end

    local SuccessDecode, Decoded = pcall(HttpService.JSONDecode, HttpService, Content)
    if not SuccessDecode or typeof(Decoded) ~= "table" or typeof(Decoded.objects) ~= "table" then
        return false, "Failed to decode config data"
    end

    local Library = SaveManager.Library
    local LoadingOrder = SaveManager.LoadingOrder
    local IgnoreIndexes = SaveManager.Ignore

    if SaveManager.UseLoadingOrder == true and typeof(LoadingOrder) == "table" then
        table.sort(Decoded.objects, function(a, b)
            local aIndex = table.find(LoadingOrder, a.type) or math.huge
            local bIndex = table.find(LoadingOrder, b.type) or math.huge
            return aIndex < bIndex
        end)
    end

    --// Keybind Menu
    if Library.KeybindFrame and typeof(Decoded.keybindMenu) == "table" then
        local KeybindFrameData = Decoded.keybindMenu
        local IsVisible = KeybindFrameData.visible == true
        local Position = SpecialValueParser.UDim2.Decode(KeybindFrameData.position)

        Library.KeybindFrame.Visible = IsVisible
        Library.KeybindFrame.Position = Position or Library.KeybindFrame.Position

        local KeybindMenuToggle = Library.Options and Library.Options.KeybindMenuOpen
        if KeybindMenuToggle then
            KeybindMenuToggle:SetValue(IsVisible)
        end
    end

    --// Elements
    for _, Option in Decoded.objects do
        if not Option.type then continue end
        if IgnoreIndexes[Option.idx] then continue end

        local Parser = ElementParser[Option.type]
        if not Parser then continue end

        task.defer(Parser.Load, Option.idx, Option)
    end

    return true
end

function SaveManager:Delete(ConfigName)
    if IsStringEmpty(ConfigName) then
        return false, "No config is selected"
    end

    local ConfigPath = GetConfigPath(ConfigName)
    if ConfigPath == false or not isfile(ConfigPath) then
        return false, "Config file does not exist"
    end

    local SuccessDelete, ErrorMessage = pcall(delfile, ConfigPath)
    if not SuccessDelete then
        return false, "Failed to delete config file: " .. tostring(ErrorMessage)
    end

    if ConfigName == SaveManager.AutoloadConfig then
        SaveManager:DeleteAutoLoadConfig()
    end

    return true
end

--// Auto Load Config \\--
function SaveManager:GetAutoloadConfig()
    SaveManager:CheckFolderTree()

    local AutoloadPath = GetAutoloadPath()
    if AutoloadPath == false then
        return "none", false, "Invalid path provided"
    end

    if not isfile(AutoloadPath) then
        return "none", false, "Autoload config is not set"
    end

    local SuccessRead, AutoloadConfigName = pcall(readfile, AutoloadPath)
    if not (SuccessRead and typeof(AutoloadConfigName) == "string") then
        return "none", false, AutoloadConfigName
    end

    local ConfigExists = DoesConfigExist(AutoloadConfigName)
    if not ConfigExists then
        return "none", false, "Config file not found"
    end

    SaveManager.AutoloadConfig = AutoloadConfigName
    return AutoloadConfigName, true
end

function SaveManager:SaveAutoloadConfig(ConfigName)
    if IsStringEmpty(ConfigName) then
        return false, "No config is selected"
    end

    SaveManager:CheckFolderTree()

    local AutoloadPath = GetAutoloadPath()
    if AutoloadPath == false then
        return false, "Invalid path provided"
    end

    if not DoesConfigExist(ConfigName) then
        return false, "Config does not exist"
    end

    local SuccessWrite, ErrorMessage = pcall(writefile, AutoloadPath, ConfigName)
    if not SuccessWrite then
        return false, ErrorMessage
    end

    SaveManager.AutoloadConfig = ConfigName
    return true
end

function SaveManager:LoadAutoloadConfig()
    local ConfigName, Success, FetchErrorMessage = SaveManager:GetAutoloadConfig()
    if not Success or FetchErrorMessage then
        if FetchErrorMessage ~= "Autoload config is not set" then
            SaveManager.Library:Notify(string.format("Failed to load autoload config: %s", FetchErrorMessage))
        end

        return
    end

    local SuccessLoad, LoadErrorMessage = SaveManager:Load(ConfigName)
    if not SuccessLoad then
        SaveManager.Library:Notify(string.format("Failed to load autoload config: %s", LoadErrorMessage))
        return
    end

    SaveManager.Library:Notify(string.format("Successfully loaded autoload config %q", ConfigName))
end

function SaveManager:DeleteAutoLoadConfig()
    SaveManager:CheckFolderTree()

    local AutoloadPath = GetAutoloadPath()
    if AutoloadPath == false then
        return false, "Invalid path provided"
    end

    if not isfile(AutoloadPath) then
        return false, "Autoload config is not set"
    end

    local SuccessDelete, ErrorMessage = pcall(delfile, AutoloadPath)
    if not SuccessDelete then
        return false, ErrorMessage
    end

    SaveManager.AutoloadConfig = nil
    return true
end

--// GUI \\--
local function ShowDialog(
    Condition,

    Index,
    Title,
    Description,

    DestructiveText,
    DestructiveAction
)
    if Condition() == false then
        return DestructiveAction()
    end

    return SaveManager.Library.Window:AddDialog(Index, {
        Title = Title,
        Description = Description,
        AutoDismiss = false,

        FooterButtons = {
            Cancel = {
                Title = "Cancel",
                Variant = "Ghost",
                Order = 1,
                Callback = function(Dialog)
                    Dialog:Dismiss()
                end
            },

            DestructiveAction = {
                Title = DestructiveText,
                Variant = "Destructive",
                Order = 2,
                Callback = function(Dialog)
                    Dialog:Dismiss()
                    DestructiveAction()
                end
            }
        }
    })
end

function SaveManager:BuildConfigSection(Tab, IconName)
    assert(SaveManager.Library, "Library is not set, call SaveManager:SetLibrary(Library) first.")
    local ConfigurationBox = Tab:AddRightGroupbox("Configuration", IconName or "folder-cog")

    local ConfigNameInput, ConfigList, AutoloadConfigLabel
    local function RefreshList()
        ConfigList:SetValues(SaveManager:RefreshConfigList())
        ConfigList:SetValue(nil)
    end

    local function RefreshAutoloadConfigLabel()
        local AutoloadConfigName, _Success, _ErrorMessage = SaveManager:GetAutoloadConfig()

        AutoloadConfigLabel:SetText(string.format("Current autoload config: %s", AutoloadConfigName))
        if ConfigList then RefreshList() end
    end

    --// Create
    ConfigurationBox:AddInput("SaveManager_ConfigName", {
        Text = "Config name"
    })

    ConfigurationBox:AddButton("Create config", function()
        local ConfigName = ConfigNameInput.Value
        if IsStringEmpty(ConfigName) then
            SaveManager.Library:Notify("Configuration name cannot be empty.")
            return
        end

        if string.lower(ConfigName) == "autoload" then
            SaveManager.Library:Notify("Invalid config name provided.")
            return
        end

        ShowDialog(
            function()
                return DoesConfigExist(ConfigName)
            end,

            "SaveManager_CreateConfig",
            "Config already exists",
            string.format("A config named %q already exists. Overwriting will replace it with your current settings.", ConfigName),

            "Overwrite",
            function()
                local Success, ErrorMessage = SaveManager:Save(ConfigName)
                if not Success then
                    SaveManager.Library:Notify(string.format("Failed to create config %q: %s", ConfigName, ErrorMessage))
                    return
                end

                SaveManager.Library:Notify(string.format("Successfully created config %q", ConfigName))
                RefreshList()
            end
        )
    end)

    ConfigurationBox:AddDivider()

    --// Manage
    ConfigurationBox:AddDropdown("SaveManager_ConfigList", {
        Text = "Config list",

        Values = SaveManager:RefreshConfigList(),
        AllowNull = true,
        Multi = false,

        FormatDisplayValue = function(Value)
            if Value == SaveManager.AutoloadConfig then
                return string.format("%s (autoload)", Value)
            end

            return Value
        end,
        FormatListValue = function(Value)
            if Value == SaveManager.AutoloadConfig then
                return string.format("%s (autoload)", Value)
            end

            return Value
        end
    })

    ConfigurationBox:AddButton({
        Text = "Load config",
        DoubleClick = false,

        Func = function()
            local ConfigName = ConfigList.Value
            if IsStringEmpty(ConfigName) then
                SaveManager.Library:Notify("Please select a config first.")
                return
            end

            local Success, ErrorMessage = SaveManager:Load(ConfigName)
            if not Success then
                SaveManager.Library:Notify(string.format("Failed to load config %q: %s", ConfigName, ErrorMessage))
                return
            end

            SaveManager.Library:Notify(string.format("Successfully loaded config %q", ConfigName))
        end
    })

    ConfigurationBox:AddButton({
        Text = "Overwrite config",
        DoubleClick = false,

        Func = function()
            local ConfigName = ConfigList.Value
            if IsStringEmpty(ConfigName) then
                SaveManager.Library:Notify("Please select a config first.")
                return
            end

            ShowDialog(
                function()
                    return true --// Always show
                end,

                "SaveManager_OverwriteConfig",
                "Overwrite config",
                string.format("Are you sure you want to overwrite %q with your current settings? This cannot be undone.", ConfigName),

                "Overwrite",
                function()
                    local Success, ErrorMessage = SaveManager:Save(ConfigName)
                    if not Success then
                        SaveManager.Library:Notify(string.format("Failed to overwrite config %q: %s", ConfigName, ErrorMessage))
                        return
                    end

                    SaveManager.Library:Notify(string.format("Successfully overwrote config %q", ConfigName))
                end
            )
        end
    })

    ConfigurationBox:AddButton({
        Text = "Delete config",
        DoubleClick = false,

        Func = function()
            local ConfigName = ConfigList.Value
            if IsStringEmpty(ConfigName) then
                SaveManager.Library:Notify("Please select a config first.")
                return
            end

            ShowDialog(
                function()
                    return true --// Always show
                end,

                "SaveManager_DeleteConfig",
                "Delete config",
                string.format("Are you sure you want to delete %q? This cannot be undone.", ConfigName),

                "Delete",
                function()
                    local Success, ErrorMessage = SaveManager:Delete(ConfigName)
                    if not Success then
                        SaveManager.Library:Notify(string.format("Failed to delete config %q: %s", ConfigName, ErrorMessage))
                        return
                    end

                    SaveManager.Library:Notify(string.format("Successfully deleted config %q", ConfigName))
                    RefreshAutoloadConfigLabel()
                end
            )
        end
    })

    ConfigurationBox:AddButton("Refresh list", RefreshList)

    --// Autoload Config
    ConfigurationBox:AddButton({
        Text = "Set as autoload",
        DoubleClick = false,

        Func = function()
            local ConfigName = ConfigList.Value
            if IsStringEmpty(ConfigName) then
                SaveManager.Library:Notify("Please select a config first.")
                return
            end

            local Success, ErrorMessage = SaveManager:SaveAutoloadConfig(ConfigName)
            if not Success then
                SaveManager.Library:Notify(string.format("Failed to set autoload config %q: %s", ConfigName, ErrorMessage))
                return
            end

            SaveManager.Library:Notify(string.format("Successfully set autoload config to %q", ConfigName))
            RefreshAutoloadConfigLabel()
        end
    })

    ConfigurationBox:AddButton({
        Text = "Reset autoload",
        DoubleClick = false,

        Func = function()
            ShowDialog(
                function()
                    return true --// Always show
                end,

                "SaveManager_ResetAutoload",
                "Reset autoload config",
                "Are you sure you want to clear the autoload config? No config will be loaded automatically on next launch.",

                "Reset",
                function()
                    local Success, ErrorMessage = SaveManager:DeleteAutoLoadConfig()
                    if not Success then
                        SaveManager.Library:Notify(string.format("Failed to reset autoload config: %s", ErrorMessage))
                        return
                    end

                    SaveManager.Library:Notify("Successfully reset autoload config.")
                    RefreshAutoloadConfigLabel()
                end
            )
        end
    })

    AutoloadConfigLabel = ConfigurationBox:AddLabel("Current autoload config: ...", true);

    --// Set variables
    ConfigNameInput, ConfigList =
        SaveManager.Library.Options.SaveManager_ConfigName,
        SaveManager.Library.Options.SaveManager_ConfigList;

    --// Refresh
    RefreshAutoloadConfigLabel()
    SaveManager:SetIgnoreIndexes({ "SaveManager_ConfigList", "SaveManager_ConfigName" })

    return ConfigurationBox
end

SaveManager:BuildFolderTree()
return SaveManager
end

__evilrollerplayers_hook_shared.linoria_theme_manager = function()
local cloneref = (cloneref or clonereference or function(instance: any)
    return instance
end)
local clonefunction = (clonefunction or copyfunction or function(func) 
    return func 
end)

local httprequest = request or http_request or (http and http.request)
local getassetfunc = getcustomasset

local HttpService: HttpService = cloneref(game:GetService("HttpService"))
local isfolder, isfile, listfiles = isfolder, isfile, listfiles;

local assert = function(condition, errorMessage) 
    if (not condition) then
        error(if errorMessage then errorMessage else "assert failed", 3)
    end
end

if typeof(clonefunction) == "function" then
    -- Fix is_____ functions for shitsploits, those functions should never error, only return a boolean.

    local
        isfolder_copy,
        isfile_copy,
        listfiles_copy = clonefunction(isfolder), clonefunction(isfile), clonefunction(listfiles)

    local isfolder_success, isfolder_error = pcall(function()
        return isfolder_copy("test" .. tostring(math.random(1000000, 9999999)))
    end)

    if isfolder_success == false or typeof(isfolder_error) ~= "boolean" then
        isfolder = function(folder)
            local success, data = pcall(isfolder_copy, folder)
            return (if success then data else false)
        end

        isfile = function(file)
            local success, data = pcall(isfile_copy, file)
            return (if success then data else false)
        end

        listfiles = function(folder)
            local success, data = pcall(listfiles_copy, folder)
            return (if success then data else {})
        end
    end
end

local ThemeManager = {} do
	local ThemeFields = { "FontColor", "MainColor", "AccentColor", "BackgroundColor", "OutlineColor", "RiskColor", "VideoLink" }
	ThemeManager.Folder = "LinoriaLibSettings"
	-- if not isfolder(ThemeManager.Folder) then makefolder(ThemeManager.Folder) end

	ThemeManager.Library = nil
	ThemeManager.BuiltInThemes = {
		['Default']       = { 1, { FontColor = "ffffff", MainColor = "1c1c1c", AccentColor = "0055ff", BackgroundColor = "141414", OutlineColor = "323232" } },
		['BBot']          = { 2, { FontColor = "ffffff", MainColor = "1e1e1e", AccentColor = "7e48a3", BackgroundColor = "232323", OutlineColor = "141414" } },
		['Fatality']      = { 3, { FontColor = "ffffff", MainColor = "1e1842", AccentColor = "c50754", BackgroundColor = "191335", OutlineColor = "3c355d" } },
		['Jester']        = { 4, { FontColor = "ffffff", MainColor = "242424", AccentColor = "db4467", BackgroundColor = "1c1c1c", OutlineColor = "373737" } },
		['Mint']          = { 5, { FontColor = "ffffff", MainColor = "242424", AccentColor = "3db488", BackgroundColor = "1c1c1c", OutlineColor = "373737" } },
		['Tokyo Night']   = { 6, { FontColor = "ffffff", MainColor = "191925", AccentColor = "6759b3", BackgroundColor = "16161f", OutlineColor = "323232" } },
		['Ubuntu']        = { 7, { FontColor = "ffffff", MainColor = "3e3e3e", AccentColor = "e2581e", BackgroundColor = "323232", OutlineColor = "191919" } },
		['Quartz']        = { 8, { FontColor = "ffffff", MainColor = "232330", AccentColor = "426e87", BackgroundColor = "1d1b26", OutlineColor = "27232f" } },
	}

	function ApplyBackgroundVideo(videoLink)
		if
			typeof(videoLink) ~= "string" or
			not (getassetfunc and writefile and readfile and isfile) or
			not (ThemeManager.Library and ThemeManager.Library.InnerVideoBackground)
		then return; end;

		--// Variables \\--
		local videoInstance = ThemeManager.Library.InnerVideoBackground;
		local extension = videoLink:match(".*/(.-)?") or videoLink:match(".*/(.-)$"); extension = tostring(extension);
		local filename = string.sub(extension, 0, -6);
		local _, domain = videoLink:match("^(https?://)([^/]+)"); domain = tostring(domain); -- _ is protocol

		--// Check URL \\--
		if videoLink == "" then
			videoInstance:Pause();
			videoInstance.Video = "";
			videoInstance.Visible = false;
			return
		end
		if #extension > 5 and string.sub(extension, -5) ~= ".webm" then return; end;

		--// Fetch Video Data \\--
		local videoFile = ThemeManager.Folder .. "/themes/" .. string.gsub(domain .. filename, 0, 249) .. ".webm";
		if not isfile(videoFile) then
			local success, requestRes = pcall(httprequest, { Url = videoLink, Method = 'GET' })
			if not (success and typeof(requestRes) == "table" and typeof(requestRes.Body) == "string") then return; end;

			writefile(videoFile, requestRes.Body)
		end

		--// Play Video \\--
		videoInstance.Video = getassetfunc(videoFile);
		videoInstance.Visible = true;
		videoInstance:Play();
	end

	function ThemeManager:SetLibrary(library)
		self.Library = library
	end

	--// Folders \\--
	function ThemeManager:GetPaths()
	    local paths = {}

		local parts = self.Folder:split('/')
		for idx = 1, #parts do
			paths[#paths + 1] = table.concat(parts, '/', 1, idx)
		end

		paths[#paths + 1] = self.Folder .. '/themes'
		
		return paths
	end

	function ThemeManager:BuildFolderTree()
		local paths = self:GetPaths()

		for i = 1, #paths do
			local str = paths[i]
			if isfolder(str) then continue end
			makefolder(str)
		end
	end

	function ThemeManager:CheckFolderTree()
		if isfolder(self.Folder) then return end
		self:BuildFolderTree()

		task.wait(0.1)
	end

	function ThemeManager:SetFolder(folder)
		self.Folder = folder;
		self:BuildFolderTree()
	end
	
	--// Apply, Update theme \\--
	function ThemeManager:ApplyTheme(theme)
		local customThemeData = self:GetCustomTheme(theme)
		local data = customThemeData or self.BuiltInThemes[theme]

		if not data then return end

		-- custom themes are just regular dictionaries instead of an array with { index, dictionary }
		if self.Library.InnerVideoBackground ~= nil then
			self.Library.InnerVideoBackground.Visible = false
		end
		
		local scheme = data[2]
		for idx, col in next, customThemeData or scheme do
			if idx == "VideoLink" then
				self.Library[idx] = col
				
				if self.Library.Options[idx] then
					self.Library.Options[idx]:SetValue(col)
				end
				
				ApplyBackgroundVideo(col)
			else
				self.Library[idx] = Color3.fromHex(col)
				
				if self.Library.Options[idx] then
					self.Library.Options[idx]:SetValueRGB(Color3.fromHex(col))
				end
			end
		end

		self:ThemeUpdate()
	end

	function ThemeManager:ThemeUpdate()
		-- This allows us to force apply themes without loading the themes tab :)
		if self.Library.InnerVideoBackground ~= nil then
			self.Library.InnerVideoBackground.Visible = false
		end

		for i, field in next, ThemeFields do
			if self.Library.Options and self.Library.Options[field] then
				self.Library[field] = self.Library.Options[field].Value

				if field == "VideoLink" then
					ApplyBackgroundVideo(self.Library.Options[field].Value)
				end
			end
		end

		self.Library.AccentColorDark = self.Library:GetDarkerColor(self.Library.AccentColor);
		self.Library:UpdateColorsUsingRegistry()
	end

	--// Get, Load, Save, Delete, Refresh \\--
	function ThemeManager:GetCustomTheme(file)
		local path = self.Folder .. '/themes/' .. file .. '.json'
		if not isfile(path) then
			return nil
		end

		local data = readfile(path)
		local success, decoded = pcall(HttpService.JSONDecode, HttpService, data)
		
		if not success then
			return nil
		end

		return decoded
	end

	function ThemeManager:LoadDefault()
		local theme = 'Default'
		local content = isfile(self.Folder .. '/themes/default.txt') and readfile(self.Folder .. '/themes/default.txt')

		local isDefault = true
		if content then
			if self.BuiltInThemes[content] then
				theme = content
			elseif self:GetCustomTheme(content) then
				theme = content
				isDefault = false;
			end
		elseif self.BuiltInThemes[self.DefaultTheme] then
			theme = self.DefaultTheme
		end

		if isDefault then
			self.Library.Options.ThemeManager_ThemeList:SetValue(theme)
		else
			self:ApplyTheme(theme)
		end
	end

	function ThemeManager:SaveDefault(theme)
		writefile(self.Folder .. '/themes/default.txt', theme)
	end

	function ThemeManager:SaveCustomTheme(file)
		if file:gsub(' ', '') == '' then
			self.Library:Notify('Invalid file name for theme (empty)', 3)
			return
		end

		local theme = {}
		for _, field in next, ThemeFields do
			if field == "VideoLink" then
				theme[field] = self.Library.Options[field].Value
			else
				theme[field] = self.Library.Options[field].Value:ToHex()
			end
		end

		writefile(self.Folder .. '/themes/' .. file .. '.json', HttpService:JSONEncode(theme))
	end

	function ThemeManager:Delete(name)
		if (not name) then
			return false, 'no config file is selected'
		end

		local file = self.Folder .. '/themes/' .. name .. '.json'
		if not isfile(file) then return false, 'invalid file' end

		local success = pcall(delfile, file)
		if not success then return false, 'delete file error' end
		
		return true
	end
	
	function ThemeManager:ReloadCustomThemes()
		local list = listfiles(self.Folder .. '/themes')

		local out = {}
		for i = 1, #list do
			local file = list[i]
			if file:sub(-5) == '.json' then
				-- i hate this but it has to be done ...

				local pos = file:find('.json', 1, true)
				local start = pos

				local char = file:sub(pos, pos)
				while char ~= '/' and char ~= '\\' and char ~= '' do
					pos = pos - 1
					char = file:sub(pos, pos)
				end

				if char == '/' or char == '\\' then
					table.insert(out, file:sub(pos + 1, start - 1))
				end
			end
		end

		return out
	end

	--// GUI \\--
	function ThemeManager:CreateThemeManager(groupbox)
		groupbox:AddLabel('Background color'):AddColorPicker('BackgroundColor', { Default = self.Library.BackgroundColor });
		groupbox:AddLabel('Main color')	:AddColorPicker('MainColor', { Default = self.Library.MainColor });
		groupbox:AddLabel('Accent color'):AddColorPicker('AccentColor', { Default = self.Library.AccentColor });
		groupbox:AddLabel('Outline color'):AddColorPicker('OutlineColor', { Default = self.Library.OutlineColor });
		groupbox:AddLabel('Font color')	:AddColorPicker('FontColor', { Default = self.Library.FontColor });
		groupbox:AddInput('VideoLink', { Text = '.webm Video Background (Link)', Default = self.Library.VideoLink });
		
		local ThemesArray = {}
		for Name, Theme in next, self.BuiltInThemes do
			table.insert(ThemesArray, Name)
		end

		table.sort(ThemesArray, function(a, b) return self.BuiltInThemes[a][1] < self.BuiltInThemes[b][1] end)

		groupbox:AddDivider()

		groupbox:AddDropdown('ThemeManager_ThemeList', { Text = 'Theme list', Values = ThemesArray, Default = 1 })
		groupbox:AddButton('Set as default', function()
			self:SaveDefault(self.Library.Options.ThemeManager_ThemeList.Value)
			self.Library:Notify(string.format('Set default theme to %q', self.Library.Options.ThemeManager_ThemeList.Value))
		end)

		self.Library.Options.ThemeManager_ThemeList:OnChanged(function()
			self:ApplyTheme(self.Library.Options.ThemeManager_ThemeList.Value)
		end)

		groupbox:AddDivider()

		groupbox:AddInput('ThemeManager_CustomThemeName', { Text = 'Custom theme name' })
		groupbox:AddButton('Create theme', function() 
			local name = self.Library.Options.ThemeManager_CustomThemeName.Value
			if name:gsub(" ", "") == "" then
                self.Library:Notify("Invalid theme name (empty)", 2)
                return
            end

            self:SaveCustomTheme(name)

            self.Library:Notify(string.format("Created theme %q", name))
			self.Library.Options.ThemeManager_CustomThemeList:SetValues(self:ReloadCustomThemes())
			self.Library.Options.ThemeManager_CustomThemeList:SetValue(nil)
		end)

		groupbox:AddDivider()

		groupbox:AddDropdown('ThemeManager_CustomThemeList', { Text = 'Custom themes', Values = self:ReloadCustomThemes(), AllowNull = true, Default = 1 })
		groupbox:AddButton('Load theme', function()
			local name = self.Library.Options.ThemeManager_CustomThemeList.Value

			self:ApplyTheme(name)
			self.Library:Notify(string.format('Loaded theme %q', name))
		end)
		groupbox:AddButton('Overwrite theme', function()
			local name = self.Library.Options.ThemeManager_CustomThemeList.Value

			self:SaveCustomTheme(name)
			self.Library:Notify(string.format('Overwrote config %q', name))
		end)
		groupbox:AddButton('Delete theme', function()
			local name = self.Library.Options.ThemeManager_CustomThemeList.Value

			local success, err = self:Delete(name)
			if not success then
				self.Library:Notify('Failed to delete theme: ' .. err)
				return
			end

			self.Library:Notify(string.format('Deleted theme %q', name))
			self.Library.Options.ThemeManager_CustomThemeList:SetValues(self:ReloadCustomThemes())
			self.Library.Options.ThemeManager_CustomThemeList:SetValue(nil)
		end)
		groupbox:AddButton('Refresh list', function()
			self.Library.Options.ThemeManager_CustomThemeList:SetValues(self:ReloadCustomThemes())
			self.Library.Options.ThemeManager_CustomThemeList:SetValue(nil)
		end)
		groupbox:AddButton('Set as default', function()
			if self.Library.Options.ThemeManager_CustomThemeList.Value ~= nil and self.Library.Options.ThemeManager_CustomThemeList.Value ~= '' then
				self:SaveDefault(self.Library.Options.ThemeManager_CustomThemeList.Value)
				self.Library:Notify(string.format('Set default theme to %q', self.Library.Options.ThemeManager_CustomThemeList.Value))
			end
		end)
		groupbox:AddButton('Reset default', function()
			local success = pcall(delfile, self.Folder .. '/themes/default.txt')
			if not success then 
				self.Library:Notify('Failed to reset default: delete file error')
				return
			end
				
			self.Library:Notify('Set default theme to nothing')
			self.Library.Options.ThemeManager_CustomThemeList:SetValues(self:ReloadCustomThemes())
			self.Library.Options.ThemeManager_CustomThemeList:SetValue(nil)
		end)

		self:LoadDefault()

		local function UpdateTheme() self:ThemeUpdate() end
		self.Library.Options.BackgroundColor:OnChanged(UpdateTheme)
		self.Library.Options.MainColor:OnChanged(UpdateTheme)
		self.Library.Options.AccentColor:OnChanged(UpdateTheme)
		self.Library.Options.OutlineColor:OnChanged(UpdateTheme)
		self.Library.Options.FontColor:OnChanged(UpdateTheme)
	end

	function ThemeManager:CreateGroupBox(tab)
		assert(self.Library, 'ThemeManager:CreateGroupBox -> Must set ThemeManager.Library first!')
		return tab:AddLeftGroupbox('Themes')
	end

	function ThemeManager:ApplyToTab(tab)
		assert(self.Library, 'ThemeManager:ApplyToTab -> Must set ThemeManager.Library first!')
		local groupbox = self:CreateGroupBox(tab)
		self:CreateThemeManager(groupbox)
	end

	function ThemeManager:ApplyToGroupbox(groupbox)
		assert(self.Library, 'ThemeManager:ApplyToGroupbox -> Must set ThemeManager.Library first!')
		self:CreateThemeManager(groupbox)
	end

	ThemeManager:BuildFolderTree()
end

getgenv().LinoriaThemeManager = ThemeManager
return ThemeManager
end

__evilrollerplayers_hook_shared.script_paths = function()
-- =============================================================================
--  Paths - on-disk storage and UI preferences
-- =============================================================================
--  Owns every file this script touches on your machine. All of it lives under a
--  single folder in your executor's workspace directory:
--
--      <executor workspace>/evilrollerplayersHail/
--          UISettings.json                  general menu preferences
--          AutoShow.txt                     mirror of the "auto show" preference
--          settings/<config>.json           saved feature configs
--          RIVALS Skyboxes.json             custom skybox list (World tab)
--          RIVALS Custom Sounds.json        custom sound list (Client Effects)
--          RIVALS Movement Recordings.json  saved movement recordings
--          RIVALS Sounds/                   cached downloaded sounds
-- =============================================================================

-- Change these two to rename the script. DisplayName is what the menu title bar
-- shows; StorageRoot is the folder name on disk (renaming it orphans any configs
-- already saved under the old name).
local DisplayName = "evilrollerplayer's Hail v3"
local StorageRoot = 'evilrollerplayers Hail v3'

-- Where queue_on_teleport should re-read the script from when "Auto Execute on
-- Teleport" is enabled. Save the built script to this path (relative to your
-- executor's workspace folder) for that option to work. If you load the script
-- from a URL instead, replace the body of queue_on_teleport_script() below with
-- your own loadstring line.
local LocalScriptPath = StorageRoot .. '/evilrollerplayersHail_Source_Runnable.lua'

local AutoShowPath = StorageRoot .. '/AutoShow.txt'
local UiSettingsPath = StorageRoot .. '/UISettings.json'
local HttpService = game:GetService('HttpService')

local DefaultUiSettings = {
    auto_show = false,
    show_notification = true,
    show_keybind_states = false,
    auto_execute_on_teleport = false,
    auto_load_config = true,
    auto_save_config = true,
    load_config_name = 'Legit',
    menu_keybind = 'RightShift',
}

local module = {}

-- pcall'd because a handful of executors ship no filesystem API at all. Losing
-- persistence is survivable; erroring out of the bootstrap is not.
pcall(function()
    if not isfolder(StorageRoot) then
        makefolder(StorageRoot)
    end
end)

local function clone_table(source)
    local copy = {}
    for key, value in pairs(source) do
        copy[key] = value
    end
    return copy
end

local function apply_ui_setting_overrides(defaults, overrides)
    if type(overrides) ~= 'table' then
        return defaults
    end

    for key, value in pairs(overrides) do
        if DefaultUiSettings[key] ~= nil and value ~= nil then
            defaults[key] = value
        end
    end

    return defaults
end

-- Never trusts the file on disk: every key is type-checked against the default
-- it replaces, so a hand-edited or corrupted JSON degrades to defaults instead
-- of feeding a wrong-typed value into the UI library.
local function sanitize_ui_settings(settings, defaults)
    local data = clone_table(defaults)
    if type(settings) ~= 'table' then
        return data
    end

    for key, fallback in pairs(defaults) do
        local value = settings[key]
        if type(fallback) == 'boolean' then
            if type(value) == 'boolean' then
                data[key] = value
            end
        elseif type(fallback) == 'string' then
            if type(value) == 'string' and value ~= '' then
                data[key] = value
            end
        end
    end

    return data
end

local function read_legacy_auto_show(default_value)
    local path = module.auto_show_path()
    if not isfile(path) then
        return default_value
    end

    local success, value = pcall(readfile, path)
    if not success then
        return default_value
    end

    value = string.lower(tostring(value))
    if value == 'true' then
        return true
    end
    if value == 'false' then
        return false
    end

    return default_value
end

function module.storage_root()
    return StorageRoot
end

function module.auto_show_path()
    return AutoShowPath
end

function module.ui_settings_path()
    return UiSettingsPath
end

function module.default_ui_settings(overrides)
    return apply_ui_setting_overrides(clone_table(DefaultUiSettings), overrides)
end

function module.config_path(config_name)
    return StorageRoot .. '/settings/' .. config_name .. '.json'
end

function module.load_ui_settings(overrides)
    local defaults = module.default_ui_settings(overrides)

    if isfile(UiSettingsPath) then
        local read_ok, raw = pcall(readfile, UiSettingsPath)
        if read_ok then
            local decode_ok, decoded = pcall(function()
                return HttpService:JSONDecode(raw)
            end)
            if decode_ok then
                return sanitize_ui_settings(decoded, defaults)
            end
        end
    end

    defaults.auto_show = read_legacy_auto_show(defaults.auto_show)
    return defaults
end

function module.save_ui_settings(settings, overrides)
    local data = sanitize_ui_settings(settings, module.default_ui_settings(overrides))
    writefile(UiSettingsPath, HttpService:JSONEncode(data))
    writefile(module.auto_show_path(), data.auto_show and 'true' or 'false')
    return data
end

-- AutoShow is mirrored into its own plain-text file so the menu can decide
-- whether to open itself before the JSON settings have been parsed.
function module.ensure_auto_show_file()
    local path = module.auto_show_path()
    local ui_settings = module.load_ui_settings()
    writefile(path, ui_settings.auto_show and 'true' or 'false')
    return path
end

function module.queue_on_teleport_script()
    local ok, source = pcall(function() return readfile(LocalScriptPath) end)
    if not ok or type(source) ~= 'string' or #source == 0 then
        return nil, 'Auto Execute: run the downloaded full script once to create its local copy.'
    end
    return string.format([==[
        if not game:IsLoaded() then game.Loaded:Wait() end
        local ok, source = pcall(function() return readfile(%q) end)
        if not ok or type(source) ~= 'string' or #source == 0 then
            warn("[evilrollerplayer's Hail] Auto Execute: the saved script is missing. Run the full script again.")
            return
        end
        local run, err = loadstring(source, "evilrollerplayersHail")
        if not run then warn("[evilrollerplayer's Hail] Auto Execute: " .. tostring(err)); return end
        local env = type(getgenv) == 'function' and getgenv() or _G
        env.Executed = nil
        _G.__evilrollerplayersHailExecuted = nil
        run()
    ]==], LocalScriptPath)
end

function module.format_title()
    return DisplayName
end

return module
end

__evilrollerplayers_hook_shared.connection_registry = function()
local module = {}

local function disconnect_handle(handle)
    if handle == nil then
        return
    end

    if type(handle) == 'function' then
        pcall(handle)
        return
    end

    if type(handle) == 'table' then
        local disconnect_method = handle.Disconnect
        if type(disconnect_method) == 'function' then
            pcall(disconnect_method, handle)
        end
        return
    end

    pcall(function()
        handle:Disconnect()
    end)
end

function module.new()
    local handles = {}
    local registry = {}

    function registry:register(name, handle)
        if handles[name] ~= nil then
            disconnect_handle(handles[name])
        end

        handles[name] = handle
        return handle
    end

    function registry:get(name)
        return handles[name]
    end

    function registry:disconnect(names)
        for _, name in ipairs(names) do
            if handles[name] ~= nil then
                disconnect_handle(handles[name])
                handles[name] = nil
            end
        end
    end

    function registry:disconnect_all()
        for name, handle in pairs(handles) do
            disconnect_handle(handle)
            handles[name] = nil
        end
    end

    setmetatable(registry, {
        __newindex = function(_, name, handle)
            registry:register(name, handle)
        end,
        __index = function(_, name)
            return handles[name]
        end,
    })

    return registry
end

return module
end

__evilrollerplayers_hook_shared.ui_settings = function()
local module = {}
function module.new(args)
    local window, library = args.window, args.library
    local options, toggles = args.options, args.toggles
    local sm, tm, paths = args.save_manager, args.theme_manager, args.script_paths
    local http = game:GetService('HttpService')
    local previous = paths.load_ui_settings(args.defaults or {})
    local prefPath = paths.storage_root() .. '/MenuPreferences.json'
    local prefs = {}
    pcall(function()
        if isfile(prefPath) then
            local saved = http:JSONDecode(readfile(prefPath))
            if type(saved) == 'table' then prefs = saved end
        end
    end)
    local settings = {}
    local building, stopped = true, false
    local teleportConnection
    local originalNotify = library.Notify
    local autoloadName, autoloadValid = sm:GetAutoloadConfig()
    local function notify(text) originalNotify(library, text, 4) end
    local function action(fn)
        return function(...)
            local ok, err = pcall(fn, ...)
            if not ok then notify(tostring(err)) end
        end
    end
    local function check(ok, err)
        if ok == false then error(tostring(err or 'Operation failed'), 0) end
    end
    local function validName(value)
        local name = tostring(value or ''):match('^%s*(.-)%s*$')
        if name == '' or #name > 80 or name:find('[<>:"/\\|?*%c]') or name:sub(-1) == '.' then
            error('Enter a name of 1–80 characters without path separators or special filename characters.', 0)
        end
        return name
    end
    local function readNumber(key, default, minimum, maximum)
        local value = tonumber(prefs[key])
        if not value or value ~= value then return default end
        return math.clamp(value, minimum, maximum)
    end
    local preferenceIds = {
        'MenuKeybind', 'P3S1T3', 'evilrollerplayersMenuOpacity', 'evilrollerplayersKeybindMenuMode',
        'evilrollerplayersNotifications', 'P3S1T2', 'evilrollerplayersNotificationSide', 'evilrollerplayersNotificationDuration',
        'evilrollerplayersBackgroundImage', 'P3S1T4', 'AutoExecuteKeybind',
    }
    local function persist()
        if building or stopped then return end
        local saved = {}
        for _, id in ipairs(preferenceIds) do
            local control = toggles[id] or options[id]
            if control then saved[id] = control.Value end
        end
        pcall(function() writefile(prefPath, http:JSONEncode(saved)) end)
        previous.menu_keybind = options.MenuKeybind.Value
        previous.show_keybind_states = toggles.P3S1T3.Value
        previous.show_notification = toggles.P3S1T2.Value
        previous.auto_execute_on_teleport = toggles.P3S1T4.Value
        previous.auto_load_config = autoloadValid == true
        previous.auto_save_config = false
        previous.load_config_name = autoloadValid and autoloadName or 'RIVALS Default'
        paths.save_ui_settings(previous, args.defaults or {})
    end

    local tab = window:AddTab('UI Settings', 'settings')
    local menuTabs = tab:AddLeftTabbox('Menu settings')
    local menu = menuTabs:AddTab('Menu')
    local notifications = menuTabs:AddTab('Notifications')
    menu:AddLabel('Menu bind'):AddKeyPicker('MenuKeybind', {
        Default = type(prefs.MenuKeybind) == 'string' and prefs.MenuKeybind or previous.menu_keybind or 'RightShift',
        NoUI = true, Text = 'Menu bind',
    })
    library.ToggleKeybind = options.MenuKeybind
    options.MenuKeybind:OnChanged(persist)
    local autoExecuteDefault = previous.auto_execute_on_teleport == true
    if type(prefs.P3S1T4) == 'boolean' then autoExecuteDefault = prefs.P3S1T4 end
    menu:AddToggle('P3S1T4', {
        Text = 'Auto Execute', Default = autoExecuteDefault,
        Tooltip = 'Run the script again after teleporting or rejoining.',
        Callback = function(on)
            previous.auto_execute_on_teleport = on
            if not building then
                settings:sync_queue_on_teleport()
                persist()
            end
        end,
    }):AddKeyPicker('AutoExecuteKeybind', {
        Default = type(prefs.AutoExecuteKeybind) == 'string' and prefs.AutoExecuteKeybind or 'None',
        Mode = 'Toggle', Modes = { 'Toggle' }, SyncToggleState = true, Text = 'Auto Execute',
    })
    options.AutoExecuteKeybind:OnChanged(persist)
    menu:AddToggle('P3S1T3', {
        Text = 'Keybind Menu', Default = prefs.P3S1T3 == true,
        Callback = function(on)
            if library.KeybindFrame then library.KeybindFrame.Visible = on end
            persist()
        end,
    })
    local originalTransparency = setmetatable({}, { __mode = 'k' })
    local function applyOpacity(value)
        if not window.Holder then return end
        local all = window.Holder:GetDescendants()
        all[#all + 1] = window.Holder
        for _, instance in ipairs(all) do
            if instance:IsA('GuiObject') then
                local base = originalTransparency[instance]
                if base == nil then base = instance.BackgroundTransparency; originalTransparency[instance] = base end
                instance.BackgroundTransparency = 1 - (1 - base) * value / 100
            end
        end
    end
    menu:AddSlider('evilrollerplayersMenuOpacity', {
        Text = 'Menu Transparency', Default = readNumber('evilrollerplayersMenuOpacity', 100, 0, 100),
        Min = 0, Max = 100, Rounding = 0, Suffix = '%', Compact = true,
        Callback = function(value) applyOpacity(value); persist() end,
    })
    local function applyKeybindMode(value)
        library.KeybindMenuMode = value
        for _, option in pairs(options) do
            if option.Type == 'KeyPicker' and type(option.Update) == 'function' then option:Update() end
        end
        persist()
    end
    menu:AddDropdown('evilrollerplayersKeybindMenuMode', {
        Text = 'Keybind Menu Mode', Values = { 'Toggled', 'Always' },
        Default = prefs.evilrollerplayersKeybindMenuMode == 'Always' and 'Always' or 'Toggled', Callback = applyKeybindMode,
    })
    notifications:AddToggle('evilrollerplayersNotifications', { Text = 'Notifications', Default = prefs.evilrollerplayersNotifications ~= false, Callback = persist })
    notifications:AddToggle('P3S1T2', { Text = 'Load notification', Default = prefs.P3S1T2 ~= false, Callback = persist })
    notifications:AddDropdown('evilrollerplayersNotificationSide', {
        Text = 'Position', Values = { 'Left', 'Right' }, Default = prefs.evilrollerplayersNotificationSide == 'Right' and 'Right' or 'Left',
        Callback = function(value) library:SetNotifySide(value); persist() end,
    })
    notifications:AddSlider('evilrollerplayersNotificationDuration', {
        Text = 'Duration', Min = 1, Max = 10, Default = readNumber('evilrollerplayersNotificationDuration', 4, 1, 10),
        Rounding = 0, Suffix = 's', Callback = persist,
    })
    library.Notify = function(self, text, duration, ...)
        if not toggles.evilrollerplayersNotifications.Value then return nil end
        if type(text) == 'table' then
            text = table.clone(text)
            text.Time = text.Time or options.evilrollerplayersNotificationDuration.Value
        end
        return originalNotify(self, text, duration or options.evilrollerplayersNotificationDuration.Value, ...)
    end

    local config = tab:AddRightGroupbox('Configuration')
    config:AddInput('evilrollerplayersNewConfigName', { Text = 'Config name', Default = '', AllowEmpty = true, Finished = true })
    local configNames = sm:RefreshConfigList()
    config:AddDropdown('UILoadConfigName', {
        Text = 'Config list', Values = configNames, AllowNull = true,
        Default = autoloadValid and autoloadName or configNames[1],
    })
    local autoloadLabel
    local function refreshAutoload()
        autoloadName, autoloadValid = sm:GetAutoloadConfig()
        if autoloadLabel then autoloadLabel:SetText('Current autoload config: ' .. (autoloadValid and autoloadName or 'none')) end
        persist()
    end
    local function selectedConfig()
        local name = validName(options.UILoadConfigName.Value)
        if not isfile(paths.config_path(name)) then error('Select an existing config.', 0) end
        return name
    end
    local function refreshConfigs(selected)
        configNames = sm:RefreshConfigList()
        options.UILoadConfigName:SetValues(configNames)
        local value = selected or options.UILoadConfigName.Value
        options.UILoadConfigName:SetValue(table.find(configNames, value) and value or nil)
        refreshAutoload()
    end
    config:AddButton({ Text = 'Create config', Func = action(function()
        local name = validName(options.evilrollerplayersNewConfigName.Value)
        if isfile(paths.config_path(name)) then error('That config already exists. Use Overwrite config.', 0) end
        check(args.on_save(name))
        refreshConfigs(name)
        notify('Created config: ' .. name)
    end) }):AddButton({ Text = 'Load config', Func = action(function()
        selectedConfig()
        check(args.on_load_saved())
        notify('Config loaded')
    end) })
    config:AddButton({ Text = 'Overwrite config', Func = action(function()
        check(args.on_save(selectedConfig()))
        notify('Config overwritten')
    end) }):AddButton({ Text = 'Delete config', Func = action(function()
        local name = selectedConfig()
        check(sm:Delete(name))
        if autoloadValid and name == autoloadName then sm:DeleteAutoLoadConfig() end
        refreshConfigs()
    end) })
    config:AddButton({ Text = 'Refresh list', Func = action(function() refreshConfigs() end) })
    config:AddButton({ Text = 'Set autoload', Func = action(function()
        check(sm:SaveAutoloadConfig(selectedConfig()))
        refreshAutoload()
    end) }):AddButton({ Text = 'Remove autoload', Func = action(function()
        if autoloadValid then check(sm:DeleteAutoLoadConfig()) end
        refreshAutoload()
    end) })
    autoloadLabel = config:AddLabel('Current autoload config: ' .. (autoloadValid and autoloadName or 'none'), true)
    config:AddDivider()
    local importing = false
    config:AddInput('evilrollerplayersImportSource', {
        Text = 'Import from clipboard', Placeholder = 'Paste config here...', Default = '', AllowEmpty = true, Finished = true,
        Callback = action(function(text)
            if importing or text == '' then return end
            local doc = http:JSONDecode(text)
            if type(doc) ~= 'table' or type(doc.objects) ~= 'table' then error('Paste a saved config JSON.', 0) end
            local name = validName(options.evilrollerplayersNewConfigName.Value ~= '' and options.evilrollerplayersNewConfigName.Value or doc.name)
            if isfile(paths.config_path(name)) then error('Choose a new config name before importing.', 0) end
            for _, object in pairs(doc.objects) do
                if type(object) ~= 'table' or type(object.idx) ~= 'string' or type(object.type) ~= 'string' then
                    error('The config contains an invalid setting.', 0)
                end
            end
            doc.name = name
            sm:CheckFolderTree()
            writefile(paths.config_path(name), http:JSONEncode(doc))
            refreshConfigs(name)
            importing = true; options.evilrollerplayersImportSource:SetValue(''); importing = false
            notify('Imported ' .. name .. '. Press Load config to apply it.')
        end),
    })
    config:AddButton({ Text = 'Copy config to clipboard', Func = action(function()
        local copy = setclipboard or toclipboard
        if type(copy) ~= 'function' then error('Clipboard access is unavailable.', 0) end
        copy(readfile(paths.config_path(selectedConfig())))
        notify('Config copied')
    end) })

    local themeTabs = tab:AddLeftTabbox('Theme settings')
    local themes = themeTabs:AddTab('Themes')
    local background = themeTabs:AddTab('Background')
    for _, field in ipairs({ {'MainColor', 'Main Color'}, {'AccentColor', 'Accent Color'},
        {'BackgroundColor', 'Background Color'}, {'OutlineColor', 'Outline Color'},
        {'FontColor', 'Text Color'}, {'RiskColor', 'Risk Text Color'} }) do
        themes:AddLabel(field[2]):AddColorPicker(field[1], { Default = library[field[1]] })
        options[field[1]]:OnChanged(function() tm:ThemeUpdate() end)
    end
    background:AddInput('evilrollerplayersBackgroundImage', {
        Text = 'Background image asset ID', Default = type(prefs.evilrollerplayersBackgroundImage) == 'string' and prefs.evilrollerplayersBackgroundImage or '',
        AllowEmpty = true, Finished = true,
        Callback = function(value) window:SetBackgroundImage(value); persist() end,
    })
    background:AddInput('VideoLink', {
        Text = '.webm background link', Default = library.VideoLink or '', AllowEmpty = true, Finished = true,
        Callback = action(function() tm:ThemeUpdate() end),
    })
    local builtins = {}
    for name in pairs(tm.BuiltInThemes) do builtins[#builtins + 1] = name end
    table.sort(builtins, function(a, b) return tm.BuiltInThemes[a][1] < tm.BuiltInThemes[b][1] end)
    themes:AddDropdown('ThemeManager_ThemeList', { Text = 'Theme list', Values = builtins, Default = 1,
        Callback = action(function(name) if name then tm:ApplyTheme(name) end end) })
    themes:AddButton({ Text = 'Set Default', Func = action(function() tm:SaveDefault(options.ThemeManager_ThemeList.Value) end) })
    themes:AddInput('ThemeManager_CustomThemeName', { Text = 'Custom theme name', Default = '', AllowEmpty = true, Finished = true })
    local function themePath(name) return tm.Folder .. '/themes/' .. validName(name) .. '.json' end
    local function refreshThemes(selected)
        local names = tm:ReloadCustomThemes()
        table.sort(names)
        options.ThemeManager_CustomThemeList:SetValues(names)
        local name = selected or options.ThemeManager_CustomThemeList.Value
        options.ThemeManager_CustomThemeList:SetValue(table.find(names, name) and name or nil)
    end
    themes:AddButton({ Text = 'Create theme', Func = action(function()
        local name = validName(options.ThemeManager_CustomThemeName.Value)
        if isfile(themePath(name)) then error('That theme exists. Use Overwrite Theme.', 0) end
        tm:SaveCustomTheme(name)
        refreshThemes(name)
    end) })
    themes:AddDropdown('ThemeManager_CustomThemeList', { Text = 'Custom themes', Values = tm:ReloadCustomThemes(), AllowNull = true })
    local function selectedTheme()
        local name = validName(options.ThemeManager_CustomThemeList.Value)
        if not isfile(themePath(name)) then error('Select an existing theme.', 0) end
        return name
    end
    themes:AddButton({ Text = 'Load theme', Func = action(function() tm:ApplyTheme(selectedTheme()) end) })
    themes:AddButton({ Text = 'Overwrite Theme', Func = action(function() tm:SaveCustomTheme(selectedTheme()) end) }):AddButton({
        Text = 'Delete Theme', Func = action(function()
            local name = selectedTheme()
            check(tm:Delete(name))
            local defaultPath = tm.Folder .. '/themes/default.txt'
            if isfile(defaultPath) and readfile(defaultPath) == name then delfile(defaultPath) end
            refreshThemes()
        end),
    })
    themes:AddButton({ Text = 'Set Default', Func = action(function() tm:SaveDefault(selectedTheme()) end) }):AddButton({
        Text = 'Reset Default', Func = action(function()
            local path = tm.Folder .. '/themes/default.txt'
            if isfile(path) then delfile(path) end
        end),
    })
    themes:AddButton({ Text = 'Refresh', Func = action(function() refreshThemes() end) })
    tab:AddRightGroupbox('lua'):AddLabel('in development')

    local ignore = { 'UILoadConfigName', 'evilrollerplayersNewConfigName', 'evilrollerplayersImportSource', 'RiskColor', 'VideoLink',
        'P3S1T1', 'P3S1T4', 'P3S1T5', 'UIAutoSaveConfig' }
    for _, id in ipairs(preferenceIds) do ignore[#ignore + 1] = id end
    for _, id in ipairs(args.extra_ignore_ids or {}) do ignore[#ignore + 1] = id end
    sm:IgnoreThemeSettings()
    sm:SetIgnoreIndexes(ignore)
    tm:LoadDefault()
    tm.AppliedToTab = true
    building = false

    function settings:get_config_names() return table.clone(args.config_names or {}) end
    function settings:resolve_save_config_name() return options.UILoadConfigName.Value or 'RIVALS Default' end
    function settings:resolve_load_config_name() return self:resolve_save_config_name() end
    function settings:should_auto_save_config() return false end
    function settings:schedule_auto_save() end
    function settings:refresh_auto_save_bindings() end
    function settings:with_config_load_suspended(fn) return fn() end
    function settings:should_auto_load_config() return autoloadValid == true end
    function settings:sync_queue_on_teleport()
        local enabled = toggles.P3S1T4.Value == true
        previous.auto_execute_on_teleport = enabled
        if (not enabled or stopped) and teleportConnection then
            teleportConnection:Disconnect()
            teleportConnection = nil
        end
        if enabled and not teleportConnection and not stopped
            and __evilrollerplayers_hook_genv.evilrollerplayersHailCaps.gate('Auto Execute', 'queue_on_teleport') then
            teleportConnection = args.local_player.OnTeleport:Connect(function(state)
                if not stopped and toggles.P3S1T4.Value and state == Enum.TeleportState.InProgress then args.queue_loader() end
            end)
            library:GiveSignal(teleportConnection)
        end
    end
    function settings:shutdown_for_unload()
        stopped = true
        if teleportConnection then teleportConnection:Disconnect(); teleportConnection = nil end
        library.Notify = originalNotify
    end
    function settings:register_callbacks() end
    function settings:reconcile_loaded_ui_settings()
        if library.KeybindFrame then library.KeybindFrame.Visible = toggles.P3S1T3.Value end
        applyKeybindMode(options.evilrollerplayersKeybindMenuMode.Value)
        library:SetNotifySide(options.evilrollerplayersNotificationSide.Value)
        applyOpacity(options.evilrollerplayersMenuOpacity.Value)
        window:SetBackgroundImage(options.evilrollerplayersBackgroundImage.Value)
        self:sync_queue_on_teleport()
        refreshConfigs()
    end
    function settings:notify_loaded(duration)
        if toggles.P3S1T2.Value then library:Notify('Loaded - ' .. options.MenuKeybind.Value .. ' to toggle menu', duration or 5) end
    end
    library:OnUnload(function() settings:shutdown_for_unload() end)
    return settings
end
return module
end

__evilrollerplayers_hook_shared.game_bootstrap = function()
local module = {}

local function elevate_ui_identity()
    if type(__evilrollerplayersHailElevateIdentity) == 'function' then
        __evilrollerplayersHailElevateIdentity()
    elseif type(setthreadidentity) == 'function' then
        pcall(setthreadidentity, 8)
    end
end

function module.create_window(args)
    elevate_ui_identity()
    local ui_settings = args.script_paths.load_ui_settings(args.ui_settings_defaults)

    elevate_ui_identity()
    return args.library:CreateWindow({
        Position = args.position,
        Title = args.title,
        Center = args.center,
        AutoShow = ui_settings.auto_show == true,
        DisableSearch = true,
        Footer = args.footer or 'TESTER ONLY v3',
        Icon = args.icon,
        IconSize = args.icon_size,
    })
end

function module.create_standard_shared_ui(args)
    elevate_ui_identity()
    local shared_ui
    local defaults = args.defaults or {
        auto_show = false,
        show_notification = true,
        show_keybind_states = false,
        auto_execute_on_teleport = false,
        auto_load_config = true,
        auto_save_config = true,
        load_config_name = 'Legit',
    }

    local function reconcile_loaded_state()
        if args.reconcile_loaded_state then
            args.reconcile_loaded_state()
        end
    end

    elevate_ui_identity()
    shared_ui = args.ui_settings.new({
        window = args.window,
        library = args.library,
        theme_manager = args.theme_manager,
        script_paths = args.script_paths,
        save_manager = args.save_manager,
        current_config_name = args.current_config_name,
        config_names = args.config_names,
        use_global_config_names = args.use_global_config_names,
        resolve_config_name = args.resolve_config_name,
        toggles = args.toggles,
        options = args.options,
        local_player = args.local_player,
        defaults = defaults,
        persist_menu_keybind = args.persist_menu_keybind,
        extra_ignore_ids = args.extra_ignore_ids,
        queue_loader = function()
            -- args.queue_on_teleport is Header's safe no-op capture when the
            -- executor lacks the real function; gate so the reload silently
            -- not happening comes with an explanation
            if __evilrollerplayers_hook_genv.evilrollerplayersHailCaps.gate('Auto Execute', 'queue_on_teleport') then
                local loader, err = args.script_paths.queue_on_teleport_script()
                if not loader then
                    args.library:Notify(err)
                    return
                end
                args.queue_on_teleport(loader)
            end
        end,
        on_save = function(config_name)
            local save_name = shared_ui and shared_ui.resolve_save_config_name and shared_ui:resolve_save_config_name() or args.current_config_name
            if config_name then
                save_name = config_name
            end
            if args.before_save then
                args.before_save(shared_ui, save_name)
            end
            local ok, err = args.save_manager:Save(save_name)
            if ok and args.on_save then
                args.on_save(shared_ui, save_name)
            end
            return ok, err
        end,
        on_load_saved = function()
            local load_name = shared_ui and shared_ui.resolve_load_config_name and shared_ui:resolve_load_config_name() or args.current_config_name
            local loaded, loadError
            if shared_ui and shared_ui.with_config_load_suspended then
                loaded, loadError = shared_ui:with_config_load_suspended(function()
                    return args.save_manager:Load(load_name)
                end)
            else
                loaded, loadError = args.save_manager:Load(load_name)
            end
            if not loaded then return false, loadError end
            shared_ui:reconcile_loaded_ui_settings()
            reconcile_loaded_state()
            if args.on_load_saved then
                args.on_load_saved(shared_ui, load_name)
            end
        end,
        on_load_default = function()
            local save_name = shared_ui and shared_ui.resolve_save_config_name and shared_ui:resolve_save_config_name() or args.current_config_name
            if shared_ui and shared_ui.with_config_load_suspended then
                shared_ui:with_config_load_suspended(function()
                    if type(args.reset_config_to_default) == 'function' then
                        args.save_manager:Load(args.default_config_name)
                        args.reset_config_to_default(shared_ui, save_name)
                        args.save_manager:Load(save_name)
                    else
                        args.save_manager:Load(args.default_config_name)
                        args.save_manager:Save(save_name)
                    end
                end)
            else
                if type(args.reset_config_to_default) == 'function' then
                    args.save_manager:Load(args.default_config_name)
                    args.reset_config_to_default(shared_ui, save_name)
                    args.save_manager:Load(save_name)
                else
                    args.save_manager:Load(args.default_config_name)
                    args.save_manager:Save(save_name)
                end
            end
            shared_ui:reconcile_loaded_ui_settings()
            reconcile_loaded_state()
            if args.on_load_default then
                args.on_load_default(shared_ui, save_name)
            end
        end,
    })

    return shared_ui
end

function module.prepare_setup(args)
    elevate_ui_identity()
    local sm = args.save_manager
    local default_name = args.default_config_name

    if not isfile(args.script_paths.config_path(default_name)) then
        sm:Save(default_name)
    end
    if args.shared_ui and args.shared_ui.get_config_names then
        for _, config_name in ipairs(args.shared_ui:get_config_names()) do
            if not isfile(args.script_paths.config_path(config_name)) then
                local ok = nil
                if type(args.reset_config_to_default) == 'function' then
                    ok = args.reset_config_to_default(args.shared_ui, config_name)
                end
                if ok == false or ok == nil then
                    sm:Save(config_name)
                end
            end
        end
    end

    if not args.defer_load then
        module.load_config(args)
    end

    args.shared_ui:register_callbacks()
    args.shared_ui:reconcile_loaded_ui_settings()
end

function module.load_config(args)
    elevate_ui_identity()
    local sm = args.save_manager
    local current = args.current_config_name
    local default_name = args.default_config_name
    local shared_ui = args.shared_ui

    local function load_config_name(config_name)
        if shared_ui and shared_ui.with_config_load_suspended then
            return shared_ui:with_config_load_suspended(function()
                return sm:Load(config_name)
            end)
        end

        return sm:Load(config_name)
    end

    if shared_ui and shared_ui.should_auto_load_config and shared_ui:should_auto_load_config() then
        local load_name = shared_ui and shared_ui.resolve_load_config_name and shared_ui:resolve_load_config_name() or current
        local ok = load_config_name(load_name)
        if not ok then
            load_config_name(default_name)
        end
    else
        load_config_name(default_name)
    end
end

return module
end

__evilrollerplayers_hook_shared.rivals_ragebot_kernel = function()
-- RivalsRagebotKernel.lua
-- The ragebot, lifted verbatim out of the RIVALS feature module into its own
-- shared module so it can be read (and lifted out) on its own. It runs as plain
-- client Lua on a per-frame loop.
--
-- init(ctx) is called once from the RIVALS module, at the point the old IIFE
-- ran. It is handed the seven names the block reads from outer scope: four
-- stable tables by reference (RivalsRuntimeBridge / Options / Toggles /
-- FighterDataCache), two respawn-reassigned handles via live getters (GetChar /
-- GetRoot), and the global environment (Genv). Genv stays an explicit ctx field
-- so the kernel works wherever it is emitted.
--
-- It fires the fighter combat remote directly and uses metatable / getgc / debug
-- surfaces. That is evilrollerplayers's original method, reproduced rather than softened.
return {
    init = function(ctx)
        local RivalsRuntimeBridge = ctx.RivalsRuntimeBridge
        local Options = ctx.Options
        local Toggles = ctx.Toggles
        local FighterDataCache = ctx.FighterDataCache
        local GetChar = ctx.GetChar
