                            player = player,
                            entity = entity,
                            model = model,
                            hitboxHead = hitboxHead,
                            hitboxBody = hitboxBody,
                            rootPart = rootPart,
                            itemObserver = rawget(fighter, 'itemObserver') or rawget(fighter, 'ItemObserver'),
                            alive = humanoid == nil or humanoid.Health > 0,
                            invincible = isTargetInvincible(entity),
                            hacker = false,
