                    for _, entry in ipairs(enemies) do
                        if entry.hacker and isValidTarget(entry) then
                            return entry
                        end
                    end
                end
                for _, entry in ipairs(enemies) do
                    if not (prioritizeHackers and entry.hacker) and isValidTarget(entry) then
                        return entry
                    end
                end
