        if M.cent == nil then M.cent = moduleAt({"Modules","ClientReplicatedClasses","ClientEntity"}) end
        if M.pdc  == nil then M.pdc  = moduleAt({"Controllers","PlayerDataController"}) end
        if _optTries < 3 then
            _optTries = _optTries + 1
