        if slot == nil then return entry end
        for _, kind in pairs({ "Skin", "Charm", "Wrap", "Finisher" }) do
            local sel = slot[kind]
            if sel ~= nil then
                if sel.Name == NONE_COSMETIC then
                    entry[kind] = nil
                elseif sel.Name == RANDOM_COSMETIC then
                    entry[kind] = sel
                else
                    entry[kind] = sel
                end
            end
        end
        return entry
