            function RivalsRuntimeBridge.ViewmodelVisuals.ApplyCrosshairPreset(name)
                local visuals = RivalsRuntimeBridge.ViewmodelVisuals
                local preset = visuals.CrosshairPresets[name]
                if not preset then
                    return
                end
                local wanted = preset.Toggles or {}
                for _, toggleId in ipairs(visuals.CrosshairPresetManagedToggles) do
                    local toggle = Toggles and Toggles[toggleId]
                    if toggle and wanted[toggleId] ~= true and toggle.Value then
                        toggle:SetValue(false)
                    end
                end
                for optionId, value in pairs(preset.Options or {}) do
                    local option = Options and Options[optionId]
                    if option and type(option.SetValue) == 'function' then
                        option:SetValue(value)
                    end
                end
                for optionId, rgb in pairs(preset.Colors or {}) do
                    local option = Options and Options[optionId]
                    if option and type(option.SetValueRGB) == 'function' then
                        option:SetValueRGB(Color3.fromRGB(rgb[1], rgb[2], rgb[3]))
                    end
                end
                for _, toggleId in ipairs(visuals.CrosshairPresetManagedToggles) do
                    local toggle = Toggles and Toggles[toggleId]
                    if toggle and wanted[toggleId] == true and not toggle.Value then
                        toggle:SetValue(true)
                    end
                end
                -- Picking a preset means the player wants to see it.
                if Toggles and Toggles.P1S26T1 and not Toggles.P1S26T1.Value then
                    Toggles.P1S26T1:SetValue(true)
                end
                visuals.RefreshAll()
            end

            -- evilrollerplayers parity: native crosshair suppression rides the game's own
            -- Crosshair._Update hook instead of walking PlayerGui on a timer.
            function RivalsRuntimeBridge.ViewmodelVisuals.RestoreNativeCrosshairs()
                RivalsRuntimeBridge.NativeRemovals.SetNativeCrosshairHidden(false)
            end

            function RivalsRuntimeBridge.ViewmodelVisuals.HideNativeCrosshairs()
                RivalsRuntimeBridge.NativeRemovals.SetNativeCrosshairHidden(true)
            end

            function RivalsRuntimeBridge.ViewmodelVisuals.SetCrosshairArm(arm, position, size, color, outlineColor, outlineThickness, visible)
                arm.Fill.Visible = visible
                arm.Outline.Visible = visible and outlineThickness > 0
                arm.Fill.Position = UDim2.fromOffset(position.X, position.Y)
                arm.Fill.Size = UDim2.fromOffset(size.X, size.Y)
                arm.Fill.BackgroundColor3 = color
                arm.Outline.Position = arm.Fill.Position
                arm.Outline.Size = UDim2.fromOffset(size.X + outlineThickness * 2, size.Y + outlineThickness * 2)
                arm.Outline.BackgroundColor3 = outlineColor
            end

            function RivalsRuntimeBridge.ViewmodelVisuals.ResolveCrosshairPosition(deltaTime, center)
                local visuals = RivalsRuntimeBridge.ViewmodelVisuals
                -- evilrollerplayers resets the follow spring immediately while Follow Target is
                -- disabled; ordinary custom-crosshair placement is never smoothed.
                if not visuals.ReadToggle('P1S26T9') then
                    visuals.FollowPosition = center
                    return center
                end
                local targetPosition = center
                if visuals.ReadToggle('P2S1T1')
                    and type(RivalsRuntimeBridge.GetBestAimbotTarget) == 'function' then
                    -- Cosmetic follow indicator: piggyback on the aim systems' sweep
                    -- when one ran recently instead of paying a full raycast sweep
                    -- per frame just to place a crosshair (it lerps anyway).
                    local targetInfo
                    if os.clock() - (RivalsRuntimeBridge.LastAimbotSweepAt or 0) <= 0.05 then
                        targetInfo = RivalsRuntimeBridge.LastAimbotSweepTarget
                    else
                        targetInfo = RivalsRuntimeBridge.GetBestAimbotTarget(true, AimbotBridge.IsAimbotIgnoreFovEnabled())
                    end
                    local camera = Workspace.CurrentCamera
                    if targetInfo and targetInfo.worldPosition and camera then
                        local projected, onScreen = camera:WorldToViewportPoint(targetInfo.worldPosition)
                        if onScreen and projected.Z > 0 then
                            targetPosition = Vector2.new(projected.X, projected.Y)
                        end
                    end
                end
                if not visuals.FollowPosition then
                    visuals.FollowPosition = targetPosition
                end
                local alpha = math.clamp(1 - math.exp(-math.max(deltaTime or 0, 0) * 15), 0, 1)
                visuals.FollowPosition = visuals.FollowPosition:Lerp(targetPosition, alpha)
                return visuals.FollowPosition
            end

            function RivalsRuntimeBridge.ViewmodelVisuals.UpdateCrosshair(deltaTime)
                local visuals = RivalsRuntimeBridge.ViewmodelVisuals
                if not visuals.ReadToggle('P1S26T1') then
                    if visuals.Crosshair and visuals.Crosshair.Gui then
                        visuals.Crosshair.Gui.Enabled = false
                    end
                    visuals.FollowPosition = nil
                    visuals.RestoreNativeCrosshairs()
                    return
                end

                -- evilrollerplayers's active gate: the custom crosshair only draws while the game
                -- would show a native one - an equipped item with a live crosshair
                -- object. In the lobby / unspawned / holding nothing there is no
                -- equipped item, so the gui turns off. Native suppression stays armed
                -- the whole time the toggle is on (evilrollerplayers arms it once in ApplyStatic).
                visuals.HideNativeCrosshairs()
                if not RivalsRuntimeBridge.NativeRemovals.IsNativeCrosshairActive() then
                    if visuals.Crosshair and visuals.Crosshair.Gui then
                        visuals.Crosshair.Gui.Enabled = false
                    end
                    return
                end

                local crosshair = visuals.EnsureCrosshair()
                crosshair.Gui.Enabled = true
                -- evilrollerplayers's a5 position provider is exactly ViewportSize / 2. It does
                -- not follow the game's cosmetic viewmodel-offset reticle, because
                -- that offset grows sharply when ADS narrows the camera FOV.
                local camera = Workspace.CurrentCamera
                local viewport = camera and camera.ViewportSize or Vector2.new(1920, 1080)
                local center = Vector2.new(viewport.X * 0.5, viewport.Y * 0.5)
                local position = visuals.ResolveCrosshairPosition(deltaTime, center)
                crosshair.Container.Position = UDim2.fromOffset(math.round(position.X), math.round(position.Y))
                local textPosition = center
                if visuals.ReadToggle('P1S26T9')
                    and visuals.ReadOption('P1S26D2', 'Crosshair') == 'Crosshair + Text' then
                    textPosition = position
                end
                local elapsed = os.clock()

                local angle = visuals.ReadOption('P1S26S4', 0)
                if visuals.ReadToggle('P1S26T8') then
                    angle = (angle + elapsed * visuals.ReadOption('P1S26S5', 90)) % 360
                end
                crosshair.Container.Rotation = angle
                local style = visuals.ReadOption('P1S26D1', 'Lines')
                local imageMode = style == 'Image'
                crosshair.Image.Visible = imageMode
                if imageMode then
                    local size = visuals.ReadOption('P1S26S6', 32)
                    crosshair.Image.Size = UDim2.fromOffset(size, size)
                    crosshair.Image.Image = visuals.ResolveCrosshairImage(visuals.ReadOption('P1S26I1', ''))
                    crosshair.Image.ImageTransparency = math.clamp(visuals.ReadOption('P1S26S7', 0), 0, 1)
                end

                local textEnabled = visuals.ReadToggle('P1S26T11')
                crosshair.Text.Visible = textEnabled
                if textEnabled then
                    crosshair.Text.Text = tostring(visuals.ReadOption('P1S26I2', ''))
                    crosshair.Text.TextSize = visuals.ReadOption('P1S26S14', 14)
                    crosshair.Text.Font = visuals.FontMap[visuals.ReadOption('P1S26D4', 'Inconsolata')] or Enum.Font.Code
                    crosshair.Text.Position = UDim2.fromOffset(
                        math.round(textPosition.X),
                        math.round(textPosition.Y + visuals.ReadOption('P1S26S15', 24))
                    )
                    local textColor = visuals.ReadOption('P1S26C11', Color3.new(1, 1, 1))
                    local gradientColor, gradientOffset, gradientRotation = visuals.ResolveTextGradient(elapsed, textColor)
                    crosshair.TextGradient.Color = gradientColor
                    crosshair.TextGradient.Offset = gradientOffset
                    crosshair.TextGradient.Rotation = gradientRotation
                    crosshair.TextStroke.Enabled = visuals.ReadToggle('P1S26T12')
                    crosshair.TextStroke.Color = visuals.ReadOption('P1S26C12', Color3.new(0, 0, 0))
                    crosshair.TextStroke.Thickness = visuals.ReadOption('P1S26S16', 1)
                end

                local length = visuals.ReadOption('P1S26S1', 12)
                local thickness = visuals.ReadOption('P1S26S2', 2)
                local gap = visuals.ReadOption('P1S26S3', 6)
                if visuals.ReadToggle('P1S26T7') then
                    local minimum = visuals.ReadOption('P1S26S8', 4)
                    local maximum = visuals.ReadOption('P1S26S9', 16)
                    local wave = 0.5 - 0.5 * math.cos(elapsed * visuals.ReadOption('P1S26S10', 3))
                    gap = gap + minimum + (maximum - minimum) * wave
                end
                local outlineThickness = visuals.ReadToggle('P1S26T2') and visuals.ReadOption('P1S26S11', 1) or 0
                local outlineColor = visuals.ReadOption('P1S26C1', Color3.new(0, 0, 0))
                local armDefinitions = {
                    {Key = 'Top', Position = Vector2.new(0, -(gap + length * 0.5)), Size = Vector2.new(thickness, length), Toggle = 'P1S26T3', Color = 'P1S26C2', Fraction = 0},
                    {Key = 'Bottom', Position = Vector2.new(0, gap + length * 0.5), Size = Vector2.new(thickness, length), Toggle = 'P1S26T4', Color = 'P1S26C3', Fraction = 0.5},
                    {Key = 'Left', Position = Vector2.new(-(gap + length * 0.5), 0), Size = Vector2.new(length, thickness), Toggle = 'P1S26T5', Color = 'P1S26C4', Fraction = 0.75},
                    {Key = 'Right', Position = Vector2.new(gap + length * 0.5, 0), Size = Vector2.new(length, thickness), Toggle = 'P1S26T6', Color = 'P1S26C5', Fraction = 0.25},
                }
                for _, definition in ipairs(armDefinitions) do
                    local baseColor = visuals.ReadOption(definition.Color, Color3.new(1, 1, 1))
                    visuals.SetCrosshairArm(
                        crosshair[definition.Key], definition.Position, definition.Size,
                        visuals.ResolveLineColor(baseColor, definition.Fraction, elapsed),
                        outlineColor, outlineThickness,
                        not imageMode and visuals.ReadToggle(definition.Toggle)
                    )
                end
            end

            function RivalsRuntimeBridge.ViewmodelVisuals.RefreshAll()
                RivalsRuntimeBridge.ViewmodelVisuals.LastReconcileAt = tick()
                RivalsRuntimeBridge.ViewmodelVisuals.ReconcileModels()
                RivalsRuntimeBridge.ViewmodelVisuals.UpdateCrosshair(0)
            end

            function RivalsRuntimeBridge.ViewmodelVisuals.Update(deltaTime)
                local visuals = RivalsRuntimeBridge.ViewmodelVisuals
                if tick() - visuals.LastReconcileAt >= 0.25 then
                    visuals.LastReconcileAt = tick()
                    visuals.ReconcileModels()
                end
                visuals.UpdateCrosshair(deltaTime)
            end

            function RivalsRuntimeBridge.ViewmodelVisuals.Destroy()
                local visuals = RivalsRuntimeBridge.ViewmodelVisuals
                visuals.RestoreNativeCrosshairs()
                for part, snapshot in pairs(visuals.AppearanceSnapshots) do
                    visuals.RestoreAppearance(part, snapshot)
                end
                visuals.AppearanceSnapshots = setmetatable({}, { __mode = 'k' })
                for instance, snapshot in pairs(visuals.TextureSnapshots) do
                    visuals.RestoreTexture(instance, snapshot)
                end
                visuals.TextureSnapshots = {}
                for _, entries in pairs(visuals.Highlights) do
                    for _, highlight in pairs(entries) do
                        pcall(function() highlight:Destroy() end)
                    end
                end
                visuals.Highlights = {}
                if visuals.Crosshair and visuals.Crosshair.Gui then
                    pcall(function() visuals.Crosshair.Gui:Destroy() end)
                end
                visuals.Crosshair = nil
                visuals.FollowPosition = nil
                visuals.LastReconcileAt = 0
            end

            -- Direct ports of evilrollerplayers's removal techniques. Each one patches the game's
            -- own drawing path once per toggle flip and restores the captured original
            -- on disable/unload, so there is no scanning and no recurring cost.
            RivalsRuntimeBridge.NativeRemovals = {
                Modules = {},
                Vignette = nil,
                Tracers = nil,
                Muzzle = nil,
                Hitsound = nil,
                Scope = {
                    OverlayHidden = false,
                    ReticleHidden = false,
                    OverlayDirty = false,
                    ReticleDirty = false,
                    Restore = nil,
                },
                -- nil means "leave the native value alone", matching evilrollerplayers's
                -- _crosshairVisible / _hitmarkerVisible tri-state.
                Crosshair = {
                    CrosshairVisible = nil,
                    HitmarkerVisible = nil,
                    Restore = nil,
                },
                Animation = { Restore = nil },
            }

            -- evilrollerplayers's sentinel: the "_Tracers" constant is repointed at a name that
            -- resolves to a no-op on the same class, so the call still succeeds.
            -- Table fields, not locals: RIVALS top scope is at Luau's 200-local limit.
            RivalsRuntimeBridge.NativeRemovals.TracerSentinel = '_Tracers\0NoGunTracers'
            RivalsRuntimeBridge.NativeRemovals.MuzzleStub = { PlayParticles = function() end }

            RivalsRuntimeBridge.NativeRemovals.ModulePaths = {
                Other = { 'Modules', 'ClientReplicatedClasses', 'ClientFighter', 'ClientItem', 'ItemInterface', 'Other' },
                Scope = { 'Modules', 'ClientReplicatedClasses', 'ClientFighter', 'ClientItem', 'ItemInterface', 'Mouse', 'Scope' },
                Gun = { 'Modules', 'ItemTypes', 'Gun' },
                ClientViewModel = { 'Modules', 'ClientReplicatedClasses', 'ClientFighter', 'ClientItem', 'ClientViewModel' },
                Crosshair = { 'Modules', 'Crosshair' },
                ViewModelAnimator = { 'Modules', 'ClientReplicatedClasses', 'ClientFighter', 'ClientItem', 'ClientViewModel', 'ViewModelAnimator' },
            }

            -- evilrollerplayers's dummy animation track: the animator's real track is swapped for this
            -- while the game's own PlayAnimation runs, so every piece of its bookkeeping
            -- still happens and nothing is actually played.
            RivalsRuntimeBridge.NativeRemovals.AnimationStub = {
                Play = function() end,
                Stop = function() end,
            }

            function RivalsRuntimeBridge.NativeRemovals.RequireModule(key)
                local native = RivalsRuntimeBridge.NativeRemovals
                local cached = native.Modules[key]
                if cached then
                    return cached
                end
                local path = native.ModulePaths[key]
                local cursor = LP:FindFirstChild('PlayerScripts')
                for _, segment in ipairs(path or {}) do
                    cursor = cursor and cursor:FindFirstChild(segment)
                end
                if not cursor then
                    return nil
                end
                local ok, value = pcall(require, cursor)
                if not ok or type(value) ~= 'table' then
                    return nil
                end
                native.Modules[key] = value
                return value
            end

            function RivalsRuntimeBridge.NativeRemovals.ReadConstant(method, index)
                for constantIndex, constantValue in debug.getconstants(method) do
                    if constantIndex == index then
                        return constantValue
                    end
                end
                return nil
            end

            -- ItemInterface.Other.Update writes AimingVignette.ImageTransparency from
            -- (1 - CurrentAimValue). Constant 2 is that literal 1; raising it to 999
            -- pushes the transparency past fully-invisible for every aim value.
            function RivalsRuntimeBridge.NativeRemovals.SetVignetteHidden(hidden)
                local native = RivalsRuntimeBridge.NativeRemovals
                if hidden then
                    if native.Vignette then
                        return
                    end
                    local other = native.RequireModule('Other')
                    local update = other and rawget(other, 'Update') or nil
                    if type(update) ~= 'function' then
                        return
                    end
                    local original = native.ReadConstant(update, 2)
                    if type(original) ~= 'number' then
                        return
                    end
                    debug.setconstant(update, 2, 999)
                    native.Vignette = { method = update, index = 2, value = original }
                else
                    local record = native.Vignette
                    if not record then
                        return
                    end
                    native.Vignette = nil
                    debug.setconstant(record.method, record.index, record.value)
                end
            end

            function RivalsRuntimeBridge.NativeRemovals.SetGunTracersHidden(hidden)
                local native = RivalsRuntimeBridge.NativeRemovals
                if hidden then
                    if native.Tracers then
                        return
                    end
                    local gun = native.RequireModule('Gun')
                    local localTracers = gun and rawget(gun, '_LocalTracers') or nil
                    if type(localTracers) ~= 'function' then
                        return
                    end
                    for index, value in debug.getconstants(localTracers) do
                        if value == '_Tracers' then
                            rawset(gun, native.TracerSentinel, function() end)
                            debug.setconstant(localTracers, index, native.TracerSentinel)
                            native.Tracers = { class = gun, method = localTracers, index = index, value = value }
                            return
                        end
                    end
                else
                    local record = native.Tracers
                    if not record then
                        return
                    end
                    native.Tracers = nil
                    debug.setconstant(record.method, record.index, record.value)
                    rawset(record.class, native.TracerSentinel, nil)
                end
            end

            function RivalsRuntimeBridge.NativeRemovals.SetMuzzleFlashHidden(hidden)
                local native = RivalsRuntimeBridge.NativeRemovals
                if hidden then
                    if native.Muzzle then
                        return
                    end
                    local viewModel = native.RequireModule('ClientViewModel')
                    local muzzleFlash = viewModel and rawget(viewModel, 'MuzzleFlash') or nil
                    if type(muzzleFlash) ~= 'function' then
                        return
                    end
                    local original = debug.getupvalue(muzzleFlash, 2)
                    if type(original) ~= 'table' then
                        return
                    end
                    debug.setupvalue(muzzleFlash, 2, native.MuzzleStub)
                    native.Muzzle = { method = muzzleFlash, value = original }
                else
                    local record = native.Muzzle
                    if not record then
                        return
                    end
                    native.Muzzle = nil
                    debug.setupvalue(record.method, 2, record.value)
                end
            end

            -- evilrollerplayers's NoGameHitsound: the game's own hitmarker sound is played by
            -- ClientViewModel.PlayHitmarkerSound; while Disable Game Sound is on,
            -- that method is swapped for a no-op so only the custom hit sound
            -- plays, and the exact original is put back on revert.
            function RivalsRuntimeBridge.NativeRemovals.SetGameHitsoundDisabled(disabled)
                local native = RivalsRuntimeBridge.NativeRemovals
                if disabled then
                    if native.Hitsound then
                        return
                    end
                    local viewModel = native.RequireModule('ClientViewModel')
                    local method = viewModel and rawget(viewModel, 'PlayHitmarkerSound') or nil
                    if type(method) ~= 'function' then
                        return
                    end
                    rawset(viewModel, 'PlayHitmarkerSound', function() end)
                    native.Hitsound = { class = viewModel, method = method }
                else
                    local record = native.Hitsound
                    if not record then
                        return
                    end
                    native.Hitsound = nil
                    rawset(record.class, 'PlayHitmarkerSound', record.method)
                end
            end

            -- evilrollerplayers wraps Scope.SetActive so the overlay frames are corrected exactly
            -- when the scope turns on, using the scope object's own frame fields.
            function RivalsRuntimeBridge.NativeRemovals.EnsureScopeHook()
                local scope = RivalsRuntimeBridge.NativeRemovals.Scope
                if scope.Restore ~= nil or not (scope.OverlayHidden or scope.ReticleHidden) then
                    return
                end
                local scopeClass = RivalsRuntimeBridge.NativeRemovals.RequireModule('Scope')
                local setActive = scopeClass and rawget(scopeClass, 'SetActive') or nil
                if type(setActive) ~= 'function' then
                    return
                end
                local wrapped = function(scopeObject, active)
                    coroutine.wrap(setActive)(scopeObject, active)
                    if not rawget(scopeObject, '_is_scope_active') then
                        return
                    end
                    if scope.OverlayDirty then
                        local visible = not scope.OverlayHidden
                        local circleFrame = rawget(scopeObject, 'CircleFrame')
                        local blurFrame = rawget(scopeObject, 'BlurFrame')
                        if circleFrame then
                            circleFrame.Visible = visible
                        end
                        if blurFrame then
                            blurFrame.Visible = visible
                        end
                    end
                    if scope.ReticleDirty then
                        local reticleContainer = rawget(scopeObject, 'ReticleContainer')
                        if reticleContainer then
                            reticleContainer.Visible = not scope.ReticleHidden
                        end
                    end
                end
                rawset(scopeClass, 'SetActive', wrapped)
                scope.Restore = { class = scopeClass, original = setActive }
            end

            function RivalsRuntimeBridge.NativeRemovals.RevertScopeHook()
                local scope = RivalsRuntimeBridge.NativeRemovals.Scope
                local restore = scope.Restore
                if not restore then
                    return
                end
                scope.Restore = nil
                rawset(restore.class, 'SetActive', restore.original)
            end

            function RivalsRuntimeBridge.NativeRemovals.SetScopeOverlayHidden(hidden)
                local scope = RivalsRuntimeBridge.NativeRemovals.Scope
                scope.OverlayHidden = hidden
                scope.OverlayDirty = true
                RivalsRuntimeBridge.NativeRemovals.EnsureScopeHook()
            end

            function RivalsRuntimeBridge.NativeRemovals.SetScopeReticleHidden(hidden)
                local scope = RivalsRuntimeBridge.NativeRemovals.Scope
                scope.ReticleHidden = hidden
                scope.ReticleDirty = true
                RivalsRuntimeBridge.NativeRemovals.EnsureScopeHook()
            end

            -- evilrollerplayers wraps the game's own Crosshair._Update and re-asserts visibility
            -- immediately after the native draw, so the native path keeps ownership and
            -- there is nothing to scan. The instance field is erased in the reference
            -- decompile; build 1035's _Update reads it as 'Frame', and its own constants
            -- name Foreground / Background / Hitmarker in the same order evilrollerplayers writes.
            function RivalsRuntimeBridge.NativeRemovals.EnsureCrosshairHook()
                local crosshair = RivalsRuntimeBridge.NativeRemovals.Crosshair
                if crosshair.Restore ~= nil then
                    return
                end
                if crosshair.CrosshairVisible == nil and crosshair.HitmarkerVisible == nil then
                    return
                end
                local class = RivalsRuntimeBridge.NativeRemovals.RequireModule('Crosshair')
                local update = class and rawget(class, '_Update') or nil
                if type(update) ~= 'function' then
                    return
                end
                local wrapped = function(instance, ...)
                    coroutine.wrap(update)(instance, ...)
                    if rawget(instance, '_destroyed') then
                        return
                    end
                    local frame = rawget(instance, 'Frame')
                    if typeof(frame) ~= 'Instance' then
                        return
                    end
                    local visible = crosshair.CrosshairVisible
                    if visible ~= nil then
                        local foreground = frame:FindFirstChild('Foreground')
                        local background = frame:FindFirstChild('Background')
                        if foreground then
                            foreground.Visible = visible
                        end
                        if background then
                            background.Visible = visible
                        end
                    end
                    local hitmarker = crosshair.HitmarkerVisible
                    if hitmarker ~= nil then
                        local marker = frame:FindFirstChild('Hitmarker')
                        if marker then
                            marker.Visible = hitmarker
                        end
                    end
                end
                rawset(class, '_Update', wrapped)
                crosshair.Restore = { class = class, original = update }
            end

            -- The wrapper alone is not enough: the game's _Update is task.defer'd from
            -- state changes only (SetType / SetVisible / SetSpacing / SetTransparency /
            -- SetAppearance), so a crosshair already on screen never updates again and
            -- the wrapper never gets a chance to hide it. evilrollerplayers pairs the hook with a
            -- registry of every local item's Mouse.MouseCrosshair.Crosshair object and
            -- writes those frames directly on toggle; new items need no direct write
            -- because their creation Refresh runs _Update through the wrapper. The walk
            -- happens at toggle time only, so there is no recurring cost.
            function RivalsRuntimeBridge.NativeRemovals.EachItemCrosshair(callback)
                local fighter = ResolveLocalFighter()
                for _, item in pairs(type(fighter) == 'table' and rawget(fighter, 'Items') or {}) do
                    local interface = type(item) == 'table' and rawget(item, 'ItemInterface') or nil
                    local mouse = type(interface) == 'table' and rawget(interface, 'Mouse') or nil
                    local mouseCrosshair = type(mouse) == 'table' and rawget(mouse, 'MouseCrosshair') or nil
                    local object = type(mouseCrosshair) == 'table' and rawget(mouseCrosshair, 'Crosshair') or nil
                    if type(object) == 'table' and not rawget(object, '_destroyed') then
                        callback(object)
                    end
                end
            end

            -- evilrollerplayers's IsCrosshairActive: true while the equipped item resolves to a
            -- live native crosshair object. Equipped truth is the fighter's own
            -- 'EquippedItem' field (the ClientItem table), the same read evilrollerplayers's item
            -- layer uses. NOT fighter:Get('EquippedItem') - the replicated Data only
            -- carries EquippedItemID strings, so Get returns nil and the gate would
            -- never open (live-proven with Fists equipped).
            function RivalsRuntimeBridge.NativeRemovals.IsNativeCrosshairActive()
                local fighter = ResolveLocalFighter()
                if type(fighter) ~= 'table' then
                    return false
                end
                local equipped = rawget(fighter, 'EquippedItem')
                if type(equipped) ~= 'table' then
                    return false
                end
                local interface = rawget(equipped, 'ItemInterface')
                local mouse = type(interface) == 'table' and rawget(interface, 'Mouse') or nil
                local mouseCrosshair = type(mouse) == 'table' and rawget(mouse, 'MouseCrosshair') or nil
                local object = type(mouseCrosshair) == 'table' and rawget(mouseCrosshair, 'Crosshair') or nil
                return type(object) == 'table' and rawget(object, '_destroyed') ~= true
            end

            function RivalsRuntimeBridge.NativeRemovals.ApplyCrosshairFrames()
                local crosshair = RivalsRuntimeBridge.NativeRemovals.Crosshair
                RivalsRuntimeBridge.NativeRemovals.EachItemCrosshair(function(object)
                    local frame = rawget(object, 'Frame')
                    if typeof(frame) ~= 'Instance' then
                        return
                    end
                    if crosshair.CrosshairVisible ~= nil then
                        local foreground = frame:FindFirstChild('Foreground')
                        local background = frame:FindFirstChild('Background')
                        if foreground then
                            foreground.Visible = crosshair.CrosshairVisible
                        end
                        if background then
                            background.Visible = crosshair.CrosshairVisible
                        end
                    end
                    if crosshair.HitmarkerVisible ~= nil then
                        local marker = frame:FindFirstChild('Hitmarker')
                        if marker then
                            marker.Visible = crosshair.HitmarkerVisible
                        end
                    end
                end)
            end

            -- Restoring replays the game's own _Update once per live crosshair (identity
            -- 2, like evilrollerplayers) so the native path repaints immediately instead of on its
            -- next organic redraw. Uses the stored original while the hook still holds
            -- it; if the hook never installed, nothing was hidden and this no-ops.
            function RivalsRuntimeBridge.NativeRemovals.RevertCrosshairFrames()
                local restore = RivalsRuntimeBridge.NativeRemovals.Crosshair.Restore
                local original = restore and restore.original or nil
                if type(original) ~= 'function' then
                    return
                end
                RivalsRuntimeBridge.NativeRemovals.EachItemCrosshair(function(object)
                    task.spawn(function()
                        local previousIdentity = type(getthreadidentity) == 'function' and getthreadidentity() or nil
                        if type(setthreadidentity) == 'function' then
                            pcall(setthreadidentity, 2)
                        end
                        coroutine.wrap(original)(object)
                        if previousIdentity ~= nil and type(setthreadidentity) == 'function' then
                            pcall(setthreadidentity, previousIdentity)
                        end
                    end)
                end)
            end

            function RivalsRuntimeBridge.NativeRemovals.RevertCrosshairHook()
                local crosshair = RivalsRuntimeBridge.NativeRemovals.Crosshair
                local restore = crosshair.Restore
                if not restore then
                    return
                end
                crosshair.Restore = nil
                rawset(restore.class, '_Update', restore.original)
            end

            function RivalsRuntimeBridge.NativeRemovals.SyncCrosshairHook()
                local crosshair = RivalsRuntimeBridge.NativeRemovals.Crosshair
                if crosshair.CrosshairVisible == nil and crosshair.HitmarkerVisible == nil then
                    RivalsRuntimeBridge.NativeRemovals.RevertCrosshairHook()
                    return
                end
                RivalsRuntimeBridge.NativeRemovals.EnsureCrosshairHook()
            end

            function RivalsRuntimeBridge.NativeRemovals.SetNativeCrosshairHidden(hidden)
                local crosshair = RivalsRuntimeBridge.NativeRemovals.Crosshair
                -- Tri-state: false = force-hide, nil = leave the native value alone.
                -- NOT `hidden and false or nil` - with false as the truthy arm that
                -- idiom collapses to nil for BOTH inputs and the setter never arms.
                local target = nil
                if hidden then
                    target = false
                end
                if crosshair.CrosshairVisible == target then
                    return
                end
                crosshair.CrosshairVisible = target
                if target == nil then
                    RivalsRuntimeBridge.NativeRemovals.RevertCrosshairFrames()
                    -- The replay repaints hitmarkers too; re-assert the half still hidden,
                    -- exactly like the wrapper does after a native update.
                    if crosshair.HitmarkerVisible ~= nil then
                        RivalsRuntimeBridge.NativeRemovals.ApplyCrosshairFrames()
                    end
                else
                    RivalsRuntimeBridge.NativeRemovals.ApplyCrosshairFrames()
                end
                RivalsRuntimeBridge.NativeRemovals.SyncCrosshairHook()
            end

            function RivalsRuntimeBridge.NativeRemovals.SetHitmarkerHidden(hidden)
                local crosshair = RivalsRuntimeBridge.NativeRemovals.Crosshair
                -- Tri-state: false = force-hide, nil = leave the native value alone.
                -- NOT `hidden and false or nil` - with false as the truthy arm that
                -- idiom collapses to nil for BOTH inputs and the setter never arms.
                local target = nil
                if hidden then
                    target = false
                end
                if crosshair.HitmarkerVisible == target then
                    return
                end
                crosshair.HitmarkerVisible = target
                if target == nil then
                    RivalsRuntimeBridge.NativeRemovals.RevertCrosshairFrames()
                    -- The replay repaints the whole frame; re-assert the half still hidden,
                    -- exactly like the wrapper does after a native update.
                    if crosshair.CrosshairVisible ~= nil then
                        RivalsRuntimeBridge.NativeRemovals.ApplyCrosshairFrames()
                    end
                else
                    RivalsRuntimeBridge.NativeRemovals.ApplyCrosshairFrames()
                end
                RivalsRuntimeBridge.NativeRemovals.SyncCrosshairHook()
            end

            -- evilrollerplayers gates the animation filters on the animator's own owner chain, because a
            -- class-level replacement sees every player's animator, not just ours.
            function RivalsRuntimeBridge.NativeRemovals.IsLocalAnimator(animator)
                local viewModel = type(animator) == 'table' and rawget(animator, 'ClientViewModel') or nil
                local item = type(viewModel) == 'table' and rawget(viewModel, 'ClientItem') or nil
                local fighter = type(item) == 'table' and rawget(item, 'ClientFighter') or nil
                return type(fighter) == 'table' and rawget(fighter, 'IsLocalPlayer') == true
            end

            -- evilrollerplayers's AnimationDisabler. It does not stop a track after the fact: it swaps
            -- the animator's own track for a no-op stub, runs the game's real PlayAnimation
            -- so all of its bookkeeping still happens, then puts the real track back. evilrollerplayers
            -- reaches PlayAnimation through a call redirect whose target list is erased in
            -- the decompile; replacing the class method directly is live-verified on this
            -- build to intercept every call (129 in 7s, including remote players'), which is
            -- the same technique their Crosshair._Update and Scope.SetActive hooks use.
            function RivalsRuntimeBridge.NativeRemovals.EnsureAnimationHook()
                local native = RivalsRuntimeBridge.NativeRemovals
                local animation = native.Animation
                if animation.Restore ~= nil then
                    return
                end
                local class = native.RequireModule('ViewModelAnimator')
                local original = class and rawget(class, 'PlayAnimation') or nil
                if type(original) ~= 'function' then
                    return
                end
                local wrapped = function(animator, animationKey, ...)
                    if not native.IsLocalAnimator(animator)
                        or not RivalsModsState.ShouldSuppressViewmodelAnimation(animator, animationKey) then
                        return original(animator, animationKey, ...)
                    end
                    local tracks = rawget(animator, '_animation_tracks')
                    local existing = type(tracks) == 'table' and tracks[animationKey] or nil
                    if existing == nil then
                        return
                    end
                    tracks[animationKey] = native.AnimationStub
                    local ok, err = pcall(original, animator, animationKey, ...)
                    tracks[animationKey] = existing
                    if not ok then
                        error(err, 0)
                    end
                end
                rawset(class, 'PlayAnimation', wrapped)
                animation.Restore = { class = class, original = original }
            end

            function RivalsRuntimeBridge.NativeRemovals.RevertAnimationHook()
                local animation = RivalsRuntimeBridge.NativeRemovals.Animation
                local restore = animation.Restore
                if not restore then
                    return
                end
                animation.Restore = nil
                rawset(restore.class, 'PlayAnimation', restore.original)
            end

            function RivalsRuntimeBridge.NativeRemovals.SyncAnimationHook()
                local native = RivalsRuntimeBridge.NativeRemovals
                if native.ReadToggle('P1S31T2') or native.ReadToggle('P1S31T3')
                    or native.ReadToggle('P1S31T4') or native.ReadToggle('P1S31T5') then
                    native.EnsureAnimationHook()
                else
                    native.RevertAnimationHook()
                end
            end

            function RivalsRuntimeBridge.NativeRemovals.ReadToggle(optionId)
                return Toggles and Toggles[optionId] and Toggles[optionId].Value == true
            end

            function RivalsRuntimeBridge.NativeRemovals.RefreshAll()
                local native = RivalsRuntimeBridge.NativeRemovals
                local caps = __evilrollerplayers_hook_genv.evilrollerplayersHailCaps
                -- The vignette/tracer/muzzle removals call debug.getconstants /
                -- debug.getupvalue with no guard of their own; the gate both notifies
                -- (once, at enable) and keeps them off executors without the surface.
                native.SetVignetteHidden(native.ReadToggle('P1S27T3')
                    and caps.gate('No ADS Vignette', 'debug.getconstants', 'debug.setconstant'))
                native.SetScopeOverlayHidden(native.ReadToggle('P1S27T4'))
                native.SetScopeReticleHidden(native.ReadToggle('P1S27T5'))
                native.SetGunTracersHidden(native.ReadToggle('P1S27T6')
                    and caps.gate('No Gun Tracers', 'debug.getconstants', 'debug.setconstant'))
                native.SetMuzzleFlashHidden(native.ReadToggle('P1S27T7')
                    and caps.gate('No Muzzle Flash', 'debug.getupvalue', 'debug.setupvalue'))
                native.SetHitmarkerHidden(native.ReadToggle('P1S27T8'))
                native.SetGameHitsoundDisabled(native.ReadToggle('P1S15T3'))
                RivalsRuntimeBridge.ReplicationRemovals.RefreshAll()
            end

            function RivalsRuntimeBridge.NativeRemovals.Destroy()
                local native = RivalsRuntimeBridge.NativeRemovals
                native.SetVignetteHidden(false)
                native.SetGunTracersHidden(false)
                native.SetMuzzleFlashHidden(false)
                native.SetGameHitsoundDisabled(false)
                native.RevertScopeHook()
                native.RevertCrosshairFrames()
                native.RevertCrosshairHook()
                native.RevertAnimationHook()
                RivalsRuntimeBridge.ReplicationRemovals.Destroy()
                RivalsRuntimeBridge.ReplicateHook.Destroy()
                local scope = native.Scope
                scope.OverlayHidden = false
                scope.ReticleHidden = false
                scope.OverlayDirty = false
                scope.ReticleDirty = false
                local crosshair = native.Crosshair
                crosshair.CrosshairVisible = nil
                crosshair.HitmarkerVisible = nil
                native.Modules = {}
            end

            -- evilrollerplayers's replication interception layer (their ReplicateHook, reference
            -- lines 71466-71615). It replaces ReplicatedController._ObjectChanged with a
            -- wrapper that normalizes every replicated call into one packet, offers that
            -- packet to handlers registered per outer enum token, and only lets the
            -- native path run when no handler set packet.block.
            --
            -- Blocking is the entire point. No Flashbang and No Burn Effect are the two
            -- removals evilrollerplayers implements by refusing the packet outright, which is not
            -- reachable from an OnClientEvent listener: a RemoteEvent connection cannot
            -- stop the game's own handler from running.
            RivalsRuntimeBridge.ReplicateHook = {
                BindingsByEnum = {},
                Restore = nil,
            }

            function RivalsRuntimeBridge.ReplicateHook.ResolveController()
                local playerScripts = LP:FindFirstChild('PlayerScripts')
                local modules = playerScripts and playerScripts:FindFirstChild('Modules')
                local module = modules and modules:FindFirstChild('ReplicatedController')
                if not module then
                    return nil
                end
                local ok, controller = pcall(require, module)
                if not ok or type(controller) ~= 'table' then
                    return nil
                end
                return controller
            end

            -- Bindings are keyed by the ENCODED enum token, because that is what arrives
            -- on the wire. Reserving before the game's enum builder has finished would
            -- key the binding under a token that never matches, so callers must reserve
            -- after the startup barrier.
            function RivalsRuntimeBridge.ReplicateHook.Reserve(enumNames)
                local hook = RivalsRuntimeBridge.ReplicateHook
                local enumLibrary = ResolveEnumLibrary()
                if not enumLibrary or type(enumLibrary.ToEnum) ~= 'function' then
                    return nil
                end
                local tokens = {}
                for _, enumName in ipairs(enumNames) do
                    local ok, token = pcall(enumLibrary.ToEnum, enumLibrary, enumName)
                    if not ok or type(token) ~= 'string' then
                        return nil
                    end
                    tokens[#tokens + 1] = token
                end

                local binding = { enabled = false, handler = nil, tokens = tokens }

                function binding:SetHandler(handler)
                    self.handler = handler
                end

                function binding:SetEnabled(enabled)
                    self.enabled = enabled and true or false
                    if self.enabled then
                        RivalsRuntimeBridge.ReplicateHook.Load()
                    end
                end

                function binding:Destroy()
                    self.handler = nil
                    self.enabled = false
                    for _, token in ipairs(self.tokens) do
                        local list = hook.BindingsByEnum[token]
                        if list then
                            for index = #list, 1, -1 do
                                if list[index] == self then
                                    table.remove(list, index)
                                end
                            end
                            if #list == 0 then
                                hook.BindingsByEnum[token] = nil
                            end
                        end
                    end
                end

                for _, token in ipairs(tokens) do
                    local list = hook.BindingsByEnum[token]
                    if not list then
                        list = {}
                        hook.BindingsByEnum[token] = list
                    end
                    table.insert(list, binding)
                end
                return binding
            end

            function RivalsRuntimeBridge.ReplicateHook.Load()
                local hook = RivalsRuntimeBridge.ReplicateHook
                if hook.Restore ~= nil then
                    return true
                end
                local controller = hook.ResolveController()
                local original = controller and rawget(controller, '_ObjectChanged') or nil
                if type(original) ~= 'function' then
                    return false
                end
                local enumLibrary = ResolveEnumLibrary()
                if not enumLibrary or type(enumLibrary.FromEnum) ~= 'function' then
                    return false
                end
                local bindingsByEnum = hook.BindingsByEnum

                -- evilrollerplayers's wrapper is declared (self, objectId, enumToken, ...). Their own
                -- Crosshair._Update and Scope.SetActive hooks both call the native path
                -- with the complete argument list, and _ObjectChanged is declared vararg
                -- with no named parameters, so the full tuple is the only call-through
                -- that stays correct whether the game invokes it with a colon or a dot.
                -- The leading-table test picks the same objectId/enum evilrollerplayers reads.
                local wrapped = function(...)
                    local packed = table.pack(...)
                    local offset = (type(packed[1]) == 'table') and 1 or 0
                    local objectId = packed[offset + 1]
                    local token = packed[offset + 2]
                    local bindings = type(token) == 'string' and bindingsByEnum[token] or nil
                    if bindings == nil or type(objectId) ~= 'string' then
                        return (coroutine.wrap(original)(...))
                    end

                    local args = { n = math.max(packed.n - offset - 2, 0) }
                    for index = 1, args.n do
                        args[index] = packed[offset + 2 + index]
                    end
                    local decoded
                    local decodeOk, decodeValue = pcall(enumLibrary.FromEnum, enumLibrary, token)
                    if decodeOk then
                        decoded = decodeValue
                    end
                    local packet = {
                        block = false,
                        objectId = objectId,
                        enumName = decoded,
                        args = args,
                    }

                    local identity
                    if type(getthreadidentity) == 'function' then
                        identity = getthreadidentity()
                    end
                    if type(setthreadidentity) == 'function' then
                        pcall(setthreadidentity, 8)
                    end
                    for _, binding in ipairs(bindings) do
                        if binding.enabled and binding.handler then
                            -- evilrollerplayers calls the handler raw. A throw here would surface
                            -- inside the game's own replication dispatch, so the call is
                            -- guarded the same way the ported scope wrapper is.
                            pcall(binding.handler, packet)
                            if packet.block then
                                break
                            end
                        end
                    end
                    if identity ~= nil and type(setthreadidentity) == 'function' then
                        pcall(setthreadidentity, identity)
                    end

                    if packet.block then
                        return
                    end
                    return (coroutine.wrap(original)(...))
                end

                rawset(controller, '_ObjectChanged', wrapped)
                hook.Restore = { controller = controller, original = original }
                return true
            end

            function RivalsRuntimeBridge.ReplicateHook.Revert()
                local hook = RivalsRuntimeBridge.ReplicateHook
                local restore = hook.Restore
                if not restore then
                    return
                end
                hook.Restore = nil
                rawset(restore.controller, '_ObjectChanged', restore.original)
            end

            -- evilrollerplayers leaves the wrapper installed until its trove is destroyed. Every
            -- replicated packet pays for a coroutine while it is up, so reverting as soon
            -- as no binding is enabled keeps it off the replication path for the rest of
            -- the session once the toggle goes back off.
            function RivalsRuntimeBridge.ReplicateHook.RevertIfIdle()
                local hook = RivalsRuntimeBridge.ReplicateHook
                if hook.Restore == nil then
                    return
                end
                for _, list in pairs(hook.BindingsByEnum) do
                    for _, binding in ipairs(list) do
                        if binding.enabled then
                            return
                        end
                    end
                end
                hook.Revert()
            end

            function RivalsRuntimeBridge.ReplicateHook.Destroy()
                local hook = RivalsRuntimeBridge.ReplicateHook
                hook.Revert()
                hook.BindingsByEnum = {}
            end

            -- evilrollerplayers's decode() on a packet argument. Handlers receive raw encoded enum
            -- tokens and compare them by name.
            function RivalsRuntimeBridge.ReplicateHook.DecodeArg(value)
                if type(value) ~= 'string' then
                    return nil
                end
                local enumLibrary = ResolveEnumLibrary()
                if not enumLibrary or type(enumLibrary.FromEnum) ~= 'function' then
                    return nil
                end
                local ok, name = pcall(enumLibrary.FromEnum, enumLibrary, value)
                if not ok or type(name) ~= 'string' then
                    return nil
                end
                return name
            end

            -- No Flashbang / No Burn Effect are the two removals evilrollerplayers implements by
            -- refusing the replicated packet instead of hiding what it drew. Flashbang is
            -- item-scoped, so its effect token sits at args[2] behind ItemChanged; burn is
            -- entity-scoped, so its token is args[1] behind EntityChanged and is gated on
            -- the packet targeting the local entity's own ObjectID.
            RivalsRuntimeBridge.ReplicationRemovals = {
                Flashbang = nil,
                Burn = nil,
            }

            function RivalsRuntimeBridge.ReplicationRemovals.EnsureBindings()
                local removals = RivalsRuntimeBridge.ReplicationRemovals
                local hook = RivalsRuntimeBridge.ReplicateHook
                if not removals.Flashbang then
                    local binding = hook.Reserve({ 'ItemChanged' })
                    if binding then
                        binding:SetHandler(function(packet)
                            if hook.DecodeArg(packet.args[2]) == 'BlindEffect' then
                                packet.block = true
                            end
                        end)
                        removals.Flashbang = binding
                    end
                end
                if not removals.Burn then
                    local binding = hook.Reserve({ 'EntityChanged' })
                    if binding then
                        binding:SetHandler(function(packet)
                            if hook.DecodeArg(packet.args[1]) ~= 'BurnEffect' then
                                return
                            end
                            local fighter = ResolveLocalFighter()
                            if not fighter then
                                return
                            end
                            -- evilrollerplayers gates on their fighter state's Entity.ObjectID. On this
                            -- build the Entity object carries no ObjectID at all (verified
                            -- absent through both raw and ordinary reads), so that literal
                            -- read is nil and would never match - the same dead-branch as
                            -- the Bullet Tracers defect. Live EntityChanged packets address
                            -- the fighter's own Data.ObjectID instead: the EntityChanged-
                            -- nested FinisherEffect owner resolved through Data.ObjectID and
                            -- never through Entity.ObjectID. Prefer evilrollerplayers's field if a build
                            -- ever supplies it, then fall back to the one that exists.
                            local entity = rawget(fighter, 'Entity')
                            local objectId = type(entity) == 'table' and rawget(entity, 'ObjectID') or nil
                            objectId = objectId
                                or RivalsRuntimeBridge.CombatFeedback.ResolveFighterObjectId(fighter)
                            if objectId == nil or objectId ~= packet.objectId then
                                return
                            end
                            packet.block = true
                        end)
                        removals.Burn = binding
                    end
                end
            end

            function RivalsRuntimeBridge.ReplicationRemovals.RefreshAll()
                local removals = RivalsRuntimeBridge.ReplicationRemovals
                local native = RivalsRuntimeBridge.NativeRemovals
                local wantFlash = native.ReadToggle('P1S27T1')
                local wantBurn = native.ReadToggle('P1S27T2')
                if wantFlash or wantBurn then
                    removals.EnsureBindings()
                end
                if removals.Flashbang then
                    removals.Flashbang:SetEnabled(wantFlash)
                end
                if removals.Burn then
                    removals.Burn:SetEnabled(wantBurn)
                end
                RivalsRuntimeBridge.ReplicateHook.RevertIfIdle()
            end

            function RivalsRuntimeBridge.ReplicationRemovals.Destroy()
                local removals = RivalsRuntimeBridge.ReplicationRemovals
                if removals.Flashbang then
                    removals.Flashbang:Destroy()
                    removals.Flashbang = nil
                end
                if removals.Burn then
                    removals.Burn:Destroy()
                    removals.Burn = nil
                end
            end

            RivalsRuntimeBridge.Movement = {
                Character = nil,
                Humanoid = nil,
                RootPart = nil,
                CollidableParts = {},
                NoclipCharacter = nil,
                NoclipConnections = nil,
                NoclipEnabled = false,
                Flight = nil,
                MechanicsController = nil,
                PlayerModule = nil,
                WalkSpeedHookLoaded = false,
                WalkSpeedHookGetter = nil,
                WalkSpeedHookUpvalueIndex = nil,
                WalkSpeedHookOldUpvalue = nil,
                WalkMultiplierEnabled = false,
                WalkMultiplier = 1,
                SlidingMultiplierEnabled = false,
                SlidingMultiplier = 1,
                JumpPowerHookLoaded = false,
                JumpPowerHookDestroyed = false,
                JumpPowerEnabled = false,
                JumpPowerMultiplier = 1,
                LongJumpPressed = false,
            }

            function RivalsRuntimeBridge.Movement.ReadToggle(optionId)
                return Toggles and Toggles[optionId] and Toggles[optionId].Value == true
            end

            function RivalsRuntimeBridge.Movement.ReadNumber(optionId, fallback)
                local option = Options and Options[optionId]
                return option and type(option.Value) == 'number' and option.Value or fallback
            end

            function RivalsRuntimeBridge.Movement.IsKeyActive(optionId)
                local option = Options and Options[optionId]
                if option and type(option.GetState) == 'function' then
                    return option:GetState()
                end
                return true
            end

            -- evilrollerplayers's JumpPower injection [91383]: replace the first constants-table upvalue of a
            -- target function with a proxy that multiplies BASE_JUMPPOWER reads. The 'meow\0d67'
            -- marker key is evilrollerplayers's own-proxy detector: a stale proxy left by an earlier run
            -- answers the marker with its wrapped original, so the scan unwraps instead of
            -- double-wrapping. A destroyed hook self-heals: the proxy restores the original
            -- upvalue on its next read instead of being torn down eagerly.
            function RivalsRuntimeBridge.Movement.ReplaceJumpPowerConstants(target)
                local movement = RivalsRuntimeBridge.Movement
                for index, value in pairs(debug.getupvalues(target)) do
                    if type(value) == 'table' then
                        local metatable = getmetatable(value)
                        local metaIndex = type(metatable) == 'table'
                            and rawget(metatable, '__index') or nil
                        local original = nil
                        if type(metaIndex) == 'function' then
                            local ok, wrapped = pcall(function()
                                return value['meow\0d67']
                            end)
                            original = ok and wrapped or nil
                        elseif rawget(value, 'BASE_JUMPPOWER') ~= nil then
                            original = value
                        end
                        if original ~= nil then
                            local upvalueIndex = index
                            debug.setupvalue(target, upvalueIndex, setmetatable({}, {
                                __index = function(_, key)
                                    if key == 'meow\0d67' then
                                        return original
                                    end
                                    if movement.JumpPowerHookDestroyed then
                                        debug.setupvalue(target, upvalueIndex, original)
                                        return rawget(original, key)
                                    end
                                    if key ~= 'BASE_JUMPPOWER' then
                                        return rawget(original, key)
                                    end
                                    return rawget(original, 'BASE_JUMPPOWER')
                                        * (movement.JumpPowerEnabled and movement.JumpPowerMultiplier or 1)
                                end,
                            }))
                            break
                        end
                    end
                end
            end

            -- evilrollerplayers's JumpPower hook [91333]: proxy BASE_JUMPPOWER wherever the game reads it -
            -- MechanicsController._HookFighter plus the LocalFighter EntityAdded callback that
            -- owns CustomGravity (and that callback's first activated proto). evilrollerplayers only builds
            -- this with a fighter present, so a nil LocalFighter defers instead of loading.
            function RivalsRuntimeBridge.Movement.AttemptLoadJumpPowerHook()
                local movement = RivalsRuntimeBridge.Movement
                if movement.JumpPowerHookLoaded then
                    return true
                end
                if type(debug.getupvalues) ~= 'function' or type(debug.setupvalue) ~= 'function'
                    or type(debug.getconstants) ~= 'function' or type(debug.getprotos) ~= 'function'
                    or type(debug.getproto) ~= 'function' then
                    return false
                end
                local mechanics = movement.ResolveMechanicsController()
                if type(mechanics) ~= 'table' then
                    return false
                end
                local metatable = getmetatable(mechanics)
                local classIndex = type(metatable) == 'table' and rawget(metatable, '__index') or nil
                local hookFighter = type(classIndex) == 'table' and rawget(classIndex, '_HookFighter') or nil
                if type(hookFighter) ~= 'function' then
                    return false
                end
                local localFighter = rawget(mechanics, 'LocalFighter')
                if localFighter == nil then
                    return false
                end
                movement.ReplaceJumpPowerConstants(hookFighter)
                local entityAdded = rawget(localFighter, 'EntityAdded')
                local handler = type(entityAdded) == 'table' and rawget(entityAdded, '_handlerListHead') or nil
                local entityCallback = nil
                while type(handler) == 'table' and entityCallback == nil do
                    local fn = rawget(handler, '_fn')
                    if type(fn) == 'function' then
                        for _, constant in pairs(debug.getconstants(fn)) do
                            if constant == 'CustomGravity' then
                                entityCallback = fn
                                break
                            end
                        end
                    end
                    handler = rawget(handler, '_next')
                end
                if entityCallback == nil then
                    LP:Kick('JumpPower error: ent')
                    return false
                end
                movement.ReplaceJumpPowerConstants(entityCallback)
                for protoIndex in pairs(debug.getprotos(entityCallback)) do
                    local activated = debug.getproto(entityCallback, protoIndex, true)
                    local instance = type(activated) == 'table' and activated[1] or nil
                    if instance ~= nil then
                        movement.ReplaceJumpPowerConstants(instance)
                    end
                end
                movement.JumpPowerHookDestroyed = false
                movement.JumpPowerHookLoaded = true
                return true
            end

            function RivalsRuntimeBridge.Movement.ClearNoclipCharacter()
                local movement = RivalsRuntimeBridge.Movement
                if movement.NoclipConnections then
                    for _, connection in ipairs(movement.NoclipConnections) do
                        connection:Disconnect()
                    end
                end
                movement.NoclipConnections = nil
                movement.NoclipCharacter = nil
                table.clear(movement.CollidableParts)
            end

            -- evilrollerplayers's Noclip registry [139965]: record only parts that were CanCollide at bind or
            -- add time, keep it current through DescendantAdded/DescendantRemoving, and restore by
            -- setting exactly those parts back to true.
            function RivalsRuntimeBridge.Movement.BindNoclipCharacter(character)
                local movement = RivalsRuntimeBridge.Movement
                movement.ClearNoclipCharacter()
                movement.NoclipCharacter = character
                for _, descendant in ipairs(character:GetDescendants()) do
                    if descendant:IsA('BasePart') and descendant.CanCollide then
                        movement.CollidableParts[descendant] = true
                    end
                end
                movement.NoclipConnections = {
                    character.DescendantAdded:Connect(function(descendant)
                        if descendant:IsA('BasePart') and descendant.CanCollide then
                            movement.CollidableParts[descendant] = true
                        end
                    end),
                    character.DescendantRemoving:Connect(function(descendant)
                        if descendant:IsA('BasePart') then
                            movement.CollidableParts[descendant] = nil
                        end
                    end),
                }
            end

            function RivalsRuntimeBridge.Movement.SetNoclipEnabled(enabled)
                local movement = RivalsRuntimeBridge.Movement
                if movement.NoclipEnabled and not enabled then
                    for part in pairs(movement.CollidableParts) do
                        part.CanCollide = true
                    end
                end
                movement.NoclipEnabled = enabled == true
            end

            function RivalsRuntimeBridge.Movement.DestroyFlight()
                local movement = RivalsRuntimeBridge.Movement
                local flight = movement.Flight
                movement.Flight = nil
                if flight then
                    pcall(function() flight.Velocity:Destroy() end)
                    pcall(function() flight.Attachment:Destroy() end)
                end
            end

            function RivalsRuntimeBridge.Movement.ResolveCharacter()
                local movement = RivalsRuntimeBridge.Movement
                local character = LP.Character
                local humanoid = character and character:FindFirstChildOfClass('Humanoid') or nil
                local rootPart = character and character:FindFirstChild('HumanoidRootPart') or nil
                if character ~= movement.Character or humanoid ~= movement.Humanoid or rootPart ~= movement.RootPart then
                    movement.ClearNoclipCharacter()
                    movement.DestroyFlight()
                    movement.Character = character
                    movement.Humanoid = humanoid
                    movement.RootPart = rootPart
                    movement.LongJumpPressed = false
                end
                return character, humanoid, rootPart
            end

            function RivalsRuntimeBridge.Movement.ResolveControlsMoveVector()
                local movement = RivalsRuntimeBridge.Movement
                if movement.PlayerModule == nil then
                    local playerScripts = LP:FindFirstChild('PlayerScripts')
                    local moduleScript = playerScripts and playerScripts:FindFirstChild('PlayerModule')
                    if moduleScript then
                        local ok, playerModule = pcall(require, moduleScript)
                        if ok and type(playerModule) == 'table'
                            and type(playerModule.GetControls) == 'function' then
                            movement.PlayerModule = playerModule
                        end
                    end
                end
                local playerModule = movement.PlayerModule
                if playerModule then
                    local ok, moveVector = pcall(function()
                        return playerModule:GetControls():GetMoveVector()
                    end)
                    if ok and typeof(moveVector) == 'Vector3' then
                        return moveVector
                    end
                end
                return Vector3.zero
            end

            -- evilrollerplayers's Flight input [103480]: W/S ride the flattened look vector, A/D the raw
            -- camera RightVector, Space rises, LeftControl/LeftShift descend; without a keyboard
            -- the PlayerModule move vector rides the unflattened look/right vectors. The sum is
            -- returned unnormalized - UpdateFlight normalizes, like evilrollerplayers's Update does.
            function RivalsRuntimeBridge.Movement.FlightMoveDirection()
                local movement = RivalsRuntimeBridge.Movement
                if UserInputService:GetFocusedTextBox() then
                    return Vector3.zero
                end
                local direction = Vector3.zero
                local cframe = Workspace.CurrentCamera.CFrame
                if UserInputService.KeyboardEnabled then
                    local look = cframe.LookVector
                    local flatLook = Vector3.new(look.X, 0, look.Z)
                    if flatLook.Magnitude > 0 then
                        flatLook = flatLook.Unit
                    end
                    if UserInputService:IsKeyDown(Enum.KeyCode.W) then
                        direction = direction + flatLook
                    end
                    if UserInputService:IsKeyDown(Enum.KeyCode.A) then
                        direction = direction - cframe.RightVector
                    end
                    if UserInputService:IsKeyDown(Enum.KeyCode.S) then
                        direction = direction - flatLook
                    end
                    if UserInputService:IsKeyDown(Enum.KeyCode.D) then
                        direction = direction + cframe.RightVector
                    end
                    if UserInputService:IsKeyDown(Enum.KeyCode.Space) then
                        direction = direction + Vector3.new(0, 1, 0)
                    end
                    if UserInputService:IsKeyDown(Enum.KeyCode.LeftControl)
                        or UserInputService:IsKeyDown(Enum.KeyCode.LeftShift) then
                        direction = direction - Vector3.new(0, 1, 0)
                    end
                else
                    local moveVector = movement.ResolveControlsMoveVector()
                    if moveVector.Magnitude > 0 then
                        direction = direction + cframe.LookVector * -moveVector.Z
                        direction = direction + cframe.RightVector * moveVector.X
                    end
                end
                return direction
            end

            function RivalsRuntimeBridge.Movement.FlattenDirection(vector)
                local flat = Vector3.new(vector.X, 0, vector.Z)
                return flat.Magnitude > 0 and flat.Unit or Vector3.zero
            end

            -- evilrollerplayers's Auto Strafe input [70819]: flattened look AND right vectors, W/S/D/A only,
            -- PlayerModule move vector without a keyboard, normalized before returning.
            function RivalsRuntimeBridge.Movement.StrafeMoveDirection()
                local movement = RivalsRuntimeBridge.Movement
                if UserInputService:GetFocusedTextBox() then
                    return Vector3.zero
                end
                local direction = Vector3.zero
                local cframe = Workspace.CurrentCamera.CFrame
                local look = movement.FlattenDirection(cframe.LookVector)
                local right = movement.FlattenDirection(cframe.RightVector)
                if UserInputService.KeyboardEnabled then
                    if UserInputService:IsKeyDown(Enum.KeyCode.W) then
                        direction = direction + look
                    end
                    if UserInputService:IsKeyDown(Enum.KeyCode.S) then
                        direction = direction - look
                    end
                    if UserInputService:IsKeyDown(Enum.KeyCode.D) then
                        direction = direction + right
                    end
                    if UserInputService:IsKeyDown(Enum.KeyCode.A) then
                        direction = direction - right
                    end
                else
                    local moveVector = movement.ResolveControlsMoveVector()
                    if moveVector.Magnitude > 0 then
                        direction = direction + look * -moveVector.Z
                        direction = direction + right * moveVector.X
                    end
                end
                if direction.Magnitude > 0 then
                    direction = direction.Unit
                end
                return direction
            end

            function RivalsRuntimeBridge.Movement.UpdateFlight(active)
                local movement = RivalsRuntimeBridge.Movement
                local rootPart = movement.RootPart
                if not active or not rootPart or rootPart.Parent == nil
                    or not movement.Humanoid or movement.Humanoid.Health <= 0 then
                    movement.DestroyFlight()
                    return
                end
                local direction = movement.FlightMoveDirection()
                if direction.Magnitude > 0 then
                    direction = direction.Unit
                end
                local velocityVector = direction * movement.ReadNumber('P10S3S4', 100)
                local flight = movement.Flight
                if flight and flight.RootPart ~= rootPart then
                    movement.DestroyFlight()
                    flight = nil
                end
                if flight then
                    flight.Velocity.VectorVelocity = velocityVector
                    return
                end
                -- evilrollerplayers's _ApplyVelocity [103530]: unnamed Attachment + LinearVelocity, world
                -- relative, infinite force, velocity assigned before Attachment0/Parent.
                local attachment = Instance.new('Attachment')
                attachment.Parent = rootPart
                local velocity = Instance.new('LinearVelocity')
                velocity.RelativeTo = Enum.ActuatorRelativeTo.World
                velocity.MaxForce = math.huge
                velocity.VectorVelocity = velocityVector
                velocity.Attachment0 = attachment
                velocity.Parent = rootPart
                movement.Flight = { RootPart = rootPart, Attachment = attachment, Velocity = velocity }
            end

            function RivalsRuntimeBridge.Movement.BlankFlightVelocity()
                local movement = RivalsRuntimeBridge.Movement
                if movement.Flight and movement.RootPart and movement.RootPart.Parent then
                    movement.RootPart.AssemblyLinearVelocity = Vector3.zero
                end
            end

            function RivalsRuntimeBridge.Movement.UpdateNoclip(active)
                local movement = RivalsRuntimeBridge.Movement
                local character = movement.Character
                local alive = character ~= nil and movement.Humanoid ~= nil and movement.Humanoid.Health > 0
                if not alive then
                    -- evilrollerplayers's died path [139956] clears the registry without restoring: the
                    -- character is on its way out, so there is nothing to put back.
                    movement.ClearNoclipCharacter()
                elseif movement.NoclipCharacter ~= character then
                    movement.BindNoclipCharacter(character)
                end
                movement.SetNoclipEnabled(active == true and alive)
                if not movement.NoclipEnabled then
                    return
                end
                for part in pairs(movement.CollidableParts) do
                    part.CanCollide = false
                end
            end

            function RivalsRuntimeBridge.Movement.UpdateAutoStrafe(deltaTime, active)
                local movement = RivalsRuntimeBridge.Movement
                local rootPart = movement.RootPart
                if not active or not rootPart or not movement.Humanoid or movement.Humanoid.Health <= 0
                    or not UserInputService:IsKeyDown(Enum.KeyCode.Space) then
                    return
                end
                local speed = movement.ReadNumber('P10S3S5', 50)
                rootPart.CFrame = rootPart.CFrame + movement.StrafeMoveDirection() * (speed / 100) * deltaTime * 60
                rootPart.AssemblyLinearVelocity = rootPart.AssemblyLinearVelocity * Vector3.new(0, 1, 0)
            end

            function RivalsRuntimeBridge.Movement.ResolveMechanicsController()
                local movement = RivalsRuntimeBridge.Movement
                if movement.MechanicsController then
                    return movement.MechanicsController
                end
                if not IsReplicatedStateReady() then
                    return nil
                end
                local playerScripts = LP:FindFirstChild('PlayerScripts')
                local controllers = playerScripts and playerScripts:FindFirstChild('Controllers')
                local mechanicsModule = controllers and controllers:FindFirstChild('MechanicsController')
                if mechanicsModule then
                    local ok, controller = pcall(require, mechanicsModule)
                    movement.MechanicsController = ok and type(controller) == 'table' and controller or nil
                end
                return movement.MechanicsController
            end

            function RivalsRuntimeBridge.Movement.AttemptLoadWalkSpeedHook()
                local movement = RivalsRuntimeBridge.Movement
                if movement.WalkSpeedHookLoaded then
                    return true
                end
                if type(debug.getupvalues) ~= 'function' or type(debug.setupvalue) ~= 'function' then
                    return false
                end
                local mechanics = movement.ResolveMechanicsController()
                if type(mechanics) ~= 'table' then
                    return false
                end
                local metatable = getmetatable(mechanics)
                local classIndex = type(metatable) == 'table' and rawget(metatable, '__index') or nil
                local getWalkSpeed = type(classIndex) == 'table' and rawget(classIndex, '_GetWalkSpeed') or nil
                if type(getWalkSpeed) ~= 'function' then
                    return false
                end
                local upvalueIndex, oldUpvalue
                for index, value in pairs(debug.getupvalues(getWalkSpeed)) do
                    if type(value) == 'table' and rawget(value, 'BASE_WALKSPEED') ~= nil then
                        upvalueIndex = index
                        oldUpvalue = value
                        break
                    end
                end
                if upvalueIndex == nil then
                    return false
                end
                movement.WalkSpeedHookGetter = getWalkSpeed
                movement.WalkSpeedHookUpvalueIndex = upvalueIndex
                movement.WalkSpeedHookOldUpvalue = oldUpvalue
                -- evilrollerplayers's injection [111866]: swap _GetWalkSpeed's constants upvalue for a proxy.
                -- One proxy serves both features: the Slide caller (debug.info level 3 names the
                -- game's Slide routine) gets the sliding multiplier first, every other caller gets
                -- the WalkSpeed multiplier, and any non-BASE_WALKSPEED read trips evilrollerplayers's kick.
                debug.setupvalue(getWalkSpeed, upvalueIndex, setmetatable({}, {
                    __index = function(_, key)
                        if key ~= 'BASE_WALKSPEED' then
                            LP:Kick('Unexpected behavior (client physics 1)')
                            return nil
                        end
                        local baseWalkSpeed = rawget(oldUpvalue, 'BASE_WALKSPEED')
                        if movement.SlidingMultiplierEnabled and debug.info(3, 'n') == 'Slide' then
                            return baseWalkSpeed * movement.SlidingMultiplier
                        end
                        if movement.WalkMultiplierEnabled then
                            return baseWalkSpeed * movement.WalkMultiplier
                        end
                        return baseWalkSpeed
                    end,
                }))
                movement.WalkSpeedHookLoaded = true
                return true
            end

            function RivalsRuntimeBridge.Movement.UpdateWalkSpeed(active)
                local movement = RivalsRuntimeBridge.Movement
                movement.WalkMultiplier = movement.ReadNumber('P10S3S1', 2)
                movement.WalkMultiplierEnabled = active == true
                movement.AttemptLoadWalkSpeedHook()
            end

            function RivalsRuntimeBridge.Movement.UpdateSliding(active)
                local movement = RivalsRuntimeBridge.Movement
                movement.SlidingMultiplier = movement.ReadNumber('P10S3S2', 10)
                movement.SlidingMultiplierEnabled = active == true
                movement.AttemptLoadWalkSpeedHook()
            end

            function RivalsRuntimeBridge.Movement.UpdateJumpPower(active)
                local movement = RivalsRuntimeBridge.Movement
                movement.JumpPowerMultiplier = movement.ReadNumber('P10S3S3', 2)
                movement.JumpPowerEnabled = active == true
                movement.AttemptLoadJumpPowerHook()
            end

            function RivalsRuntimeBridge.Movement.LaunchLongJump()
                local movement = RivalsRuntimeBridge.Movement
                local fighter = ResolveLocalFighter()
                local entity = type(fighter) == 'table' and rawget(fighter, 'Entity') or nil
                if not entity and fighter and type(fighter.GetEntity) == 'function' then
                    local ok, value = pcall(fighter.GetEntity, fighter)
                    entity = ok and value or nil
                end
                local rootPart = movement.RootPart
                local camera = Workspace.CurrentCamera
                if type(entity) ~= 'table' or not rootPart or not camera or not movement.Humanoid
                    or movement.Humanoid.Health <= 0 then
                    return false
                end
                local lookVector = camera.CFrame.LookVector
                local direction = Vector3.new(lookVector.X, 0, lookVector.Z)
                if direction.Magnitude < 0.001 then
                    local rootLook = rootPart.CFrame.LookVector
                    direction = Vector3.new(rootLook.X, 0, rootLook.Z)
                end
                direction = direction.Unit
                if Options.P10S3D1 and Options.P10S3D1.Value == 'Under Feet' then
                    direction = (direction * movement.ReadNumber('P10S3S8', 8) + Vector3.new(0, 4, 0)).Unit
                end
                local velocity = direction * movement.ReadNumber('P10S3S6', 60)
                    + Vector3.new(0, movement.ReadNumber('P10S3S7', 20), 0)
                if type(entity.AirborneCancel) ~= 'function' or type(entity.AirborneTrigger) ~= 'function' then
                    return false
                end
                pcall(entity.AirborneCancel, entity)
                local ok = pcall(entity.AirborneTrigger, entity, velocity, 4)
                return ok
            end

            function RivalsRuntimeBridge.Movement.UpdateLongJump(active)
                local movement = RivalsRuntimeBridge.Movement
                if active and not movement.LongJumpPressed then
                    movement.LaunchLongJump()
                end
                movement.LongJumpPressed = active
            end

            function RivalsRuntimeBridge.Movement.Update(deltaTime)
                local movement = RivalsRuntimeBridge.Movement
                movement.ResolveCharacter()
                movement.UpdateWalkSpeed(
                    movement.ReadToggle('P10S3T1') and movement.IsKeyActive('P10S3T1K'))
                movement.UpdateSliding(
                    movement.ReadToggle('P10S3T2') and movement.IsKeyActive('P10S3T2K'))
                -- evilrollerplayers's Jump Power has no keybind [53609]; the toggle alone drives it.
                movement.UpdateJumpPower(movement.ReadToggle('P10S3T3'))
                -- evilrollerplayers's physics pump order [90368]: autoStrafe, flight, noclip.
                movement.UpdateAutoStrafe(
                    deltaTime,
                    movement.ReadToggle('P10S3T6') and movement.IsKeyActive('P10S3T6K'))
                movement.UpdateFlight(
                    movement.ReadToggle('P10S3T4') and movement.IsKeyActive('P10S3T4K'))
                movement.UpdateNoclip(
                    movement.ReadToggle('P10S3T5') and movement.IsKeyActive('P10S3T5K'))
                movement.UpdateLongJump(
                    movement.ReadToggle('P10S3T7') and movement.IsKeyActive('P10S3T7K'))
            end

            function RivalsRuntimeBridge.Movement.RefreshAll()
                local movement = RivalsRuntimeBridge.Movement
                local caps = __evilrollerplayers_hook_genv.evilrollerplayersHailCaps
                -- Support notices only -- the Attempt*Hook loaders already decline
                -- cleanly when the debug surface is missing.
                if movement.ReadToggle('P10S3T1') or movement.ReadToggle('P10S3T2') then
                    caps.gate('WalkSpeed / Sliding Speed', 'debug.getupvalues', 'debug.setupvalue')
                end
                if movement.ReadToggle('P10S3T3') then
                    caps.gate('Jump Power', 'debug.getupvalues', 'debug.setupvalue', 'debug.getconstants', 'debug.getprotos', 'debug.getproto')
                end
                RivalsRuntimeBridge.Movement.Update(0)
            end

            function RivalsRuntimeBridge.Movement.Destroy()
                local movement = RivalsRuntimeBridge.Movement
                movement.SetNoclipEnabled(false)
                movement.ClearNoclipCharacter()
                movement.DestroyFlight()
                if movement.WalkSpeedHookLoaded and movement.WalkSpeedHookGetter
                    and movement.WalkSpeedHookUpvalueIndex ~= nil and movement.WalkSpeedHookOldUpvalue ~= nil then
                    pcall(debug.setupvalue, movement.WalkSpeedHookGetter,
                        movement.WalkSpeedHookUpvalueIndex, movement.WalkSpeedHookOldUpvalue)
                end
                movement.WalkSpeedHookLoaded = false
                movement.WalkSpeedHookGetter = nil
                movement.WalkSpeedHookUpvalueIndex = nil
                movement.WalkSpeedHookOldUpvalue = nil
                movement.WalkMultiplierEnabled = false
                movement.SlidingMultiplierEnabled = false
                -- evilrollerplayers's JumpPower Destroy [91454] flags the hook destroyed; the proxies restore
                -- their original upvalues lazily on the next read instead of being torn down here.
                movement.JumpPowerHookDestroyed = true
                movement.JumpPowerHookLoaded = false
                movement.JumpPowerEnabled = false
                movement.MechanicsController = nil
                movement.PlayerModule = nil
                movement.Character = nil
                movement.Humanoid = nil
                movement.RootPart = nil
                movement.LongJumpPressed = false
            end

            -- Device Spoof: direct 1:1 port of evilrollerplayers's DeviceSpoof [17425]. Replaces the
            -- ControlsController upvalue inside FighterController._ReplicateControls with a proxy
            -- that only answers CurrentControls (kicking any other read, exactly like evilrollerplayers) and
            -- returns the spoofed device string. The game's own replication then reports that
            -- device to the server.
            RivalsRuntimeBridge.DeviceSpoof = {
                Hook = nil,
                Controller = nil,
                -- evilrollerplayers's frozen control map [104716]: dropdown key -> replicated Controls value.
                ControlsMap = {
                    Desktop = 'MouseKeyboard',
                    Mobile = 'Touch',
                    Console = 'Gamepad',
                    VR = 'VR',
                },
            }

            -- Kept as a bridge method (not a top-scope local) so it costs no register against
            -- Luau's 200-local ceiling on the RIVALS entry scope.
            function RivalsRuntimeBridge.DeviceSpoof.ResolveControlsController()
                local spoof = RivalsRuntimeBridge.DeviceSpoof
                if spoof.Controller then
                    return spoof.Controller
                end
                if not ReplicatedStateReady then
                    BeginReplicatedStateBoot()
                    return nil
                end
                local playerScripts = LP:FindFirstChild('PlayerScripts')
                local controllers = playerScripts and playerScripts:FindFirstChild('Controllers')
                local module = controllers and controllers:FindFirstChild('ControlsController')
                if not module then
                    return nil
                end
                local ok, controller = pcall(require, module)
                if ok and type(controller) == 'table' then
                    spoof.Controller = controller
                end
                return spoof.Controller
            end

            function RivalsRuntimeBridge.DeviceSpoof.ReadEnabled()
                return Toggles and Toggles.P10S7T1 and Toggles.P10S7T1.Value == true
            end

            function RivalsRuntimeBridge.DeviceSpoof.ReadSpoofType()
                local option = Options and Options.P10S7D1
                local value = option and option.Value
                return type(value) == 'string' and value or 'VR'
            end

            function RivalsRuntimeBridge.DeviceSpoof.ResolveReplicateControls()
                local fighterController = ResolveFighterController()
                if type(fighterController) ~= 'table' then
                    return nil, nil
                end
                local metatable = getmetatable(fighterController)
                local classIndex = type(metatable) == 'table' and rawget(metatable, '__index') or nil
                local replicateControls = type(classIndex) == 'table'
                    and rawget(classIndex, '_ReplicateControls') or nil
                if type(replicateControls) ~= 'function' then
                    return nil, fighterController
                end
                return replicateControls, fighterController
            end

            -- evilrollerplayers's f1277: re-run the game's own _ReplicateControls so the (now spoofed, or on
            -- unload restored) device is pushed to the server immediately instead of on the next
            -- organic replication.
            function RivalsRuntimeBridge.DeviceSpoof.ForceReplicate()
                local replicateControls, fighterController =
                    RivalsRuntimeBridge.DeviceSpoof.ResolveReplicateControls()
                if replicateControls and fighterController then
                    pcall(replicateControls, fighterController)
                end
            end

            function RivalsRuntimeBridge.DeviceSpoof.AttemptLoadHook()
                local spoof = RivalsRuntimeBridge.DeviceSpoof
                if spoof.Hook then
                    return true
                end
                if type(debug.getupvalues) ~= 'function' or type(debug.setupvalue) ~= 'function' then
                    return false
                end
                local controlsController = spoof.ResolveControlsController()
                if type(controlsController) ~= 'table' then
                    return false
                end
                local replicateControls = spoof.ResolveReplicateControls()
                if type(replicateControls) ~= 'function' then
                    return false
                end
                local upvalueIndex
                for index, value in pairs(debug.getupvalues(replicateControls)) do
                    if value == controlsController then
                        upvalueIndex = index
                        break
                    end
                end
                if upvalueIndex == nil then
                    return false
                end
                local originalValue = debug.getupvalue(replicateControls, upvalueIndex)
                -- evilrollerplayers's injection [17552]: swap the ControlsController upvalue for a proxy that
                -- only serves CurrentControls and keeps both of evilrollerplayers's kick guards verbatim.
                debug.setupvalue(replicateControls, upvalueIndex, setmetatable({}, {
                    __index = function(_, key)
                        if key ~= 'CurrentControls' then
                            LP:Kick('Unexpected behavior (client misc 2)')
                            return nil
                        end
                        local value = spoof.ControlsMap[spoof.ReadSpoofType()]
                        if value == nil then
                            LP:Kick('Unexpected behavior (client misc 1)')
                        end
                        return value
                    end,
                }))
                spoof.Hook = {
                    Getter = replicateControls,
                    UpvalueIndex = upvalueIndex,
                    OriginalValue = originalValue,
                }
                return true
            end

            function RivalsRuntimeBridge.DeviceSpoof.AttemptUnloadHook()
                local spoof = RivalsRuntimeBridge.DeviceSpoof
                local hook = spoof.Hook
                if not hook then
                    return
                end
                spoof.Hook = nil
                pcall(debug.setupvalue, hook.Getter, hook.UpvalueIndex, hook.OriginalValue)
            end

            function RivalsRuntimeBridge.DeviceSpoof.RefreshAll()
                local spoof = RivalsRuntimeBridge.DeviceSpoof
                if spoof.ReadEnabled() then
                    -- Support notice only -- AttemptLoadHook already declines cleanly.
                    __evilrollerplayers_hook_genv.evilrollerplayersHailCaps.gate('Device Spoof', 'debug.getupvalues', 'debug.setupvalue')
                    if spoof.AttemptLoadHook() then
                        spoof.ForceReplicate()
                    end
                elseif spoof.Hook then
                    spoof.AttemptUnloadHook()
                    spoof.ForceReplicate()
                end
            end

            function RivalsRuntimeBridge.DeviceSpoof.Destroy()
                local spoof = RivalsRuntimeBridge.DeviceSpoof
                if spoof.Hook then
                    spoof.AttemptUnloadHook()
                    spoof.ForceReplicate()
                end
            end

            -- Player Spoofer: 1:1 port of evilrollerplayers's player_spoofer. This slice is the AttributeSink
            -- [31428] with its exact attribute binder [108644] and player registry [116985]. It
            -- writes spoofed nametag/stat attributes onto the Player instance, captures the
            -- original, re-asserts under an is-writing guard whenever the game overwrites the
            -- attribute, and restores the original on teardown. Scope (You vs Others) is chosen
            -- per player. Live-verified: these attributes exist on Player instances and are
            -- client-writable. 'const' fields write evilrollerplayers's fixed value when enabled
            -- (Influencer/RobloxEmployee true, NosniyTeam GroupRank 255); 'value' fields write the
            -- configured value.
            RivalsRuntimeBridge.PlayerSpoofer = {
                Binders = setmetatable({}, { __mode = 'k' }),
                LifecycleConnections = {},
                Started = false,
                Scopes = { 'You', 'Oth' },
                AttributeFields = {
                    { key = 'Winstreak', attribute = 'StatisticDuelsWinStreak', control = 'number',
                        youDefault = '999', othDefault = '0' },
                    { key = 'Level', attribute = 'Level', control = 'number',
                        youDefault = '999', othDefault = '0' },
                    { key = 'RankedElo', attribute = 'DisplayELO', control = 'number',
                        youDefault = '3600', othDefault = '0' },
                    { key = 'NametagStatus', attribute = 'PlayerStatus', control = 'text',
                        youDefault = 'Prime', othDefault = 'Prime' },
                    { key = 'Influencer', attribute = 'IsInfluencer', control = 'const', constValue = true },
                    { key = 'RobloxEmployee', attribute = 'IsRobloxEmployee', control = 'const', constValue = true },
                    { key = 'NosniyTeam', attribute = 'GroupRank', control = 'const', constValue = 255 },
                },
            }

            -- evilrollerplayers's attribute binder t78 [108648]: capture the original, re-assert the spoof
            -- whenever the game changes the attribute (guarded so our own write does not recurse),
            -- and restore on destroy.
            function RivalsRuntimeBridge.PlayerSpoofer.CreateBinder(instance, attribute)
                local binder = {
                    Instance = instance,
                    Attribute = attribute,
                    Original = instance:GetAttribute(attribute),
                    IsWriting = false,
                    Spoofed = nil,
                    Connection = nil,
                }
                binder.Connection = instance:GetAttributeChangedSignal(attribute):Connect(function()
                    if binder.IsWriting then
                        return
                    end
                    binder.Original = instance:GetAttribute(attribute)
                    binder.IsWriting = true
                    if binder.Spoofed ~= nil then
                        instance:SetAttribute(attribute, binder.Spoofed.value)
                    end
                    binder.IsWriting = false
                end)
                return binder
            end

            function RivalsRuntimeBridge.PlayerSpoofer.BinderSet(binder, spoofed)
                binder.Spoofed = spoofed
                binder.IsWriting = true
                if spoofed == nil then
                    binder.Instance:SetAttribute(binder.Attribute, binder.Original)
                else
                    binder.Instance:SetAttribute(binder.Attribute, spoofed.value)
                end
                binder.IsWriting = false
            end

            function RivalsRuntimeBridge.PlayerSpoofer.BinderDestroy(binder)
                if binder.Connection then
                    binder.Connection:Disconnect()
                end
                pcall(function()
                    binder.Instance:SetAttribute(binder.Attribute, binder.Original)
                end)
            end

            function RivalsRuntimeBridge.PlayerSpoofer.Bind(player, attribute)
                local spoofer = RivalsRuntimeBridge.PlayerSpoofer
                local entries = spoofer.Binders[player]
                if entries == nil then
                    entries = {}
                    spoofer.Binders[player] = entries
                end
                local binder = entries[attribute]
                if binder == nil then
                    binder = spoofer.CreateBinder(player, attribute)
                    entries[attribute] = binder
                end
                return binder
            end

            function RivalsRuntimeBridge.PlayerSpoofer.Unbind(player, attribute)
                local spoofer = RivalsRuntimeBridge.PlayerSpoofer
                local entries = spoofer.Binders[player]
                if entries == nil then
                    return
                end
                local binder = entries[attribute]
                if binder ~= nil then
                    spoofer.BinderDestroy(binder)
                    entries[attribute] = nil
                end
            end

            -- evilrollerplayers _SetValue/_SetConst [31490]: bind + write when enabled, unbind (restore) when not.
            function RivalsRuntimeBridge.PlayerSpoofer.SetAttributeSpoof(player, attribute, enabled, value)
                local spoofer = RivalsRuntimeBridge.PlayerSpoofer
                if enabled then
                    spoofer.BinderSet(spoofer.Bind(player, attribute), { value = value })
                else
                    spoofer.Unbind(player, attribute)
                end
            end

            function RivalsRuntimeBridge.PlayerSpoofer.ScopeSuffix(player)
                return player == LP and 'You' or 'Oth'
            end

            function RivalsRuntimeBridge.PlayerSpoofer.ReadToggle(optionId)
                return Toggles and Toggles[optionId] and Toggles[optionId].Value == true
            end

            function RivalsRuntimeBridge.PlayerSpoofer.ReadOption(optionId)
                local option = Options and Options[optionId]
                return option and option.Value
            end

            -- evilrollerplayers AttributeSink _Apply [31479]: per player, for each field write the spoof (or
            -- clear it) according to that scope's toggle and value.
            function RivalsRuntimeBridge.PlayerSpoofer.Apply(player)
                local spoofer = RivalsRuntimeBridge.PlayerSpoofer
                if not player or player.Parent == nil then
                    return
                end
                local suffix = spoofer.ScopeSuffix(player)
                for _, field in ipairs(spoofer.AttributeFields) do
                    local enabled = spoofer.ReadToggle('PSpoof' .. suffix .. field.key .. 'T')
                    if field.control == 'const' then
                        spoofer.SetAttributeSpoof(player, field.attribute, enabled, field.constValue)
                    else
                        local raw = spoofer.ReadOption('PSpoof' .. suffix .. field.key .. 'V')
                        local value = raw
                        if field.control == 'number' then
                            value = tonumber(raw)
                        elseif type(raw) == 'string' and raw == '' then
                            value = nil
                        end
                        spoofer.SetAttributeSpoof(player, field.attribute, enabled and value ~= nil, value)
                    end
                end
            end

            function RivalsRuntimeBridge.PlayerSpoofer.Cleanup(player)
                local spoofer = RivalsRuntimeBridge.PlayerSpoofer
                local entries = spoofer.Binders[player]
                if entries == nil then
                    return
                end
                for _, binder in pairs(entries) do
                    spoofer.BinderDestroy(binder)
                end
                spoofer.Binders[player] = nil
            end

            function RivalsRuntimeBridge.PlayerSpoofer.RefreshAll()
                local spoofer = RivalsRuntimeBridge.PlayerSpoofer
                spoofer.Start()
                for _, player in ipairs(Players:GetPlayers()) do
                    spoofer.Apply(player)
                end
            end

            function RivalsRuntimeBridge.PlayerSpoofer.Start()
                local spoofer = RivalsRuntimeBridge.PlayerSpoofer
                if spoofer.Started then
                    return
                end
                spoofer.Started = true
                spoofer.LifecycleConnections[#spoofer.LifecycleConnections + 1] =
                    Players.PlayerAdded:Connect(GuardRivalsCallback('PlayerSpoofer_PlayerAdded', function(player)
                        spoofer.Apply(player)
                    end))
                spoofer.LifecycleConnections[#spoofer.LifecycleConnections + 1] =
                    Players.PlayerRemoving:Connect(GuardRivalsCallback('PlayerSpoofer_PlayerRemoving', function(player)
                        spoofer.Cleanup(player)
                    end))
            end

            function RivalsRuntimeBridge.PlayerSpoofer.Destroy()
                local spoofer = RivalsRuntimeBridge.PlayerSpoofer
                for _, connection in ipairs(spoofer.LifecycleConnections) do
                    pcall(function() connection:Disconnect() end)
                end
                spoofer.LifecycleConnections = {}
                spoofer.Started = false
                for player in pairs(spoofer.Binders) do
                    spoofer.Cleanup(player)
                end
            end

            RivalsRuntimeBridge.AnimationPlayer = {}
            do
                local player = RivalsRuntimeBridge.AnimationPlayer
                local p = LP
                local workspace = Workspace
                function player.BuildUi(animPlayerTab)
