            function RivalsRuntimeBridge.CombatFeedback.ReadToggle(optionId)
                return Toggles and Toggles[optionId] and Toggles[optionId].Value == true
            end

            function RivalsRuntimeBridge.CombatFeedback.ReadOption(optionId, fallback)
                local option = Options and Options[optionId]
                if option == nil or option.Value == nil then
                    return fallback
                end
                return option.Value
            end

            function RivalsRuntimeBridge.CombatFeedback.IsEnabled()
                local feedback = RivalsRuntimeBridge.CombatFeedback
                return feedback.ReadToggle('P1S15T1') or feedback.ReadToggle('P1S16T1')
                    or feedback.ReadToggle('P1S18T1')
            end

            function RivalsRuntimeBridge.CombatFeedback.Trim(value)
                if type(value) ~= 'string' then
                    return ''
                end
                return value:match('^%s*(.-)%s*$') or ''
            end

            function RivalsRuntimeBridge.CombatFeedback.NormalizeSoundSource(value)
                local feedback = RivalsRuntimeBridge.CombatFeedback
                local source = feedback.Trim(value)
                if source == '' then
                    return nil
                end
                if source:match('^%d+$') then
                    return 'rbxassetid://' .. source
                end
                return source
            end

            function RivalsRuntimeBridge.CombatFeedback.EnsureCustomSoundsLoaded()
                local feedback = RivalsRuntimeBridge.CombatFeedback
                if feedback.CustomSoundsLoaded then
                    return
                end
                feedback.CustomSoundsLoaded = true
                feedback.CustomSounds = {}
                if type(isfile) ~= 'function' or not isfile(feedback.CustomSoundsPath) then
                    return
                end

                local ok, decoded = pcall(function()
                    return game:GetService('HttpService'):JSONDecode(readfile(feedback.CustomSoundsPath))
                end)
                local records = ok and type(decoded) == 'table' and (decoded.sounds or decoded) or nil
                if type(records) ~= 'table' then
                    return
                end

                local seen = {}
                for _, record in ipairs(records) do
                    if type(record) == 'table' then
                        local name = feedback.Trim(record.name)
                        local source = feedback.NormalizeSoundSource(record.soundId or record.source)
                        if name ~= '' and source and not seen[name] then
                            seen[name] = true
                            table.insert(feedback.CustomSounds, {
                                name = name,
                                soundId = source,
                            })
                        end
                    end
                end
                table.sort(feedback.CustomSounds, function(left, right)
                    return left.name < right.name
                end)
            end

            function RivalsRuntimeBridge.CombatFeedback.SaveCustomSounds()
                local feedback = RivalsRuntimeBridge.CombatFeedback
                if type(writefile) ~= 'function' then
                    return false
                end
                local ok = pcall(function()
                    if type(makefolder) == 'function' and type(isfolder) == 'function' and not isfolder('evilrollerplayersHail') then
                        makefolder('evilrollerplayersHail')
                    end
                    writefile(feedback.CustomSoundsPath, game:GetService('HttpService'):JSONEncode({
                        version = 1,
                        sounds = feedback.CustomSounds,
                    }))
                end)
                return ok
            end

            function RivalsRuntimeBridge.CombatFeedback.ResolveUserSoundNames()
                local feedback = RivalsRuntimeBridge.CombatFeedback
                feedback.EnsureCustomSoundsLoaded()
                local names = {}
                for _, record in ipairs(feedback.CustomSounds) do
                    table.insert(names, record.name)
                end
                return names
            end

            function RivalsRuntimeBridge.CombatFeedback.ResolveCustomSoundNames()
                local feedback = RivalsRuntimeBridge.CombatFeedback
                local userNames = feedback.ResolveUserSoundNames()
                local seen = {}
                for _, name in ipairs(userNames) do
                    seen[name] = true
                end
                local names = {}
                for _, record in ipairs(feedback.BuiltInSounds) do
                    if not seen[record.name] then
                        table.insert(names, record.name)
                    end
                end
                for _, name in ipairs(userNames) do
                    table.insert(names, name)
                end
                return names
            end

            function RivalsRuntimeBridge.CombatFeedback.RefreshCustomSoundDropdowns()
                local feedback = RivalsRuntimeBridge.CombatFeedback
                local names = feedback.ResolveCustomSoundNames()
                for _, optionId in ipairs(feedback.SoundDropdownOptionIds) do
                    local option = Options and Options[optionId]
                    if option and type(option.SetValues) == 'function' then
                        -- The manage dialog's remove list only offers user sounds; built-ins are permanent.
                        option:SetValues(optionId == 'P1S17D1' and feedback.ResolveUserSoundNames() or names)
                    end
                end
            end

            function RivalsRuntimeBridge.CombatFeedback.AddCustomSound(nameValue, sourceValue)
                local feedback = RivalsRuntimeBridge.CombatFeedback
                feedback.EnsureCustomSoundsLoaded()
                local name = feedback.Trim(nameValue)
                local source = feedback.NormalizeSoundSource(sourceValue)
                if name == '' or not source then
                    return false
                end
                for _, record in ipairs(feedback.CustomSounds) do
                    if record.name == name then
                        return false
                    end
                end
                for _, record in ipairs(feedback.BuiltInSounds) do
                    if record.name == name then
                        return false
                    end
                end

                local previous = table.clone(feedback.CustomSounds)
                table.insert(feedback.CustomSounds, {name = name, soundId = source})
                table.sort(feedback.CustomSounds, function(left, right)
                    return left.name < right.name
                end)
                if not feedback.SaveCustomSounds() then
                    feedback.CustomSounds = previous
                    return false
                end
                feedback.RefreshCustomSoundDropdowns()
                return true
            end

            function RivalsRuntimeBridge.CombatFeedback.RemoveCustomSound(nameValue)
                local feedback = RivalsRuntimeBridge.CombatFeedback
                feedback.EnsureCustomSoundsLoaded()
                local name = feedback.Trim(nameValue)
                if name == '' then
                    return false
                end
                local index = nil
                for recordIndex, record in ipairs(feedback.CustomSounds) do
                    if record.name == name then
                        index = recordIndex
                        break
                    end
                end
                if not index then
                    return false
                end

                local previous = table.clone(feedback.CustomSounds)
                table.remove(feedback.CustomSounds, index)
                if not feedback.SaveCustomSounds() then
                    feedback.CustomSounds = previous
                    return false
                end
                feedback.SoundAssetCache[name] = nil
                for _, optionId in ipairs({'P1S15D1', 'P1S15D2', 'P1S16D1'}) do
                    local option = Options and Options[optionId]
                    if option and option.Value == name and type(option.SetValue) == 'function' then
                        option:SetValue(nil)
                    end
                end
                feedback.RefreshCustomSoundDropdowns()
                return true
            end

            function RivalsRuntimeBridge.CombatFeedback.ResolveCustomSoundSource(name)
                local feedback = RivalsRuntimeBridge.CombatFeedback
                feedback.EnsureCustomSoundsLoaded()
                -- User sounds win name clashes so files saved before a built-in existed keep working.
                for _, record in ipairs(feedback.CustomSounds) do
                    if record.name == name then
                        return record.soundId
                    end
                end
                for _, record in ipairs(feedback.BuiltInSounds) do
                    if record.name == name then
                        return record.soundId
                    end
                end
                return nil
            end

            function RivalsRuntimeBridge.CombatFeedback.HashSoundUrl(url)
                local hash = 5381
                for index = 1, #url do
                    hash = (hash * 33 + string.byte(url, index)) % 2147483647
                end
                return tostring(hash)
            end

            function RivalsRuntimeBridge.CombatFeedback.ResolveSoundAsset(name)
                local feedback = RivalsRuntimeBridge.CombatFeedback
                if type(name) ~= 'string' or name == '' then
                    return nil
                end
                local cached = feedback.SoundAssetCache[name]
                if cached ~= nil then
                    return cached or nil
                end

                local source = feedback.ResolveCustomSoundSource(name)
                if not source then
                    feedback.SoundAssetCache[name] = false
                    return nil
                end
                if source:match('^rbxassetid://') or source:match('^rbxasset://') then
                    feedback.SoundAssetCache[name] = source
                    return source
                end

                local customAsset = type(getcustomasset) == 'function' and getcustomasset
                    or (type(getsynasset) == 'function' and getsynasset or nil)
                if source:match('^https?://') then
                    if type(writefile) ~= 'function' or type(customAsset) ~= 'function' then
                        feedback.SoundAssetCache[name] = false
                        return nil
                    end
                    local extension = source:match('(%.[%w]+)[%?#]') or source:match('(%.[%w]+)$') or '.mp3'
                    extension = extension:lower()
                    if extension ~= '.mp3' and extension ~= '.ogg' and extension ~= '.wav' then
                        extension = '.mp3'
                    end
                    local cachePath = string.format('%s/%s%s', feedback.CustomSoundsCacheFolder, feedback.HashSoundUrl(source), extension)
                    local ok = pcall(function()
                        if type(makefolder) == 'function' and type(isfolder) == 'function' then
                            if not isfolder('evilrollerplayersHail') then
                                makefolder('evilrollerplayersHail')
                            end
                            if not isfolder(feedback.CustomSoundsCacheFolder) then
                                makefolder(feedback.CustomSoundsCacheFolder)
                            end
                        end
                        if type(isfile) ~= 'function' or not isfile(cachePath) then
                            local requestFunction = type(request) == 'function' and request
                                or (type(http_request) == 'function' and http_request or nil)
                            local body = nil
                            if requestFunction then
                                local response = requestFunction({Url = source, Method = 'GET'})
                                local status = tonumber(response and (response.StatusCode or response.Status)) or 0
                                if status < 200 or status >= 300 then
                                    error('download failed')
                                end
                                body = response.Body
                            else
                                body = game:HttpGet(source)
                            end
                            if type(body) ~= 'string' or body == '' then
                                error('empty download')
                            end
                            writefile(cachePath, body)
                        end
                    end)
                    if ok then
                        local assetOk, asset = pcall(customAsset, cachePath)
                        if assetOk and type(asset) == 'string' and asset ~= '' then
                            feedback.SoundAssetCache[name] = asset
                            return asset
                        end
                    end
                    feedback.SoundAssetCache[name] = false
                    return nil
                end

                if type(customAsset) == 'function' and type(isfile) == 'function' and isfile(source) then
                    local ok, asset = pcall(customAsset, source)
                    if ok and type(asset) == 'string' and asset ~= '' then
                        feedback.SoundAssetCache[name] = asset
                        return asset
                    end
                end
                feedback.SoundAssetCache[name] = false
                return nil
            end

            function RivalsRuntimeBridge.CombatFeedback.PlaySound(name, volume, pitch)
                local feedback = RivalsRuntimeBridge.CombatFeedback
                local asset = feedback.ResolveSoundAsset(name)
                if not asset then
                    return
                end
                local sound = Instance.new('Sound')
                sound.Name = 'evilrollerplayersHailCombatFeedback'
                sound.SoundId = asset
                sound.Volume = math.max(0, tonumber(volume) or 1)
                sound.PlaybackSpeed = math.max(0.01, tonumber(pitch) or 1)
                sound.Parent = game:GetService('SoundService')
                game:GetService('Debris'):AddItem(sound, 20)
                sound:Play()
            end

            function RivalsRuntimeBridge.CombatFeedback.CreateChams(character, color, transparency, duration, materialName)
                local feedback = RivalsRuntimeBridge.CombatFeedback
                if typeof(character) ~= 'Instance' or not character:IsA('Model') then
                    return
                end
                local model = Instance.new('Model')
                model.Name = 'evilrollerplayersHailCombatFeedbackChams'
                local parts = {}
                local material = feedback.MaterialMap[materialName] or Enum.Material.ForceField
                local baseTransparency = math.clamp(tonumber(transparency) or 0, 0, 1)

                for _, part in ipairs(character:GetDescendants()) do
                    if part:IsA('BasePart') and part.Name ~= 'HumanoidRootPart' and (part.Transparency < 1 or part.Parent == character) then
                        local ok, ghost = pcall(function()
                            return part:Clone()
                        end)
                        if not ok or not ghost or not ghost:IsA('BasePart') then
                            ghost = Instance.new('Part')
                            ghost.Size = part.Size
                            ghost.Shape = part:IsA('Part') and part.Shape or Enum.PartType.Block
                        end
                        for _, descendant in ipairs(ghost:GetDescendants()) do
                            if not descendant:IsA('DataModelMesh') then
                                descendant:Destroy()
                            end
                        end
                        ghost.Name = part.Name
                        ghost.Anchored = true
                        ghost.CanCollide = false
                        ghost.CanQuery = false
                        ghost.CanTouch = false
                        ghost.CastShadow = false
                        ghost.LocalTransparencyModifier = 0
                        if ghost:IsA('MeshPart') then ghost.TextureID = '' end
                        for _, mesh in ipairs(ghost:GetDescendants()) do
                            if mesh:IsA('SpecialMesh') then mesh.TextureId = '' end
                        end
                        ghost.Color = typeof(color) == 'Color3' and color or Color3.fromRGB(255, 0, 0)
                        ghost.Material = material
                        ghost.Transparency = baseTransparency
                        ghost.CFrame = part.CFrame
                        pcall(function()
                            ghost.MaterialVariant = ''
                        end)
                        ghost.Parent = model
                        table.insert(parts, {Source = part, Ghost = ghost})
                    end
                end
                if #parts == 0 then
                    model:Destroy()
                    return
                end
                model.Parent = Workspace
                table.insert(feedback.Chams, {
                    Model = model,
                    Parts = parts,
                    StartedAt = tick(),
                    Duration = math.max(0.05, tonumber(duration) or 0.8),
                    Transparency = baseTransparency,
                })
            end

            -- evilrollerplayers resolves the shooting item through its whole item registry rather than
            -- the local fighter's list, so tracers also draw for other players' shots.
            -- Remote fighters only populate Items while they are rendered, so with nobody
            -- else on screen this naturally falls back to the local items.
            function RivalsRuntimeBridge.CombatFeedback.ResolveItemByObjectId(objectId)
                local function findIn(fighter)
                    if type(fighter) ~= 'table' then
                        return nil
                    end
                    for _, item in pairs(rawget(fighter, 'Items') or {}) do
                        local data = type(item) == 'table' and rawget(item, 'Data') or nil
                        local itemObjectId = type(data) == 'table' and rawget(data, 'ObjectID') or nil
                        if (itemObjectId or ReadItemValue(item, 'ObjectID')) == objectId then
                            return item
                        end
                    end
                    return nil
                end

                local item = findIn(ResolveLocalFighter())
                if item then
                    return item
                end

                local fighterController = ResolveFighterController()
                for _, fighter in pairs(fighterController and rawget(fighterController, 'Objects') or {}) do
                    item = findIn(fighter)
                    if item then
                        return item
                    end
                end
                return nil
            end

            function RivalsRuntimeBridge.CombatFeedback.ResolveTracerSpringClass()
                local feedback = RivalsRuntimeBridge.CombatFeedback
                if feedback.TracerSpringClass ~= nil then
                    return feedback.TracerSpringClass or nil
                end
                local modules = ReplicatedStorage:FindFirstChild('Modules')
                local springModule = modules and modules:FindFirstChild('Spring')
                local ok, springClass = false, nil
                if springModule then
                    ok, springClass = pcall(require, springModule)
                end
                feedback.TracerSpringClass = ok and type(springClass) == 'table' and springClass or false
                return feedback.TracerSpringClass or nil
            end

            function RivalsRuntimeBridge.CombatFeedback.CreateTracer(startPosition, finishPosition)
                local feedback = RivalsRuntimeBridge.CombatFeedback
                if typeof(startPosition) ~= 'Vector3' or typeof(finishPosition) ~= 'Vector3' then
                    return
                end
                local springClass = feedback.ResolveTracerSpringClass()
                if not springClass or type(springClass.new) ~= 'function' then
                    return
                end

                while #feedback.Tracers >= feedback.MaxTracers do
                    local oldest = table.remove(feedback.Tracers, 1)
                    if oldest then
                        pcall(function()
                            oldest.Beam:Destroy()
                            oldest.Near:Destroy()
                            oldest.Far:Destroy()
                        end)
                    end
                end

                local near = Instance.new('Attachment')
                near.Position = startPosition
                near.Parent = Workspace.Terrain
                local far = Instance.new('Attachment')
                far.Position = startPosition
                far.Parent = Workspace.Terrain
                local beam = Instance.new('Beam')
                beam.Name = 'evilrollerplayersHailBulletTracer'
                beam.Attachment0 = near
                beam.Attachment1 = far
                beam.Color = ColorSequence.new(feedback.ReadOption('P1S18C1', Color3.fromRGB(120, 220, 255)))
                beam.Width0 = feedback.ReadOption('P1S18S1', 0.06)
                beam.Width1 = beam.Width0
                beam.FaceCamera = true
                beam.LightEmission = feedback.ReadOption('P1S18S4', 1)
                beam.LightInfluence = 0
                local glow = math.clamp(feedback.ReadOption('P1S18S5', 1), 1, 25)
                beam.Brightness = 10000 ^ ((glow - 1) / 24)
                beam.Transparency = NumberSequence.new(0)
                local style = feedback.ReadOption('P1S18D1', 'Beam')
                local texture = feedback.TracerStyles[style] or ''
                if texture ~= '' then
                    beam.Texture = texture
                    beam.TextureLength = feedback.ReadOption('P1S18S2', 4)
                    beam.TextureSpeed = feedback.ReadOption('P1S18S3', 1)
                end
                beam.Parent = Workspace.Terrain

                local spring = springClass.new(0)
                spring.Speed = feedback.ReadOption('P1S18S8', 18)
                spring.Damper = feedback.ReadOption('P1S18S9', 0.7)
                spring.Target = 1
                local expand = feedback.ReadToggle('P1S18T2')
                if not expand then
                    spring.Position = 1
                    far.Position = finishPosition
                end
                table.insert(feedback.Tracers, {
                    Beam = beam,
                    Near = near,
                    Far = far,
                    Spring = spring,
                    Start = startPosition,
                    Finish = finishPosition,
                    CreatedAt = tick(),
                    Lifetime = math.max(0.1, feedback.ReadOption('P1S18S6', 0.6)),
                    FadeTime = math.max(0, feedback.ReadOption('P1S18S7', 0.35)),
                    Expand = expand,
                })
            end

            function RivalsRuntimeBridge.CombatFeedback.HandleShootEffect(objectId, raycastResults)
                local feedback = RivalsRuntimeBridge.CombatFeedback
                if not feedback.ReadToggle('P1S18T1') or type(raycastResults) ~= 'table' then
                    return
                end
                local item = feedback.ResolveItemByObjectId(objectId)
                local viewModel = type(item) == 'table' and rawget(item, 'ViewModel') or nil
                if type(viewModel) ~= 'table' or type(viewModel.GetMuzzlePosition) ~= 'function' then
                    return
                end
                local ok, muzzlePosition = pcall(viewModel.GetMuzzlePosition, viewModel)
                local camera = Workspace.CurrentCamera
                if not ok or typeof(muzzlePosition) ~= 'Vector3' or not camera then
                    return
                end
                local startPosition = muzzlePosition + camera.CFrame.LookVector
                for _, encodedResult in pairs(raycastResults) do
                    local finishPosition = type(encodedResult) == 'table' and encodedResult[utf8.char(0)] or nil
                    if typeof(finishPosition) == 'Vector3' then
                        feedback.CreateTracer(startPosition, finishPosition)
                    end
                end
            end

            function RivalsRuntimeBridge.CombatFeedback.UpdateTracers()
                local feedback = RivalsRuntimeBridge.CombatFeedback
                local now = tick()
                local currentColor = feedback.ReadOption('P1S18C1', Color3.fromRGB(120, 220, 255))
                for index = #feedback.Tracers, 1, -1 do
                    local tracer = feedback.Tracers[index]
                    local age = now - tracer.CreatedAt
                    local expired = age >= tracer.Lifetime + tracer.FadeTime
                        or not tracer.Beam or tracer.Beam.Parent == nil
                    if expired then
                        pcall(function()
                            tracer.Beam:Destroy()
                            tracer.Near:Destroy()
                            tracer.Far:Destroy()
                        end)
                        table.remove(feedback.Tracers, index)
                    else
                        tracer.Beam.Color = ColorSequence.new(currentColor)
                        if tracer.Expand then
                            tracer.Far.Position = tracer.Start:Lerp(tracer.Finish, math.clamp(tracer.Spring.Position, 0, 1))
                        end
                        local alpha = tracer.FadeTime > 0
                            and math.clamp((age - tracer.Lifetime) / tracer.FadeTime, 0, 1) or 0
                        tracer.Beam.Transparency = NumberSequence.new(alpha)
                    end
                end
            end

            function RivalsRuntimeBridge.CombatFeedback.Update()
                local feedback = RivalsRuntimeBridge.CombatFeedback
                feedback.UpdateTracers()
                local now = tick()
                for index = #feedback.Chams, 1, -1 do
                    local cham = feedback.Chams[index]
                    local progress = math.clamp((now - cham.StartedAt) / cham.Duration, 0, 1)
                    if progress >= 1 or not cham.Model or cham.Model.Parent == nil then
                        if cham.Model then
                            pcall(function()
                                cham.Model:Destroy()
                            end)
                        end
                        table.remove(feedback.Chams, index)
                    else
                        for partIndex = #cham.Parts, 1, -1 do
                            local pair = cham.Parts[partIndex]
                            if pair.Source and pair.Source.Parent and pair.Ghost and pair.Ghost.Parent then
                                pair.Ghost.CFrame = pair.Source.CFrame
                                pair.Ghost.Transparency = cham.Transparency + (1 - cham.Transparency) * progress
                            else
                                if pair.Ghost then
                                    pair.Ghost:Destroy()
                                end
                                table.remove(cham.Parts, partIndex)
                            end
                        end
                    end
                end
            end

            function RivalsRuntimeBridge.CombatFeedback.ResolveFighterObjectId(fighter)
                local data = type(fighter) == 'table' and rawget(fighter, 'Data') or nil
                local objectId = type(data) == 'table' and rawget(data, 'ObjectID') or nil
                return objectId or ReadFighterValue(fighter, 'ObjectID')
            end

            function RivalsRuntimeBridge.CombatFeedback.ResolveCharacterByObjectId(objectId)
                local feedback = RivalsRuntimeBridge.CombatFeedback
                -- Fighters cover real players; practice-range dummies live in the
                -- enemy registry, so search both.
                local controllers = {}
                controllers[#controllers + 1] = ResolveFighterController()
                controllers[#controllers + 1] = ResolveEnemyController()
                for _, controller in ipairs(controllers) do
                    for _, subject in pairs(controller.Objects or {}) do
                        if feedback.ResolveFighterObjectId(subject) == objectId then
                            local entity = type(subject) == 'table' and rawget(subject, 'Entity') or nil
                            local model = type(entity) == 'table' and rawget(entity, 'Model') or nil
                            if typeof(model) == 'Instance' and model:IsA('Model') then
                                return model
                            end
                            local player = type(subject) == 'table' and rawget(subject, 'Player') or nil
                            if typeof(player) == 'Instance' and player:IsA('Player') then
                                return player.Character
                            end
                        end
                    end
                end
                return nil
            end

            function RivalsRuntimeBridge.CombatFeedback.HandleHit(damage, partName, character)
                local feedback = RivalsRuntimeBridge.CombatFeedback
                if not feedback.ReadToggle('P1S15T1') then
                    return
                end
                if feedback.ReadToggle('P1S15T2') then
                    local isHead = partName == 'Head'
                    local soundName = isHead and feedback.ReadOption('P1S15D1', nil) or nil
                    if type(soundName) ~= 'string' or soundName == '' then
                        soundName = feedback.ReadOption('P1S15D2', nil)
                    end
                    feedback.PlaySound(
                        soundName,
                        feedback.ReadOption(isHead and 'P1S15S1' or 'P1S15S3', 1),
                        feedback.ReadOption(isHead and 'P1S15S2' or 'P1S15S4', 1)
                    )
                end
                if feedback.ReadToggle('P1S15T4') then
                    local colorOption = Options and Options.P1S15C1
                    feedback.CreateChams(
                        character,
                        colorOption and colorOption.Value,
                        colorOption and colorOption.Transparency,
                        feedback.ReadOption('P1S15S5', 0.8),
                        feedback.ReadOption('P1S15D3', 'Ghost')
                    )
                end
            end

            function RivalsRuntimeBridge.CombatFeedback.HandleKill(character)
                local feedback = RivalsRuntimeBridge.CombatFeedback
                if not feedback.ReadToggle('P1S16T1') then
                    return
                end
                if feedback.ReadToggle('P1S16T2') then
                    feedback.PlaySound(
                        feedback.ReadOption('P1S16D1', nil),
                        feedback.ReadOption('P1S16S1', 1),
                        feedback.ReadOption('P1S16S2', 1)
                    )
                end
                if feedback.ReadToggle('P1S16T3') then
                    local colorOption = Options and Options.P1S16C1
                    feedback.CreateChams(
                        character,
                        colorOption and colorOption.Value,
                        colorOption and colorOption.Transparency,
                        feedback.ReadOption('P1S16S3', 0.8),
                        feedback.ReadOption('P1S16D2', 'Ghost')
                    )
                end
            end

            -- Effect packets are not laid out at fixed argument positions. Item-scoped
            -- effects are wrapped in an outer (fighterId, ItemChanged) pair, so:
            --   flat    (ReplicationChanged, objectId, DamageNumberEffect, payload...)
            --   nested  (ReplicationChanged, fighterId, ItemChanged, itemId, ShootEffect, payload...)
            -- Locate the effect token wherever it sits. The object it belongs to is the
            -- argument immediately before it, and the payload starts immediately after.
            -- This matches how evilrollerplayers reads the stream and covers both layouts.
            -- Wire grammar is (kind, objectId, outerEnum, [innerId, innerEnum,] payload...),
            -- so argument 3 is ALWAYS the outer enum. The argument before the effect token
            -- is therefore only the owning object when that token is not sitting at index 4.
            -- Measured on live build 1035 traffic: DamageNumberEffect and EliminationEffect
            -- arrive as the outer enum (index 3, owner at 2), ShootEffect nests under
            -- ItemChanged with its own item id (index 5, owner at 4), and FinisherEffect
            -- nests under EntityChanged (index 4, owner still at 2). Reading index-1 there
            -- handed the finisher branch an encoded 'EntityChanged' token as an object id,
            -- which never resolves to a character - the same dead-branch shape as the
            -- original Bullet Tracers defect.
            function RivalsRuntimeBridge.CombatFeedback.ResolveEffectPacket(packet)
                local tokens = RivalsRuntimeBridge.CombatFeedback.EnumTokens
                for index = 3, packet.n do
                    local value = packet[index]
                    local matched = nil
                    if type(value) == 'string' then
                        for name, token in pairs(tokens) do
                            if value == token then
                                matched = name
                                break
                            end
                        end
                    end
                    if matched then
                        local objectId = (index == 4) and packet[2] or packet[index - 1]
                        if type(objectId) == 'string' then
                            return matched, objectId, index
                        end
                    end
                end
                return nil
            end

            function RivalsRuntimeBridge.CombatFeedback.HandleReplicate(...)
                local feedback = RivalsRuntimeBridge.CombatFeedback
                local packet = table.pack(...)
                local effectName, objectId, index = feedback.ResolveEffectPacket(packet)
                if not effectName then
                    return
                end

                if effectName == 'ShootEffect' and feedback.ReadToggle('P1S18T1') then
                    feedback.HandleShootEffect(objectId, packet[index + 1])
                elseif effectName == 'DamageNumberEffect' and feedback.ReadToggle('P1S15T1') then
                    local localFighter = ResolveLocalFighter()
                    if not localFighter or feedback.ResolveFighterObjectId(localFighter) ~= objectId then
                        return
                    end
                    local hitPart, damage, isHead = packet[index + 1], packet[index + 2], packet[index + 3]
                    if typeof(hitPart) ~= 'Instance' then
                        return
                    end
                    local character = hitPart:FindFirstAncestorOfClass('Model')
                    while character and not character:FindFirstChildOfClass('Humanoid')
                        and character.Parent and character.Parent:IsA('Model') do character = character.Parent end
                    if typeof(character) ~= 'Instance' or not character:IsA('Model') then
                        return
                    end
                    feedback.HandleHit(damage, isHead == true and 'Head' or 'Body', character)
                elseif effectName == 'EliminationEffect' and feedback.ReadToggle('P1S16T1') then
                    local localFighter = ResolveLocalFighter()
                    if not localFighter or feedback.ResolveFighterObjectId(localFighter) ~= objectId then
                        return
                    end
                    -- The eliminated entity arrives as a Player for real opponents but
                    -- as a plain character Model for practice-range dummies. Resolve a
                    -- character when one exists (chams); the sound plays either way.
                    local eliminated = packet[index + 1]
                    if eliminated == LP or (LP.Character and eliminated == LP.Character) then
                        return
                    end
                    local character = nil
                    if typeof(eliminated) == 'Instance' then
                        if eliminated:IsA('Player') then
                            character = eliminated.Character
                        elseif eliminated:IsA('Model') then
                            character = eliminated
                        end
                    end
                    if not character then character = feedback.ResolveCharacterByObjectId(eliminated) end
                    feedback.HandleKill(character)
                elseif effectName == 'FinisherEffect' and feedback.ReadToggle('P1S16T1') then
                    if packet[index + 3] ~= LP then
                        return
                    end
                    -- Dummies can despawn before this packet lands; the sound must not
                    -- depend on the character still resolving.
                    feedback.HandleKill(feedback.ResolveCharacterByObjectId(objectId))
                end
            end

            function RivalsRuntimeBridge.CombatFeedback.ResolveEnumTokens()
                local feedback = RivalsRuntimeBridge.CombatFeedback
                local enumLibrary = ResolveEnumLibrary()
                if not enumLibrary or enumLibrary._enum_builder_complete ~= true or type(enumLibrary.ToEnum) ~= 'function' then
                    return false
                end
                for _, enumName in ipairs({'ShootEffect', 'DamageNumberEffect', 'EliminationEffect', 'FinisherEffect'}) do
                    local ok, token = pcall(enumLibrary.ToEnum, enumLibrary, enumName)
                    if not ok or type(token) ~= 'string' then
                        return false
                    end
                    feedback.EnumTokens[enumName] = token
                end
                return true
            end

            function RivalsRuntimeBridge.CombatFeedback.RefreshBinding()
                local feedback = RivalsRuntimeBridge.CombatFeedback
                if not feedback.IsEnabled() then
                    feedback.BindingGeneration = feedback.BindingGeneration + 1
                    feedback.BindingPending = false
                    feedback.BindingConnected = false
                    if Connections then
                        Connections:disconnect({'CombatFeedback_Replicate', 'CombatFeedback_ReplicateUnreliable',
                            'CombatFeedback_EnemyReplicate', 'CombatFeedback_EnemyReplicateUnreliable'})
                    end
                    return
                end
                if feedback.BindingConnected or feedback.BindingPending or not Connections then
                    return
                end

                feedback.BindingPending = true
                feedback.BindingGeneration = feedback.BindingGeneration + 1
                local generation = feedback.BindingGeneration
                BeginReplicatedStateBoot()
                task.spawn(GuardRivalsCallback('CombatFeedback_Bind', function()
                    local deadline = tick() + 30
                    while feedback.IsEnabled() and feedback.BindingGeneration == generation
                        and not ReplicatedStateReady and tick() < deadline do
                        task.wait(0.1)
                    end
                    if not feedback.IsEnabled() or feedback.BindingGeneration ~= generation
                        or not ReplicatedStateReady or not feedback.ResolveEnumTokens() then
                        feedback.BindingPending = false
                        return
                    end

                    local remotes = ReplicatedStorage:FindFirstChild('Remotes')
                    local replication = remotes and remotes:FindFirstChild('Replication')
                    local fighter = replication and replication:FindFirstChild('Fighter')
                    local enemy = replication and replication:FindFirstChild('Enemy')
                    -- Combat effects ride the unreliable channel; the reliable one carries
                    -- state sync only. Bind both so nothing is missed if RIVALS moves them.
                    -- Practice-range dummies replicate as Enemy objects with their own remote
                    -- pair, and their kill effect (FinisherEffect, killer Player at payload+3)
                    -- arrives ONLY on the Enemy channel - captured live. Without
                    -- these binds dummy kills never reach kill feedback.
                    local replicate = fighter and fighter:FindFirstChild('Replicate')
                    local unreliable = fighter and fighter:FindFirstChild('ReplicateUnreliable')
                    local enemyReplicate = enemy and enemy:FindFirstChild('Replicate')
                    local enemyUnreliable = enemy and enemy:FindFirstChild('ReplicateUnreliable')
                    if not replicate and not unreliable then
                        feedback.BindingPending = false
                        return
                    end
                    Connections:disconnect({'CombatFeedback_Replicate', 'CombatFeedback_ReplicateUnreliable',
                        'CombatFeedback_EnemyReplicate', 'CombatFeedback_EnemyReplicateUnreliable'})
                    if replicate then
                        Connections:register('CombatFeedback_Replicate', replicate.OnClientEvent:Connect(
                            GuardRivalsCallback('CombatFeedback_Replicate', feedback.HandleReplicate)))
                    end
                    if unreliable then
                        Connections:register('CombatFeedback_ReplicateUnreliable', unreliable.OnClientEvent:Connect(
                            GuardRivalsCallback('CombatFeedback_ReplicateUnreliable', feedback.HandleReplicate)))
                    end
                    if enemyReplicate then
                        Connections:register('CombatFeedback_EnemyReplicate', enemyReplicate.OnClientEvent:Connect(
                            GuardRivalsCallback('CombatFeedback_EnemyReplicate', feedback.HandleReplicate)))
                    end
                    if enemyUnreliable then
                        Connections:register('CombatFeedback_EnemyReplicateUnreliable', enemyUnreliable.OnClientEvent:Connect(
                            GuardRivalsCallback('CombatFeedback_EnemyReplicateUnreliable', feedback.HandleReplicate)))
                    end
                    feedback.BindingPending = false
                    feedback.BindingConnected = true
                end))
            end

            function RivalsRuntimeBridge.CombatFeedback.Destroy()
                local feedback = RivalsRuntimeBridge.CombatFeedback
                feedback.BindingGeneration = feedback.BindingGeneration + 1
                feedback.BindingPending = false
                feedback.BindingConnected = false
                if Connections then
                    Connections:disconnect({'CombatFeedback_Replicate', 'CombatFeedback_ReplicateUnreliable',
                        'CombatFeedback_EnemyReplicate', 'CombatFeedback_EnemyReplicateUnreliable'})
                end
                for _, cham in ipairs(feedback.Chams) do
                    if cham.Model then
                        pcall(function()
                            cham.Model:Destroy()
                        end)
                    end
                end
                feedback.Chams = {}
                for _, tracer in ipairs(feedback.Tracers) do
                    pcall(function()
                        tracer.Beam:Destroy()
                        tracer.Near:Destroy()
                        tracer.Far:Destroy()
                    end)
                end
                feedback.Tracers = {}
                feedback.EnumTokens = {}
            end

            do
                local diag = {
                    Counts = {},
                    LastRejections = {},
                    RecentLocks = {},
                    WindowStart = 0,
                    Notification = nil,
                    LastDescription = nil,
                    LastAcquiredName = nil,
                    LastAcquiredAt = 0,
                    Unavailable = false,
                }

                local function isEnabled()
                    return Toggles.P9S2T19 and Toggles.P9S2T19.Value == true
                end

                function RivalsRuntimeBridge.RecordTargetValidityRejection(gate, subject, player, targetType, extras)
                    if not isEnabled() then return end
                    local now = tick()
                    if now - diag.WindowStart > 1 then
                        diag.Counts = {}
                        diag.WindowStart = now
                    end
                    diag.Counts[gate] = (diag.Counts[gate] or 0) + 1
                    local name = 'unknown'
                    if player then
                        name = player.DisplayName or player.Name or name
                    elseif subject and subject.Name then
                        name = subject.Name
                    end
                    local rejections = diag.LastRejections
                    rejections[#rejections + 1] = {
                        name = name,
                        gate = gate,
                        at = now,
                        targetType = targetType,
                        extras = extras,
                    }
                    while #rejections > 5 do
                        table.remove(rejections, 1)
                    end
                end

                function RivalsRuntimeBridge.RecordTargetValidityAcquired(name, info)
                    if not isEnabled() then return end
                    local now = tick()
                    diag.LastAcquiredName = name or 'unknown'
                    diag.LastAcquiredAt = now
                    local locks = diag.RecentLocks
                    locks[#locks + 1] = {
                        name = diag.LastAcquiredName,
                        at = now,
                        targetType = info and info.targetType or nil,
                        aimPart = info and info.aimPart or nil,
                        isVisible = info and info.isVisible == true,
                        screenDistance = info and info.screenDistance or nil,
                        worldDistance = info and info.worldDistance or nil,
                    }
                    while #locks > 3 do
                        table.remove(locks, 1)
                    end
                end

                -- Upstream gates fire BEFORE BuildAimbotTargetInfo runs, so they
                -- never appear in the regular rejection counts. When the aim
                -- "drops" silently this is usually one of game_not_ready /
                -- camera_not_ready / mouse_not_held / silent_blocked:<reason>.
                -- We only count these (no LastRejections entry) so the per-target
                -- rejection list stays focused on player events.
                function RivalsRuntimeBridge.RecordTargetValidityUpstreamGate(gate)
                    if not isEnabled() then return end
                    local now = tick()
                    if now - diag.WindowStart > 1 then
                        diag.Counts = {}
                        diag.WindowStart = now
                    end
                    diag.Counts[gate] = (diag.Counts[gate] or 0) + 1
                end

                -- Live snapshot of every gate that affects target acquisition.
                -- Mirrors IsReadyToFight() (gates 1-5) plus the inputs that
                -- IsLocalReadyToFight() weighs (shield latch, invincible flag,
                -- shooting-range flag) plus the tracked-target pool sizes the
                -- aimbot iterates each tick. Watching this section while the
                -- aimbot misbehaves shows exactly which boolean is flipping.
                local function buildReadinessSnapshot()
                    local function safeBool(fn)
                        if type(fn) ~= 'function' then return false end
                        local ok, v = pcall(fn)
                        return ok and v == true
                    end
                    local fighter = ResolveLocalFighter()
                    local entity = fighter and fighter.Entity
                    local liveChar = LP and LP.Character
                    local duel = FighterDataCache and FighterDataCache.LocalDuel or nil
                    local localReadyState = RivalsRuntimeBridge.LocalReadyState
                    local rangeCount, dummyCount = 0, 0
                    for _ in pairs(TrackedRangeTargets) do rangeCount = rangeCount + 1 end
                    for _ in pairs(TrackedPracticeDummies) do dummyCount = dummyCount + 1 end
                    return {
                        cameraReady = safeBool(IsAimbotCameraReady),
                        gameReady = safeBool(IsAimbotGameReady),
                        charInWorkspace = liveChar ~= nil and liveChar.Parent == Workspace,
                        entityInWorld = type(entity) == 'table' and rawget(entity, '_is_in_world') == true,
                        invincible = type(entity) == 'table' and type(entity.Data) == 'table' and entity.Data.IsInvincible == true,
                        shieldSeen = type(localReadyState) == 'table' and localReadyState.ShieldSeen == true,
                        readyNotified = type(localReadyState) == 'table' and localReadyState.ReadyNotified == true,
                        duelSeeded = type(duel) == 'table' and duel.Seeded == true,
                        inDuel = type(duel) == 'table' and duel.IsInDuel == true,
                        inShootingRange = type(duel) == 'table' and duel.Seeded == true and duel.IsInShootingRange == true,
                        localReady = safeBool(RivalsRuntimeBridge.IsLocalReadyToFight),
                        readyToFight = safeBool(RivalsRuntimeBridge.IsReadyToFight),
                        rangeCount = rangeCount,
                        dummyCount = dummyCount,
                    }
                end

                local function buildText()
                    local now = tick()
                    local lines = { 'Target Validity Diagnostic' }
                    local counts = diag.Counts
                    local keys = {}
                    for k in pairs(counts) do keys[#keys + 1] = k end
                    table.sort(keys, function(a, b) return counts[a] > counts[b] end)
                    if #keys == 0 then
                        lines[#lines + 1] = 'Last 1s rejections: none'
                    else
                        lines[#lines + 1] = 'Last 1s rejections:'
                        for _, k in ipairs(keys) do
                            lines[#lines + 1] = string.format('  %s x %d', k, counts[k])
                        end
                    end
                    -- Filter Recent rejections to player events. Dummy/range
                    -- entries would otherwise flood this list and mask the
                    -- player rejections the user wants to see. Counts above
                    -- stay total (dummy noise is still visible per-gate); only
                    -- the per-target list is filtered. Legacy entries without
                    -- targetType (predate this change) are kept for safety.
                    local rej = diag.LastRejections
                    if #rej > 0 then
                        local visible = {}
                        for i = 1, #rej do
                            local r = rej[i]
                            if not r.targetType or r.targetType == 'Players' then
                                visible[#visible + 1] = r
                            end
                        end
                        if #visible > 0 then
                            lines[#lines + 1] = 'Recent:'
                            for i = #visible, math.max(1, #visible - 2), -1 do
                                local r = visible[i]
                                lines[#lines + 1] = string.format('  %s: %s (%.2fs)', r.name, r.gate, math.max(0, now - r.at))
                            end
                        end
                    end
                    local locks = diag.RecentLocks
                    if #locks > 0 then
                        lines[#lines + 1] = 'Recent locks:'
                        for i = #locks, math.max(1, #locks - 2), -1 do
                            local l = locks[i]
                            local visTag
                            if l.isVisible then
                                visTag = 'y'
                            else
                                visTag = 'n'
                            end
                            local detail = string.format('aim=%s vis=%s', tostring(l.aimPart or '?'), visTag)
                            if l.screenDistance then
                                detail = detail .. string.format(' sd=%d', math.floor(l.screenDistance + 0.5))
                            end
                            lines[#lines + 1] = string.format('  %s [%s] (%.2fs)', l.name, detail, math.max(0, now - l.at))
                        end
                    elseif diag.LastAcquiredName then
                        lines[#lines + 1] = string.format('Last lock: %s (%.2fs ago)', diag.LastAcquiredName, math.max(0, now - diag.LastAcquiredAt))
                    else
                        lines[#lines + 1] = 'Last lock: none'
                    end
                    local snapshotOk, snapshot = pcall(buildReadinessSnapshot)
                    if snapshotOk and type(snapshot) == 'table' then
                        local function tag(b) return b and 'Y' or 'N' end
                        lines[#lines + 1] = 'Gates:'
                        lines[#lines + 1] = string.format('  CamReady=%s GameReady=%s', tag(snapshot.cameraReady), tag(snapshot.gameReady))
                        lines[#lines + 1] = string.format('  CharInWS=%s EntityInWorld=%s', tag(snapshot.charInWorkspace), tag(snapshot.entityInWorld))
                        lines[#lines + 1] = string.format('  Invincible=%s ShieldSeen=%s ReadyNotified=%s', tag(snapshot.invincible), tag(snapshot.shieldSeen), tag(snapshot.readyNotified))
                        lines[#lines + 1] = string.format('  DuelSeeded=%s InDuel=%s InShootingRange=%s', tag(snapshot.duelSeeded), tag(snapshot.inDuel), tag(snapshot.inShootingRange))
                        lines[#lines + 1] = string.format('  LocalReady=%s ReadyToFight=%s', tag(snapshot.localReady), tag(snapshot.readyToFight))
                        lines[#lines + 1] = string.format('Pools: range=%d dummies=%d', snapshot.rangeCount, snapshot.dummyCount)
                    end
                    return table.concat(lines, '\n')
                end

                local function ensureNotif(description)
                    if diag.Notification then return true end
                    if diag.Unavailable then return false end
                    if not Library or type(Library.Notify) ~= 'function' then return false end
                    local ok, n = pcall(function()
                        return Library:Notify({ Title = 'Target Validity', Description = description, Persist = true })
                    end)
                    if ok and n then diag.Notification = n; return true end
                    diag.Unavailable = true
                    return false
                end

                local function destroyNotif()
                    if diag.Notification then
                        pcall(function() diag.Notification:Destroy() end)
                        diag.Notification = nil
                    end
                    diag.LastDescription = nil
                    diag.Unavailable = false
                end

                local function updateNotif()
                    if not isEnabled() then
                        destroyNotif()
                        return
                    end
                    local description = buildText()
                    if diag.LastDescription == description then return end
                    if not ensureNotif(description) then return end
                    pcall(function() diag.Notification:ChangeDescription(description) end)
                    diag.LastDescription = description
                end

                task.spawn(function()
                    while not Library.Unloaded and task.wait(0.25) do
                        pcall(updateNotif)
                    end
                    destroyNotif()
                end)
            end

            do

            local ResolveAimbotSilentHookTarget = function(item)
                local state = AimbotSilentState
                local now = tick()
                local cacheWindow = AimbotBridge.ResolveAimbotSilentHookTargetCacheWindow(item)
                local cachedTarget = state.HookTarget

                if cachedTarget and state.HookTargetCapturedAt > 0 and (now - state.HookTargetCapturedAt) <= cacheWindow then
                    local aimPart = Options.P2S1D2 and Options.P2S1D2.Value or 'Auto'
                    local mousePosition = AimbotBridge.GetAimbotPointerPosition()
                    local maxDistance = DEFAULT_ESP_MAX_DISTANCE
                    local refreshedTarget = RivalsRuntimeBridge.RefreshAimbotTargetInfo(cachedTarget, aimPart, mousePosition, maxDistance, AIMBOT_VISIBILITY_CACHE_PROFILE)
                    if refreshedTarget then
                        state.HookTarget = refreshedTarget
                        return refreshedTarget
                    end
                end

                local targetInfo = RivalsRuntimeBridge.GetBestAimbotTarget()
                state.HookTarget = targetInfo
                state.HookTargetCapturedAt = targetInfo and now or 0
                return targetInfo
            end

            local ShouldBypassAimbotSilentReloadBlock = function(item, state, holdWindow, now, queuePending, inputSpammingFlag)
                if AimbotBridge.ReadAimbotSilentToggle('P9S2T6', true) and queuePending and not (AimbotBridge.ReadAimbotSilentToggle('P9S2T7', true) and inputSpammingFlag) then
                    return true
                end

                if AimbotBridge.ReadAimbotSilentToggle('P9S2T14', true) and holdWindow > 0 and state.ShotSignalAt > 0 and (now - state.ShotSignalAt) <= holdWindow then
                    return true
                end

                if AimbotBridge.ReadAimbotSilentToggle('P9S2T15', true) and holdWindow > 0 and state.ProjectileShotAt > 0 and (now - state.ProjectileShotAt) <= holdWindow then
                    return true
                end

                if AimbotBridge.ReadAimbotSilentToggle('P9S2T16', true) and item and rawget(item, '_is_using') then
                    return true
                end

                if AimbotBridge.ReadAimbotSilentToggle('P9S2T17', true) and item and rawget(item, '_is_throwing') then
                    return true
                end

                return false
            end

            local EvaluateAimbotSilentRuntime = function(item, shootInputHeld)
                AimbotBridge.EnsureAimbotSilentConnections(item)

                local state = AimbotSilentState
                local lastShot = AimbotBridge.ReadAimbotLastShot(item)
                if type(lastShot) == 'number' and type(state.LastShot) == 'number' and lastShot > state.LastShot then
                    state.LastShotChangedAt = tick()
                end
                state.LastShot = lastShot

                local info = item and item.Info or nil
                local shootRemaining = AimbotBridge.ReadAimbotShootRemaining(item)
                local reloadRemaining = AimbotBridge.ReadAimbotReloadRemaining(item)
                local burstCount = type(item and rawget(item, '_burst_count')) == 'number' and rawget(item, '_burst_count') or 0
                local queuePending = item and rawget(item, '_is_input_queueing') == true
                local isCharging = AimbotBridge.ReadAimbotIsCharging(item)
                local inputSpammingFlag = info and info.InputSpammingEnabled and info.InputSpammingEnabled.StartShooting
                local holdWindow = AimbotBridge.ResolveAimbotSilentHoldWindow(item)
                local now = tick()
                local reasons = {}
                local shouldAim = true
                local blockedReason = nil
                local bypassReloadBlock = ShouldBypassAimbotSilentReloadBlock(item, state, holdWindow, now, queuePending, inputSpammingFlag)

                if AimbotBridge.ReadAimbotSilentToggle('P9S2T2', true) and shootInputHeld and reloadRemaining > 0 and not isCharging and not bypassReloadBlock then
                    blockedReason = 'reload_cooldown'
                    shouldAim = false
                end

                if AimbotBridge.ReadAimbotSilentToggle('P9S2T18', true) and isCharging then
                    reasons[#reasons + 1] = 'is_charging'
                end

                if AimbotBridge.ReadAimbotSilentToggle('P9S2T3', true) and shootRemaining > 0 then
                    reasons[#reasons + 1] = 'shoot_cooldown'
                end

                if AimbotBridge.ReadAimbotSilentToggle('P9S2T4', true) and holdWindow > 0 and state.LastShotChangedAt > 0 and (now - state.LastShotChangedAt) <= holdWindow then
                    reasons[#reasons + 1] = 'last_shot'
                end

                if AimbotBridge.ReadAimbotSilentToggle('P9S2T5', true) and burstCount > 0 then
                    reasons[#reasons + 1] = 'burst_count'
                end

                if AimbotBridge.ReadAimbotSilentToggle('P9S2T6', true) and queuePending and not (AimbotBridge.ReadAimbotSilentToggle('P9S2T7', true) and inputSpammingFlag) then
                    reasons[#reasons + 1] = 'queue_pending'
                end

                if AimbotBridge.ReadAimbotSilentToggle('P9S2T9', true) and type(info and info.ShootBurst) == 'number' and info.ShootBurst > 1 and burstCount > 0 then
                    reasons[#reasons + 1] = 'shoot_burst_info'
                end

                if AimbotBridge.ReadAimbotSilentToggle('P9S2T14', true) and holdWindow > 0 and state.ShotSignalAt > 0 and (now - state.ShotSignalAt) <= holdWindow then
                    reasons[#reasons + 1] = 'shot_signal'
                end

                if AimbotBridge.ReadAimbotSilentToggle('P9S2T15', true) and holdWindow > 0 and state.ProjectileShotAt > 0 and (now - state.ProjectileShotAt) <= holdWindow then
                    reasons[#reasons + 1] = 'projectile_signal'
                end

                if AimbotBridge.ReadAimbotSilentToggle('P9S2T16', true) and item and rawget(item, '_is_using') then
                    reasons[#reasons + 1] = 'is_using'
                end

                if AimbotBridge.ReadAimbotSilentToggle('P9S2T17', true) and item and rawget(item, '_is_throwing') then
                    reasons[#reasons + 1] = 'is_throwing'
                end

                if blockedReason then
                    return {
                        shouldAim = false,
                        blockedReason = blockedReason,
                        reasons = reasons,
                        shootRemaining = shootRemaining,
                        reloadRemaining = reloadRemaining,
                        burstCount = burstCount,
                        queuePending = queuePending,
                        isCharging = isCharging,
                        inputSpammingFlag = inputSpammingFlag,
                        holdWindow = holdWindow,
                        lastShot = lastShot,
                        aimScopePercent = info and info.AimScopePercent or nil,
                        toggleAimEnabled = item and item.ToggleAimEnabled or nil,
                    }
                end

                if #reasons == 0 then
                    reasons[#reasons + 1] = shootInputHeld and 'held_input' or 'keybind'
                end

                return {
                    shouldAim = shouldAim,
                    blockedReason = nil,
                    reasons = reasons,
                    shootRemaining = shootRemaining,
                    reloadRemaining = reloadRemaining,
                    burstCount = burstCount,
                    queuePending = queuePending,
                    isCharging = isCharging,
                    inputSpammingFlag = inputSpammingFlag,
                    holdWindow = holdWindow,
                    lastShot = lastShot,
                    aimScopePercent = info and info.AimScopePercent or nil,
                    toggleAimEnabled = item and item.ToggleAimEnabled or nil,
                }
            end

            local EnsureAimbotStatusNotification = function(description)
                if AimbotStatusNotification then
                    return true
                end

                local notification = Library:Notify({
                    Title = 'Aimbot',
                    Description = description,
                    Persist = true,
                })

                if notification then
                    AimbotStatusNotification = notification
                    return true
                end
                return false
            end

            local FormatAimbotStatusNumber = function(value)
                if type(value) ~= 'number' then
                    return '--'
                end
                return string.format('%.3f', value)
            end

            local DestroyAimbotStatusNotification = function()
                if AimbotStatusNotification then
                    pcall(function()
                        AimbotStatusNotification:Destroy()
                    end)
                    AimbotStatusNotification = nil
                end
                AimbotStatusKey = nil
                AimbotStatusDescription = nil
            end

            local NotifyAimbotStatus = function(statusKey, description, force)
                local statusNotifications = Toggles.P2S1T6 and Toggles.P2S1T6.Value
                if not force and not statusNotifications then
                    DestroyAimbotStatusNotification()
                    return
                end

                description = tostring(description or 'Idle')
                if AimbotStatusKey == statusKey and AimbotStatusDescription == description then
                    return
                end

                if not EnsureAimbotStatusNotification(description) then
                    return
                end

                if AimbotStatusDescription ~= description then
                    pcall(function()
                        AimbotStatusNotification:ChangeDescription(description)
                    end)
                end

                AimbotStatusKey = statusKey
                AimbotStatusDescription = description
            end

            local BuildAimbotSilentStatus = function(targetInfo, evaluation)
                local targetName = targetInfo and targetInfo.displayName or 'No target'

                if not AimbotBridge.ResolveAimbotSilentDebugEnabled() then
                    if evaluation.blockedReason then
                        return string.format('Silent Camera blocked: %s', evaluation.blockedReason)
                    end
                    return string.format('Silent Camera: %s', targetName)
                end

                local lines = {
                    string.format('Silent Camera: %s', targetName),
                    string.format('Reason: %s', evaluation.blockedReason or table.concat(evaluation.reasons, ', ')),
                    string.format(
                        'Live: sc %s | rc %s | bc %s | q %s | chg %s | hw %s',
                        FormatAimbotStatusNumber(evaluation.shootRemaining),
                        FormatAimbotStatusNumber(evaluation.reloadRemaining),
                        tostring(evaluation.burstCount),
                        evaluation.queuePending and 'yes' or 'no',
                        evaluation.isCharging and 'yes' or 'no',
                        FormatAimbotStatusNumber(evaluation.holdWindow)
                    ),
                }

                if AimbotBridge.ReadAimbotSilentToggle('P9S2T7', true) then
                    lines[#lines + 1] = string.format('InputSpam: %s', tostring(evaluation.inputSpammingFlag))
                end

                if AimbotBridge.ReadAimbotSilentToggle('P9S2T12', false) then
                    lines[#lines + 1] = string.format('AimScopePercent: %s', tostring(evaluation.aimScopePercent))
                end

                if AimbotBridge.ReadAimbotSilentToggle('P9S2T13', false) then
                    lines[#lines + 1] = string.format('ToggleAimEnabled: %s', tostring(evaluation.toggleAimEnabled))
                end

                if AimbotBridge.ReadAimbotSilentToggle('P9S2T4', true) then
                    lines[#lines + 1] = string.format('LastShot: %s', FormatAimbotStatusNumber(evaluation.lastShot))
                end

                return table.concat(lines, '\n')
            end

            local AppendAimbotTargetPartCandidate = function(candidates, seen, candidate)
                if candidate and candidate:IsA('BasePart') and not seen[candidate] then
                    seen[candidate] = true
                    candidates[#candidates + 1] = candidate
                end
            end

            local GetAimbotTargetPartCandidates = function(subject, aimPart)
                if not subject then
                    return {}
                end

                if subject:IsA('BasePart') then
                    if DedicatedAimbotHitboxPartNames[subject.Name] then
                        return {subject}
                    end
                    return {}
                end

                if not subject:IsA('Model') then
                    return {}
                end

                local candidates = {}
                local seen = {}
                local function addNamed(name)
                    AppendAimbotTargetPartCandidate(candidates, seen, subject:FindFirstChild(name))
                end

                if aimPart == 'Head' then
                    addNamed('HitboxHead')
                elseif aimPart == 'HumanoidRootPart' then
                    addNamed('HitboxBody')
                elseif aimPart == 'Closest' then
                    addNamed('HitboxBody')
                    addNamed('HitboxHead')
                else
                    addNamed('HitboxHead')
                    addNamed('HitboxBody')
                end

                if #candidates == 0 then
                    addNamed('HumanoidRootPart')
                end

                return candidates
            end

            local GetAimbotTargetPartSamplePoints = function(part, targetType)
                if not part or not part:IsA('BasePart') then
                    return {}
                end

                local samples = {part.Position}
                local useExtendedSampling = targetType == 'Players' or targetType == 'Practice Dummies'
                useExtendedSampling = useExtendedSampling and DedicatedAimbotHitboxPartNames[part.Name]

                if not useExtendedSampling then
                    return samples
                end

                local cframe = part.CFrame
                local halfSize = part.Size * 0.5
                local insetX = halfSize.X * 0.9
                local insetY = halfSize.Y * 0.9
                local insetZ = halfSize.Z * 0.9
                local isHeadPart = part.Name == 'HitboxHead'

                local function addLocalPoint(x, y, z)
                    samples[#samples + 1] = cframe:PointToWorldSpace(Vector3.new(x, y, z))
                end

                if isHeadPart then
                    samples = {}
                    samples[#samples + 1] = part.Position
                    addLocalPoint(0, halfSize.Y, 0)
                    addLocalPoint(0, insetY * 0.82, insetZ * 0.45)
                    addLocalPoint(0, insetY * 0.82, -insetZ * 0.45)
                    addLocalPoint(insetX * 0.55, insetY * 0.78, 0)
                    addLocalPoint(-insetX * 0.55, insetY * 0.78, 0)
                    return samples
                end

                addLocalPoint(insetX, 0, 0)
                addLocalPoint(-insetX, 0, 0)
                addLocalPoint(0, insetY, 0)
                addLocalPoint(0, -insetY, 0)
                addLocalPoint(0, 0, insetZ)
                addLocalPoint(0, 0, -insetZ)

                return samples
            end

            local ResolveVisiblePointOnAimbotPart = function(subject, candidate, targetType)
                for _, samplePoint in ipairs(GetAimbotTargetPartSamplePoints(candidate, targetType)) do
                    if IsVisible(subject, candidate, samplePoint) then
                        return samplePoint
                    end
                end
                return nil
            end

            local IsHeadAimbotTargetPart = function(candidate)
                if not candidate then
                    return false
                end

                local name = candidate.Name
                return name == 'HitboxHead'
            end
            
            local ResolveRandomVisibleAimbotTargetPart = function(subject, candidates, fallback, targetType)
                local headCandidates = {}
                local bodyCandidates = {}

                for _, candidate in ipairs(candidates) do
                    if IsHeadAimbotTargetPart(candidate) then
                        headCandidates[#headCandidates + 1] = candidate
                    else
                        bodyCandidates[#bodyCandidates + 1] = candidate
                    end
                end

                local randomBucketRoll = math.random(1, 2)
                local bucketOrder = randomBucketRoll == 1
                    and { headCandidates, bodyCandidates }
                    or { bodyCandidates, headCandidates }

                for _, bucket in ipairs(bucketOrder) do
                    local visibleCandidates = {}
                    for _, candidate in ipairs(bucket) do
                        local visiblePoint = ResolveVisiblePointOnAimbotPart(subject, candidate, targetType)
                        if visiblePoint then
                            visibleCandidates[#visibleCandidates + 1] = {
                                part = candidate,
                                point = visiblePoint,
                            }
                        end
                    end

                    if #visibleCandidates > 0 then
                        local randomIndex = math.random(1, #visibleCandidates)
                        local randomEntry = visibleCandidates[randomIndex]
                        return randomEntry.part, randomEntry.point, true
                    end
                end

                return fallback, fallback and fallback.Position or nil, false
            end

            local ResolveVisibleAimbotTargetPart
            local ResolvePrefilteredAimbotTargetPart
            do
                local ResolveVisibilityCacheProfileId = function(cacheProfile)
                    local profileId = cacheProfile and cacheProfile.Id
                    if type(profileId) == 'string' and profileId ~= '' then
                        return profileId
                    end

                    return AIMBOT_VISIBILITY_CACHE_PROFILE.Id
                end

                local ReadCachedAimbotVisibility = function(subject, aimPart, cacheProfile)
                    local now = os.clock()
                    local cachedByProfile = AimbotVisibilityCache[subject]
                    local profileId = ResolveVisibilityCacheProfileId(cacheProfile)
                    local cachedByAimPart = cachedByProfile and cachedByProfile[profileId]
                    local cachedEntry = cachedByAimPart and cachedByAimPart[aimPart]
                    if cachedEntry and cachedEntry.expiresAt >= now then
                        local cachedPart = cachedEntry.part
                        if not cachedPart or cachedPart.Parent then
                            return cachedEntry.part, cachedEntry.point, cachedEntry.isVisible, true
                        end
                    end

                    return nil, nil, nil, false
                end

                local WriteCachedAimbotVisibility = function(subject, aimPart, part, point, isVisible, cacheProfile)
                    if not subject then
                        return
                    end

                    local hiddenCacheWindow = cacheProfile and cacheProfile.HiddenWindow or AIMBOT_HIDDEN_CACHE_WINDOW
                    local visibleCacheWindow = cacheProfile and cacheProfile.VisibleWindow or AIMBOT_VISIBLE_CACHE_WINDOW
                    local cacheWindow = isVisible and visibleCacheWindow or hiddenCacheWindow
                    local profileId = ResolveVisibilityCacheProfileId(cacheProfile)
                    if cacheWindow <= 0 then
                        local cachedByProfile = AimbotVisibilityCache[subject]
                        local cachedByAimPart = cachedByProfile and cachedByProfile[profileId]
                        if cachedByAimPart then
                            cachedByAimPart[aimPart] = nil
                        end
                        return
                    end

                    local cachedByProfile = AimbotVisibilityCache[subject]
                    if not cachedByProfile then
                        cachedByProfile = {}
                        AimbotVisibilityCache[subject] = cachedByProfile
                    end

                    local cachedByAimPart = cachedByProfile[profileId]
                    if not cachedByAimPart then
                        cachedByAimPart = {}
                        cachedByProfile[profileId] = cachedByAimPart
                    end

                    cachedByAimPart[aimPart] = {
                        part = part,
                        point = point,
                        isVisible = isVisible,
                        expiresAt = os.clock() + cacheWindow,
                    }
                end

                ResolveVisibleAimbotTargetPart = function(subject, aimPart, targetType, cacheProfile)
                    cacheProfile = cacheProfile or AIMBOT_VISIBILITY_CACHE_PROFILE
                    if aimPart ~= 'Random' then
                        local cachedPart, cachedPoint, cachedVisible, hasCachedEntry = ReadCachedAimbotVisibility(subject, aimPart, cacheProfile)
                        if hasCachedEntry then
                            return cachedPart, cachedPoint, cachedVisible
                        end
                    end

                    local candidates = GetAimbotTargetPartCandidates(subject, aimPart)
                    local fallback = candidates[1]
                    if aimPart == 'Random' then
                        return ResolveRandomVisibleAimbotTargetPart(subject, candidates, fallback, targetType)
                    end

                    for _, candidate in ipairs(candidates) do
                        local visiblePoint = ResolveVisiblePointOnAimbotPart(subject, candidate, targetType)
                        if visiblePoint then
                            WriteCachedAimbotVisibility(subject, aimPart, candidate, visiblePoint, true, cacheProfile)
                            return candidate, visiblePoint, true
                        end
                    end

                    local fallbackPoint = fallback and fallback.Position or nil
                    WriteCachedAimbotVisibility(subject, aimPart, fallback, fallbackPoint, false, cacheProfile)
                    return fallback, fallbackPoint, false
                end

                ResolvePrefilteredAimbotTargetPart = function(subject, aimPart, targetType, mousePosition, maxDistance, fovRadius, ignoreFov, camera, cacheProfile)
                    if not subject or not camera then
                        return nil, nil, false
                    end

                    cacheProfile = cacheProfile or AIMBOT_VISIBILITY_CACHE_PROFILE
                    if aimPart ~= 'Random' then
                        local cachedPart, cachedPoint, cachedVisible, hasCachedEntry = ReadCachedAimbotVisibility(subject, aimPart, cacheProfile)
                        if hasCachedEntry then
                            return cachedPart, cachedPoint, cachedVisible
                        end
                    end

                    local rootPosition = HumanoidRootPart and HumanoidRootPart.Position or nil
                    local maxDistanceSquared = maxDistance * maxDistance

                    local function SamplePointPassesAimbotPrefilter(samplePoint)
                        if rootPosition then
                            local samplePointOffset = samplePoint - rootPosition
                            if samplePointOffset:Dot(samplePointOffset) > maxDistanceSquared then
                                return false
                            end
                        end

                        if ignoreFov then
                            return true
                        end

                        local screenPosition, onScreen = camera:WorldToViewportPoint(samplePoint)
                        if not onScreen or screenPosition.Z <= 0 then
                            return false
                        end

                        local screenDistance = (Vector2.new(screenPosition.X, screenPosition.Y) - mousePosition).Magnitude
                        return screenDistance <= fovRadius
                    end

                    local function ResolvePrefilteredVisiblePoint(candidate)
                        if not candidate or not candidate:IsA('BasePart') then
                            return nil, false, false
                        end

                        local fallbackPoint = nil
                        for _, samplePoint in ipairs(GetAimbotTargetPartSamplePoints(candidate, targetType)) do
                            if SamplePointPassesAimbotPrefilter(samplePoint) then
                                fallbackPoint = samplePoint
                                if IsVisible(subject, candidate, samplePoint) then
                                    return samplePoint, true, true
                                end
                            end
                        end

                        return fallbackPoint, false, fallbackPoint ~= nil
                    end

                    local candidates = GetAimbotTargetPartCandidates(subject, aimPart)
                    if aimPart == 'Closest' then
                        local closestOrigin = rootPosition or camera.CFrame.Position
                        local closestVisiblePart = nil
                        local closestVisiblePoint = nil
                        local closestVisibleDistanceSquared = nil
                        local closestFallbackPart = nil
                        local closestFallbackPoint = nil
                        local closestFallbackDistanceSquared = nil

                        for _, candidate in ipairs(candidates) do
                            if candidate and candidate:IsA('BasePart') then
                                for _, samplePoint in ipairs(GetAimbotTargetPartSamplePoints(candidate, targetType)) do
                                    if SamplePointPassesAimbotPrefilter(samplePoint) then
                                        local samplePointOffset = samplePoint - closestOrigin
                                        local samplePointDistanceSquared = samplePointOffset:Dot(samplePointOffset)
                                        if IsVisible(subject, candidate, samplePoint) then
                                            if not closestVisibleDistanceSquared or samplePointDistanceSquared < closestVisibleDistanceSquared then
                                                closestVisiblePart = candidate
                                                closestVisiblePoint = samplePoint
                                                closestVisibleDistanceSquared = samplePointDistanceSquared
                                            end
                                        elseif not closestFallbackDistanceSquared or samplePointDistanceSquared < closestFallbackDistanceSquared then
                                            closestFallbackPart = candidate
                                            closestFallbackPoint = samplePoint
                                            closestFallbackDistanceSquared = samplePointDistanceSquared
                                        end
                                    end
                                end
                            end
                        end

                        if closestVisiblePart then
                            WriteCachedAimbotVisibility(subject, aimPart, closestVisiblePart, closestVisiblePoint, true, cacheProfile)
                            return closestVisiblePart, closestVisiblePoint, true
                        end

                        if closestFallbackPart then
                            WriteCachedAimbotVisibility(subject, aimPart, closestFallbackPart, closestFallbackPoint, false, cacheProfile)
                        end

                        return closestFallbackPart, closestFallbackPoint, false
                    end
                    if aimPart == 'Random' then
                        local headCandidates = {}
                        local bodyCandidates = {}

                        for _, candidate in ipairs(candidates) do
                            if IsHeadAimbotTargetPart(candidate) then
                                headCandidates[#headCandidates + 1] = candidate
                            else
                                bodyCandidates[#bodyCandidates + 1] = candidate
                            end
                        end

                        local randomBucketRoll = math.random(1, 2)
                        local bucketOrder = randomBucketRoll == 1
                            and { headCandidates, bodyCandidates }
                            or { bodyCandidates, headCandidates }
                        local fallbackPart = nil
                        local fallbackPoint = nil

                        for _, bucket in ipairs(bucketOrder) do
                            local visibleCandidates = {}
                            for _, candidate in ipairs(bucket) do
                                local visiblePoint, isVisible, passedPrefilter = ResolvePrefilteredVisiblePoint(candidate)
                                if passedPrefilter and not fallbackPart then
                                    fallbackPart = candidate
                                    fallbackPoint = visiblePoint
                                end
                                if isVisible then
                                    visibleCandidates[#visibleCandidates + 1] = {
                                        part = candidate,
                                        point = visiblePoint,
                                    }
                                end
                            end

                            if #visibleCandidates > 0 then
                                local randomIndex = math.random(1, #visibleCandidates)
                                local randomEntry = visibleCandidates[randomIndex]
                                return randomEntry.part, randomEntry.point, true
                            end
                        end

                        return fallbackPart, fallbackPoint, false
                    end

                    local fallbackPart = nil
                    local fallbackPoint = nil
                    for _, candidate in ipairs(candidates) do
                        local visiblePoint, isVisible, passedPrefilter = ResolvePrefilteredVisiblePoint(candidate)
                        if passedPrefilter and not fallbackPart then
                            fallbackPart = candidate
                            fallbackPoint = visiblePoint
                        end
                        if isVisible then
                            WriteCachedAimbotVisibility(subject, aimPart, candidate, visiblePoint, true, cacheProfile)
                            return candidate, visiblePoint, true
                        end
                    end

                    if fallbackPart then
                        WriteCachedAimbotVisibility(subject, aimPart, fallbackPart, fallbackPoint, false, cacheProfile)
                    end

                    return fallbackPart, fallbackPoint, false
                end
            end

            local IsAimbotPlayerTargetAlive = function(subject)
                local humanoid = subject:FindFirstChild('Humanoid')
                return humanoid ~= nil and humanoid.Health > 0
            end

            local BuildAimbotTargetInfo = function(subject, targetType, aimPart, mousePosition, player, maxDistance, fovRadius, ignoreFov, camera, cacheProfile, allowHiddenTargets, requireVisible)
                if not subject or not subject.Parent then
                    RivalsRuntimeBridge.RecordTargetValidityRejection('subject_invalid', subject, player, targetType)
                    return nil
                end

                if player and not IsAimbotPlayerTargetAlive(subject) then
                    local humanoid = subject and subject:FindFirstChild('Humanoid')
                    RivalsRuntimeBridge.RecordTargetValidityRejection('not_alive', subject, player, targetType, {
                        humanoidHealth = humanoid and humanoid.Health,
                        hasHumanoid = humanoid ~= nil,
                    })
                    return nil
                end

                if player and AimbotBridge.ShouldIgnoreAimbotKatanaDeflectTarget(player, AimbotBridge.ResolveAimbotEquippedItem()) then
                    RivalsRuntimeBridge.RecordTargetValidityRejection('katana_deflect', subject, player, targetType)
                    return nil
                end

                camera = camera or Workspace.CurrentCamera
                if not camera then
                    RivalsRuntimeBridge.RecordTargetValidityRejection('no_camera', subject, player, targetType)
                    return nil
                end

                maxDistance = maxDistance or DEFAULT_ESP_MAX_DISTANCE
                if ignoreFov == nil then
                    ignoreFov = AimbotBridge.IsAimbotIgnoreFovEnabled()
                end
                if not ignoreFov and type(fovRadius) ~= 'number' then
                    fovRadius = Options.P2S1S2 and Options.P2S1S2.Value or 170
                end

                allowHiddenTargets = allowHiddenTargets == true
                requireVisible = requireVisible == true

                local equippedItem = AimbotBridge.ResolveAimbotEquippedItem()
                local equippedInfo = equippedItem and equippedItem.Info or nil
                local effectiveAimPart = ((equippedInfo and equippedInfo.Class == 'Melee') or (equippedInfo and equippedInfo.Type == 'Melee')) and 'Closest' or aimPart
                local rootPosition = HumanoidRootPart and HumanoidRootPart.Position or nil
                local maxDistanceSquared = maxDistance * maxDistance
                local part, worldPosition, isVisible = ResolvePrefilteredAimbotTargetPart(subject, effectiveAimPart, targetType, mousePosition, maxDistance, fovRadius, ignoreFov, camera, cacheProfile)
                if not part or not part:IsA('BasePart') or not worldPosition then
                    RivalsRuntimeBridge.RecordTargetValidityRejection('no_part_resolved', subject, player, targetType)
                    return nil
                end
                if requireVisible and not isVisible then
                    RivalsRuntimeBridge.RecordTargetValidityRejection('not_visible', subject, player, targetType)
                    return nil
                elseif not isVisible and not allowHiddenTargets then
                    RivalsRuntimeBridge.RecordTargetValidityRejection('not_visible', subject, player, targetType)
                    return nil
                end

                local worldDistance = 0
                if rootPosition then
                    local rootOffset = worldPosition - rootPosition
                    local worldDistanceSquared = rootOffset:Dot(rootOffset)
                    if worldDistanceSquared > maxDistanceSquared then
                        RivalsRuntimeBridge.RecordTargetValidityRejection('out_of_range', subject, player, targetType, {
                            worldDistance = math.sqrt(worldDistanceSquared),
                            maxDistance = maxDistance,
                        })
                        return nil
                    end
                    worldDistance = math.sqrt(worldDistanceSquared)
                end

                local screenPosition, onScreen = camera:WorldToViewportPoint(worldPosition)
                local isOnScreen = onScreen and screenPosition.Z > 0
                if not ignoreFov and not isOnScreen then
                    RivalsRuntimeBridge.RecordTargetValidityRejection('off_screen', subject, player, targetType)
                    return nil
                end

                local screenVector = Vector2.new(screenPosition.X, screenPosition.Y)
                local screenDistance = (screenVector - mousePosition).Magnitude
                if not ignoreFov and screenDistance > fovRadius then
                    RivalsRuntimeBridge.RecordTargetValidityRejection('out_of_fov', subject, player, targetType, {
                        screenDistance = screenDistance,
                        fovRadius = fovRadius,
                    })
                    return nil
                end

                local resolvedDisplayName = player and (player.DisplayName or player.Name) or subject.Name
                RivalsRuntimeBridge.RecordTargetValidityAcquired(resolvedDisplayName, {
                    targetType = targetType,
                    aimPart = effectiveAimPart,
                    isVisible = isVisible,
                    screenDistance = screenDistance,
                    worldDistance = worldDistance,
                })
                return {
                    instance = subject,
                    part = part,
                    player = player,
                    targetType = targetType,
                    worldPosition = worldPosition,
                    worldDistance = worldDistance,
                    screenDistance = screenDistance,
                    -- Cursor-first: any on-screen target ranks by pointer proximity,
                    -- even with Ignore FOV on (it used to fall back to worldDistance,
                    -- which made the aim grab whoever stood closest to the PLAYER).
                    -- Off-screen targets (only eligible under Ignore FOV, where the
                    -- mirrored projection makes screenDistance garbage) sort behind
                    -- everything on screen, by world distance among themselves.
                    selectionDistance = isOnScreen and screenDistance
                        or (AIMBOT_OFFSCREEN_SELECTION_PENALTY + worldDistance),
                    displayName = resolvedDisplayName,
                    isVisible = isVisible,
                }
            end

            local ConsiderBestAimbotTarget = function(bestTarget, subject, targetType, aimPart, mousePosition, maxDistance, fovRadius, ignoreFov, player, camera, cacheProfile, requireVisible)
                local targetInfo = BuildAimbotTargetInfo(subject, targetType, aimPart, mousePosition, player, maxDistance, fovRadius, ignoreFov, camera, cacheProfile, nil, requireVisible)
                if targetInfo and (not requireVisible or targetInfo.isVisible)
                    and (not bestTarget or targetInfo.selectionDistance < bestTarget.selectionDistance) then
                    return targetInfo
                end

                return bestTarget
            end

            local RefreshAimbotTargetInfo = function(targetInfo, aimPart, mousePosition, maxDistance, cacheProfile)
                if not targetInfo then
                    return nil
                end

                if targetInfo.player and not ShouldShow(targetInfo.player, false) then
                    return nil
                end

                if targetInfo.player and AimbotBridge.ShouldIgnoreAimbotKatanaDeflectTarget(targetInfo.player, AimbotBridge.ResolveAimbotEquippedItem()) then
                    return nil
                end

                local subject = targetInfo.instance
                if targetInfo.player then
                    local fighter = TrackedFightersByPlayer[targetInfo.player]
                    local entity = fighter and fighter.Entity
                    subject = entity and entity.Model
                    -- Spawn-shield policy: shielded players are
                    -- not valid aim targets anywhere. Selection skips them and this drops
                    -- a cached target whose shield is up, so the next sweep re-selects
                    -- among vulnerable players. Ragebot keeps its documented pre-track
                    -- hover; the triggerbot/aim-lock/silent emission gates stay as the
                    -- last line of defense.
                    if FighterDataCache.ReadEntity(entity) then
                        return nil
                    end
                end
                if ShouldIgnoreRivalsRiotShieldTarget(targetInfo.player, subject or (targetInfo.player and targetInfo.player.Character), AimbotBridge.ResolveAimbotEquippedItem()) then
                    return nil
                end
                return BuildAimbotTargetInfo(subject, targetInfo.targetType, aimPart, mousePosition, targetInfo.player, maxDistance, nil, nil, nil, cacheProfile)
            end

            RivalsRuntimeBridge.PrimeAimbotAim = function(targetInfo, item)
                if not targetInfo then
                    return false
                end

                if not RivalsRuntimeBridge.IsReadyToFight() then
                    RivalsRuntimeBridge.LogDiagnosticEvent('PrimeAimbotAim', 'Refused: gate closed')
                    return false
                end

                local targetPart = targetInfo.part
                local worldPosition = targetInfo.worldPosition
                local camera = Workspace.CurrentCamera
                if not targetPart or not targetPart.Parent or not worldPosition or not camera then
                    return false
                end

                camera.CFrame = CFrame.lookAt(camera.CFrame.Position, worldPosition)

                return true
            end

            RivalsRuntimeBridge.BuildAimbotTargetInfo = BuildAimbotTargetInfo
            RivalsRuntimeBridge.ConsiderBestAimbotTarget = ConsiderBestAimbotTarget
            RivalsRuntimeBridge.ResolveVisibleAimbotTargetPart = ResolveVisibleAimbotTargetPart
            RivalsRuntimeBridge.RefreshAimbotTargetInfo = RefreshAimbotTargetInfo
            RivalsRuntimeBridge.DestroyAimbotStatusNotification = DestroyAimbotStatusNotification
            RivalsRuntimeBridge.NotifyAimbotStatus = NotifyAimbotStatus
            RivalsRuntimeBridge.BuildAimbotSilentStatus = BuildAimbotSilentStatus
            RivalsRuntimeBridge.EvaluateAimbotSilentRuntime = EvaluateAimbotSilentRuntime
            RivalsRuntimeBridge.ResolveAimbotSilentHookTarget = ResolveAimbotSilentHookTarget
            end

            do
            local CursorTriggerbotRaycastFilter = {}
            local CursorTriggerbotRaycastParams = RaycastParams.new()
            CursorTriggerbotRaycastParams.FilterType = Enum.RaycastFilterType.Exclude
            CursorTriggerbotRaycastParams.FilterDescendantsInstances = CursorTriggerbotRaycastFilter
            local CursorTriggerbotRaycastFilterCharacter = nil

            local function ResolveCursorTriggerbotRaycastParams()
                local character = LP.Character
                if character ~= CursorTriggerbotRaycastFilterCharacter then
                    CursorTriggerbotRaycastFilterCharacter = character
                    CursorTriggerbotRaycastFilter[1] = character
                    CursorTriggerbotRaycastFilter[2] = nil
                    CursorTriggerbotRaycastParams.FilterDescendantsInstances = CursorTriggerbotRaycastFilter
                end

                return CursorTriggerbotRaycastParams
            end

            local function ResolveCursorTriggerbotTarget()
                EnsureAimbotTargetTracking()

                local camera = Workspace.CurrentCamera
                if not camera then
                    return nil
                end

                local mousePosition = AimbotBridge.GetAimbotPointerPosition()
                local ray = camera:ViewportPointToRay(mousePosition.X, mousePosition.Y)
                local raycastParams = ResolveCursorTriggerbotRaycastParams()

                local result = Workspace:Raycast(ray.Origin, ray.Direction * DEFAULT_ESP_MAX_DISTANCE, raycastParams)
                local hitInstance = result and result.Instance
                if not hitInstance then
                    return nil
                end

                local aimPart = Options.P2S1D2 and Options.P2S1D2.Value or 'Auto'
                local subject = hitInstance:FindFirstAncestorWhichIsA('Model')
                if not subject then
                    return nil
                end

                local player = Players:GetPlayerFromCharacter(subject)
                if player then
                    -- Spawn-shield pre-track: track during invincibility, fire-gate runs at the trigger.
                    if not ShouldShow(player, false) or ShouldIgnoreRivalsRiotShieldTarget(player, subject, AimbotBridge.ResolveAimbotEquippedItem()) then
                        return nil
                    end
                    return RivalsRuntimeBridge.BuildAimbotTargetInfo(subject, 'Players', aimPart, mousePosition, player, nil, nil, nil, nil, TRIGGERBOT_VISIBILITY_CACHE_PROFILE)
                end

                if TrackedRangeTargets[subject] then
                    return RivalsRuntimeBridge.BuildAimbotTargetInfo(subject, 'Range Targets', aimPart, mousePosition, nil, nil, nil, nil, nil, TRIGGERBOT_VISIBILITY_CACHE_PROFILE)
                end

                if TrackedPracticeDummies[subject] then
                    return RivalsRuntimeBridge.BuildAimbotTargetInfo(subject, 'Practice Dummies', aimPart, mousePosition, nil, nil, nil, nil, nil, TRIGGERBOT_VISIBILITY_CACHE_PROFILE)
                end

                return nil
            end

            local SharedTryTriggerbotShot
            local SharedGetBestTriggerbotTarget
            local GetBestTriggerbotTarget
            do
            local function IsMeleeFastFireItem(item)
                local info = item and item.Info or nil
                return info and (info.Class == 'Melee' or info.Type == 'Melee') and true or false
            end

            local function ResolveTriggerbotShotInterval(item)
                if MeleeFastFire.Enabled and IsMeleeFastFireItem(item) then
                    return MeleeFastFire.IntervalSec
                end
                local info = item and item.Info or nil
                local shotInterval = 0.05
                if type(info and info.ShootCooldown) == 'number' then
                    shotInterval = math.max(shotInterval, info.ShootCooldown)
                end
                if type(info and info.ShootBurstCooldown) == 'number' then
                    shotInterval = math.max(shotInterval, info.ShootBurstCooldown)
                end
                if type(info and info.QuickShotCooldown) == 'number' then
                    shotInterval = math.max(shotInterval, info.QuickShotCooldown)
                end
                if type(info and info.ChargeReleaseCooldown) == 'number' then
                    shotInterval = math.max(shotInterval, info.ChargeReleaseCooldown)
                end
                if type(info and info.AttackCooldown) == 'number' then
                    shotInterval = math.max(shotInterval, info.AttackCooldown)
                end
                if type(info and info.BladeCooldown) == 'number' then
                    shotInterval = math.max(shotInterval, info.BladeCooldown)
                end
                local weaponSpeedScale = ResolveRivalsWeaponSpeedScale()
                return math.max(0.05, shotInterval * weaponSpeedScale)
            end

            AimbotBridge.IsShotImmediatelyReady = function(item)
                if not item then return false end
                local interval = ResolveTriggerbotShotInterval(item)
                local lastAt = (MeleeFastFire.Enabled and IsMeleeFastFireItem(item)) and MeleeFastFire.LastShotAt or AimbotTriggerbotLastShotAt
                if (tick() - lastAt) < interval then return false end
                if AimbotBridge.ReadAimbotReloadRemaining(item) > 0 then return false end
                if AimbotBridge.ReadAimbotShootRemaining(item) > 0 then return false end
                if AimbotBridge.ReadAimbotIsCharging(item) then return false end
                return true
            end

            local function IsTriggerbotHoldItem(item)
                return item and item.Name == 'Flamethrower'
            end

            local function FireTriggerbotShot()
                if not RivalsRuntimeBridge.IsReadyToFight() then
                    RivalsRuntimeBridge.LogDiagnosticEvent('Triggerbot', 'Refused FireTriggerbotShot: gate closed')
                    return false
                end

                if AimbotInputState.SyntheticInputBlocked() then
                    return false
                end

                local now = tick()
                local item = AimbotBridge.ResolveAimbotEquippedItem()
                local isMelee = MeleeFastFire.Enabled and IsMeleeFastFireItem(item)
                local floor = isMelee and MeleeFastFire.IntervalSec or 0.05
                local lastAt = isMelee and MeleeFastFire.LastShotAt or AimbotTriggerbotLastShotAt
                if (now - lastAt) < floor then
                    return false
                end

                local pointerPosition = AimbotBridge.GetAimbotPointerPosition()
                local virtualInputManager = Instance.new('VirtualInputManager')
                virtualInputManager:SendMouseButtonEvent(pointerPosition.X, pointerPosition.Y, 0, true, game, 1)
                if IsTriggerbotHoldItem(item) then
                    AimbotSilentConnections.TriggerbotHoldingMouse = true
                    AimbotSilentConnections.TriggerbotHoldX = pointerPosition.X
                    AimbotSilentConnections.TriggerbotHoldY = pointerPosition.Y
                else
                    task.defer(function()
                        virtualInputManager:SendMouseButtonEvent(pointerPosition.X, pointerPosition.Y, 0, false, game, 1)
                    end)
                end

                if isMelee then
                    MeleeFastFire.LastShotAt = now
                else
                    AimbotTriggerbotLastShotAt = now
                end
                return true
            end

            local function TryTriggerbotShot(targetInfo, item, shouldPrime)
                if not targetInfo or not item or AimbotInputState.LeftMouse then
                    AimbotBridge.ReleaseTriggerbotMouseHold()
                    AimbotBridge.ResetTriggerbotReactionState()
                    return false
                end

                if not RivalsRuntimeBridge.IsReadyToFight() then
                    RivalsRuntimeBridge.LogDiagnosticEvent('Triggerbot', 'Refused: gate closed')
                    AimbotBridge.ReleaseTriggerbotMouseHold()
                    AimbotBridge.ResetTriggerbotReactionState()
                    return false
                end

                -- Spawn-shield fire gate: target was pre-tracked, but block emission while
                -- IsInvincible is true. The instant the flag flips, the next tick fires.
                if targetInfo.player and IsRivalsSpawnShieldActive(targetInfo.player.Character) then
                    AimbotBridge.ReleaseTriggerbotMouseHold()
                    AimbotBridge.ResetTriggerbotReactionState()
                    return false
                end

                local now = tick()
                local targetIdentity = targetInfo.player or targetInfo.instance or targetInfo.part
                local reactionTime = Options.P2S1S7 and Options.P2S1S7.Value or 0
                if AimbotSilentConnections.TriggerbotTarget ~= targetIdentity then
                    AimbotSilentConnections.TriggerbotTarget = targetIdentity
                    AimbotSilentConnections.TriggerbotTargetAcquiredAt = now
                    if reactionTime > 0 then
                        AimbotBridge.ReleaseTriggerbotMouseHold()
                        return false
                    end
                elseif (now - AimbotSilentConnections.TriggerbotTargetAcquiredAt) < reactionTime then
                    AimbotBridge.ReleaseTriggerbotMouseHold()
                    return false
                end

                local holdTriggerbot = IsTriggerbotHoldItem(item)
                if holdTriggerbot and AimbotSilentConnections.TriggerbotHoldingMouse then
                    if shouldPrime then
                        RivalsRuntimeBridge.PrimeAimbotAim(targetInfo, item)
                    end
                    return true
                end

                if AimbotBridge.ReadAimbotReloadRemaining(item) > 0 or AimbotBridge.ReadAimbotShootRemaining(item) > 0 or AimbotBridge.ReadAimbotIsCharging(item) then
                    AimbotBridge.ReleaseTriggerbotMouseHold()
                    return false
                end

                local triggerbotInterval = ResolveTriggerbotShotInterval(item)
                local isMelee = MeleeFastFire.Enabled and IsMeleeFastFireItem(item)
                local gateLastAt = isMelee and MeleeFastFire.LastShotAt or AimbotTriggerbotLastShotAt
                if (now - gateLastAt) < triggerbotInterval then
                    return false
                end

                if shouldPrime then
                    RivalsRuntimeBridge.PrimeAimbotAim(targetInfo, item)
                end

                if not holdTriggerbot then
                    AimbotBridge.ReleaseTriggerbotMouseHold()
                end

                return FireTriggerbotShot()
            end

            local CollectBestAimbotTarget = function(requireVisible, ignoreFovOverride, fovRadiusOverride)
                EnsureAimbotTargetTracking()

                local aimPart = Options.P2S1D2 and Options.P2S1D2.Value or 'Auto'
                local fovRadius = fovRadiusOverride or (Options.P2S1S2 and Options.P2S1S2.Value or 170)
                local maxDistance = DEFAULT_ESP_MAX_DISTANCE
                local ignoreFov = ignoreFovOverride
                if ignoreFov == nil then
                    ignoreFov = AimbotBridge.IsAimbotIgnoreFovEnabled()
                end
                local mousePosition = AimbotBridge.GetAimbotPointerPosition()
                local camera = Workspace.CurrentCamera
                if not camera then
                    return nil
                end

                local bestTarget = nil

                for _, fighter in ipairs(LocalFighterController and LocalFighterController.Objects or {}) do
                    local player = fighter and fighter.Player
                    if player and player ~= LP and player.Parent == Players then
                        local entity = fighter.Entity
                        local subject = entity and entity.Model
                        if not ShouldShow(player, false) then
                            RivalsRuntimeBridge.RecordTargetValidityRejection('team_or_self', subject, player, 'Players')
                        -- evilrollerplayers parity (their "Vulnerable" target rule): spawn-
                        -- shielded players are skipped at SELECTION, not just at emission.
                        -- Shots into the shield do nothing, and a shielded best-target used
                        -- to stall the lock and eat silent shots while a vulnerable enemy
                        -- stood in view. Live-verified: Data.IsInvincible is still the flag
                        -- (true while shielded, key absent otherwise).
                        elseif FighterDataCache.ReadEntity(entity) then
                            RivalsRuntimeBridge.RecordTargetValidityRejection('invincible', subject, player, 'Players')
                        elseif ShouldIgnoreRivalsRiotShieldTarget(player, subject or player.Character, AimbotBridge.ResolveAimbotEquippedItem()) then
                            RivalsRuntimeBridge.RecordTargetValidityRejection('riot_shield', subject, player, 'Players')
                        else
                            bestTarget = RivalsRuntimeBridge.ConsiderBestAimbotTarget(bestTarget, subject, 'Players', aimPart, mousePosition, maxDistance, fovRadius, ignoreFov, player, camera, AIMBOT_VISIBILITY_CACHE_PROFILE, requireVisible)
                        end
                    end
                end

                for model in pairs(TrackedRangeTargets) do
                    if not model.Parent then
                        TrackedRangeTargets[model] = nil
                    else
                        bestTarget = RivalsRuntimeBridge.ConsiderBestAimbotTarget(bestTarget, model, 'Range Targets', aimPart, mousePosition, maxDistance, fovRadius, ignoreFov, nil, camera, AIMBOT_VISIBILITY_CACHE_PROFILE, requireVisible)
                    end
                end

                for model in pairs(TrackedPracticeDummies) do
                    if not model.Parent then
                        TrackedPracticeDummies[model] = nil
                    else
                        bestTarget = RivalsRuntimeBridge.ConsiderBestAimbotTarget(bestTarget, model, 'Practice Dummies', aimPart, mousePosition, maxDistance, fovRadius, ignoreFov, nil, camera, AIMBOT_VISIBILITY_CACHE_PROFILE, requireVisible)
                    end
                end

                if fovRadiusOverride == nil then
                    RivalsRuntimeBridge.LastAimbotSweepTarget = bestTarget
                    RivalsRuntimeBridge.LastAimbotSweepAt = os.clock()
                end
                return bestTarget
            end

            local GetBestAimbotTarget = CollectBestAimbotTarget
            RivalsRuntimeBridge.GetBestAimbotTarget = GetBestAimbotTarget

            function RivalsRuntimeBridge.FlickbotNormal(rng, mean, standardDeviation)
                local first = math.max(rng:NextNumber(), 1e-15)
                local second = rng:NextNumber()
                return mean + standardDeviation
                    * (math.sqrt(-2 * math.log(first)) * math.cos(2 * math.pi * second))
            end

            function RivalsRuntimeBridge.FlickbotGamma(rng, shape, scale)
                local factor = 1
                if shape < 1 then
                    factor = rng:NextNumber() ^ (1 / shape)
                    shape = shape + 1
                end
                local adjustedShape = shape - (1 / 3)
                local root = math.sqrt(9 * adjustedShape)
                while true do
                    local sample = RivalsRuntimeBridge.FlickbotNormal(rng, 0, 1)
                    local candidate = (1 + (sample / root)) ^ 3
                    if candidate > 0 then
                        local uniform = math.max(rng:NextNumber(), 1e-15)
                        if uniform < 1 - (0.0331 * sample ^ 4)
                            or math.log(uniform) < (0.5 * sample * sample)
                                + adjustedShape * (1 - candidate + math.log(candidate)) then
                            return adjustedShape * candidate * scale * factor
                        end
                    end
                end
            end

            function RivalsRuntimeBridge.FlickbotErf(value)
                local sign = value < 0 and -1 or 1
                local magnitude = math.abs(value)
                local factor = 1 / (1 + 0.3275911 * magnitude)
                local polynomial = 0.254829592 * factor
                    - 0.284496736 * factor ^ 2
                    + 1.421413741 * factor ^ 3
                    - 1.453152027 * factor ^ 4
                    + 1.061405429 * factor ^ 5
                return sign * (1 - polynomial * math.exp(-magnitude * magnitude))
            end

            function RivalsRuntimeBridge.FlickbotLognormalCdf(timeMs, startMs, mean, sigma)
                if timeMs <= startMs then
                    return 0
                end
                return 0.5 * (1 + RivalsRuntimeBridge.FlickbotErf(
                    (math.log(timeMs - startMs) - mean) / (sigma * math.sqrt(2))
                ))
            end

            function RivalsRuntimeBridge.FlickbotLognormalPdf(timeMs, startMs, mean, sigma)
                if timeMs <= startMs then
                    return 0
                end
                local elapsed = timeMs - startMs
                local standardized = (math.log(elapsed) - mean) / sigma
                return math.exp(-0.5 * standardized * standardized)
                    / (sigma * math.sqrt(2 * math.pi) * elapsed)
            end

            function RivalsRuntimeBridge.FlickbotBump(value)
                if value <= 0 or value >= 1 then
                    return 0
                end
                return value * value * (1 - value) ^ 3 / 0.03456
            end

            function RivalsRuntimeBridge.ApplyFlickbotProfile()
                local flickbot = RivalsRuntimeBridge.Flickbot
                local durationMs = math.max(Options.P2S1S10 and Options.P2S1S10.Value or 110, 20)
                flickbot.FittsA = durationMs / 4
                flickbot.FittsB = durationMs / 4
                flickbot.TargetWidth = 80
                flickbot.PeakTimeRatio = 0.32
                flickbot.PrimarySigmaMin = 0.2
                flickbot.PrimarySigmaMax = 0.26
                flickbot.UndershootMin = 0.97
                flickbot.UndershootMax = 1
                flickbot.OvershootProbability = 0.08
                flickbot.OvershootMin = 1.01
                flickbot.OvershootMax = 1.04
                flickbot.SecondCorrectionProbability = 0
                flickbot.CorrectionSigmaMin = 0.1
                flickbot.CorrectionSigmaMax = 0.14
                flickbot.CurvatureScale = math.clamp(
                    Options.P2S1S11 and Options.P2S1S11.Value or 12,
                    0,
                    50
                ) / 1000
                local humanness = math.clamp(
                    Options.P2S1S12 and Options.P2S1S12.Value or 30,
                    0,
                    100
                ) / 30
                flickbot.OuSigma = 0.5 * humanness
                flickbot.TremorAmplitudeMin = 0.05 * humanness
                flickbot.TremorAmplitudeMax = 0.18 * humanness
                flickbot.SignalDependentNoise = 0.02
            end

            function RivalsRuntimeBridge.GenerateFlickbotTrajectory(startX, startY, targetX, targetY)
                RivalsRuntimeBridge.ApplyFlickbotProfile()
                local flickbot = RivalsRuntimeBridge.Flickbot
                local rng = flickbot.Rng
                local function randomBetween(minimum, maximum)
                    return minimum + rng:NextNumber() * (maximum - minimum)
                end
                local function normal(mean, standardDeviation)
                    return RivalsRuntimeBridge.FlickbotNormal(rng, mean, standardDeviation)
                end

                local deltaX = targetX - startX
                local deltaY = targetY - startY
                local distance = math.sqrt(deltaX * deltaX + deltaY * deltaY)
                if distance < 1 then
                    return {}
                end
                local directionX = deltaX / distance
                local directionY = deltaY / distance
                local directionAngle = math.atan2(deltaY, deltaX)
                local indexOfDifficulty = math.log(distance / flickbot.TargetWidth + 1) / math.log(2)
                local duration = math.max(
                    (flickbot.FittsA + flickbot.FittsB * indexOfDifficulty)
                        * math.exp(normal(0, 0.08)),
                    80
                )
                local distanceFactor
                if randomBetween(0, 1) < flickbot.OvershootProbability then
                    distanceFactor = randomBetween(flickbot.OvershootMin, flickbot.OvershootMax)
                else
                    distanceFactor = randomBetween(flickbot.UndershootMin, flickbot.UndershootMax)
                end
                local primaryDistance = distance * distanceFactor
                local primarySigma = randomBetween(flickbot.PrimarySigmaMin, flickbot.PrimarySigmaMax)
                local peakRatio = randomBetween(flickbot.PeakTimeRatio - 0.03, flickbot.PeakTimeRatio + 0.03)
                local primaryMean = math.log(duration * peakRatio) + primarySigma * primarySigma
                local corrections = {}
                local remaining = distance - primaryDistance
                if math.abs(remaining) > 0.5 then
                    local sign = remaining > 0 and 1 or -1
                    local correctionDistance = math.abs(remaining) * randomBetween(0.88, 1.02)
                    local correctionSigma = randomBetween(flickbot.CorrectionSigmaMin, flickbot.CorrectionSigmaMax)
                    local correctionPeak = randomBetween(0.12, 0.18)
                    corrections[#corrections + 1] = {
                        distance = correctionDistance,
                        startMs = duration * randomBetween(0.55, 0.68),
                        mean = math.log(duration * correctionPeak) + correctionSigma * correctionSigma,
                        sigma = correctionSigma,
                        directionX = directionX * sign,
                        directionY = directionY * sign,
                    }
                    local secondRemaining = remaining - correctionDistance * sign
                    if math.abs(secondRemaining) > 0.3
                        and randomBetween(0, 1) < flickbot.SecondCorrectionProbability then
                        local secondSign = secondRemaining > 0 and 1 or -1
                        local secondSigma = randomBetween(0.1, 0.16)
                        local secondPeak = randomBetween(0.08, 0.12)
                        corrections[#corrections + 1] = {
                            distance = math.abs(secondRemaining) * randomBetween(0.85, 1.05),
                            startMs = duration * randomBetween(0.78, 0.88),
                            mean = math.log(duration * secondPeak) + secondSigma * secondSigma,
                            sigma = secondSigma,
                            directionX = directionX * secondSign,
                            directionY = directionY * secondSign,
                        }
                    end
                end

                local angleScale = 0.5 + 0.8 * math.abs(math.sin(directionAngle))
                    - 0.15 * math.abs(math.cos(directionAngle))
                local curvature = distance * flickbot.CurvatureScale * angleScale * normal(0, 1)
                local tremorFrequency = randomBetween(flickbot.TremorFrequencyMin, flickbot.TremorFrequencyMax)
                local tremorAmplitude = randomBetween(flickbot.TremorAmplitudeMin, flickbot.TremorAmplitudeMax)
                local tremorPhaseX = randomBetween(0, 2 * math.pi)
                local tremorPhaseY = randomBetween(0, 2 * math.pi)
                local noiseX = 0
                local noiseY = 0
                local endTime = duration * 1.15
                local sampleTimes = {}
                local sampleTime = 0
                while sampleTime < endTime do
                    sampleTime = sampleTime + math.clamp(
                        RivalsRuntimeBridge.FlickbotGamma(
                            rng,
                            flickbot.GammaShape,
                            flickbot.SampleDeltaMean / flickbot.GammaShape
                        ),
                        2,
                        25
                    )
                    if sampleTime <= endTime + 15 then
                        sampleTimes[#sampleTimes + 1] = sampleTime
                    end
                end

                local trajectory = {}
                for index, timeMs in ipairs(sampleTimes) do
                    local deltaMs = index > 1 and (timeMs - sampleTimes[index - 1]) or flickbot.SampleDeltaMean
                    local deltaSeconds = deltaMs / 1000
                    local primaryProgress = RivalsRuntimeBridge.FlickbotLognormalCdf(
                        timeMs,
                        0,
                        primaryMean,
                        primarySigma
                    )
                    local x = startX + directionX * primaryDistance * primaryProgress
                        - directionY * curvature * RivalsRuntimeBridge.FlickbotBump(primaryProgress)
                    local y = startY + directionY * primaryDistance * primaryProgress
                        + directionX * curvature * RivalsRuntimeBridge.FlickbotBump(primaryProgress)
                    for _, correction in ipairs(corrections) do
                        local correctionProgress = RivalsRuntimeBridge.FlickbotLognormalCdf(
                            timeMs,
                            correction.startMs,
                            correction.mean,
                            correction.sigma
                        )
                        x = x + correction.directionX * correction.distance * correctionProgress
                        y = y + correction.directionY * correction.distance * correctionProgress
                    end

                    local velocity = primaryDistance * RivalsRuntimeBridge.FlickbotLognormalPdf(
                        timeMs,
                        0,
                        primaryMean,
                        primarySigma
                    )
                    for _, correction in ipairs(corrections) do
                        velocity = velocity + correction.distance * RivalsRuntimeBridge.FlickbotLognormalPdf(
                            timeMs,
                            correction.startMs,
                            correction.mean,
                            correction.sigma
                        )
                    end
                    noiseX = noiseX + (-flickbot.OuTheta * noiseX * deltaSeconds
                        + flickbot.OuSigma * math.sqrt(deltaSeconds) * normal(0, 1))
                    noiseY = noiseY + (-flickbot.OuTheta * noiseY * deltaSeconds
                        + flickbot.OuSigma * math.sqrt(deltaSeconds) * normal(0, 1))
                    local timeSeconds = timeMs / 1000
                    local tremorScale = 1 / (1 + velocity * 0.3)
                    local tremorX = math.sin(2 * math.pi * tremorFrequency * timeSeconds + tremorPhaseX)
                    local tremorY = math.sin(2 * math.pi * tremorFrequency * timeSeconds + tremorPhaseY)
                    trajectory[#trajectory + 1] = {
                        x = x + noiseX + tremorAmplitude * tremorScale * tremorX
                            + flickbot.SignalDependentNoise * velocity * normal(0, 1),
                        y = y + noiseY + tremorAmplitude * tremorScale * tremorY
                            + flickbot.SignalDependentNoise * velocity * normal(0, 1),
                        t = timeMs,
                    }
                end
                return trajectory
            end

            function RivalsRuntimeBridge.StartFlickbot()
                local flickbot = RivalsRuntimeBridge.Flickbot
                local camera = Workspace.CurrentCamera
                if RivalsRuntimeBridge.MovementRecorder.IsCameraClaimed()
                    or not camera or not RivalsRuntimeBridge.IsReadyToFight() then
                    return false
                end
                local targetInfo = GetBestAimbotTarget(true)
                local targetPart = targetInfo and targetInfo.part or nil
                if not targetPart or not targetPart.Parent then
                    return false
                end
                local targetPoint = camera:WorldToViewportPoint(targetPart.Position)
                if targetPoint.Z <= 0 then
                    return false
                end
                local viewport = camera.ViewportSize
                local generated = RivalsRuntimeBridge.GenerateFlickbotTrajectory(
                    viewport.X * 0.5,
                    viewport.Y * 0.5,
                    targetPoint.X,
                    targetPoint.Y
                )
                if #generated < 2 then
                    return false
                end
                local trajectory = table.create(#generated)
                for index, point in ipairs(generated) do
                    trajectory[index] = {
                        direction = camera:ViewportPointToRay(point.x, point.y).Direction,
                        t = point.t,
                    }
                end
                flickbot.Trajectory = trajectory
                flickbot.TrajectoryIndex = 1
                flickbot.ElapsedMs = 0
                flickbot.TotalMs = trajectory[#trajectory].t
                flickbot.BakedEndDirection = trajectory[#trajectory].direction
                flickbot.Selected = targetInfo
                flickbot.State = 'Flicking'
                return true
            end

            function RivalsRuntimeBridge.SampleFlickbotTrajectory(deltaTime)
                local flickbot = RivalsRuntimeBridge.Flickbot
                local trajectory = flickbot.Trajectory
                flickbot.ElapsedMs = flickbot.ElapsedMs + deltaTime * 1000
                local index = flickbot.TrajectoryIndex
                while index < #trajectory and trajectory[index + 1].t <= flickbot.ElapsedMs do
                    index = index + 1
                end
                flickbot.TrajectoryIndex = index
                local current = trajectory[index]
                local following = trajectory[index + 1]
                if not following then
                    return trajectory[#trajectory].direction, true
                end
                local interval = following.t - current.t
                local alpha = interval > 0
                    and math.clamp((flickbot.ElapsedMs - current.t) / interval, 0, 1)
                    or 1
                return current.direction:Lerp(following.direction, alpha), false
            end

            function RivalsRuntimeBridge.FinishFlickbotToCooldown()
                local flickbot = RivalsRuntimeBridge.Flickbot
                flickbot.Selected = nil
                flickbot.Trajectory = nil
                local cooldownMs = math.clamp(Options.P2S1S9 and Options.P2S1S9.Value or 250, 0, 2000)
                if cooldownMs > 0 then
                    flickbot.State = 'Cooldown'
                    flickbot.Timer = cooldownMs / 1000
                else
                    flickbot.State = 'Idle'
                    flickbot.Timer = 0
                end
            end

            function RivalsRuntimeBridge.IsFlickbotCameraClaimed()
                local state = RivalsRuntimeBridge.Flickbot.State
                return state == 'Flicking' or state == 'PostShot'
            end

            function RivalsRuntimeBridge.UpdateFlickbot(deltaTime)
                local flickbot = RivalsRuntimeBridge.Flickbot
                if RivalsRuntimeBridge.MovementRecorder.IsCameraClaimed() then
                    if flickbot.State ~= 'Idle' or flickbot.WasHeld then
                        RivalsRuntimeBridge.ResetFlickbot()
                    end
                    return
                end
                local enabled = Toggles.P2S1T12 and Toggles.P2S1T12.Value == true
                local keypicker = Options.P2S1T12K
                local held = enabled and keypicker and type(keypicker.GetState) == 'function'
                    and keypicker:GetState() == true
                if not enabled then
                    if flickbot.State ~= 'Idle' or flickbot.WasHeld then
                        RivalsRuntimeBridge.ResetFlickbot()
                    end
                    return
                end
                if held and not flickbot.WasHeld and flickbot.State == 'Idle'
                    and not AimbotInputState.SyntheticInputBlocked() then
                    RivalsRuntimeBridge.StartFlickbot()
                end
                flickbot.WasHeld = held

                local frameDelta = math.clamp(type(deltaTime) == 'number' and deltaTime or (1 / 60), 0, 0.1)
                if flickbot.State == 'Flicking' then
                    local selected = flickbot.Selected
                    local targetPart = selected and selected.part or nil
                    local camera = Workspace.CurrentCamera
                    if not targetPart or not targetPart.Parent or not camera or not flickbot.Trajectory then
                        RivalsRuntimeBridge.FinishFlickbotToCooldown()
                        return
                    end
                    local direction, finished = RivalsRuntimeBridge.SampleFlickbotTrajectory(frameDelta)
                    if flickbot.TotalMs > 0 then
                        local targetOffset = targetPart.Position - camera.CFrame.Position
                        if targetOffset.Magnitude > 0.001 then
                            local progress = math.clamp(flickbot.ElapsedMs / flickbot.TotalMs, 0, 1)
                            local corrected = direction
                                + (targetOffset.Unit - flickbot.BakedEndDirection) * progress
                            if corrected.Magnitude > 0.001 then
                                direction = corrected.Unit
                            end
                        end
                    end
                    local cameraController = RivalsModsState.ResolveCameraController()
                    if cameraController and type(cameraController.SetRotation) == 'function' then
                        local pitch, yaw = CFrame.lookAt(camera.CFrame.Position, camera.CFrame.Position + direction):ToOrientation()
                        cameraController:SetRotation(Vector2.new(pitch, yaw))
                    end
                    if finished then
                        if Toggles.P2S1T13 and Toggles.P2S1T13.Value == true then
                            flickbot.State = 'PostShot'
                            flickbot.Timer = math.clamp(
                                Options.P2S1S8 and Options.P2S1S8.Value or 0,
                                0,
                                250
                            ) / 1000
                        else
                            RivalsRuntimeBridge.FinishFlickbotToCooldown()
                        end
                    end
                elseif flickbot.State == 'PostShot' then
                    -- No camera hold here: SetRotation state persists through PostShot.
                    flickbot.Timer = flickbot.Timer - frameDelta
                    if flickbot.Timer <= 0 then
                        FireTriggerbotShot()
                        RivalsRuntimeBridge.FinishFlickbotToCooldown()
                    end
                elseif flickbot.State == 'Cooldown' then
                    flickbot.Timer = flickbot.Timer - frameDelta
                    if flickbot.Timer <= 0 then
                        flickbot.State = 'Idle'
                        flickbot.Timer = 0
                    end
                end
            end

            RivalsRuntimeBridge.UpdateCameraAim = function(deltaTime)
                if RivalsRuntimeBridge.MovementRecorder.IsCameraClaimed()
                    or RivalsRuntimeBridge.IsFlickbotCameraClaimed()
                    or not AimbotBridge.IsCameraAimEnabled()
                    or not IsAimbotGameReady()
                    or not IsAimbotCameraReady()
                    or not RivalsRuntimeBridge.IsReadyToFight() then
                    AimbotBridge.ResetCameraAimRandomState()
                    return
                end

                local camera = Workspace.CurrentCamera
                local ignoreFov = AimbotBridge.IsCameraIgnoreFovEnabled()
                local targetInfo = GetBestAimbotTarget(true, ignoreFov, Options.evilrollerplayersCameraFovRadius and Options.evilrollerplayersCameraFovRadius.Value or 282)
                local configuredAimPart = Options.P2S1D2 and Options.P2S1D2.Value or 'Auto'
                if configuredAimPart == 'Random' and targetInfo then
                    local targetIdentity = targetInfo.player or targetInfo.instance
                    local stablePart = AimbotSilentConnections.CameraAimRandomPart
                    if AimbotSilentConnections.CameraAimRandomTarget == targetIdentity
                        and stablePart and stablePart.Parent then
                        local stableAimPart = IsHeadAimbotTargetPart(stablePart) and 'Head' or 'HumanoidRootPart'
                        local stableTargetInfo = RivalsRuntimeBridge.RefreshAimbotTargetInfo(
                            targetInfo,
                            stableAimPart,
                            AimbotBridge.GetAimbotPointerPosition(),
                            DEFAULT_ESP_MAX_DISTANCE,
                            AIMBOT_VISIBILITY_CACHE_PROFILE
                        )
                        if stableTargetInfo then
                            targetInfo = stableTargetInfo
                        end
                    end
                    AimbotSilentConnections.CameraAimRandomTarget = targetIdentity
                    AimbotSilentConnections.CameraAimRandomPart = targetInfo.part
                else
                    AimbotBridge.ResetCameraAimRandomState()
                end
                local targetPart = targetInfo and targetInfo.part or nil
                local worldPosition = targetInfo and targetInfo.worldPosition or nil
                if not camera or not targetPart or not targetPart.Parent or not worldPosition then
                    return
                end
                if targetInfo.player and IsRivalsSpawnShieldActive(targetInfo.player.Character) then
                    return
                end

                -- evilrollerplayers parity: never write Camera.CFrame (the native CameraController
                -- re-renders from its Rotation state every frame and stomps the write).
                -- Rotate the game's own state through CameraController:SetRotation so the
                -- game renders the turn and shot direction follows.
                local cameraController = RivalsModsState.ResolveCameraController()
                if not cameraController or type(cameraController.SetRotation) ~= 'function' then
                    return
                end
                local currentRotation = rawget(cameraController, 'Rotation')
                if typeof(currentRotation) ~= 'Vector2' then
                    return
                end

                local aimSpeed = Options.P2S2S1 and Options.P2S2S1.Value or 35
                local frameDelta = math.clamp(type(deltaTime) == 'number' and deltaTime or (1 / 60), 0, 0.1)
                local blendAlpha = math.clamp(1 - math.exp(-frameDelta * (2 + (aimSpeed * 0.58))), 0, 1)

                -- Rotation is Vector2(pitch, yaw) in radians; yaw accumulates past +/-pi,
                -- so the yaw delta must wrap to the nearest turn (evilrollerplayers's rotate-towards).
                local pitch, yaw = CFrame.lookAt(camera.CFrame.Position, worldPosition):ToOrientation()
                cameraController:SetRotation(Vector2.new(
                    currentRotation.X + (pitch - currentRotation.X) * blendAlpha,
                    currentRotation.Y + ((yaw - currentRotation.Y + math.pi) % (2 * math.pi) - math.pi) * blendAlpha
                ))
            end

            local GetBestTriggerbotTarget = function()
                EnsureAimbotTargetTracking()

                local aimPart = Options.P2S1D2 and Options.P2S1D2.Value or 'Auto'
                local fovRadius = Options.P2S1S2 and Options.P2S1S2.Value or 170
                local maxDistance = DEFAULT_ESP_MAX_DISTANCE
                local ignoreFov = AimbotBridge.IsAimbotIgnoreFovEnabled()
                local mousePosition = AimbotBridge.GetAimbotPointerPosition()
                local camera = Workspace.CurrentCamera
                if not camera then
                    return nil
                end

                local bestTarget = nil

                for _, fighter in ipairs(LocalFighterController and LocalFighterController.Objects or {}) do
                    local player = fighter and fighter.Player
                    if player and player ~= LP and player.Parent == Players then
                        local entity = fighter.Entity
                        local subject = entity and entity.Model
                        if not ShouldShow(player, false) then
                            RivalsRuntimeBridge.RecordTargetValidityRejection('team_or_self', subject, player, 'Players')
                        -- Spawn-shield selection skip, same rule as the aimbot sweep. The
                        -- TryTriggerbotShot fire gate still backstops cached targets.
                        elseif FighterDataCache.ReadEntity(entity) then
                            RivalsRuntimeBridge.RecordTargetValidityRejection('invincible', subject, player, 'Players')
                        elseif ShouldIgnoreRivalsRiotShieldTarget(player, subject or player.Character, AimbotBridge.ResolveAimbotEquippedItem()) then
                            RivalsRuntimeBridge.RecordTargetValidityRejection('riot_shield', subject, player, 'Players')
                        else
                            bestTarget = RivalsRuntimeBridge.ConsiderBestAimbotTarget(bestTarget, subject, 'Players', aimPart, mousePosition, maxDistance, fovRadius, ignoreFov, player, camera, TRIGGERBOT_VISIBILITY_CACHE_PROFILE)
                        end
                    end
                end

                for model in pairs(TrackedRangeTargets) do
                    if not model.Parent then
                        TrackedRangeTargets[model] = nil
                    else
                        bestTarget = RivalsRuntimeBridge.ConsiderBestAimbotTarget(bestTarget, model, 'Range Targets', aimPart, mousePosition, maxDistance, fovRadius, ignoreFov, nil, camera, TRIGGERBOT_VISIBILITY_CACHE_PROFILE)
                    end
                end

                for model in pairs(TrackedPracticeDummies) do
                    if not model.Parent then
                        TrackedPracticeDummies[model] = nil
                    else
                        bestTarget = RivalsRuntimeBridge.ConsiderBestAimbotTarget(bestTarget, model, 'Practice Dummies', aimPart, mousePosition, maxDistance, fovRadius, ignoreFov, nil, camera, TRIGGERBOT_VISIBILITY_CACHE_PROFILE)
                    end
                end

                RivalsRuntimeBridge.LastAimbotSweepTarget = bestTarget
                RivalsRuntimeBridge.LastAimbotSweepAt = os.clock()
                return bestTarget
            end

            SharedTryTriggerbotShot = TryTriggerbotShot
            SharedGetBestTriggerbotTarget = GetBestTriggerbotTarget
            end

            local function ResolveTriggerbotTarget(aimbotEnabled, currentTargetInfo)
                local aimPart = Options.P2S1D2 and Options.P2S1D2.Value or 'Auto'
                local maxDistance = DEFAULT_ESP_MAX_DISTANCE
                local mousePosition = AimbotBridge.GetAimbotPointerPosition()
                local refreshedTarget = currentTargetInfo and RivalsRuntimeBridge.RefreshAimbotTargetInfo(currentTargetInfo, aimPart, mousePosition, maxDistance, TRIGGERBOT_VISIBILITY_CACHE_PROFILE)
                if refreshedTarget then
                    return refreshedTarget
                end

                local cursorTargetInfo = ResolveCursorTriggerbotTarget()
                if cursorTargetInfo then
                    return cursorTargetInfo
                end

                return GetBestTriggerbotTarget()
            end

            local TryTriggerbotShot = SharedTryTriggerbotShot
            GetBestTriggerbotTarget = SharedGetBestTriggerbotTarget

            RivalsRuntimeBridge.BeginAimbotSilentShot = function(item)
                if (AimbotSilentState.ShotPrimeDepth or 0) > 0 then
                    return false, nil, nil
                end

                local enabled = AimbotBridge.IsAimbotSelected()
                local keybindActive = AimbotBridge.IsAimbotEnabled()
                local shootInputHeld = AimbotBridge.IsAimbotShootInputHeld()
                local aimAssistActive = keybindActive or shootInputHeld
                local readyToFight = RivalsRuntimeBridge.IsReadyToFight()
                RivalsRuntimeBridge.RecordCharacterLoadingCheckpoint('Silent Aim', readyToFight, enabled and aimAssistActive)
                if not (enabled and aimAssistActive and readyToFight) then
                    return false, nil, nil
                end

                if not AimbotBridge.RollSilentHitChance() then
                    return false, nil, nil
                end

                local targetInfo = RivalsRuntimeBridge.ResolveAimbotSilentHookTarget(item)
                if not targetInfo then
                    return false, nil, nil
                end

                -- Spawn-shield fire gate (matches TryTriggerbotShot and the aim-lock
                -- glide): never redirect a live shot into a shielded player.
                if targetInfo.player and IsRivalsSpawnShieldActive(targetInfo.player.Character) then
                    return false, nil, nil
                end

                local camera = Workspace.CurrentCamera
                local originalCFrame = camera and camera.CFrame or nil
                if not camera or not originalCFrame or not RivalsRuntimeBridge.PrimeAimbotAim(targetInfo, item) then
                    return false, nil, nil
                end

                AimbotSilentState.ShotPrimeDepth = (AimbotSilentState.ShotPrimeDepth or 0) + 1
                if AimbotBridge.ResolveAimbotSilentDebugEnabled() then
                    RivalsRuntimeBridge.NotifyAimbotStatus('silent_prime', string.format('Silent Camera shot-hook: %s', targetInfo.displayName), true)
                end

                return true, camera, originalCFrame
            end

            RivalsRuntimeBridge.FinishAimbotSilentShot = function(didPrime, camera, originalCFrame)
                if not didPrime then
                    return
                end

                AimbotSilentState.ShotPrimeDepth = math.max((AimbotSilentState.ShotPrimeDepth or 1) - 1, 0)
                if camera and originalCFrame and Workspace.CurrentCamera == camera and RivalsRuntimeBridge.IsReadyToFight() then
                    camera.CFrame = originalCFrame
                end
            end

            RivalsModsState.BeginAimbotSilentShot = RivalsRuntimeBridge.BeginAimbotSilentShot
            RivalsModsState.FinishAimbotSilentShot = RivalsRuntimeBridge.FinishAimbotSilentShot

            local function EnsureAimbotSilentStartShootingHook(item)
                if AimbotSilentConnections.HookedItem == item then
                    return
                end

                if not AimbotBridge.IsAimbotSilentShotHookItem(item) then
                    return
                end

                local originalStartShooting = item.StartShooting
                local wrappedStartShooting
                wrappedStartShooting = function(self, ...)
                    local didPrime, camera, originalCFrame = RivalsRuntimeBridge.BeginAimbotSilentShot(self)
                    local baseStartShooting = RivalsModsState.ResolveGunStartShootingBase(originalStartShooting)
                    local results = table.pack(pcall(baseStartShooting, self, ...))
                    RivalsRuntimeBridge.FinishAimbotSilentShot(didPrime, camera, originalCFrame)
                    if not results[1] then
                        ReportRivalsRuntimeIssue('silent_start_shooting', results[2])
                        return nil
                    end
                    return table.unpack(results, 2, results.n)
                end

                AimbotSilentConnections.HookedItem = item
                AimbotSilentConnections.OriginalStartShooting = originalStartShooting
                AimbotSilentConnections.WrappedStartShooting = wrappedStartShooting
                item.StartShooting = wrappedStartShooting
            end

            local function UpdateAimbot()
                if not (Toggles.P2S1T6 and Toggles.P2S1T6.Value) then
                    RivalsRuntimeBridge.DestroyAimbotStatusNotification()
                end

                local enabled = AimbotBridge.IsAimbotSelected()
                local triggerbotEnabled = AimbotBridge.IsTriggerbotEnabled()
                local keybindActive = enabled and AimbotBridge.IsAimbotEnabled()
                local shootInputHeld = enabled and AimbotBridge.IsAimbotShootInputHeld()
                local aimAssistActive = enabled and (keybindActive or shootInputHeld)
                RivalsRuntimeBridge.RecordCharacterLoadingCheckpoint('Silent Aim', RivalsRuntimeBridge.IsReadyToFight(), enabled == true)
                local aimbotGameReady = enabled and IsAimbotGameReady()
                local triggerbotGameReady = triggerbotEnabled and IsAimbotGameReady()
                local cameraAimActive = AimbotBridge.IsCameraAimEnabled()
                local cameraAimGameReady = cameraAimActive and IsAimbotGameReady()
                local gameReady = aimbotGameReady or triggerbotGameReady

                local silentAimUsesFov = enabled and aimAssistActive and not AimbotBridge.IsAimbotIgnoreFovEnabled()
                local cameraAimUsesFov = cameraAimActive and not AimbotBridge.IsCameraIgnoreFovEnabled()
                AimbotBridge.UpdateAimbotFovCircle(
                    enabled and aimAssistActive, aimbotGameReady, silentAimUsesFov, false
                )
                AimbotBridge.UpdateAimbotFovCircle(
                    cameraAimActive, cameraAimGameReady, cameraAimUsesFov, true
                )

                if not enabled and not triggerbotEnabled then
                    AimbotBridge.ResetAimbotRuntimeState()
                    AimbotBridge.ResetTriggerbotReactionState()
                    RivalsRuntimeBridge.DestroyAimbotStatusNotification()
                    return
                end

                if not gameReady then
                    RivalsRuntimeBridge.RecordTargetValidityUpstreamGate('game_not_ready')
                    AimbotBridge.ResetAimbotRuntimeState()
                    AimbotBridge.ResetTriggerbotReactionState()
                    RivalsRuntimeBridge.DestroyAimbotStatusNotification()
                    return
                end

                local item = AimbotBridge.ResolveAimbotEquippedItem()
                if item and enabled then
                    EnsureAimbotSilentStartShootingHook(item)
                end

                local cameraReady = IsAimbotCameraReady()
                if not cameraReady then
                    RivalsRuntimeBridge.RecordTargetValidityUpstreamGate('camera_not_ready')
                    AimbotBridge.ResetAimbotRuntimeState()
                    AimbotBridge.ResetTriggerbotReactionState()
                    RivalsRuntimeBridge.NotifyAimbotStatus('camera_wait', 'Waiting for camera.')
                    return
                end

                local targetInfo = nil

                if not enabled or not aimAssistActive then
                    if enabled then
                        RivalsRuntimeBridge.RecordTargetValidityUpstreamGate('mouse_not_held')
                    end
                    AimbotBridge.ResetAimbotRuntimeState()
                    if enabled then
                        RivalsRuntimeBridge.DestroyAimbotStatusNotification()
                    end
                else
                    local evaluation = RivalsRuntimeBridge.EvaluateAimbotSilentRuntime(item, shootInputHeld)
                    local statusForce = AimbotBridge.ResolveAimbotSilentDebugEnabled()
                    local shouldContinuousAim = evaluation.shouldAim and AimbotBridge.ShouldUseAimbotSilentContinuousAim(item)
                    if shouldContinuousAim then
                        local now = os.clock()
                        local chance = Options.evilrollerplayersSilentHitChance and Options.evilrollerplayersSilentHitChance.Value or 100
                        if AimbotSilentState.ChanceItem ~= item or AimbotSilentState.ChanceValue ~= chance
                            or now >= (AimbotSilentState.ChanceUntil or 0) then
                            AimbotSilentState.ChanceItem = item
                            AimbotSilentState.ChanceValue = chance
                            AimbotSilentState.ChanceUntil = now + 0.1
                            AimbotSilentState.ChanceAllowed = AimbotBridge.RollSilentHitChance()
                        end
                        shouldContinuousAim = AimbotSilentState.ChanceAllowed == true
                    end
                    if evaluation.blockedReason then
                        RivalsRuntimeBridge.RecordTargetValidityUpstreamGate('silent_blocked:' .. tostring(evaluation.blockedReason))
                        RivalsRuntimeBridge.NotifyAimbotStatus('silent_blocked', RivalsRuntimeBridge.BuildAimbotSilentStatus(nil, evaluation), statusForce)
                    else
                        if shouldContinuousAim then
                            targetInfo = RivalsRuntimeBridge.GetBestAimbotTarget()
                            if not targetInfo then
                                RivalsRuntimeBridge.NotifyAimbotStatus('no_target', 'No target visible.')
                            else
                                RivalsRuntimeBridge.PrimeAimbotAim(targetInfo, item)
                            end
                        end

                        RivalsRuntimeBridge.NotifyAimbotStatus('tracking', RivalsRuntimeBridge.BuildAimbotSilentStatus(targetInfo, evaluation), statusForce)
                    end
                end

                if not triggerbotEnabled then
                    AimbotBridge.ReleaseTriggerbotMouseHold()
                    AimbotBridge.ResetTriggerbotReactionState()
                    return
                end

                local triggerTargetInfo = ResolveTriggerbotTarget(enabled, targetInfo)
                if not triggerTargetInfo then
                    AimbotBridge.ReleaseTriggerbotMouseHold()
                    AimbotBridge.ResetTriggerbotReactionState()
                    if not enabled then
                        RivalsRuntimeBridge.DestroyAimbotStatusNotification()
                    end
                    return
                end

                if TryTriggerbotShot(triggerTargetInfo, item, enabled) and not enabled then
                    RivalsRuntimeBridge.NotifyAimbotStatus('tracking', string.format('Triggerbot: %s', triggerTargetInfo.displayName))
                end
            end

            RivalsRuntimeBridge.UpdateAimbot = UpdateAimbot
            end

            do
            -- =============================================
            -- ESP Render Loop
            -- =============================================

            local function UpdateESP(deltaTime)
                local settings = EspRenderSettings
                local espEnabled = settings.Enabled
                if not espEnabled then
                    RivalsRuntimeBridge.ESPUpdateAccumulator = 0
                    RivalsRuntimeBridge.NextESPReconcileAt = 0
                    DestroyAllESP()
                    return
                end

                RivalsRuntimeBridge.ESPUpdateAccumulator = (RivalsRuntimeBridge.ESPUpdateAccumulator or 0)
                    + (type(deltaTime) == 'number' and deltaTime or (1 / 60))
                if RivalsRuntimeBridge.ESPUpdateAccumulator < (1 / 60) then
                    return
                end
                RivalsRuntimeBridge.ESPUpdateAccumulator = 0

                local now = tick()
                if now >= (RivalsRuntimeBridge.NextESPReconcileAt or 0) then
                    RivalsRuntimeBridge.NextESPReconcileAt = now + 0.25
                    ReconcileESPPlayers()
                end

                local espColor = settings.VisibleColor
                local hiddenColor = settings.HiddenColor
                local maxDist = DEFAULT_ESP_MAX_DISTANCE
                local fillAlpha = settings.FillAlpha
                local outlineAlpha = settings.OutlineAlpha
                local showHighlight = settings.ShowHighlight
                local showName = settings.ShowName
                local showHealth = settings.ShowHealth
                local showArrows = settings.ShowArrows
                local showDistance = settings.ShowDistance
                local showWeapon = settings.ShowWeapon
                local showLookDir = settings.ShowLookDir
                local showTeammates = settings.ShowTeammates
                local showBox = settings.ShowBox
                local showAmmoText = settings.ShowAmmoText
                local showStatus = settings.ShowRank or settings.ShowWinStreak or settings.ShowDeflecting
                local teammateColor = espColor
                local lookDirColor = settings.LookDirColor
                local rawCardLayout = PLAYER_CARD_THEME
                local myTeamId = showTeammates and LP:GetAttribute('TeamID') or nil
                local myRobloxTeam = showTeammates and LP.Team or nil

                local cam = Workspace.CurrentCamera
                if not cam then return end
                local viewportSize = cam.ViewportSize
                local vpX, vpY = viewportSize.X, viewportSize.Y
                local centerX, centerY = vpX / 2, vpY / 2

                local uiScale = (vpY > 0 and vpY or 1080) / 1080
                local paneGap = uiScale
                local statusGap = uiScale
                local textFont = 3
                local cardLayout = {
                    HorizontalBarWidth = rawCardLayout.HorizontalBarWidth * uiScale,
                    NameOffsetY = rawCardLayout.NameOffsetY * uiScale,
                    BarTopGap = rawCardLayout.BarTopGap * uiScale,
                    HorizontalBarOffsetY = rawCardLayout.HorizontalBarOffsetY * uiScale,
                    BarHeight = rawCardLayout.BarHeight * uiScale,
                    HorizontalBarTextPadding = rawCardLayout.HorizontalBarTextPadding * uiScale,
                    HorizontalBarTextPaddingY = rawCardLayout.HorizontalBarTextPaddingY * uiScale,
                    BarRadius = rawCardLayout.BarRadius * uiScale,
                    BarInset = rawCardLayout.BarInset * uiScale,
                }

                InitCharacter()
                local rootPosition = HumanoidRootPart and HumanoidRootPart.Position or nil
                local maxDistSquared = maxDist * maxDist

                for player, entry in pairs(ESPObjects) do
                    repeat
                    local character = player.Character

                    if not character or not ShouldShow(player, showTeammates) then
                        HideESP(entry)
                        break
                    end

                    local characterParts = ReadCharacterEspParts(character, entry.characterParts)
                    entry.characterParts = characterParts
                    local hrp = characterParts.HumanoidRootPart
                    if not hrp then
                        HideESP(entry)
                        break
                    end

                    local hum = characterParts.Humanoid
                    local rootPos = hrp.Position
                    local dist = 0
                    if rootPosition then
                        local rootOffset = rootPos - rootPosition
                        local worldDistanceSquared = rootOffset:Dot(rootOffset)
                        if worldDistanceSquared > maxDistSquared then
                            HideESP(entry)
                            break
                        end
                        dist = math.sqrt(worldDistanceSquared)
                    end

                    local isTeammate = false
                    if showTeammates then
                        local theirTeam = player:GetAttribute('TeamID')
                        if myTeamId and theirTeam then
                            isTeammate = myTeamId == theirTeam
                        elseif player.Team and myRobloxTeam then
                            isTeammate = player.Team == myRobloxTeam
                        end
                    end

                    local screenPos, onScreen = cam:WorldToViewportPoint(rootPos)

                    -- Off-screen: only show a directional arrow near the screen edge
                    if not onScreen or screenPos.Z <= 0 then
                        entry.highlight.Enabled = false
                        SetDrawingVisible(entry.nameText, false)
                        HideRoundedRect(entry.healthBarBg)
                        HideRoundedRect(entry.healthBarFill)
                        SetDrawingVisible(entry.healthText, false)
                        SetDrawingVisible(entry.healthSuffixText, false)
                        SetDrawingVisible(entry.metaText, false)
                        SetDrawingVisible(entry.ammoText, false)
                        SetDrawingVisible(entry.distanceText, false)
                        SetDrawingVisible(entry.lookLine, false)
                        if entry.statusText then
                            SetDrawingVisible(entry.statusText, false)
                        end
                        RivalsRuntimeBridge.ESPClassic.HideBox(entry)

                        HideArrowIndicator(entry.arrow)
                        if showArrows then
                            local dir = cam.CFrame:VectorToObjectSpace(rootPos - cam.CFrame.Position)
                            local angle = math.atan2(dir.X, -dir.Z)
                            local edgeDist = math.min(vpX, vpY) * PLAYER_CARD_THEME.ArrowEdgeScale
                            local arrowCenter = Vector2.new(
                                centerX + math.sin(angle) * edgeDist,
                                centerY - math.cos(angle) * edgeDist
                            )
                            local arrowDirection = Vector2.new(math.sin(angle), -math.cos(angle))
                            local arrowColor = isTeammate and teammateColor or hiddenColor
                            DrawArrowIndicator(entry.arrow, arrowCenter, arrowDirection, arrowColor, uiScale)
                        end
                        break
                    end

                    -- Visibility check (raycast)
                    local _, _, visible = RivalsRuntimeBridge.ResolveVisibleAimbotTargetPart(character, 'Auto', 'Players', ESP_VISIBILITY_CACHE_PROFILE)
                    local currentColor
                    if isTeammate then
                        currentColor = teammateColor
                    else
                        currentColor = visible and espColor or hiddenColor
                    end

                    -- Roblox Highlight (AlwaysOnTop, color swapped by visibility)
                    entry.highlight.Enabled = showHighlight
                    if showHighlight then
                        local outlineColor = BlendColor(currentColor, PLAYER_CARD_THEME.FrameColor, 0.24)
                        entry.highlight.Adornee = character
                        entry.highlight.OutlineColor = outlineColor
                        entry.highlight.FillColor = currentColor
                        entry.highlight.FillTransparency = fillAlpha
                        entry.highlight.OutlineTransparency = outlineAlpha
                    end

                    local depth = screenPos.Z
                    local boxHeight = (5.5 / depth) * vpY * 0.5
                    local boxY = screenPos.Y - boxHeight / 2

                    HideArrowIndicator(entry.arrow)

                    local displayName = player.Name
                    local weaponInfo = (showWeapon or showAmmoText) and GetCachedWeaponInfo(player) or nil
                    local hasHealthBar = showHealth and hum ~= nil
                    local useVerticalHealth = hasHealthBar and settings.UseVerticalHealth
                    local useHorizontalHealth = hasHealthBar and not useVerticalHealth
                    local screenBounds = nil
                    if hasHealthBar or showName or showWeapon or showDistance or showBox or showAmmoText or showStatus then
                        screenBounds = GetHitboxScreenBounds(characterParts, character, cam)
                    end
                    local weaponValue = BuildPlayerWeaponText(
                        weaponInfo and weaponInfo.label or nil,
                        showWeapon
                    )
                    local distanceValue = BuildPlayerDistanceText(dist, showDistance)
                    local healthValue = useVerticalHealth
                        and BuildVerticalHealthText(hum)
                        or BuildHealthText(hum, useHorizontalHealth)
                    local mainTextSize = math.max(math.round(16 * uiScale), 8)
                    local hasName = showName and displayName ~= ''
                    local hasMeta = weaponValue ~= ''
                    local hasDistance = distanceValue ~= ''
                    local hasHealthText = healthValue ~= ''
                    local ammo = weaponInfo and weaponInfo.ammo or nil
                    local maxAmmo = weaponInfo and weaponInfo.maxAmmo or nil
                    local hasAmmoText = showAmmoText
                        and type(ammo) == 'number'
                        and type(maxAmmo) == 'number'
                        and maxAmmo > 0
                        and maxAmmo < math.huge
                    local ammoValue = hasAmmoText and string.format(
                        '%s/%s',
                        FormatAmmoValue(ammo),
                        FormatAmmoValue(maxAmmo)
                    ) or ''

                    SetDrawingTextState(entry.nameText, hasName, displayName, mainTextSize, true, PLAYER_CARD_THEME.BarTextColor, textFont)
                    SetDrawingTextState(entry.metaText, hasMeta, weaponValue, mainTextSize, true, PLAYER_CARD_THEME.BarTextColor, textFont)
                    SetDrawingTextState(entry.ammoText, hasAmmoText, ammoValue, mainTextSize, true, PLAYER_CARD_THEME.BarTextColor, textFont)
                    SetDrawingTextState(entry.distanceText, hasDistance, distanceValue, mainTextSize, true, PLAYER_CARD_THEME.BarTextColor, textFont)
                    local hasHealthSuffix = useHorizontalHealth and hasHealthText
                    SetDrawingTextState(entry.healthText, hasHealthBar and hasHealthText, healthValue, mainTextSize, not useHorizontalHealth, PLAYER_CARD_THEME.BarTextColor, textFont)
                    SetDrawingTextState(entry.healthSuffixText, hasHealthBar and hasHealthSuffix, 'HP', mainTextSize, false, PLAYER_CARD_THEME.BarTextColor, textFont)

                    local nameBounds = hasName and entry.nameText.TextBounds or Vector2.new(0, 0)
                    local metaBounds = hasMeta and entry.metaText.TextBounds or Vector2.new(0, 0)
                    local ammoBounds = hasAmmoText and entry.ammoText.TextBounds or Vector2.new(0, 0)
                    local healthTextBounds = (hasHealthBar and hasHealthText) and entry.healthText.TextBounds or Vector2.new(0, 0)
                    local healthSuffixBounds = (hasHealthBar and hasHealthSuffix) and entry.healthSuffixText.TextBounds or Vector2.new(0, 0)
                    local healthGap = hasHealthSuffix and (2 * uiScale) or 0
                    local healthCombinedWidth = healthTextBounds.X + healthGap + healthSuffixBounds.X
                    local nameHeight = hasName and math.max(nameBounds.Y, mainTextSize) or 0
                    local metaHeight = hasMeta and math.max(metaBounds.Y, mainTextSize) or 0
                    local ammoHeight = hasAmmoText and math.max(ammoBounds.Y, mainTextSize) or 0
                    local fallbackWidth = boxHeight * 0.55
                    local renderBounds = screenBounds or {
                        MinX = screenPos.X - (fallbackWidth * 0.5),
                        MaxX = screenPos.X + (fallbackWidth * 0.5),
                        MinY = boxY,
                        MaxY = boxY + boxHeight,
                        Width = fallbackWidth,
                        Height = boxHeight,
                        CenterX = screenPos.X,
                        CenterY = screenPos.Y,
                    }

                    if showBox then
                        RivalsRuntimeBridge.ESPClassic.DrawBox(entry, renderBounds, currentColor, uiScale)
                    else
                        RivalsRuntimeBridge.ESPClassic.HideBox(entry)
                    end

                    if useHorizontalHealth then
                        local horizontalBarWidth = hasHealthText
                            and math.max(cardLayout.HorizontalBarWidth, healthCombinedWidth + (cardLayout.HorizontalBarTextPadding * 2))
                            or cardLayout.HorizontalBarWidth
                        local horizontalBarHeight = hasHealthText
                            and math.max(cardLayout.BarHeight, healthTextBounds.Y + (cardLayout.HorizontalBarTextPaddingY * 2))
                            or cardLayout.BarHeight
                        local topClusterHeight = horizontalBarHeight
                            + (hasName and (nameHeight + cardLayout.BarTopGap) or 0)
                        local cursorY = renderBounds.MinY - topClusterHeight - 2 - cardLayout.NameOffsetY

                        if hasName then
                            entry.nameText.Position = Vector2.new(math.round(renderBounds.CenterX), math.round(cursorY))
                            cursorY = cursorY + nameHeight + cardLayout.BarTopGap
                        end

                        local healthRatio = math.clamp(hum.Health / math.max(hum.MaxHealth, 1), 0, 1)
                        local healthColor = GetHealthBarColor(healthRatio)
                        local barWidth = horizontalBarWidth
                        local barX = renderBounds.CenterX - (barWidth * 0.5)
                        local barY = cursorY + cardLayout.HorizontalBarOffsetY
                        local barInset = cardLayout.BarInset
                        local fillX = barX + barInset
                        local fillY = barY + barInset
                        local fillHeight = math.max(horizontalBarHeight - (barInset * 2), 1)
                        local fillWidth = math.max(
                            healthRatio * math.max(barWidth - (barInset * 2), 0),
                            healthRatio > 0 and 1 or 0
                        )

                        SetRoundedRect(
                            entry.healthBarBg,
                            barX,
                            barY,
                            barWidth,
                            horizontalBarHeight,
                            cardLayout.BarRadius,
                            PLAYER_CARD_THEME.BarBackgroundColor,
                            PLAYER_CARD_THEME.BarBackgroundTransparency
                        )
                        if fillWidth > 0 then
                            SetRoundedRect(
                                entry.healthBarFill,
                                fillX,
                                fillY,
                                fillWidth,
                                fillHeight,
                                math.max(cardLayout.BarRadius - barInset, 0),
                                healthColor,
                                1
                            )
                        else
                            HideRoundedRect(entry.healthBarFill)
                        end

                        if hasHealthText then
                            local valueX = renderBounds.CenterX - (healthCombinedWidth * 0.5)
                            local suffixX = valueX + healthTextBounds.X + healthGap
                            local textY = barY + (horizontalBarHeight * 0.5) - (healthTextBounds.Y * 0.5)
                            entry.healthText.Center = false
                            entry.healthText.Position = Vector2.new(math.round(valueX), math.round(textY))
                            entry.healthSuffixText.Center = false
                            entry.healthSuffixText.Position = Vector2.new(math.round(suffixX), math.round(textY))
                        end
                    else
                        if hasName then
                            entry.nameText.Position = Vector2.new(
                                math.round(renderBounds.CenterX),
                                math.round(renderBounds.MinY - nameHeight - paneGap)
                            )
                        end
                        SetDrawingVisible(entry.healthSuffixText, false)
                        if useVerticalHealth then
                            local healthRatio = math.clamp(hum.Health / math.max(hum.MaxHealth, 1), 0, 1)
                            entry.displayHealthRatio = RivalsRuntimeBridge.ESPClassic.SmoothRatio(entry.displayHealthRatio, healthRatio, deltaTime)
                            local railWidth = math.max(PLAYER_CARD_THEME.Classic.BarWidth * uiScale, 3)
                            local railGap = PLAYER_CARD_THEME.Classic.BarGap * uiScale
                            local railX = renderBounds.MinX - railWidth - railGap
                            local railY = renderBounds.MinY
                            local railHeight = math.max(renderBounds.Height, 1)
                            local barInset = math.max(PLAYER_CARD_THEME.Classic.BarInset * uiScale, 0.75)
                            local fillHeight = math.max(
                                entry.displayHealthRatio * math.max(railHeight - (barInset * 2), 0),
                                entry.displayHealthRatio > 0 and 1 or 0
                            )
                            local fillY = railY + railHeight - barInset - fillHeight

                            SetRoundedRect(
                                entry.healthBarBg,
                                railX,
                                railY,
                                railWidth,
                                railHeight,
                                0,
                                PLAYER_CARD_THEME.BarBackgroundColor,
                                PLAYER_CARD_THEME.BarBackgroundTransparency
                            )
                            if fillHeight > 0 then
                                SetRoundedRect(
                                    entry.healthBarFill,
                                    railX + barInset,
                                    fillY,
                                    math.max(railWidth - (barInset * 2), 1),
                                    fillHeight,
                                    0,
                                    RivalsRuntimeBridge.ESPClassic.GetReactiveBarColor(entry.displayHealthRatio),
                                    1
                                )
                            else
                                HideRoundedRect(entry.healthBarFill)
                            end

                            if hasHealthText then
                                local labelX = railX - (healthTextBounds.X * 0.5) - paneGap
                                local labelY = math.clamp(
                                    fillY - (healthTextBounds.Y * 0.5),
                                    railY,
                                    math.max(railY + railHeight - healthTextBounds.Y, railY)
                                )
                                entry.healthText.Center = true
                                entry.healthText.Position = Vector2.new(math.round(labelX), math.round(labelY))
                            else
                                SetDrawingVisible(entry.healthText, false)
                            end
                        else
                            HideRoundedRect(entry.healthBarBg)
                            HideRoundedRect(entry.healthBarFill)
                            SetDrawingVisible(entry.healthText, false)
                        end
                    end

                    local infoStartY = renderBounds.MaxY + paneGap
                    if hasAmmoText then
                        entry.ammoText.Position = Vector2.new(math.round(renderBounds.CenterX), math.round(infoStartY))
                        infoStartY = infoStartY + ammoHeight + paneGap
                    end

                    if hasMeta then
                        entry.metaText.Position = Vector2.new(math.round(renderBounds.CenterX), math.round(infoStartY))
                        infoStartY = infoStartY + metaHeight + paneGap
                    end
                    if hasDistance then
                        entry.distanceText.Position = Vector2.new(math.round(renderBounds.CenterX), math.round(infoStartY))
                    end

                    local statusValue = showStatus and RivalsRuntimeBridge.ESPClassic.BuildStatusText(player, settings, entry) or ''
                    if statusValue ~= '' then
                        local statusText = RivalsRuntimeBridge.ESPClassic.EnsureStatusText(entry)
                        local statusSize = math.max(math.round(12 * uiScale), 8)
                        SetDrawingTextState(statusText, true, statusValue, statusSize, false, PLAYER_CARD_THEME.BarTextColor, textFont)
                        statusText.Position = Vector2.new(
                            math.round(renderBounds.MaxX + statusGap),
                            math.round(renderBounds.MinY)
                        )
                    elseif entry.statusText then
                        SetDrawingVisible(entry.statusText, false)
                    end

                    -- Look direction line (from head, extends in aim direction)
                    SetDrawingVisible(entry.lookLine, showLookDir)
                    if showLookDir then
                        local head = characterParts.HitboxHead
                        if head then
                            local headPos = head.Position
                            local lookEnd = headPos + head.CFrame.LookVector * 5
                            local headScreen, headOn = cam:WorldToViewportPoint(headPos)
                            local endScreen, endOn = cam:WorldToViewportPoint(lookEnd)
                            if headOn and endOn and headScreen.Z > 0 then
                                entry.lookLine.From = Vector2.new(headScreen.X, headScreen.Y)
                                entry.lookLine.To = Vector2.new(endScreen.X, endScreen.Y)
                                entry.lookLine.Color = lookDirColor
                                entry.lookLine.Thickness = math.max(uiScale, 1)
                            else
                                SetDrawingVisible(entry.lookLine, false)
                            end
                        else
                            SetDrawingVisible(entry.lookLine, false)
                        end
                    end
                    until true
                end
            end
            RivalsRuntimeBridge.UpdateESP = UpdateESP

            RivalsRuntimeBridge.CharacterLoadingState = {}
            RivalsRuntimeBridge.DiagnosticLogState = {LastByMessage = {}, ThrottleSeconds = 2}
            RivalsRuntimeBridge.InitialSpawnCooldownComplete = false
            RivalsRuntimeBridge.MatchBoundaryDetectionInstalled = false

            -- Spawn-shield readiness latch. The game grants invincibility (the
            -- spawn shield) the moment our local fighter is fully bound and the
            -- round is live -- the authoritative "loaded and safe to act" signal
            -- from the game itself. Replaces the prior 2.5s task.wait + 2s
            -- CharacterChangedAt heuristic. Shooting range never grants a shield,
            -- so IsLocalReadyToFight falls through to the IsInShootingRange
            -- branch there. Latch resets on new local Fighter (match boundary)
            -- and on LP.CharacterAdded (mid-match respawn).
            --
            -- InitialLifeAdoptionOpen covers executing the script MID-LIFE: the
            -- shield expired before we loaded, so the latch could never see it
            -- and every aim feature stayed dark until the next respawn. evilrollerplayers
            -- has no shield wait at all -- its gate is "player context built +
            -- equipped gun" (HasEquippedGun), both live game state. We adopt
            -- the current life once, at script start, on the same evidence
            -- (entity in world + an item equipped); any later life goes through
            -- the shield latch as before, so the half-loaded-character problem
            -- the latch solved stays solved.
            RivalsRuntimeBridge.LocalReadyState = {
                ShieldSeen = false,
                LastSeenFighter = nil,
                ReadyNotified = false,
                InitialLifeAdoptionOpen = true,
            }

            -- Both helpers live on the bridge (not local functions) so deeply
            -- nested closures defined far away in the chunk (e.g. CharacterAdded
            -- handlers in RegisterCharacterLifecycle) can reach them via the
            -- already-captured RivalsRuntimeBridge upvalue. Local-function
            -- upvalue capture across thousands of lines + many enclosing
            -- functions hits Luau's per-function upvalue chain limits and
            -- silently produces nil at the call site.
            RivalsRuntimeBridge.ResetLocalShieldLatch = function()
                local state = RivalsRuntimeBridge.LocalReadyState
                state.ShieldSeen = false
                state.LastSeenFighter = nil
                state.ReadyNotified = false
                -- Any new-life event (new Fighter, CharacterAdded) closes the
                -- mid-life adoption window; from here on only the shield latch
                -- (or shooting range) can declare the character ready.
                state.InitialLifeAdoptionOpen = false
            end

            RivalsRuntimeBridge.NotifyLocalReadyOnce = function(source)
                local state = RivalsRuntimeBridge.LocalReadyState
                if state.ReadyNotified then
                    return
                end
                state.ReadyNotified = true
                RivalsRuntimeBridge.LogDiagnosticEvent('Ready', 'Loaded -- ready to fight (' .. tostring(source) .. ')')
            end

            RivalsRuntimeBridge.IsLocalReadyToFight = function()
                if not IsAimbotGameReady() then
                    return false
                end

                local duel = FighterDataCache.LocalDuel
                if duel and duel.Seeded and duel.IsInShootingRange == true then
                    RivalsRuntimeBridge.NotifyLocalReadyOnce('shooting range')
                    return true
                end

                local state = RivalsRuntimeBridge.LocalReadyState
                if state.ShieldSeen then
                    return true
                end

                local fighter = ResolveLocalFighter()
                if not fighter then
                    return false
                end

                -- Pre-seeded shooting-range path: AttachLocalDuelWatchers (which
                -- sets duel.Seeded=true) runs from per-spawn setup AFTER
                -- WaitForLocalReady returns, but WaitForLocalReady polls THIS
                -- function. In the shooting range there's no spawn shield, so
                -- without this branch the gate never opens until 30s timeout
                -- or the user enters a duel (which triggers the shield, which
                -- causes AttachLocalDuelWatchers to fire). Sync-read the same
                -- field the cache would have read.
                if type(fighter.Data) == 'table' and fighter.Data.IsInShootingRange == true then
                    RivalsRuntimeBridge.NotifyLocalReadyOnce('shooting range (sync)')
                    return true
                end

                if state.LastSeenFighter ~= fighter then
                    state.LastSeenFighter = fighter
                end

                -- Direct sync read of the entity's Data first. Covers the case
                -- where the FighterDataCache.Track signal hadn't connected yet
                -- when IsInvincible flipped so the cache missed the transition
                -- window but the flag is still up at this poll.
                local entity = fighter.Entity
                if entity and type(entity.Data) == 'table' and entity.Data.IsInvincible == true then
                    state.ShieldSeen = true
                    RivalsRuntimeBridge.NotifyLocalReadyOnce('spawn shield')
                    return true
                end

                -- Signal-driven cache as a backup path.
                if FighterDataCache.Cache[fighter] == true then
                    state.ShieldSeen = true
                    RivalsRuntimeBridge.NotifyLocalReadyOnce('spawn shield (cache)')
                    return true
                end

                -- evilrollerplayers parity (mid-life execute): adopt the CURRENT life once at
                -- script start when the game itself says it is live -- entity in
                -- world with an item equipped, the same evidence evilrollerplayers's
                -- HasEquippedGun gate runs on. Without this, executing after your
                -- spawn shield expired held every aim feature dark until the next
                -- respawn. One-shot: ResetLocalShieldLatch closes the window on
                -- any new-life event, so respawns keep the proven shield latch.
                if state.InitialLifeAdoptionOpen then
                    if type(entity) == 'table' and rawget(entity, '_is_in_world') == true
                        and rawget(fighter, 'EquippedItem') ~= nil then
                        state.InitialLifeAdoptionOpen = false
                        state.ShieldSeen = true
                        RivalsRuntimeBridge.NotifyLocalReadyOnce('mid-life adopt (equipped item)')
                        return true
                    end
                end

                return false
            end

            RivalsRuntimeBridge.WaitForLocalReady = function(timeoutSec)
                local deadline = timeoutSec and (tick() + timeoutSec) or nil
                while not RivalsRuntimeBridge.IsLocalReadyToFight() do
                    if deadline and tick() > deadline then
                        return false
                    end
                    task.wait()
                end
                return true
            end

            -- Subscribe to FighterController.ObjectAdded once. RIVALS creates
            -- a fresh Fighter object per-player-per-match; mid-match deaths
            -- and respawns reuse the same Fighter (just create new Entities
            -- via fighter.EntityAdded). So a new local Fighter being added is
            -- the deterministic, game-state-authoritative signal that a new
            -- match has started -- no time-gap heuristics required. Resets
            -- the initial-spawn cooldown so the new match gets the same
            -- protective wait that the first match after script load gets.
            RivalsRuntimeBridge.EnsureMatchBoundaryDetection = function()
                if RivalsRuntimeBridge.MatchBoundaryDetectionInstalled then
                    return
                end

                local controller = ResolveFighterController()
                if not controller then
                    return
                end

                local addedSignal = controller.ObjectAdded
                if type(addedSignal) ~= 'table' or type(addedSignal.Connect) ~= 'function' then
                    return
                end

                local ok, conn = pcall(function()
                    return addedSignal:Connect(function(newFighter)
                        if type(newFighter) ~= 'table' then
                            return
                        end
                        local isLocal = newFighter.IsLocalPlayer == true
                            or rawget(newFighter, 'Player') == LP
                        if not isLocal then
                            return
                        end
                        RivalsRuntimeBridge.InitialSpawnCooldownComplete = false
                        RivalsRuntimeBridge.ResetLocalShieldLatch()
                        RivalsRuntimeBridge.LogDiagnosticEvent(
                            'MatchBoundary',
                            'New local fighter detected; readiness latch reset'
                        )
                        if RivalsRuntimeBridge.RunPickupSpawnSetup then
                            RivalsRuntimeBridge.RunPickupSpawnSetup()
                        end
                    end)
                end)

                if ok and conn then
                    if Library and type(Library.GiveSignal) == 'function' then
                        pcall(function() Library:GiveSignal(conn) end)
                    end
                    RivalsRuntimeBridge.MatchBoundaryDetectionInstalled = true
                    if controller.LocalFighter and RivalsRuntimeBridge.RunPickupSpawnSetup then
                        RivalsRuntimeBridge.RunPickupSpawnSetup()
                    end
                end
            end

            RivalsRuntimeBridge.LogDiagnosticEvent = function(scope, message)
                if not (Toggles.P9S3T1 and Toggles.P9S3T1.Value == true) then
                    return
                end

                local now = tick()
                local key = tostring(scope) .. '|' .. tostring(message)
                local state = RivalsRuntimeBridge.DiagnosticLogState
                local last = state.LastByMessage[key]
                if last and (now - last) < state.ThrottleSeconds then
                    return
                end
                state.LastByMessage[key] = now

                if Library and type(Library.Notify) == 'function' then
                    pcall(function()
                        Library:Notify({
                            Title = 'Character Loading Check',
                            Description = string.format('[%s] %s', tostring(scope), tostring(message)),
                            Time = 3,
                        })
                    end)
                end
            end

            RivalsRuntimeBridge.RecordCharacterLoadingCheckpoint = function(featureName, isReady, isEnabled)
                local state = RivalsRuntimeBridge.CharacterLoadingState
                local wasReady = state[featureName] == true
                state[featureName] = isReady

                if not isReady or not isEnabled or wasReady then
                    return
                end

                if not (Toggles.P9S3T1 and Toggles.P9S3T1.Value == true) then
                    return
                end

                if Library and type(Library.Notify) == 'function' then
                    pcall(function()
                        Library:Notify({
                            Title = 'Character Loading Check',
                            Description = featureName .. ' ready',
                            Time = 3,
                        })
                    end)
                end
            end

            RivalsRuntimeBridge.IsReadyToFight = function()
                if not IsAimbotCameraReady() then
                    return false
                end
                if not IsAimbotGameReady() then
                    return false
                end
                local fighter = ResolveLocalFighter()
                local entity = fighter and fighter.Entity
                if type(entity) == 'table' and rawget(entity, '_is_in_world') ~= true then
                    return false
                end

                -- NOTE (LRN-20260427-003): Do not add a `LP.Character.Parent
                -- == Workspace` check here. RIVALS parents live characters
                -- in a sub-folder of Workspace during normal matches, so a
                -- strict direct-parent check returns false during 100% of
                -- real play (verified with diagnostic: CharInWS=N while
                -- EntityInWorld/ShieldSeen/LocalReady=Y and locks succeed).
                -- The other gates above and below already cover viewport
                -- preview rigs and post-death states. If a HurtEffect-class
                -- transient ever surfaces, use IsDescendantOf(Workspace) or
                -- an explicit bad-parent blacklist -- never direct-parent.

                -- Lazy-install the match-boundary detector. Idempotent and
                -- cheap (just a flag check) once installed. We try here in
                -- case Initialize-time install missed because the
                -- FighterController wasn't ready yet.
                RivalsRuntimeBridge.EnsureMatchBoundaryDetection()

                -- C: spawn-shield latch (or shooting-range fallback). The
                -- game's IsInvincible flag flipping true is the authoritative
                -- "your character is loaded and the round is live" signal --
                -- replaces the prior 2s CharacterChangedAt heuristic which
                -- was a guess at when the camera controller had finished
                -- re-binding. Shooting range never grants a shield, so
                -- IsLocalReadyToFight falls through to its IsInShootingRange
                -- branch there.
                if not RivalsRuntimeBridge.IsLocalReadyToFight() then
                    return false
                end

                return true
            end

            RivalsRuntimeBridge.AcquireActiveCharacter = function()
                if not RivalsRuntimeBridge.IsReadyToFight() then
                    return nil
                end
                if LP.Character ~= Char then
                    return nil
                end
                if not HumanoidRootPart or HumanoidRootPart.Parent ~= Char then
                    return nil
                end
                return Char, HumanoidRootPart, Humanoid
            end
            end

            do

            local BuildRivalsEspUi = nil
            local BuildRivalsAimbotUi = nil
            local BuildRivalsModsUi = nil
            local BuildRivalsVisualsUi = nil
            local BuildRivalsRagebotUi = nil
            local BuildRivalsCosmeticsUi = nil
            local BuildRivalsPickupUi = nil
            local BuildRivalsMiscUi = nil
            local BuildRivalsDebugUi = nil
            local BuildRivalsUi = nil
            local RivalsRagebot = {
                RespawnRequestInterval = 1,
                RespawnBurstCount       = 5,
                RespawnBurstDelay       = 0.1,
                RadiusIn               = 10,
                RadiusOut              = 35,
                InOutToggleHz          = 15,
                WeaponRanges           = {
                    -- Per-weapon override keyed on item.Name (exact match).
                    -- Anything not listed here falls back to RadiusIn/RadiusOut.
                    ['Shotgun'] = { In = 5, Out = 5 },
                },
                HeightBase             = 3,
                HeightWobbleAmp        = 2,
                HeightWobbleRateHz     = 2.7,
                OOBBufferDistance      = 4,
                KillSeatBufferDistance     = 1.5,
                KillSeatScoreRayLength     = 8,
                KillSeatRefreshIntervalSec = 0.4,
                KillSeatBuildTtlSec        = 60,
