                KillSeatScoreDistanceWeight = 0.05,
                KillSeatRefineStep         = 0.05,
                HostileTeleportDeltaStuds  = 50,
                HostileTeleportMinSpeed    = 150,
                HostileTeleportWindowSec   = 5,
                HostileTeleportMinCount    = 1,
                HostileTrackerSampleMinDt  = 0.05,
                HoldCFrameStaleTtlSec      = 0.15,
