                local ok, cosmeticLibrary = pcall(require, cosmeticLibraryModule)
                if not ok or type(cosmeticLibrary) ~= 'table' then
                    return nil
                end

                RivalsCosmetics.Catalog.CosmeticLibrary = cosmeticLibrary
                return cosmeticLibrary
            end

