            function RivalsCosmetics.ResolveDefaultWeaponTemplate(weaponName)
                if type(weaponName) ~= 'string' or weaponName == '' then
                    return nil
                end

                local weaponTemplatesFolder = RivalsCosmetics.ResolveDefaultWeaponTemplatesFolder()
                local weaponTemplate = weaponTemplatesFolder and weaponTemplatesFolder:FindFirstChild(weaponName)
                if weaponTemplate and RivalsCosmetics.IsModelContainer(weaponTemplate) then
                    return weaponTemplate
                end

                return nil
            end

            function RivalsCosmetics.ResolveWeaponTemplate(weaponName)
                if type(weaponName) ~= 'string' or weaponName == '' then
                    return nil
                end

                local weaponTemplatesFolder = RivalsCosmetics.ResolveWeaponTemplatesFolder()
                local weaponTemplate = weaponTemplatesFolder and weaponTemplatesFolder:FindFirstChild(weaponName)
                if weaponTemplate and RivalsCosmetics.IsModelContainer(weaponTemplate) then
                    return weaponTemplate
                end

                return nil
            end

            function RivalsCosmetics.ResolveWeaponNames()
                local cachedWeaponNames = RivalsCosmetics.Catalog.WeaponNames
                if cachedWeaponNames then
                    return cachedWeaponNames
                end

                local cosmeticLibrary = RivalsCosmetics.ResolveCosmeticLibrary()
                local cosmetics = cosmeticLibrary and cosmeticLibrary.Cosmetics or nil
                local weaponNames = {}
                local seenWeaponNames = {}
                if type(cosmetics) == 'table' then
                    for _, cosmeticData in pairs(cosmetics) do
                        local weaponName = cosmeticData and cosmeticData.ItemName or nil
                        if cosmeticData and cosmeticData.Type == 'Skin' and type(weaponName) == 'string' and weaponName ~= '' and not RivalsCosmetics.IsPlaceholderCatalogName(weaponName) and seenWeaponNames[weaponName] ~= true and RivalsCosmetics.ResolveWeaponTemplate(weaponName) then
                            seenWeaponNames[weaponName] = true
                            weaponNames[#weaponNames + 1] = weaponName
                        end
                    end
                end

                table.sort(weaponNames)
                RivalsCosmetics.Catalog.WeaponNames = weaponNames
                return weaponNames
            end

            function RivalsCosmetics.ResolveEditorWeaponNames()
                local values = {RIVALS_COSMETIC_ALL_WEAPONS}
                for _, weaponName in ipairs(RivalsCosmetics.ResolveWeaponNames()) do
                    values[#values + 1] = weaponName
                end
                return values
            end

            function RivalsCosmetics.ResolveWeaponSkinValues(weaponName)
                if type(weaponName) ~= 'string' or weaponName == '' then
                    return RivalsCosmetics.ResolveSentinelValues()
                end

                local cacheKey = string.format('SkinValues_%s', weaponName)
                local cachedValues = RivalsCosmetics.Catalog[cacheKey]
                if cachedValues then
                    return cachedValues
                end

                local cosmeticLibrary = RivalsCosmetics.ResolveCosmeticLibrary()
                local cosmetics = cosmeticLibrary and cosmeticLibrary.Cosmetics or nil
                local values = RivalsCosmetics.ResolveSentinelValues()
                if type(cosmetics) == 'table' then
                    local skinNames = {}
                    for cosmeticName, cosmeticData in pairs(cosmetics) do
                        if cosmeticData and cosmeticData.Type == 'Skin' and cosmeticData.ItemName == weaponName and not RivalsCosmetics.IsPlaceholderCatalogName(cosmeticName) then
                            skinNames[#skinNames + 1] = cosmeticName
                        end
                    end

                    table.sort(skinNames)
                    for _, skinName in ipairs(skinNames) do
                        values[#values + 1] = skinName
                    end
                end

                RivalsCosmetics.Catalog[cacheKey] = values
                return values
            end

