                local cachedWrapValues = RivalsCosmetics.Catalog.WrapValues
                if cachedWrapValues then
                    return cachedWrapValues
                end

                local cosmeticLibrary = RivalsCosmetics.ResolveCosmeticLibrary()
                local cosmetics = cosmeticLibrary and cosmeticLibrary.Cosmetics or nil
                local values = RivalsCosmetics.ResolveSentinelValues()
                if type(cosmetics) == 'table' then
                    local wrapNames = {}
                    for cosmeticName, cosmeticData in pairs(cosmetics) do
                        if cosmeticData and cosmeticData.Type == 'Wrap' and not RivalsCosmetics.IsPlaceholderCatalogName(cosmeticName) then
                            wrapNames[#wrapNames + 1] = cosmeticName
                        end
                    end

                    table.sort(wrapNames)
                    for _, wrapName in ipairs(wrapNames) do
                        values[#values + 1] = wrapName
                    end
                end

                RivalsCosmetics.Catalog.WrapValues = values
                return values
            end

            function RivalsCosmetics.ResolveCharmAssetsFolder()
                local cached = RivalsCosmetics.Catalog.CharmAssetsFolder
                if cached and cached.Parent then
                    return cached
                end

                local playerScripts = RivalsCosmetics.ResolvePlayerScripts()
                local assets = playerScripts and playerScripts:FindFirstChild('Assets')
                local charmsFolder = assets and assets:FindFirstChild('Charms')
                if charmsFolder then
                    RivalsCosmetics.Catalog.CharmAssetsFolder = charmsFolder
                end
                return charmsFolder
            end

            function RivalsCosmetics.ResolveCharmValues()
                local cachedCharmValues = RivalsCosmetics.Catalog.CharmValues
                if cachedCharmValues then
                    return cachedCharmValues
                end

                local cosmeticLibrary = RivalsCosmetics.ResolveCosmeticLibrary()
                local cosmetics = cosmeticLibrary and cosmeticLibrary.Cosmetics or nil
                local assetsFolder = RivalsCosmetics.ResolveCharmAssetsFolder()
                local availableAssetNames = nil
                if assetsFolder then
                    availableAssetNames = {}
                    for _, child in ipairs(assetsFolder:GetChildren()) do
                        availableAssetNames[child.Name] = true
                    end
                end

                local values = RivalsCosmetics.ResolveSentinelValues()
                if type(cosmetics) == 'table' then
                    local charmNames = {}
                    for cosmeticName, cosmeticData in pairs(cosmetics) do
                        if cosmeticData and cosmeticData.Type == 'Charm' and not RivalsCosmetics.IsPlaceholderCatalogName(cosmeticName) then
                            if availableAssetNames == nil or availableAssetNames[cosmeticName] == true then
                                charmNames[#charmNames + 1] = cosmeticName
                            end
                        end
                    end

                    table.sort(charmNames)
                    for _, charmName in ipairs(charmNames) do
                        values[#values + 1] = charmName
                    end
                end

                RivalsCosmetics.Catalog.CharmValues = values
                return values
            end

            function RivalsCosmetics.ResolveRankCharmCatalog()
                local cached = RivalsCosmetics.Catalog.RankCharmCatalog
                if cached then
                    return cached
                end

                local modules = ReplicatedStorage:FindFirstChild('Modules')
                local seasonLibraryModule = modules and modules:FindFirstChild('SeasonLibrary')
                if not seasonLibraryModule then
                    return nil
                end

                local ok, seasonLibrary = pcall(require, seasonLibraryModule)
                local currentSeason = ok and type(seasonLibrary) == 'table' and seasonLibrary.CurrentSeason or nil
                local rankProfile = type(currentSeason) == 'table' and currentSeason.RankProfile or nil
                local ranksOrder = type(rankProfile) == 'table' and rankProfile.RanksOrder or nil
                local ranks = type(rankProfile) == 'table' and rankProfile.Ranks or nil
                local seasonsByVersion = type(seasonLibrary) == 'table' and seasonLibrary.SeasonsByVersion or nil
                if type(ranksOrder) ~= 'table' or type(ranks) ~= 'table' or type(seasonsByVersion) ~= 'table' then
                    return nil
                end

                local rankNames = {}
                local ranksByName = {}
                for _, rankName in ipairs(ranksOrder) do
                    local rankData = ranks[rankName]
                    if type(rankName) == 'string' and type(rankData) == 'table' then
                        rankNames[#rankNames + 1] = rankName
                        ranksByName[rankName] = {
                            Name = rankName,
                            RequiredELO = rankData.RequiredELO,
                            RequiresLeaderboard = rankData.RequiredELOLeaderboardRanking ~= nil,
                        }
                    end
                end

                local versions = {}
                for version in pairs(seasonsByVersion) do
                    versions[#versions + 1] = version
                end
                table.sort(versions)

                local seasonEntries = {}
                local seasonLabels = {}
                local seasonByLabel = {}
                local seasonByCharmName = {}
                for _, version in ipairs(versions) do
                    local seasonData = seasonsByVersion[version]
                    if type(seasonData) == 'table' then
                        local charmName = string.format('Season %s', tostring(version))
                        local label = string.format('Season %s (%s)', tostring(version), tostring(seasonData.Name))
                        local entry = {
                            Version = version,
                            CharmName = charmName,
                            Label = label,
                        }
                        seasonEntries[#seasonEntries + 1] = entry
                        seasonLabels[#seasonLabels + 1] = label
                        seasonByLabel[label] = charmName
                        seasonByCharmName[charmName] = entry
                    end
                end

                local catalog = {
                    RankNames = rankNames,
                    RanksByName = ranksByName,
                    SeasonEntries = seasonEntries,
                    SeasonLabels = seasonLabels,
                    SeasonByLabel = seasonByLabel,
                    SeasonByCharmName = seasonByCharmName,
                }
                RivalsCosmetics.Catalog.RankCharmCatalog = catalog
                return catalog
            end

            function RivalsCosmetics.ResolveRankCharmSeasonValues()
                local catalog = RivalsCosmetics.ResolveRankCharmCatalog()
                return catalog and table.clone(catalog.SeasonLabels) or {}
            end

            function RivalsCosmetics.ResolveRankCharmRankValues()
                local values = {RIVALS_RANK_CHARM_OFF}
                local catalog = RivalsCosmetics.ResolveRankCharmCatalog()
                for _, rankName in ipairs(catalog and catalog.RankNames or {}) do
                    values[#values + 1] = rankName
                end
                return values
            end

            function RivalsCosmetics.IsSeasonRankCharm(charmName)
                return type(charmName) == 'string'
                    and #charmName >= 8
                    and charmName:sub(1, 7) == 'Season '
                    and tonumber(charmName:sub(8)) ~= nil
            end

            function RivalsCosmetics.ParseRankCharmLeaderboardRank(value)
                local trimmed = tostring(value or ''):match('^%s*(.-)%s*$')
                if not trimmed or trimmed == '' then
                    return nil
                end

                local rank = tonumber(trimmed)
                if not rank or rank < 1 then
                    return nil
                end
                return math.floor(rank)
            end

            function RivalsCosmetics.BuildRankCharmMetadata(charmName)
                if not RivalsCosmetics.IsSeasonRankCharm(charmName) then
                    return nil
                end

                local override = RivalsCosmeticsState.RankCharmOverridesBySeason[charmName]
                local catalog = type(override) == 'table' and RivalsCosmetics.ResolveRankCharmCatalog() or nil
                local rank = catalog and catalog.RanksByName[override.rankName] or nil
                if not rank then
                    return nil
                end

                local leaderboardRank = override.leaderboardRank
                if rank.Name == 'Unranked' then
                    return {
                        SeasonELO = nil,
                        SeasonLeaderboardRank = leaderboardRank,
                    }
                end
                if rank.RequiresLeaderboard and leaderboardRank == nil then
                    leaderboardRank = 1
                end
                return {
                    SeasonELO = rank.RequiredELO,
                    SeasonLeaderboardRank = leaderboardRank,
                }
            end

            function RivalsCosmetics.PatchRankCharmPayload(payload)
                if type(payload) ~= 'table' then
                    return nil
                end

                local metadata = RivalsCosmetics.BuildRankCharmMetadata(payload.Name)
                if not metadata then
                    return nil
                end

                local patched = table.clone(payload)
                patched.Metadata = metadata
                return patched
            end

            function RivalsCosmetics.NormalizeRankCharmOverrides(value)
                local normalized = {}
                local catalog = RivalsCosmetics.ResolveRankCharmCatalog()
                if type(value) ~= 'table' or not catalog then
                    return normalized
                end

                local function addOverride(charmName, override)
                    if not RivalsCosmetics.IsSeasonRankCharm(charmName)
                        or not catalog.SeasonByCharmName[charmName]
                        or type(override) ~= 'table' then
                        return
                    end
                    local rankName = type(override.rankName) == 'string' and override.rankName or nil
                    if not rankName or not catalog.RanksByName[rankName] then
                        return
                    end
                    local leaderboardRank = RivalsCosmetics.ParseRankCharmLeaderboardRank(override.leaderboardRank)
                    normalized[charmName] = {
                        rankName = rankName,
                        leaderboardRank = leaderboardRank,
                    }
                end

                if value.rankName ~= nil or value.leaderboardRank ~= nil then
                    for _, season in ipairs(catalog.SeasonEntries) do
                        addOverride(season.CharmName, value)
                    end
                    return normalized
                end

                for charmName, override in pairs(value) do
                    addOverride(charmName, override)
                end
                return normalized
            end

            function RivalsCosmetics.ResolveSelectedRankCharmSeason()
                local catalog = RivalsCosmetics.ResolveRankCharmCatalog()
                if not catalog then
                    return nil
                end

                local charmName = RivalsCosmeticsState.SelectedRankCharmSeason
                if catalog.SeasonByCharmName[charmName] then
                    return charmName
                end

                local firstSeason = catalog.SeasonEntries[1]
                charmName = firstSeason and firstSeason.CharmName or nil
                RivalsCosmeticsState.SelectedRankCharmSeason = charmName
                return charmName
            end

            function RivalsCosmetics.SyncRankCharmEditorFromState()
                local catalog = RivalsCosmetics.ResolveRankCharmCatalog()
                local charmName = catalog and RivalsCosmetics.ResolveSelectedRankCharmSeason() or nil
                if not charmName then
                    return false
                end

                local season = catalog.SeasonByCharmName[charmName]
                local override = RivalsCosmeticsState.RankCharmOverridesBySeason[charmName]
                local rankName = type(override) == 'table' and override.rankName or RIVALS_RANK_CHARM_OFF
                local leaderboardRank = type(override) == 'table' and override.leaderboardRank or nil

                RivalsCosmeticsState.RefreshingDropdownValues = RivalsCosmeticsState.RefreshingDropdownValues + 1
                RivalsCosmetics.SyncDropdownOption(RivalsCosmetics.ResolveEditorOptionId('RankSeason'), catalog.SeasonLabels, season.Label)
                RivalsCosmetics.SyncDropdownOption(RivalsCosmetics.ResolveEditorOptionId('RankName'), RivalsCosmetics.ResolveRankCharmRankValues(), rankName)
                local leaderboardOption = Options[RivalsCosmetics.ResolveEditorOptionId('RankLeaderboard')]
                if leaderboardOption and type(leaderboardOption.SetValue) == 'function' then
                    pcall(function()
                        leaderboardOption:SetValue(leaderboardRank ~= nil and tostring(leaderboardRank) or '')
                    end)
                end
                RivalsCosmeticsState.RefreshingDropdownValues = math.max(RivalsCosmeticsState.RefreshingDropdownValues - 1, 0)
                return true
            end

            function RivalsCosmetics.SetSelectedRankCharmSeason(value)
                local catalog = RivalsCosmetics.ResolveRankCharmCatalog()
                local charmName = catalog and (catalog.SeasonByLabel[value] or (catalog.SeasonByCharmName[value] and value)) or nil
                if not charmName then
                    return false
                end

                RivalsCosmeticsState.SelectedRankCharmSeason = charmName
                RivalsCosmetics.SyncRankCharmEditorFromState()
                return true
            end

            function RivalsCosmetics.SetRankCharmOverrideForSeason(charmName, rankName, leaderboardValue)
                local catalog = RivalsCosmetics.ResolveRankCharmCatalog()
                if not catalog or not RivalsCosmetics.IsSeasonRankCharm(charmName) then
                    return false
                end

                local previous = RivalsCosmeticsState.RankCharmOverridesBySeason[charmName]
                if rankName == nil or rankName == RIVALS_RANK_CHARM_OFF or not catalog.RanksByName[rankName] then
                    if previous == nil then
                        return false
                    end
                    RivalsCosmeticsState.RankCharmOverridesBySeason[charmName] = nil
                    return true
                end

                local leaderboardRank = RivalsCosmetics.ParseRankCharmLeaderboardRank(leaderboardValue)
                if type(previous) == 'table'
                    and previous.rankName == rankName
                    and previous.leaderboardRank == leaderboardRank then
                    return false
                end
                RivalsCosmeticsState.RankCharmOverridesBySeason[charmName] = {
                    rankName = rankName,
                    leaderboardRank = leaderboardRank,
                }
                return true
            end

            function RivalsCosmetics.RefreshRankCharmApplication()
                RivalsCosmetics.RestoreInjectedWeaponData()
                pcall(RivalsCosmetics.UpdatePreviewViewport)
                return RivalsCosmetics.ApplyAll()
            end

            function RivalsCosmetics.UpdateSelectedRankCharmOverride(rankName, leaderboardValue)
                local charmName = RivalsCosmetics.ResolveSelectedRankCharmSeason()
                if not charmName then
                    return false
                end

                local changed = RivalsCosmetics.SetRankCharmOverrideForSeason(charmName, rankName, leaderboardValue)
                RivalsCosmetics.SyncRankCharmEditorFromState()
                if changed then
                    RivalsCosmetics.RefreshRankCharmApplication()
                    if type(RivalsCosmetics.QueueCosmeticPresetAutoSave) == 'function' then
                        RivalsCosmetics.QueueCosmeticPresetAutoSave()
                    end
                end
                return changed
            end

            function RivalsCosmetics.ResolveSkinOptionId(weaponName)
                local cachedOptionId = RivalsCosmetics.SkinOptionIdsByWeapon[weaponName]
                if cachedOptionId then
                    return cachedOptionId
                end

                local sanitizedWeaponName = tostring(weaponName or ''):gsub('[^%w]+', '')
                local optionId = string.format('P5SKIN_%s', sanitizedWeaponName)
                RivalsCosmetics.SkinOptionIdsByWeapon[weaponName] = optionId
                return optionId
            end

            function RivalsCosmetics.ResolveWrapOptionId(weaponName)
                local cachedOptionId = RivalsCosmetics.WrapOptionIdsByWeapon[weaponName]
                if cachedOptionId then
                    return cachedOptionId
                end

                local sanitizedWeaponName = tostring(weaponName or ''):gsub('[^%w]+', '')
                local optionId = string.format('P5WRAP_%s', sanitizedWeaponName)
                RivalsCosmetics.WrapOptionIdsByWeapon[weaponName] = optionId
                return optionId
            end

            function RivalsCosmetics.ResolveCharmOptionId(weaponName)
                local cachedOptionId = RivalsCosmetics.CharmOptionIdsByWeapon[weaponName]
                if cachedOptionId then
                    return cachedOptionId
                end

                local sanitizedWeaponName = tostring(weaponName or ''):gsub('[^%w]+', '')
                local optionId = string.format('P5CHARM_%s', sanitizedWeaponName)
                RivalsCosmetics.CharmOptionIdsByWeapon[weaponName] = optionId
                return optionId
            end

            function RivalsCosmetics.ResolveWrapInvertedOptionId(weaponName)
                local cachedOptionId = RivalsCosmetics.WrapInvertedOptionIdsByWeapon[weaponName]
                if cachedOptionId then
                    return cachedOptionId
                end

                local sanitizedWeaponName = tostring(weaponName or ''):gsub('[^%w]+', '')
                local optionId = string.format('P5WRAPINV_%s', sanitizedWeaponName)
                RivalsCosmetics.WrapInvertedOptionIdsByWeapon[weaponName] = optionId
                return optionId
            end

            function RivalsCosmetics.ResolveSelectionTable(kind)
                if kind == 'Skin' then
                    return RivalsCosmeticsState.SelectedSkinByWeapon
                elseif kind == 'Wrap' then
                    return RivalsCosmeticsState.SelectedWrapByWeapon
                elseif kind == 'Charm' then
                    return RivalsCosmeticsState.SelectedCharmByWeapon
                elseif kind == 'Finisher' then
                    return RivalsCosmeticsState.SelectedFinisherByWeapon
                elseif kind == 'WrapInverted' then
                    return RivalsCosmeticsState.SelectedWrapInvertedByWeapon
                end

                return nil
            end

            function RivalsCosmetics.IsFavoriteKind(kind)
                for _, availableKind in ipairs(RivalsCosmetics.FavoriteKinds) do
                    if kind == availableKind then
                        return true
                    end
                end
                return false
            end

            function RivalsCosmetics.NormalizeFavoritesState(value)
                local normalized = { favorites = {}, onlyUse = {} }
                if type(value) ~= 'table' then
                    return normalized
                end

                local favorites = type(value.favorites) == 'table' and value.favorites
                    or type(value.favoritedCosmetics) == 'table' and value.favoritedCosmetics or {}
                for weaponName, entries in pairs(favorites) do
                    if type(weaponName) == 'string' and weaponName ~= '' and type(entries) == 'table' then
                        local cleanEntries = {}
                        for cosmeticName, enabled in pairs(entries) do
                            if type(cosmeticName) == 'string' and cosmeticName ~= '' and enabled == true then
                                cleanEntries[cosmeticName] = true
                            end
                        end
                        if next(cleanEntries) ~= nil then
                            normalized.favorites[weaponName] = cleanEntries
                        end
                    end
                end

                local onlyUse = type(value.onlyUse) == 'table' and value.onlyUse
                    or type(value.onlyUseFavoritesSelections) == 'table' and value.onlyUseFavoritesSelections or {}
                for weaponName, entries in pairs(onlyUse) do
                    if type(weaponName) == 'string' and weaponName ~= '' and type(entries) == 'table' then
                        local cleanEntries = {}
                        for kind, enabled in pairs(entries) do
                            if RivalsCosmetics.IsFavoriteKind(kind) and enabled == true then
                                cleanEntries[kind] = true
                            end
                        end
                        if next(cleanEntries) ~= nil then
                            normalized.onlyUse[weaponName] = cleanEntries
                        end
                    end
                end
                return normalized
            end

            function RivalsCosmetics.ResolveFavoritesState()
                return RivalsCosmetics.NormalizeFavoritesState({
                    favorites = RivalsCosmeticsState.FavoritedCosmeticsByWeapon,
                    onlyUse = RivalsCosmeticsState.OnlyUseFavoritesByWeapon,
                })
            end

            function RivalsCosmetics.IsFavorited(weaponName, cosmeticName)
                local entries = RivalsCosmeticsState.FavoritedCosmeticsByWeapon[weaponName]
                return type(entries) == 'table' and entries[cosmeticName] == true
            end

            function RivalsCosmetics.SetFavorited(weaponName, cosmeticName, enabled)
                if not RivalsCosmetics.IsKnownWeaponName(weaponName)
                    or not RivalsCosmetics.IsCosmeticValueSelected(cosmeticName) then
                    return false
                end
                local entries = RivalsCosmeticsState.FavoritedCosmeticsByWeapon[weaponName]
                if type(entries) ~= 'table' then
                    entries = {}
                    RivalsCosmeticsState.FavoritedCosmeticsByWeapon[weaponName] = entries
                end
                if enabled then
                    entries[cosmeticName] = true
                else
                    entries[cosmeticName] = nil
                    if next(entries) == nil then
                        RivalsCosmeticsState.FavoritedCosmeticsByWeapon[weaponName] = nil
                    end
                end
                return true
            end

            function RivalsCosmetics.UsesOnlyFavorites(weaponName, kind)
                local entries = RivalsCosmeticsState.OnlyUseFavoritesByWeapon[weaponName]
                return type(entries) == 'table' and entries[kind] == true
            end

            function RivalsCosmetics.SetOnlyUseFavorites(weaponName, kind, enabled)
                if not RivalsCosmetics.IsKnownWeaponName(weaponName) or not RivalsCosmetics.IsFavoriteKind(kind) then
                    return false
                end
                local entries = RivalsCosmeticsState.OnlyUseFavoritesByWeapon[weaponName]
                if type(entries) ~= 'table' then
                    entries = {}
                    RivalsCosmeticsState.OnlyUseFavoritesByWeapon[weaponName] = entries
                end
                if enabled then
                    entries[kind] = true
                else
                    entries[kind] = nil
                    if next(entries) == nil then
                        RivalsCosmeticsState.OnlyUseFavoritesByWeapon[weaponName] = nil
                    end
                end
                local randomByKind = RivalsCosmeticsState.StableRandomSelectionByWeapon[weaponName]
                if randomByKind then
                    randomByKind[kind] = nil
                end
                return true
            end

            function RivalsCosmetics.SetStoredSelection(weaponName, kind, value)
                if type(weaponName) ~= 'string' or weaponName == '' then
                    return false
                end

                local selectionTable = RivalsCosmetics.ResolveSelectionTable(kind)
                if not selectionTable then
                    return false
                end

                if kind ~= 'WrapInverted' then
                    value = RivalsCosmetics.NormalizeSelectionValue(value)
                end

                if value == nil or value == '' then
                    selectionTable[weaponName] = nil
                else
                    selectionTable[weaponName] = value
                end
                return true
            end

            function RivalsCosmetics.ResolveStoredSelectionValue(weaponName, kind)
                if type(weaponName) ~= 'string' or weaponName == '' then
                    return nil
                end

                local selectionTable = RivalsCosmetics.ResolveSelectionTable(kind)
                local storedValue = selectionTable and selectionTable[weaponName]
                if storedValue ~= nil then
                    return storedValue
                end

                if kind == 'Skin' then
                    local option = Options[RivalsCosmetics.ResolveSkinOptionId(weaponName)]
                    return option and RivalsCosmetics.NormalizeSelectionValue(option.Value) or nil
                elseif kind == 'Wrap' then
                    local option = Options[RivalsCosmetics.ResolveWrapOptionId(weaponName)]
                    return option and RivalsCosmetics.NormalizeSelectionValue(option.Value) or nil
                elseif kind == 'Charm' then
                    local option = Options[RivalsCosmetics.ResolveCharmOptionId(weaponName)]
                    return option and RivalsCosmetics.NormalizeSelectionValue(option.Value) or nil
                elseif kind == 'Finisher' then
                    local option = Options[RivalsCosmetics.ResolveFinisherOptionId(weaponName)]
                    return option and RivalsCosmetics.NormalizeSelectionValue(option.Value) or nil
                elseif kind == 'WrapInverted' then
                    local toggle = Toggles[RivalsCosmetics.ResolveWrapInvertedOptionId(weaponName)]
                    if toggle and toggle.Value ~= nil then
                        return toggle.Value == true
                    end
                end

                return nil
            end

            function RivalsCosmetics.ResolveValidDropdownValue(value, values)
                if type(values) == 'table' then
                    for _, availableValue in ipairs(values) do
                        if availableValue == value then
                            return value
                        end
                    end

                    return values[1]
                end

                return nil
            end

            function RivalsCosmetics.ResolveBaseSelectionValues(weaponName, kind)
                if kind == 'Skin' then
                    return RivalsCosmetics.ResolveWeaponSkinValues(weaponName)
                elseif kind == 'Wrap' then
                    return RivalsCosmetics.ResolveWrapValues()
                elseif kind == 'Charm' then
                    return RivalsCosmetics.ResolveCharmValues()
                elseif kind == 'Finisher' then
                    return RivalsCosmetics.ResolveFinisherValues()
                end
                return nil
            end

            function RivalsCosmetics.ResolveSelectionValues(weaponName, kind)
                local values = RivalsCosmetics.ResolveBaseSelectionValues(weaponName, kind)
                if not RivalsCosmetics.UsesOnlyFavorites(weaponName, kind) then
                    return values
                end

                local filtered = {}
                for _, value in ipairs(values or {}) do
                    if not RivalsCosmetics.IsCosmeticValueSelected(value)
                        or RivalsCosmetics.IsFavorited(weaponName, value) then
                        filtered[#filtered + 1] = value
                    end
                end
                return filtered
            end

            function RivalsCosmetics.ResolveEffectiveSelectionValue(weaponName, kind, value)
                value = RivalsCosmetics.NormalizeSelectionValue(value)
                if RivalsCosmetics.IsCosmeticValueSelected(value)
                    and RivalsCosmetics.UsesOnlyFavorites(weaponName, kind)
                    and not RivalsCosmetics.IsFavorited(weaponName, value) then
                    return RIVALS_COSMETIC_UNSELECTED
                end
                if value ~= RIVALS_COSMETIC_RANDOM then
                    return value
                end

                local randomByKind = RivalsCosmeticsState.StableRandomSelectionByWeapon[weaponName]
                if not randomByKind then
                    randomByKind = {}
                    RivalsCosmeticsState.StableRandomSelectionByWeapon[weaponName] = randomByKind
                end

                local values = RivalsCosmetics.ResolveSelectionValues(weaponName, kind)
                local cachedValue = randomByKind[kind]
                if RivalsCosmetics.ResolveValidDropdownValue(cachedValue, values) == cachedValue
                    and RivalsCosmetics.IsCosmeticValueSelected(cachedValue) then
                    return cachedValue
                end

                local candidates = {}
                for _, candidate in ipairs(values or {}) do
                    if RivalsCosmetics.IsCosmeticValueSelected(candidate) then
                        candidates[#candidates + 1] = candidate
                    end
                end

                if #candidates == 0 then
                    randomByKind[kind] = nil
                    return RIVALS_COSMETIC_UNSELECTED
                end

                cachedValue = candidates[math.random(1, #candidates)]
                randomByKind[kind] = cachedValue
                return cachedValue
            end

            function RivalsCosmetics.ResolveWrapInvertedValue(weaponName)
                if not RivalsCosmetics.IsEnabled() then
                    return false
                end
                if type(weaponName) ~= 'string' or weaponName == '' then
                    return false
                end
                local value = RivalsCosmetics.ResolveStoredSelectionValue(weaponName, 'WrapInverted')
                return value == true
            end

            function RivalsCosmetics.ResolveDefaultPreviewWeaponName()
                local weaponNames = RivalsCosmetics.ResolveWeaponNames()
                for _, weaponName in ipairs(weaponNames) do
                    local value = RivalsCosmetics.ResolveStoredSelectionValue(weaponName, 'Skin')
                    if RivalsCosmetics.IsCosmeticValueSelected(value) then
                        return weaponName
                    end
                end
                for _, weaponName in ipairs(weaponNames) do
                    local wrapValue = RivalsCosmetics.ResolveStoredSelectionValue(weaponName, 'Wrap')
                    local charmValue = RivalsCosmetics.ResolveStoredSelectionValue(weaponName, 'Charm')
                    local finisherValue = RivalsCosmetics.ResolveStoredSelectionValue(weaponName, 'Finisher')
                    local invertedValue = RivalsCosmetics.ResolveStoredSelectionValue(weaponName, 'WrapInverted')
                    if RivalsCosmetics.IsCosmeticValueSelected(wrapValue)
                        or RivalsCosmetics.IsCosmeticValueSelected(charmValue)
                        or RivalsCosmetics.IsCosmeticValueSelected(finisherValue)
                        or invertedValue == true then
                        return weaponName
                    end
                end

                return weaponNames[1]
            end

            function RivalsCosmetics.SetPreviewWeaponName(weaponName)
                if type(weaponName) ~= 'string' or weaponName == '' then
                    return false
                end

                for _, availableWeaponName in ipairs(RivalsCosmetics.ResolveWeaponNames()) do
                    if availableWeaponName == weaponName then
                        RivalsCosmeticsState.PreviewWeaponName = weaponName
                        return true
                    end
                end

                return false
            end

            function RivalsCosmetics.ResolvePreviewWeaponName()
                local previewWeaponName = RivalsCosmeticsState.PreviewWeaponName
                if RivalsCosmetics.SetPreviewWeaponName(previewWeaponName) then
                    return previewWeaponName
                end

                previewWeaponName = RivalsCosmetics.ResolveDefaultPreviewWeaponName()
                RivalsCosmeticsState.PreviewWeaponName = previewWeaponName
                return previewWeaponName
            end

            function RivalsCosmetics.ResolveSkinSelectionValue(weaponName)
                if not RivalsCosmetics.IsSkinEnabled() then
                    return nil
                end

                if type(weaponName) ~= 'string' or weaponName == '' then
                    return nil
                end

                local pendingSkinName = RivalsCosmeticsState.PendingSkinSelectionByWeapon[weaponName]
                local value = pendingSkinName
                if value == nil then
                    value = RivalsCosmetics.ResolveStoredSelectionValue(weaponName, 'Skin')
                end

                return RivalsCosmetics.ResolveEffectiveSelectionValue(weaponName, 'Skin', value)
            end

            function RivalsCosmetics.ResolveSelectedSkinName(weaponName)
                local value = RivalsCosmetics.ResolveSkinSelectionValue(weaponName)
                if RivalsCosmetics.IsCosmeticValueSelected(value) then
                    return value
                end

                return nil
            end

            function RivalsCosmetics.ResolveWrapSelectionValue(weaponName)
                if not RivalsCosmetics.IsWrapEnabled() then
                    return nil
                end

                if type(weaponName) ~= 'string' or weaponName == '' then
                    return nil
                end

                local pendingWrapName = RivalsCosmeticsState.PendingWrapSelectionByWeapon[weaponName]
                local value = pendingWrapName
                if value == nil then
                    value = RivalsCosmetics.ResolveStoredSelectionValue(weaponName, 'Wrap')
                end

                return RivalsCosmetics.ResolveEffectiveSelectionValue(weaponName, 'Wrap', value)
            end

            function RivalsCosmetics.ResolveSelectedWrapName(weaponName)
                local value = RivalsCosmetics.ResolveWrapSelectionValue(weaponName)
                if RivalsCosmetics.IsCosmeticValueSelected(value) then
                    return value
                end

                return nil
            end

            function RivalsCosmetics.ResolveCharmSelectionValue(weaponName)
                if not RivalsCosmetics.IsEnabled() then
                    return nil
                end

                if type(weaponName) ~= 'string' or weaponName == '' then
                    return nil
                end

                local pendingCharmName = RivalsCosmeticsState.PendingCharmSelectionByWeapon[weaponName]
                local value = pendingCharmName
                if value == nil then
                    value = RivalsCosmetics.ResolveStoredSelectionValue(weaponName, 'Charm')
                end

                return RivalsCosmetics.ResolveEffectiveSelectionValue(weaponName, 'Charm', value)
            end

            function RivalsCosmetics.ResolveSelectedCharmName(weaponName)
                local value = RivalsCosmetics.ResolveCharmSelectionValue(weaponName)
                if RivalsCosmetics.IsCosmeticValueSelected(value) then
                    return value
                end

                return nil
            end

            function RivalsCosmetics.ResolveFinisherAssetsFolder()
                local cached = RivalsCosmetics.Catalog.FinisherAssetsFolder
                if cached and cached.Parent then
                    return cached
                end

                local replicatedStorage = game:GetService('ReplicatedStorage')
                local modules = replicatedStorage:FindFirstChild('Modules')
                local finishersFolder = modules and modules:FindFirstChild('Finishers')
                if finishersFolder then
                    RivalsCosmetics.Catalog.FinisherAssetsFolder = finishersFolder
                end
                return finishersFolder
            end

            function RivalsCosmetics.ResolveFinisherValues()
                local cachedFinisherValues = RivalsCosmetics.Catalog.FinisherValues
                if cachedFinisherValues then
                    return cachedFinisherValues
                end

                local cosmeticLibrary = RivalsCosmetics.ResolveCosmeticLibrary()
                local cosmetics = cosmeticLibrary and cosmeticLibrary.Cosmetics or nil
                local assetsFolder = RivalsCosmetics.ResolveFinisherAssetsFolder()
                local availableAssetNames = nil
                if assetsFolder then
                    availableAssetNames = {}
                    for _, child in ipairs(assetsFolder:GetChildren()) do
                        availableAssetNames[child.Name] = true
                    end
                end

                local values = RivalsCosmetics.ResolveSentinelValues()
                if type(cosmetics) == 'table' then
                    local finisherNames = {}
                    for cosmeticName, cosmeticData in pairs(cosmetics) do
                        if cosmeticData and cosmeticData.Type == 'Finisher' and not RivalsCosmetics.IsPlaceholderCatalogName(cosmeticName) then
                            if availableAssetNames == nil or availableAssetNames[cosmeticName] == true then
                                finisherNames[#finisherNames + 1] = cosmeticName
                            end
                        end
                    end

                    table.sort(finisherNames)
                    for _, finisherName in ipairs(finisherNames) do
                        values[#values + 1] = finisherName
                    end
                end

                RivalsCosmetics.Catalog.FinisherValues = values
                return values
            end

            function RivalsCosmetics.ResolveFinisherOptionId(weaponName)
                local cachedOptionId = RivalsCosmetics.FinisherOptionIdsByWeapon[weaponName]
                if cachedOptionId then
                    return cachedOptionId
                end

                local sanitizedWeaponName = tostring(weaponName or ''):gsub('[^%w]+', '')
                local optionId = string.format('P5FINISHER_%s', sanitizedWeaponName)
                RivalsCosmetics.FinisherOptionIdsByWeapon[weaponName] = optionId
                return optionId
            end

            function RivalsCosmetics.ResolveCosmeticOptionInfo(optionId)
                if type(optionId) ~= 'string' then
                    return nil
                end

                for _, weaponName in ipairs(RivalsCosmetics.ResolveWeaponNames()) do
                    if optionId == RivalsCosmetics.ResolveSkinOptionId(weaponName) then
                        return { weaponName = weaponName, kind = 'Skin', type = 'Dropdown' }
                    elseif optionId == RivalsCosmetics.ResolveWrapOptionId(weaponName) then
                        return { weaponName = weaponName, kind = 'Wrap', type = 'Dropdown' }
                    elseif optionId == RivalsCosmetics.ResolveCharmOptionId(weaponName) then
                        return { weaponName = weaponName, kind = 'Charm', type = 'Dropdown' }
                    elseif optionId == RivalsCosmetics.ResolveFinisherOptionId(weaponName) then
                        return { weaponName = weaponName, kind = 'Finisher', type = 'Dropdown' }
                    elseif optionId == RivalsCosmetics.ResolveWrapInvertedOptionId(weaponName) then
                        return { weaponName = weaponName, kind = 'WrapInverted', type = 'Toggle' }
                    end
                end

                return nil
            end

            function RivalsCosmetics.ResolveFinisherSelectionValue(weaponName)
                if not RivalsCosmetics.IsEnabled() then
                    return nil
                end

                if type(weaponName) ~= 'string' or weaponName == '' then
                    return nil
                end

                local pendingFinisherName = RivalsCosmeticsState.PendingFinisherSelectionByWeapon[weaponName]
                local value = pendingFinisherName
                if value == nil then
                    value = RivalsCosmetics.ResolveStoredSelectionValue(weaponName, 'Finisher')
                end

                return RivalsCosmetics.ResolveEffectiveSelectionValue(weaponName, 'Finisher', value)
            end

            function RivalsCosmetics.ResolveSelectedFinisherName(weaponName)
                local value = RivalsCosmetics.ResolveFinisherSelectionValue(weaponName)
                if RivalsCosmetics.IsCosmeticValueSelected(value) then
                    return value
                end

                return nil
            end

            function RivalsCosmetics.ResolveSelectedPlaybackFinisherName()
                if not RivalsCosmetics.IsEnabled() then
                    return nil
                end

                local fighter = ResolveLocalFighter()
                local item = fighter and fighter.EquippedItem or nil
                local weaponName = item and item.Name or nil
                if type(weaponName) ~= 'string' or weaponName == '' then
                    return nil
                end

                local selectedFinisherName = RivalsCosmetics.ResolveSelectedFinisherName(weaponName)
                if type(selectedFinisherName) == 'string' and selectedFinisherName ~= '' then
                    return selectedFinisherName
                end

                return nil
            end

            function RivalsCosmetics.IsKnownWeaponName(weaponName)
                if type(weaponName) ~= 'string' or weaponName == '' then
                    return false
                end

                for _, availableWeaponName in ipairs(RivalsCosmetics.ResolveWeaponNames()) do
                    if availableWeaponName == weaponName then
                        return true
                    end
                end

                return false
            end

            function RivalsCosmetics.IsKnownEditorWeaponName(weaponName)
                return weaponName == RIVALS_COSMETIC_ALL_WEAPONS or RivalsCosmetics.IsKnownWeaponName(weaponName)
            end

            function RivalsCosmetics.ResolveSelectedEditorWeaponName()
                local selectedWeaponName = RivalsCosmeticsState.SelectedEditorWeaponName
                if RivalsCosmetics.IsKnownEditorWeaponName(selectedWeaponName) then
                    return selectedWeaponName
                end

                local option = Options[RivalsCosmetics.ResolveEditorOptionId('Weapon')]
                selectedWeaponName = option and option.Value or nil
                if RivalsCosmetics.IsKnownEditorWeaponName(selectedWeaponName) then
                    RivalsCosmeticsState.SelectedEditorWeaponName = selectedWeaponName
                    if selectedWeaponName ~= RIVALS_COSMETIC_ALL_WEAPONS then
                        RivalsCosmetics.SetPreviewWeaponName(selectedWeaponName)
                    end
                    return selectedWeaponName
                end

                RivalsCosmeticsState.SelectedEditorWeaponName = RIVALS_COSMETIC_ALL_WEAPONS
                return RIVALS_COSMETIC_ALL_WEAPONS
            end

            function RivalsCosmetics.SyncDropdownOption(optionId, values, value)
                local option = Options[optionId]
                if not option then
                    return false
                end

                if type(option.SetValues) == 'function' and type(values) == 'table' then
                    pcall(function()
                        option:SetValues(values)
                    end)
                end

                if type(option.SetValue) == 'function' then
                    pcall(function()
                        option:SetValue(value)
                    end)
                end

                return true
            end

            function RivalsCosmetics.ResolveEditorSelectionValue(weaponName, kind, values)
                if weaponName ~= RIVALS_COSMETIC_ALL_WEAPONS then
                    local storedValue = RivalsCosmetics.ResolveStoredSelectionValue(weaponName, kind)
                    return RivalsCosmetics.ResolveValidDropdownValue(storedValue, values) or RIVALS_COSMETIC_UNSELECTED
                end

                local commonValue = nil
                for _, availableWeaponName in ipairs(RivalsCosmetics.ResolveWeaponNames()) do
                    local storedValue = RivalsCosmetics.ResolveStoredSelectionValue(availableWeaponName, kind)
                    storedValue = RivalsCosmetics.ResolveValidDropdownValue(storedValue, values) or RIVALS_COSMETIC_UNSELECTED
                    if commonValue == nil then
                        commonValue = storedValue
                    elseif commonValue ~= storedValue then
                        return RIVALS_COSMETIC_UNSELECTED
                    end
                end
                return commonValue or RIVALS_COSMETIC_UNSELECTED
            end

            function RivalsCosmetics.ResolveEditorWrapInvertedValue(weaponName)
                if weaponName ~= RIVALS_COSMETIC_ALL_WEAPONS then
                    return RivalsCosmetics.ResolveStoredSelectionValue(weaponName, 'WrapInverted') == true
                end

                local sawWeapon = false
                for _, availableWeaponName in ipairs(RivalsCosmetics.ResolveWeaponNames()) do
                    sawWeapon = true
                    if RivalsCosmetics.ResolveStoredSelectionValue(availableWeaponName, 'WrapInverted') ~= true then
                        return false
                    end
                end
                return sawWeapon
            end

            function RivalsCosmetics.SyncActiveWeaponEditorFromState()
                local weaponName = RivalsCosmetics.ResolveSelectedEditorWeaponName()
                if not weaponName then
                    return false
                end

                local weaponValues = RivalsCosmetics.ResolveEditorWeaponNames()
                local skinValues = weaponName == RIVALS_COSMETIC_ALL_WEAPONS and RivalsCosmetics.ResolveSentinelValues()
                    or RivalsCosmetics.ResolveSelectionValues(weaponName, 'Skin')
                local wrapValues = weaponName == RIVALS_COSMETIC_ALL_WEAPONS and RivalsCosmetics.ResolveWrapValues()
                    or RivalsCosmetics.ResolveSelectionValues(weaponName, 'Wrap')
                local charmValues = weaponName == RIVALS_COSMETIC_ALL_WEAPONS and RivalsCosmetics.ResolveCharmValues()
                    or RivalsCosmetics.ResolveSelectionValues(weaponName, 'Charm')
                local finisherValues = weaponName == RIVALS_COSMETIC_ALL_WEAPONS and RivalsCosmetics.ResolveFinisherValues()
                    or RivalsCosmetics.ResolveSelectionValues(weaponName, 'Finisher')

                local skinValue = RivalsCosmetics.ResolveEditorSelectionValue(weaponName, 'Skin', skinValues)
                local wrapValue = RivalsCosmetics.ResolveEditorSelectionValue(weaponName, 'Wrap', wrapValues)
                local charmValue = RivalsCosmetics.ResolveEditorSelectionValue(weaponName, 'Charm', charmValues)
                local finisherValue = RivalsCosmetics.ResolveEditorSelectionValue(weaponName, 'Finisher', finisherValues)
                local invertedValue = RivalsCosmetics.ResolveEditorWrapInvertedValue(weaponName)

                RivalsCosmeticsState.RefreshingDropdownValues = RivalsCosmeticsState.RefreshingDropdownValues + 1
                RivalsCosmetics.SyncDropdownOption(RivalsCosmetics.ResolveEditorOptionId('Weapon'), weaponValues, weaponName)
                RivalsCosmetics.SyncDropdownOption(RivalsCosmetics.ResolveEditorOptionId('Skin'), skinValues, skinValue)
                RivalsCosmetics.SyncDropdownOption(RivalsCosmetics.ResolveEditorOptionId('Wrap'), wrapValues, wrapValue)
                RivalsCosmetics.SyncDropdownOption(RivalsCosmetics.ResolveEditorOptionId('Charm'), charmValues, charmValue)
                RivalsCosmetics.SyncDropdownOption(RivalsCosmetics.ResolveEditorOptionId('Finisher'), finisherValues, finisherValue)

                local invertedToggle = Toggles[RivalsCosmetics.ResolveEditorOptionId('WrapInverted')]
                if invertedToggle and type(invertedToggle.SetValue) == 'function' then
                    pcall(function()
                        invertedToggle:SetValue(invertedValue)
                    end)
                end
                RivalsCosmeticsState.RefreshingDropdownValues = math.max(RivalsCosmeticsState.RefreshingDropdownValues - 1, 0)

                return true
            end

            function RivalsCosmetics.ResolveSelectedFavoriteKind()
                local option = Options.P5FAVORITE_TYPE
                local kind = option and option.Value or RivalsCosmetics.FavoriteKinds[1]
                return RivalsCosmetics.IsFavoriteKind(kind) and kind or RivalsCosmetics.FavoriteKinds[1]
            end

            function RivalsCosmetics.SyncFavoriteEditorFromState()
                local weaponName = RivalsCosmetics.ResolveSelectedEditorWeaponName()
                local kind = RivalsCosmetics.ResolveSelectedFavoriteKind()
                local onlyUse = weaponName ~= RIVALS_COSMETIC_ALL_WEAPONS
                    and RivalsCosmetics.UsesOnlyFavorites(weaponName, kind) or false
                local toggle = Toggles.P5FAVORITE_ONLY
                if toggle and type(toggle.SetValue) == 'function' then
                    RivalsCosmeticsState.RefreshingDropdownValues = RivalsCosmeticsState.RefreshingDropdownValues + 1
                    pcall(function()
                        toggle:SetValue(onlyUse)
                    end)
                    RivalsCosmeticsState.RefreshingDropdownValues = math.max(RivalsCosmeticsState.RefreshingDropdownValues - 1, 0)
                end
                return weaponName ~= RIVALS_COSMETIC_ALL_WEAPONS
            end

            function RivalsCosmetics.SetSelectedFavoriteKind(kind)
                if not RivalsCosmetics.IsFavoriteKind(kind) then
                    return false
                end
                RivalsCosmetics.SyncFavoriteEditorFromState()
                return true
            end

            function RivalsCosmetics.RefreshFavoriteApplication()
                RivalsCosmetics.SyncActiveWeaponEditorFromState()
                RivalsCosmetics.SyncFavoriteEditorFromState()
                RivalsCosmetics.RestoreAppliedCosmetics()
                pcall(RivalsCosmetics.UpdatePreviewViewport)
                RivalsCosmetics.ApplyAll()
                if type(RivalsCosmetics.QueueCosmeticPresetAutoSave) == 'function' then
                    RivalsCosmetics.QueueCosmeticPresetAutoSave()
                end
                return true
            end

            function RivalsCosmetics.ToggleSelectedFavorite()
                local weaponName = RivalsCosmetics.ResolveSelectedEditorWeaponName()
                local kind = RivalsCosmetics.ResolveSelectedFavoriteKind()
                if weaponName == RIVALS_COSMETIC_ALL_WEAPONS then
                    return false
                end
                local cosmeticName = RivalsCosmetics.ResolveStoredSelectionValue(weaponName, kind)
                if not RivalsCosmetics.IsCosmeticValueSelected(cosmeticName) then
                    return false
                end
                if not RivalsCosmetics.SetFavorited(
                    weaponName,
                    cosmeticName,
                    not RivalsCosmetics.IsFavorited(weaponName, cosmeticName)
                ) then
                    return false
                end
                local randomByKind = RivalsCosmeticsState.StableRandomSelectionByWeapon[weaponName]
                if randomByKind then
                    randomByKind[kind] = nil
                end
                return RivalsCosmetics.RefreshFavoriteApplication()
            end

            function RivalsCosmetics.SetSelectedOnlyUseFavorites(enabled)
                local weaponName = RivalsCosmetics.ResolveSelectedEditorWeaponName()
                local kind = RivalsCosmetics.ResolveSelectedFavoriteKind()
                if weaponName == RIVALS_COSMETIC_ALL_WEAPONS
                    or not RivalsCosmetics.SetOnlyUseFavorites(weaponName, kind, enabled == true) then
                    return false
                end
                return RivalsCosmetics.RefreshFavoriteApplication()
            end

            function RivalsCosmetics.SetSelectedEditorWeapon(weaponName)
                if not RivalsCosmetics.IsKnownEditorWeaponName(weaponName) then
                    return false
                end

                RivalsCosmeticsState.SelectedEditorWeaponName = weaponName
                if weaponName ~= RIVALS_COSMETIC_ALL_WEAPONS then
                    RivalsCosmetics.SetPreviewWeaponName(weaponName)
                end
                RivalsCosmetics.SyncActiveWeaponEditorFromState()
                RivalsCosmetics.SyncFavoriteEditorFromState()
                pcall(RivalsCosmetics.UpdatePreviewViewport)
                return true
            end

            function RivalsCosmetics.IsValidEditorSelection(weaponName, kind, value)
                if kind == 'WrapInverted' then
                    return type(value) == 'boolean'
                end

                value = RivalsCosmetics.NormalizeSelectionValue(value)
                local values = nil
                if weaponName == RIVALS_COSMETIC_ALL_WEAPONS and kind == 'Skin' then
                    values = RivalsCosmetics.ResolveSentinelValues()
                else
                    values = RivalsCosmetics.ResolveSelectionValues(weaponName, kind)
                end
                return RivalsCosmetics.ResolveValidDropdownValue(value, values) == value
            end

            function RivalsCosmetics.SetSelectionForSelectedEditorWeapon(kind, value)
                local previewWeaponName = RivalsCosmetics.ResolveSelectedEditorWeaponName()
                if not previewWeaponName or not RivalsCosmetics.IsValidEditorSelection(previewWeaponName, kind, value) then
                    return false
                end

                value = kind == 'WrapInverted' and value == true or RivalsCosmetics.NormalizeSelectionValue(value)

                if previewWeaponName == RIVALS_COSMETIC_ALL_WEAPONS then
                    for _, weaponName in ipairs(RivalsCosmetics.ResolveWeaponNames()) do
                        RivalsCosmetics.SetStoredSelection(weaponName, kind, value)
                    end
                elseif not RivalsCosmetics.SetStoredSelection(previewWeaponName, kind, value) then
                    return false
                end

                RivalsCosmetics.RestoreAppliedCosmetics()
                pcall(RivalsCosmetics.UpdatePreviewViewport)
                RivalsCosmetics.ApplyAll()
                if type(RivalsCosmetics.QueueCosmeticPresetAutoSave) == 'function' then
                    RivalsCosmetics.QueueCosmeticPresetAutoSave()
                end
                return true
            end

            function RivalsCosmetics.RerollRandomSelections()
                RivalsCosmeticsState.StableRandomSelectionByWeapon = {}
                RivalsCosmetics.RestoreAppliedCosmetics()
                pcall(RivalsCosmetics.UpdatePreviewViewport)
                RivalsCosmetics.ApplyAll()
                return true
            end

            function RivalsCosmetics.BuildevilrollerplayersItemSelection(weaponName)
                local selection = {}
                local hasSelection = false
                local skin = RivalsCosmetics.ResolveSkinSelectionValue(weaponName)
                local wrap = RivalsCosmetics.ResolveWrapSelectionValue(weaponName)
                local charm = RivalsCosmetics.ResolveCharmSelectionValue(weaponName)
                local finisher = RivalsCosmetics.ResolveFinisherSelectionValue(weaponName)

                if skin ~= nil and skin ~= RIVALS_COSMETIC_UNSELECTED then
                    selection.skin = skin
                    hasSelection = true
                end
                if wrap ~= nil and wrap ~= RIVALS_COSMETIC_UNSELECTED then
                    selection.wrap = {
                        name = wrap,
                        inverted = RivalsCosmetics.ResolveWrapInvertedValue(weaponName) == true,
                    }
                    hasSelection = true
                end
                if charm ~= nil and charm ~= RIVALS_COSMETIC_UNSELECTED then
                    selection.charm = charm
                    hasSelection = true
                end
                if finisher ~= nil and finisher ~= RIVALS_COSMETIC_UNSELECTED then
                    selection.finisher = finisher
                    hasSelection = true
                end

                return hasSelection and selection or nil
            end

            function RivalsCosmetics.BuildevilrollerplayersCosmeticPayload(cosmeticName, inverted)
                if cosmeticName == nil or cosmeticName == RIVALS_COSMETIC_NONE then
                    return nil
                end

                local payload = { Name = cosmeticName }
                if inverted ~= nil then
                    payload.Inverted = inverted == true and true or nil
                end
                return payload
            end

            function RivalsCosmetics.OverrideWeaponData(weaponName, weaponData)
                if type(weaponData) ~= 'table' then
                    return weaponData
                end

                local selection = RivalsCosmetics.BuildevilrollerplayersItemSelection(weaponName)
                local patchedNaturalCharm = RivalsCosmetics.PatchRankCharmPayload(weaponData.Charm)
                local hasOnlyUseFavoritesOverride = false
                for _, cosmeticType in ipairs(RivalsCosmetics.FavoriteKinds) do
                    if RivalsCosmetics.UsesOnlyFavorites(weaponName, cosmeticType) then
                        hasOnlyUseFavoritesOverride = true
                        break
                    end
                end
                if selection == nil and patchedNaturalCharm == nil and not hasOnlyUseFavoritesOverride then
                    return weaponData
                end

                local overriddenWeaponData = table.clone(weaponData)
                if selection ~= nil then
                    if selection.skin ~= nil then
                        overriddenWeaponData.Skin = RivalsCosmetics.BuildevilrollerplayersCosmeticPayload(selection.skin)
                    end
                    if selection.wrap ~= nil then
                        overriddenWeaponData.Wrap = RivalsCosmetics.BuildevilrollerplayersCosmeticPayload(
                            selection.wrap.name,
                            selection.wrap.inverted
                        )
                    end
                    if selection.charm ~= nil then
                        overriddenWeaponData.Charm = RivalsCosmetics.BuildevilrollerplayersCosmeticPayload(selection.charm)
                    end
                    if selection.finisher ~= nil then
                        overriddenWeaponData.Finisher = RivalsCosmetics.BuildevilrollerplayersCosmeticPayload(selection.finisher)
                    end
                end
                overriddenWeaponData.Charm = RivalsCosmetics.PatchRankCharmPayload(overriddenWeaponData.Charm)
                    or overriddenWeaponData.Charm

                for _, cosmeticType in ipairs(RivalsCosmetics.FavoriteKinds) do
                    local cosmeticData = overriddenWeaponData[cosmeticType]
                    if RivalsCosmetics.UsesOnlyFavorites(weaponName, cosmeticType)
                        and type(cosmeticData) == 'table'
                        and type(cosmeticData.Name) == 'string' then
                        cosmeticData = table.clone(cosmeticData)
                        cosmeticData.OnlyUseFavorites = true
                        overriddenWeaponData[cosmeticType] = cosmeticData
                    end
                end

                overriddenWeaponData.Level = rawget(weaponData, 'Level')
                overriddenWeaponData.Prestige = rawget(weaponData, 'Prestige')
                overriddenWeaponData.XP = rawget(weaponData, 'XP')
                return overriddenWeaponData
            end

            function RivalsCosmetics.ResolveItemLibrary()
                local cached = RivalsCosmetics.Catalog.ItemLibrary
                if cached then
                    return cached
                end

                local modules = ReplicatedStorage:FindFirstChild('Modules')
                local itemLibraryModule = modules and modules:FindFirstChild('ItemLibrary')
                if not itemLibraryModule then
                    return nil
                end

                local ok, itemLibrary = pcall(require, itemLibraryModule)
                if not ok or type(itemLibrary) ~= 'table' then
                    return nil
                end

                RivalsCosmetics.Catalog.ItemLibrary = itemLibrary
                return itemLibrary
            end

            function RivalsCosmetics.ResolveEquipmentModule()
                local cached = RivalsCosmetics.Catalog.EquipmentModule
                if cached then
                    return cached
                end

                local playerScripts = RivalsCosmetics.ResolvePlayerScripts()
                local modules = playerScripts and playerScripts:FindFirstChild('Modules')
                local userInterface = modules and modules:FindFirstChild('UserInterface')
                local equipmentModule = userInterface and userInterface:FindFirstChild('Equipment')
                if not equipmentModule then
                    return nil
                end

                local ok, equipment = pcall(require, equipmentModule)
                if not ok or type(equipment) ~= 'table' then
                    return nil
                end

                RivalsCosmetics.Catalog.EquipmentModule = equipment
                return equipment
            end

            function RivalsCosmetics.BuildNativeUnlockedInventory()
                local cached = RivalsCosmeticsState.NativeUnlockedInventory
                if type(cached) == 'table' then
                    return cached
                end

                local cosmeticLibrary = RivalsCosmetics.ResolveCosmeticLibrary()
                local itemLibrary = RivalsCosmetics.ResolveItemLibrary()
                local cosmetics = cosmeticLibrary and cosmeticLibrary.Cosmetics or nil
                local items = itemLibrary and itemLibrary.Items or nil
                if type(cosmetics) ~= 'table' or type(items) ~= 'table' then
                    return nil
                end

                -- evilrollerplayers's inventory contract is intentionally asymmetric: weapon-specific
                -- skins and emotes are booleans, while universal cosmetics map every item.
                local allItemNames = {}
                for itemName in pairs(items) do
                    if type(itemName) == 'string' and itemName ~= '' then
                        allItemNames[itemName] = true
                    end
                end

                local inventory = {}
                for cosmeticName, cosmeticData in pairs(cosmetics) do
                    local cosmeticType = type(cosmeticData) == 'table' and cosmeticData.Type or nil
                    if type(cosmeticName) == 'string' then
                        if cosmeticType == 'Skin' or cosmeticType == 'Emote' then
                            inventory[cosmeticName] = true
                        elseif cosmeticType == 'Wrap' or cosmeticType == 'Charm' or cosmeticType == 'Finisher' then
                            inventory[cosmeticName] = allItemNames
                        end
                    end
                end

                RivalsCosmeticsState.NativeUnlockedInventory = inventory
                return inventory
            end

            function RivalsCosmetics.CloneNativeFavorites(value)
                local cloned = {}
                if type(value) ~= 'table' then
                    return cloned
                end

                for itemName, entries in pairs(value) do
                    if type(itemName) == 'string' and type(entries) == 'table' then
                        local itemFavorites = {}
                        for cosmeticName, enabled in pairs(entries) do
                            if type(cosmeticName) == 'string' and enabled == true then
                                itemFavorites[cosmeticName] = true
                            end
                        end
                        if next(itemFavorites) ~= nil then
                            cloned[itemName] = itemFavorites
                        end
                    end
                end
                return cloned
            end

            function RivalsCosmetics.SeedNativeFavorites(baseFavorites)
                if RivalsCosmeticsState.NativeFavoritesSeeded then
                    return
                end
                if next(RivalsCosmeticsState.FavoritedCosmeticsByWeapon) == nil then
                    RivalsCosmeticsState.FavoritedCosmeticsByWeapon = RivalsCosmetics.CloneNativeFavorites(baseFavorites)
                end
                RivalsCosmeticsState.NativeFavoritesSeeded = true
            end

            function RivalsCosmetics.ResolveNativeDataField(fieldName, originalValue)
                if not RivalsCosmetics.IsEnabled() then
                    return originalValue
                end
                if fieldName == 'CosmeticInventory' then
                    return RivalsCosmetics.BuildNativeUnlockedInventory() or originalValue
                end
                if fieldName == 'FavoritedCosmetics' then
                    RivalsCosmetics.SeedNativeFavorites(originalValue)
                    return RivalsCosmeticsState.FavoritedCosmeticsByWeapon
                end
                return originalValue
            end

            function RivalsCosmetics.EnsureNativeDataView()
                if not RivalsCosmetics.IsEnabled() then
                    return false
                end
                return type(RivalsCosmetics.BuildNativeUnlockedInventory()) == 'table'
            end

            function RivalsCosmetics.TriggerNativeDataChanged(fieldName)
                local playerDataController = RivalsCosmetics.ResolvePlayerDataController()
                local currentData = playerDataController and playerDataController.CurrentData or nil
                if type(currentData) ~= 'table' then
                    return false
                end

                local events = rawget(currentData, '_value_changed_events')
                local signal = type(events) == 'table' and events[fieldName] or nil
                if type(signal) == 'table' and type(signal.Fire) == 'function' then
                    return pcall(signal.Fire, signal)
                end
                return false
            end

            function RivalsCosmetics.RefreshNativeCosmeticsScene()
                RivalsCosmetics.TriggerNativeDataChanged('CosmeticInventory')
                RivalsCosmetics.TriggerNativeDataChanged('FavoritedCosmetics')

                local equipment = RivalsCosmetics.ResolveEquipmentModule()
                local interface = equipment and equipment.Interface or nil
                local customize = interface and interface.Customize or nil
                local cosmetics = customize and customize.Cosmetics or nil
                if type(cosmetics) ~= 'table' then
                    return false
                end

                local onStateChanged = cosmetics.OnStateChanged
                if type(onStateChanged) ~= 'function' then
                    return false
                end

                task.spawn(function()
                    local previousIdentity = type(getthreadidentity) == 'function' and getthreadidentity() or nil
                    if type(setthreadidentity) == 'function' then
                        pcall(setthreadidentity, 2)
                    end
                    pcall(onStateChanged, cosmetics)
                    if previousIdentity ~= nil and type(setthreadidentity) == 'function' then
                        pcall(setthreadidentity, previousIdentity)
                    end
                end)
                return true
            end

            function RivalsCosmetics.ReadEquipmentStateValue(fieldName)
                local equipment = RivalsCosmetics.ResolveEquipmentModule()
                local equipmentState = equipment and equipment.EquipmentState or nil
                if type(equipmentState) ~= 'table' then
                    return nil
                end
                local ok, value = pcall(function()
                    return equipmentState[fieldName]
                end)
                return ok and value or nil
            end

            function RivalsCosmetics.NormalizeNativeStateName(value)
                if type(value) == 'string' then
                    return value
                end
                if type(value) == 'table' and type(value.Name) == 'string' then
                    return value.Name
                end
                if typeof(value) == 'EnumItem' then
                    return value.Name
                end
                return nil
            end

            function RivalsCosmetics.ResolveNativeFavoriteName(cosmeticName, cosmeticType)
                local nativeName = cosmeticName
                if cosmeticName == RIVALS_COSMETIC_NONE then
                    nativeName = 'NONE_COSMETIC'
                elseif cosmeticName == RIVALS_COSMETIC_RANDOM then
                    nativeName = 'RANDOM_COSMETIC'
                end

                local cosmeticLibrary = RivalsCosmetics.ResolveCosmeticLibrary()
                if type(cosmeticLibrary) == 'table' and type(cosmeticLibrary.GetNoneSpecificCosmeticName) == 'function' then
                    local ok, resolved = pcall(cosmeticLibrary.GetNoneSpecificCosmeticName, cosmeticLibrary, nativeName, cosmeticType)
                    if ok and type(resolved) == 'string' and resolved ~= '' then
                        return resolved
                    end
                end
                return nativeName
            end

            function RivalsCosmetics.QueueNativeStateSave()
                RivalsCosmeticsState.NativeSaveToken = RivalsCosmeticsState.NativeSaveToken + 1
                local saveToken = RivalsCosmeticsState.NativeSaveToken
                task.delay(0.2, function()
                    if RivalsCosmeticsState.NativeSaveToken == saveToken then
                        pcall(RivalsCosmetics.SaveSelectionsToConfig)
                    end
                end)
            end

            function RivalsCosmetics.CaptureNativeSelection(toggleFavorite, toggleOnlyUseFavorites, invertedOverride)
                if not RivalsCosmetics.IsEnabled() then
                    return false
                end

                local weaponName = RivalsCosmetics.NormalizeNativeStateName(RivalsCosmetics.ReadEquipmentStateValue('SelectedWeapon'))
                local cosmeticType = RivalsCosmetics.NormalizeNativeStateName(RivalsCosmetics.ReadEquipmentStateValue('CustomizingType'))
                local cosmeticName = RivalsCosmetics.NormalizeNativeStateName(RivalsCosmetics.ReadEquipmentStateValue('SelectedCosmetic'))
                if type(weaponName) ~= 'string' or not RivalsCosmetics.IsFavoriteKind(cosmeticType) then
                    return false
                end

                if type(cosmeticName) ~= 'string' or cosmeticName == '' or cosmeticName == 'NONE_COSMETIC' then
                    cosmeticName = RIVALS_COSMETIC_NONE
                elseif cosmeticName == 'RANDOM_COSMETIC' then
                    cosmeticName = RIVALS_COSMETIC_RANDOM
                end

                local changed = false
                if toggleFavorite then
                    local favoriteName = RivalsCosmetics.ResolveNativeFavoriteName(cosmeticName, cosmeticType)
                    if cosmeticName == RIVALS_COSMETIC_NONE then
                        favoriteName = 'NONE_COSMETIC_' .. cosmeticType
                    end
                    changed = RivalsCosmetics.SetFavorited(
                        weaponName,
                        favoriteName,
                        not RivalsCosmetics.IsFavorited(weaponName, favoriteName)
                    ) or changed
                else
                    if toggleOnlyUseFavorites then
                        changed = RivalsCosmetics.SetOnlyUseFavorites(
                            weaponName,
                            cosmeticType,
                            not RivalsCosmetics.UsesOnlyFavorites(weaponName, cosmeticType)
                        ) or changed
                    end
                    if RivalsCosmetics.ResolveStoredSelectionValue(weaponName, cosmeticType) ~= cosmeticName then
                        changed = RivalsCosmetics.SetStoredSelection(weaponName, cosmeticType, cosmeticName) or changed
                    end
                    if cosmeticType == 'Wrap' then
                        local inverted = invertedOverride
                        if inverted == nil then
                            inverted = RivalsCosmeticsState.NativeInvertedValue
                        end
                        inverted = inverted == true
                        if RivalsCosmetics.ResolveStoredSelectionValue(weaponName, 'WrapInverted') ~= inverted then
                            changed = RivalsCosmetics.SetStoredSelection(weaponName, 'WrapInverted', inverted) or changed
                        end
                    end
                end

                if not changed then
                    return false
                end

                RivalsCosmetics.TriggerNativeDataChanged('WeaponInventory')
                RivalsCosmetics.TriggerNativeDataChanged('WeaponData')
                pcall(RivalsCosmetics.ReloadWeaponViewModel, weaponName)
                pcall(RivalsCosmetics.ApplyWraps)
                pcall(RivalsCosmetics.RefreshNativeCosmeticsScene)
                RivalsCosmetics.QueueNativeStateSave()
                return true
            end

            function RivalsCosmetics.EnsureNativeInvertedState()
                if RivalsCosmeticsState.NativeEquipmentStateRestore ~= nil then
                    return true
                end

                local equipment = RivalsCosmetics.ResolveEquipmentModule()
                local equipmentState = type(equipment) == 'table' and rawget(equipment, 'EquipmentState') or nil
                local originalMetatable = type(equipmentState) == 'table' and getmetatable(equipmentState) or nil
                local originalIndex = type(originalMetatable) == 'table' and rawget(originalMetatable, '__index') or nil
                if type(equipmentState) ~= 'table' or originalMetatable == nil or originalIndex == nil then
                    return false
                end

                local selectedWeapon = rawget(equipmentState, 'SelectedWeapon')
                if type(selectedWeapon) == 'string' and selectedWeapon ~= '' then
                    RivalsCosmeticsState.NativeInvertedValue = RivalsCosmetics.ResolveWrapInvertedValue(selectedWeapon) == true
                end
                rawset(equipmentState, 'CosmeticInverted', nil)
                setmetatable(equipmentState, {
                    __index = function(_, key)
                        if key == 'CosmeticInverted' then
                            local weaponName = rawget(equipmentState, 'SelectedWeapon')
                            if type(weaponName) == 'string' and weaponName ~= '' then
                                RivalsCosmeticsState.NativeInvertedValue = RivalsCosmetics.ResolveWrapInvertedValue(weaponName) == true
                                return RivalsCosmeticsState.NativeInvertedValue
                            end
                        end
                        if type(originalIndex) == 'table' then
                            return rawget(originalIndex, key)
                        end
                        return originalIndex(equipmentState, key)
                    end,
                    __newindex = function(target, key, value)
                        if key ~= 'CosmeticInverted' or value == nil then
                            rawset(target, key, value)
                            return
                        end
                        RivalsCosmeticsState.NativeInvertedValue = value == true
                        RivalsCosmetics.CaptureNativeSelection(false, false, RivalsCosmeticsState.NativeInvertedValue)
                    end,
                })
                RivalsCosmeticsState.NativeEquipmentStateRestore = {
                    EquipmentState = equipmentState,
                    Metatable = originalMetatable,
                }
                return true
            end

            function RivalsCosmetics.EnsureNativeCosmeticSlotBinding()
                if RivalsCosmeticsState.NativeCosmeticSlotConstructor ~= nil then
                    return true
                end

                local cosmeticSlot = RivalsCosmetics.ResolveCosmeticSlot()
                local constructor = type(cosmeticSlot) == 'table' and rawget(cosmeticSlot, 'new') or nil
                if type(constructor) ~= 'function' or type(debug.getupvalue) ~= 'function'
                    or type(debug.setupvalue) ~= 'function' then
                    return false
                end

                local prototype = debug.getupvalue(constructor, 1)
                if type(prototype) ~= 'table' then
                    return false
                end

                local proxy = {}
                proxy.__index = function(instance, key)
                    if key ~= 'Frame' then
                        return rawget(prototype, key)
                    end

                    if type(debug.info) == 'function' and type(debug.getupvalues) == 'function' then
                        local source, caller = debug.info(2, 'sf')
                        local upvalues = type(caller) == 'function' and debug.getupvalues(caller) or nil
                        if type(source) == 'string' and source:match('Cosmetics$')
                            and type(upvalues) == 'table' and type(upvalues[9]) == 'boolean' then
                            debug.setupvalue(caller, 9, false)
                        end
                    end
                    return rawget(instance, RIVALS_COSMETIC_SLOT_FRAME_SENTINEL)
                end
                proxy.__newindex = function(instance, key, value)
                    if key ~= 'Frame' then
                        rawset(instance, key, value)
                        return
                    end

                    local source = type(debug.info) == 'function' and debug.info(3, 's') or nil
                    if type(source) == 'string' and source:match('Cosmetics$')
                        and rawget(instance, 'IsLocked') ~= true and value ~= nil then
                        local button = value:FindFirstChild('Button')
                        if button ~= nil then
                            button.MouseButton1Click:Connect(function()
                                RivalsCosmetics.CaptureNativeSelection(false, false)
                            end)
                        end
                    end
                    rawset(instance, RIVALS_COSMETIC_SLOT_FRAME_SENTINEL, value)
                end

                debug.setupvalue(constructor, 1, proxy)
                RivalsCosmeticsState.NativeCosmeticSlotConstructor = constructor
                RivalsCosmeticsState.NativeCosmeticSlotPrototype = prototype
                return true
            end

            function RivalsCosmetics.ResolveNativeOptionButton(optionName)
                local equipment = RivalsCosmetics.ResolveEquipmentModule()
                local interface = type(equipment) == 'table' and rawget(equipment, 'Interface') or nil
                local customize = type(interface) == 'table' and rawget(interface, 'Customize') or nil
                local options = type(customize) == 'table' and rawget(customize, 'Options') or nil
                local container = type(options) == 'table' and rawget(options, 'Container') or nil
                local option = container and container:FindFirstChild(optionName) or nil
                local inner = option and option:FindFirstChild('Container') or nil
                return inner and inner:FindFirstChild('Button') or nil
            end

            function RivalsCosmetics.EnsureNativeUiBindings()
                if RivalsCosmeticsState.NativeUiBound then
                    return true
                end

                if not RivalsCosmetics.EnsureNativeCosmeticSlotBinding()
                    or not RivalsCosmetics.EnsureNativeInvertedState() then
                    RivalsCosmetics.RestoreNativeUiBindings()
                    return false
                end

                local favoritedButton = RivalsCosmetics.ResolveNativeOptionButton('Favorited')
                local onlyUseFavoritesButton = RivalsCosmetics.ResolveNativeOptionButton('OnlyUseFavorites')
                if favoritedButton ~= nil then
                    RivalsCosmeticsState.NativeFavoriteConnection = favoritedButton.MouseButton1Click:Connect(function()
                        RivalsCosmetics.CaptureNativeSelection(true, false)
                    end)
                end
                if onlyUseFavoritesButton ~= nil then
                    RivalsCosmeticsState.NativeOnlyUseFavoritesConnection = onlyUseFavoritesButton.MouseButton1Click:Connect(function()
                        RivalsCosmetics.CaptureNativeSelection(false, true)
                    end)
                end

                RivalsCosmeticsState.NativeUiBound = true
                return true
            end

            function RivalsCosmetics.RestoreNativeUiBindings()
                local favoriteConnection = RivalsCosmeticsState.NativeFavoriteConnection
                if favoriteConnection ~= nil then
                    favoriteConnection:Disconnect()
                end
                local onlyUseFavoritesConnection = RivalsCosmeticsState.NativeOnlyUseFavoritesConnection
                if onlyUseFavoritesConnection ~= nil then
                    onlyUseFavoritesConnection:Disconnect()
                end

                local equipmentRestore = RivalsCosmeticsState.NativeEquipmentStateRestore
                if type(equipmentRestore) == 'table' and type(equipmentRestore.EquipmentState) == 'table' then
                    setmetatable(equipmentRestore.EquipmentState, equipmentRestore.Metatable)
                end

                local constructor = RivalsCosmeticsState.NativeCosmeticSlotConstructor
                local prototype = RivalsCosmeticsState.NativeCosmeticSlotPrototype
                if type(constructor) == 'function' and type(prototype) == 'table'
                    and type(debug.setupvalue) == 'function' then
                    debug.setupvalue(constructor, 1, prototype)
                end

                RivalsCosmeticsState.NativeFavoriteConnection = nil
                RivalsCosmeticsState.NativeOnlyUseFavoritesConnection = nil
                RivalsCosmeticsState.NativeEquipmentStateRestore = nil
                RivalsCosmeticsState.NativeCosmeticSlotConstructor = nil
                RivalsCosmeticsState.NativeCosmeticSlotPrototype = nil
                RivalsCosmeticsState.NativeUiBound = false
                return true
            end

            function RivalsCosmetics.ResolveOriginalPlayerDataField(fieldName)
                local restore = RivalsCosmeticsState.PlayerDataRestore
                local data = type(restore) == 'table' and restore.Inner or nil
                if type(data) ~= 'table' then
                    local playerDataController = RivalsCosmetics.ResolvePlayerDataController()
                    local currentData = playerDataController and rawget(playerDataController, 'CurrentData') or nil
                    data = type(currentData) == 'table' and rawget(currentData, 'Data') or nil
                end
                return type(data) == 'table' and rawget(data, fieldName) or nil
            end

            function RivalsCosmetics.RestorePlayerDataProxy()
                local restore = RivalsCosmeticsState.PlayerDataRestore
                if type(restore) ~= 'table' then
                    return true
                end
                RivalsCosmeticsState.PlayerDataRestore = nil
                if type(restore.Current) == 'table' then
                    rawset(restore.Current, 'Data', restore.Inner)
                end
                return true
            end

            function RivalsCosmetics.LoadPlayerDataProxy(currentData)
                if type(currentData) ~= 'table' then
                    return false
                end

                local restore = RivalsCosmeticsState.PlayerDataRestore
                if type(restore) == 'table' then
                    if restore.Current == currentData then
                        return true
                    end
                    RivalsCosmetics.RestorePlayerDataProxy()
                end

                local inner = rawget(currentData, 'Data')
                if type(inner) ~= 'table' then
                    return false
                end

                local proxy = setmetatable({}, {
                    __index = function(_, fieldName)
                        return RivalsCosmetics.ResolveNativeDataField(fieldName, rawget(inner, fieldName))
                    end,
                    __newindex = function(_, fieldName, value)
                        rawset(inner, fieldName, value)
                    end,
                })
                rawset(currentData, 'Data', proxy)
                RivalsCosmeticsState.PlayerDataRestore = {
                    Current = currentData,
                    Inner = inner,
                    Proxy = proxy,
                }
                return true
            end

            function RivalsCosmetics.ResolvePlayerDataGetWeaponDataFunction()
                local playerDataController = RivalsCosmetics.ResolvePlayerDataController()
                local metatable = type(playerDataController) == 'table' and getmetatable(playerDataController) or nil
                local index = type(metatable) == 'table' and rawget(metatable, '__index') or nil
                return type(index) == 'table' and rawget(index, 'GetWeaponData') or nil
            end

            function RivalsCosmetics.FindOriginalWeaponData(weaponName)
                local inventory = RivalsCosmetics.ResolveOriginalPlayerDataField('WeaponInventory')
                if type(inventory) ~= 'table' then
                    return nil
                end
                for _, weaponData in pairs(inventory) do
                    if type(weaponData) == 'table' and rawget(weaponData, 'Name') == weaponName then
                        return weaponData
                    end
                end
                return nil
            end

            function RivalsCosmetics.EnsureItemDataHook()
                if RivalsCosmeticsState.PlayerDataGetWeaponDataConstantIndex ~= nil then
                    return true
                end

                local getWeaponData = RivalsCosmetics.ResolvePlayerDataGetWeaponDataFunction()
                local playerDataUtility = RivalsCosmetics.ResolvePlayerDataUtility()
                if type(getWeaponData) ~= 'function' or type(playerDataUtility) ~= 'table'
                    or type(debug.getconstants) ~= 'function' or type(debug.setconstant) ~= 'function' then
                    return false
                end

                local constantIndex = nil
                for index, value in pairs(debug.getconstants(getWeaponData)) do
                    if value == 'GetWeaponData' then
                        constantIndex = index
                        break
                    end
                end
                if constantIndex == nil then
                    return false
                end

                local previousSentinel = rawget(playerDataUtility, RIVALS_GET_WEAPON_DATA_SENTINEL)
                debug.setconstant(getWeaponData, constantIndex, RIVALS_GET_WEAPON_DATA_SENTINEL)
                rawset(playerDataUtility, RIVALS_GET_WEAPON_DATA_SENTINEL, function(_, playerData, weaponName)
                    local originalWeaponData = RivalsCosmetics.FindOriginalWeaponData(weaponName)
                    if originalWeaponData == nil then
                        return nil
                    end

                    local player = type(playerData) == 'table' and rawget(playerData, 'Player') or nil
                    if player == nil and type(playerData) == 'table' then
                        player = rawget(playerData, '_player_object')
                    end
                    if typeof(player) ~= 'Instance' or not player:IsA('Player') then
                        player = LP
                    end
                    if player ~= LP or not RivalsCosmetics.IsEnabled() then
                        return originalWeaponData
                    end
                    return RivalsCosmetics.OverrideWeaponData(weaponName, originalWeaponData)
                end)

                RivalsCosmeticsState.PlayerDataUtility = playerDataUtility
                RivalsCosmeticsState.PlayerDataUtilityGetWeaponData = previousSentinel
                RivalsCosmeticsState.PlayerDataGetWeaponDataFunction = getWeaponData
                RivalsCosmeticsState.PlayerDataGetWeaponDataConstantIndex = constantIndex
                RivalsCosmeticsState.PlayerDataGetWeaponDataConstantValue = 'GetWeaponData'
                return true
            end

            function RivalsCosmetics.RestoreItemDataHook()
                local getWeaponData = RivalsCosmeticsState.PlayerDataGetWeaponDataFunction
                local constantIndex = RivalsCosmeticsState.PlayerDataGetWeaponDataConstantIndex
                local originalConstant = RivalsCosmeticsState.PlayerDataGetWeaponDataConstantValue
                if type(getWeaponData) == 'function' and type(constantIndex) == 'number'
                    and type(debug.setconstant) == 'function' then
                    pcall(debug.setconstant, getWeaponData, constantIndex, originalConstant)
                end

                local playerDataUtility = RivalsCosmeticsState.PlayerDataUtility
                if type(playerDataUtility) == 'table' then
                    rawset(
                        playerDataUtility,
                        RIVALS_GET_WEAPON_DATA_SENTINEL,
                        RivalsCosmeticsState.PlayerDataUtilityGetWeaponData
                    )
                end

                RivalsCosmeticsState.PlayerDataUtility = nil
                RivalsCosmeticsState.PlayerDataUtilityGetWeaponData = nil
                RivalsCosmeticsState.PlayerDataGetWeaponDataFunction = nil
                RivalsCosmeticsState.PlayerDataGetWeaponDataConstantIndex = nil
                RivalsCosmeticsState.PlayerDataGetWeaponDataConstantValue = nil
                return true
            end

            function RivalsCosmetics.EnsurePlayerDataHook()
                local playerDataController = RivalsCosmetics.ResolvePlayerDataController()
                local currentData = type(playerDataController) == 'table' and rawget(playerDataController, 'CurrentData') or nil
                if type(playerDataController) ~= 'table' or type(currentData) ~= 'table' then
                    return false
                end

                RivalsCosmeticsState.PlayerDataController = playerDataController
                local dataLoaded = RivalsCosmetics.LoadPlayerDataProxy(currentData)
                local itemHookLoaded = RivalsCosmetics.EnsureItemDataHook()
                if RivalsCosmeticsState.PlayerDataAddedConnection == nil then
                    local playerDataAdded = rawget(playerDataController, 'PlayerDataAdded')
                    if type(playerDataAdded) == 'table' and type(playerDataAdded.Connect) == 'function' then
                        RivalsCosmeticsState.PlayerDataAddedConnection = playerDataAdded:Connect(function()
                            task.defer(function()
                                local nextCurrentData = rawget(playerDataController, 'CurrentData')
                                RivalsCosmetics.LoadPlayerDataProxy(nextCurrentData)
                                RivalsCosmetics.RefreshNativeCosmeticsScene()
                            end)
                        end)
                    end
                end

                RivalsCosmeticsState.PlayerDataHooked = dataLoaded == true
                return dataLoaded == true and itemHookLoaded == true
            end

            function RivalsCosmetics.RestorePlayerDataHook()
                local playerDataAddedConnection = RivalsCosmeticsState.PlayerDataAddedConnection
                if playerDataAddedConnection ~= nil then
                    playerDataAddedConnection:Disconnect()
                end
                RivalsCosmeticsState.PlayerDataAddedConnection = nil
                RivalsCosmetics.RestoreItemDataHook()
                RivalsCosmetics.RestorePlayerDataProxy()
                RivalsCosmeticsState.PlayerDataController = nil
                RivalsCosmeticsState.PlayerDataHooked = false
                return true
            end

            function RivalsCosmetics.EncodeGameKey(key)
                local enumLibrary = ResolveEnumLibrary()
                local toEnum = type(enumLibrary) == 'table' and rawget(enumLibrary, '_to_enum') or nil
                local encoded = type(toEnum) == 'table' and rawget(toEnum, key) or nil
                return encoded ~= nil and encoded or key
            end

            function RivalsCosmetics.ApplyevilrollerplayersViewModelSelection(weaponName, viewModelData, selection)
                if type(viewModelData) ~= 'table' or type(selection) ~= 'table' then
                    return viewModelData
                end

                if selection.skin ~= nil then
                    viewModelData[RivalsCosmetics.EncodeGameKey('Name')] = selection.skin == RIVALS_COSMETIC_NONE
                        and weaponName or selection.skin
                end
                if selection.wrap ~= nil then
                    local wrapKey = RivalsCosmetics.EncodeGameKey('Wrap')
                    if selection.wrap.name == RIVALS_COSMETIC_NONE then
                        viewModelData[wrapKey] = nil
                    else
                        viewModelData[wrapKey] = {
                            Name = selection.wrap.name,
                            Inverted = selection.wrap.inverted == true,
                        }
                    end
                end
                if selection.charm ~= nil then
                    local charmKey = RivalsCosmetics.EncodeGameKey('Charm')
                    if selection.charm == RIVALS_COSMETIC_NONE then
                        viewModelData[charmKey] = nil
                    else
                        local charm = { Name = selection.charm }
                        viewModelData[charmKey] = RivalsCosmetics.PatchRankCharmPayload(charm) or charm
                    end
                end
                return viewModelData
            end

            function RivalsCosmetics.GetClientItemRestoreData(player, weaponName)
                local byPlayer = RivalsCosmeticsState.ClientItemRestoreData[player]
                return type(byPlayer) == 'table' and byPlayer[weaponName] or nil
            end

            function RivalsCosmetics.EnsureClientItemRestoreData(player, weaponName, viewModelData)
                if type(viewModelData) ~= 'table' then
                    return
                end
                local byPlayer = RivalsCosmeticsState.ClientItemRestoreData[player]
                if type(byPlayer) ~= 'table' then
                    byPlayer = {}
                    RivalsCosmeticsState.ClientItemRestoreData[player] = byPlayer
                end
                if byPlayer[weaponName] == nil then
                    byPlayer[weaponName] = table.clone(viewModelData)
                end
            end

            function RivalsCosmetics.EnsureClientViewModelHook()
                if RivalsCosmeticsState.ClientViewModelHooked then
                    return true
                end

                local clientItem = RivalsCosmetics.ResolveClientItemClass()
                local constructor = type(clientItem) == 'table' and rawget(clientItem, 'new') or nil
                if type(constructor) ~= 'function' or type(debug.getupvalues) ~= 'function'
                    or type(debug.getstack) ~= 'function' or type(debug.setupvalue) ~= 'function' then
                    return false
                end

                local prototypeIndex = nil
                local prototype = nil
                for index, value in pairs(debug.getupvalues(constructor)) do
                    if type(value) == 'table' and rawget(value, 'CreateSpectatorSound') ~= nil then
                        prototypeIndex = index
                        prototype = value
                        break
                    end
                end
                if type(prototypeIndex) ~= 'number' or type(prototype) ~= 'table' then
                    return false
                end

                local proxy = {}
                proxy.__index = function(_, key)
                    local value = rawget(prototype, key)
                    if value == nil then
                        local metatable = getmetatable(prototype)
                        local index = type(metatable) == 'table' and rawget(metatable, '__index') or nil
                        if type(index) == 'table' then
                            value = rawget(index, key)
                        elseif type(index) == 'function' then
                            value = index(prototype, key)
                        end
                    end
                    return value
                end
                proxy.__newindex = function(instance, key, value)
                    if key ~= 'Info' then
                        rawset(instance, key, value)
                        return
                    end

                    rawset(instance, 'Info', value)
                    setmetatable(instance, prototype)
                    local stack = debug.getstack(2, 1)
                    local viewModel = type(stack) == 'table' and rawget(stack, 'ViewModel') or nil
                    local clientFighter = rawget(instance, 'ClientFighter')
                    local player = type(clientFighter) == 'table' and rawget(clientFighter, 'Player') or nil
                    local weaponName = rawget(instance, 'Name')
                    local selection = player == LP and RivalsCosmetics.BuildevilrollerplayersItemSelection(weaponName) or nil
                    local dataKey = RivalsCosmetics.EncodeGameKey('Data')
                    local viewModelData = type(viewModel) == 'table' and viewModel[dataKey] or nil
                    if type(selection) ~= 'table' or type(viewModelData) ~= 'table' then
                        return
                    end

                    RivalsCosmetics.EnsureClientItemRestoreData(player, weaponName, viewModelData)
                    RivalsCosmetics.ApplyevilrollerplayersViewModelSelection(weaponName, viewModelData, selection)
                end

                debug.setupvalue(constructor, prototypeIndex, proxy)
                RivalsCosmeticsState.ClientItemConstructor = constructor
                RivalsCosmeticsState.ClientItemPrototype = prototype
                RivalsCosmeticsState.ClientItemPrototypeIndex = prototypeIndex
                RivalsCosmeticsState.ClientViewModelHooked = true
                return true
            end

            function RivalsCosmetics.RestoreClientViewModelHook()
                local constructor = RivalsCosmeticsState.ClientItemConstructor
                local prototype = RivalsCosmeticsState.ClientItemPrototype
                local prototypeIndex = RivalsCosmeticsState.ClientItemPrototypeIndex
                if type(constructor) == 'function' and type(prototype) == 'table'
                    and type(prototypeIndex) == 'number' and type(debug.setupvalue) == 'function' then
                    debug.setupvalue(constructor, prototypeIndex, prototype)
                end

                RivalsCosmeticsState.ClientItemConstructor = nil
                RivalsCosmeticsState.ClientItemPrototype = nil
                RivalsCosmeticsState.ClientItemPrototypeIndex = nil
                RivalsCosmeticsState.ClientViewModelHooked = false
                return true
            end

            function RivalsCosmetics.EnsureFinisherHook()
                if RivalsCosmeticsState.ClientEntityFinisherHooked then
                    return true
                end

                local clientEntity = RivalsCosmetics.ResolveClientEntityClass()
                if type(clientEntity) ~= 'table' or type(clientEntity._PlayFinisher) ~= 'function' then
                    return false
                end

                local previousOriginalPlayFinisher = rawget(clientEntity, '__evilrollerplayersHailOriginalPlayFinisher')
                if rawget(clientEntity, '__evilrollerplayersHailFinisherHooked') == true and type(previousOriginalPlayFinisher) == 'function' then
                    clientEntity._PlayFinisher = previousOriginalPlayFinisher
                end

                local originalPlayFinisher = clientEntity._PlayFinisher
                local wrappedPlayFinisher = function(self, finisherName, ...)
                    local selectedFinisherName = RivalsCosmetics.ResolveSelectedPlaybackFinisherName()
                    if type(selectedFinisherName) == 'string' and selectedFinisherName ~= '' then
                        return originalPlayFinisher(self, selectedFinisherName, ...)
                    end

                    return originalPlayFinisher(self, finisherName, ...)
                end

                RivalsCosmeticsState.HookedClientEntityClass = clientEntity
                RivalsCosmeticsState.OriginalClientEntityPlayFinisher = originalPlayFinisher
                RivalsCosmeticsState.ClientEntityPlayFinisherWrapper = wrappedPlayFinisher
                clientEntity.__evilrollerplayersHailOriginalPlayFinisher = originalPlayFinisher
                clientEntity.__evilrollerplayersHailFinisherHooked = true
                clientEntity._PlayFinisher = wrappedPlayFinisher
                RivalsCosmeticsState.ClientEntityFinisherHooked = true
                return true
            end

            function RivalsCosmetics.RestoreFinisherHook()
                local clientEntity = RivalsCosmeticsState.HookedClientEntityClass
                local originalPlayFinisher = RivalsCosmeticsState.OriginalClientEntityPlayFinisher
                local wrappedPlayFinisher = RivalsCosmeticsState.ClientEntityPlayFinisherWrapper
                if type(clientEntity) == 'table' and type(originalPlayFinisher) == 'function' then
                    if clientEntity._PlayFinisher == wrappedPlayFinisher or rawget(clientEntity, '__evilrollerplayersHailFinisherHooked') == true then
                        clientEntity._PlayFinisher = originalPlayFinisher
                    end
                    clientEntity.__evilrollerplayersHailOriginalPlayFinisher = nil
                    clientEntity.__evilrollerplayersHailFinisherHooked = nil
                end

                RivalsCosmeticsState.HookedClientEntityClass = nil
                RivalsCosmeticsState.OriginalClientEntityPlayFinisher = nil
                RivalsCosmeticsState.ClientEntityPlayFinisherWrapper = nil
                RivalsCosmeticsState.ClientEntityFinisherHooked = false

                return true
            end

            function RivalsCosmetics.QueueRuntimeApplyWhenReady()
                if RivalsCosmeticsState.RuntimeApplyRetryPending then
                    return false
                end

                RivalsCosmeticsState.RuntimeApplyRetryPending = true
                task.spawn(GuardRivalsCallback('Cosmetics_WaitForReplicatedState', function()
                    while RivalsCosmeticsState.RuntimeApplyRetryPending
                        and RivalsCosmeticsState.CosmeticsUiLoaded == true
                        and (RivalsCosmetics.IsEnabled() or RivalsEmotes.IsEnabled())
                        and not ReplicatedStateReady do
                        task.wait(0.25)
                    end

                    RivalsCosmeticsState.RuntimeApplyRetryPending = false
                    if RivalsCosmeticsState.CosmeticsUiLoaded == true
                        and (RivalsCosmetics.IsEnabled() or RivalsEmotes.IsEnabled())
                        and ReplicatedStateReady then
                        RivalsCosmetics.ApplyAll()
                        RivalsEmotes.ApplyAll()
                    end
                end))
                return true
            end

            function RivalsCosmetics.ShouldUseCosmeticsRuntime()
                if RivalsCosmeticsState.CosmeticsUiLoaded ~= true then
                    return false
                end
                if not RivalsCosmetics.IsEnabled() then
                    RivalsCosmeticsState.RuntimeApplyRetryPending = false
                    return false
                end
                if not ReplicatedStateReady then
                    RivalsCosmetics.QueueRuntimeApplyWhenReady()
                    return false
                end
                return true
            end

            function RivalsCosmetics.SetConfigName(configName)
                if type(configName) == 'string' and configName ~= '' then
                    RivalsCosmeticsState.CosmeticsConfigName = configName
                end
            end

            function RivalsEmotes.ResolveEmoteValues()
                local cachedEmoteValues = RivalsEmotes.Catalog.EmoteValues
                if cachedEmoteValues then
                    return cachedEmoteValues
                end

                local cosmeticLibrary = RivalsCosmetics.ResolveCosmeticLibrary()
                local cosmetics = cosmeticLibrary and cosmeticLibrary.Cosmetics or nil
                local values = {DEFAULT_RIVALS_COSMETIC_VALUE}
                if type(cosmetics) == 'table' then
                    local emoteNames = {}
                    for cosmeticName, cosmeticData in pairs(cosmetics) do
                        if cosmeticData and cosmeticData.Type == 'Emote' then
                            if not RivalsCosmetics.IsPlaceholderCatalogName(cosmeticName) then
                                emoteNames[#emoteNames + 1] = cosmeticName
                            end
                        end
                    end

                    table.sort(emoteNames)
                    for _, emoteName in ipairs(emoteNames) do
                        values[#values + 1] = emoteName
                    end
                end

                RivalsEmotes.Catalog.EmoteValues = values
                return values
            end

            function RivalsEmotes.IsCatalogEmoteName(emoteName)
                if not RivalsCosmetics.IsCosmeticValueSelected(emoteName) then
                    return false
                end
                if RivalsCosmetics.IsPlaceholderCatalogName(emoteName) then
                    return false
                end

                local cosmeticLibrary = RivalsCosmetics.ResolveCosmeticLibrary()
                local cosmetics = cosmeticLibrary and cosmeticLibrary.Cosmetics or nil
                local cosmeticData = type(cosmetics) == 'table' and cosmetics[emoteName] or nil
                return type(cosmeticData) == 'table' and cosmeticData.Type == 'Emote'
            end

            function RivalsEmotes.ResolveEmoteSlotCount()
                local constants = RivalsEmotes.ResolveConstants()
                if type(constants) == 'table' then
                    return constants.MAX_EQUIPPABLE_EMOTES or 8
                end
                return 8
            end

            function RivalsEmotes.BuildEquippedEmoteData(emoteName)
                if not RivalsEmotes.IsCatalogEmoteName(emoteName) then
                    return nil
                end

                return RivalsCosmetics.BuildCosmeticData(nil, emoteName, 'Emote')
            end

            function RivalsEmotes.BuildUnlockedCosmeticInventory(baseInventory)
                local unlockedInventory = {}
                if type(baseInventory) == 'table' then
                    for key, value in pairs(baseInventory) do
                        unlockedInventory[key] = value
                    end
                end

                for _, emoteName in ipairs(RivalsEmotes.ResolveEmoteValues()) do
                    if RivalsCosmetics.IsCosmeticValueSelected(emoteName) then
                        unlockedInventory[emoteName] = true
                    end
                end
                return unlockedInventory
            end

            function RivalsEmotes.ResolveRawCosmeticInventory()
                return RivalsCosmetics.ResolveOriginalPlayerDataField('CosmeticInventory')
            end

            function RivalsEmotes.IsNaturallyOwnedEmote(emoteName)
                if not RivalsEmotes.IsCatalogEmoteName(emoteName) then
                    return false
                end

                local inventory = RivalsEmotes.ResolveRawCosmeticInventory()
                local cosmeticLibrary = RivalsCosmetics.ResolveCosmeticLibrary()
                if type(cosmeticLibrary) == 'table' and type(cosmeticLibrary.OwnsCosmetic) == 'function' then
                    local ok, owns = pcall(cosmeticLibrary.OwnsCosmetic, cosmeticLibrary, inventory, emoteName)
                    if ok then
                        return owns == true
                    end
                end

                return type(inventory) == 'table' and inventory[emoteName] ~= nil
            end

            function RivalsEmotes.ResolveEmoteController()
                local cachedEmoteController = RivalsEmotes.Catalog.EmoteController
                if cachedEmoteController then
                    return cachedEmoteController
                end

                local playerScripts = RivalsCosmetics.ResolvePlayerScripts()
                local controllers = playerScripts and playerScripts:FindFirstChild('Controllers')
                local emoteControllerModule = controllers and controllers:FindFirstChild('EmoteController')
                if not emoteControllerModule then
                    return nil
                end

                local ok, emoteController = pcall(require, emoteControllerModule)
                if not ok or type(emoteController) ~= 'table' then
                    return nil
                end

                RivalsEmotes.Catalog.EmoteController = emoteController
                return emoteController
            end

            function RivalsEmotes.ResolveConstants()
                local cachedConstants = RivalsEmotes.Catalog.Constants
                if cachedConstants then
                    return cachedConstants
                end

                local modules = ReplicatedStorage:FindFirstChild('Modules')
                local constantsModule = modules and modules:FindFirstChild('CONSTANTS')
                if not constantsModule then
                    return nil
                end

                local ok, constants = pcall(require, constantsModule)
                if not ok or type(constants) ~= 'table' then
                    return nil
                end

                RivalsEmotes.Catalog.Constants = constants
                return constants
            end

            function RivalsEmotes.ResolveCurrentData()
                local playerDataController = RivalsCosmetics.ResolvePlayerDataController()
                return playerDataController and playerDataController.CurrentData or nil
            end

            function RivalsEmotes.CloneEquippedEmotes(equippedEmotes)
                local cloned = {}
                if type(equippedEmotes) == 'table' then
                    for key, value in pairs(equippedEmotes) do
                        cloned[key] = value
                    end
                end
                return cloned
            end

            function RivalsEmotes.ResolveEquippedEmotes(currentData)
                if not currentData then
                    return nil
                end

                if type(currentData.Get) == 'function' then
                    local ok, equippedEmotes = pcall(function()
                        return currentData:Get('EquippedEmotes')
                    end)
                    if ok and type(equippedEmotes) == 'table' then
                        return equippedEmotes
                    end
                end

                local data = type(currentData.Data) == 'table' and currentData.Data or nil
                if not data then
                    return nil
                end

                if type(data.EquippedEmotes) ~= 'table' then
                    data.EquippedEmotes = {}
                end
                return data.EquippedEmotes
            end

            function RivalsEmotes.IsValidEquippedEmoteData(data)
                return type(data) == 'table' and RivalsCosmetics.IsCosmeticValueSelected(data.Name)
            end

            function RivalsEmotes.ResolveSlotOptionId(slotIndex)
                local numericSlot = math.floor(tonumber(slotIndex) or 1)
                return string.format('P5EMOTE_SLOT%d', numericSlot)
            end

            function RivalsEmotes.ResolveSelectedEmoteForSlot(slotIndex)
                local option = Options[RivalsEmotes.ResolveSlotOptionId(slotIndex)]
                local emoteName = option and option.Value or nil
                if RivalsEmotes.IsCatalogEmoteName(emoteName) then
                    return emoteName
                end
                return nil
            end

            function RivalsEmotes.ApplyConfiguredEmoteSlots()
                local currentData = RivalsEmotes.ResolveCurrentData()
                local equippedEmotes = RivalsEmotes.ResolveEquippedEmotes(currentData)
                if not currentData or type(equippedEmotes) ~= 'table' then
                    return false
                end

                local changed = false
                for slotIndex = 1, RivalsEmotes.ResolveEmoteSlotCount() do
                    local emoteName = RivalsEmotes.ResolveSelectedEmoteForSlot(slotIndex)
                    if emoteName then
                        local slotKey = tostring(slotIndex)
                        local slotData = equippedEmotes[slotKey]
                        if not RivalsEmotes.IsValidEquippedEmoteData(slotData) or slotData.Name ~= emoteName then
                            if not RivalsCosmeticsState.OriginalEquippedEmotes then
                                RivalsCosmeticsState.OriginalEquippedEmotes = RivalsEmotes.CloneEquippedEmotes(equippedEmotes)
                            end
                            equippedEmotes[slotIndex] = nil
                            equippedEmotes[slotKey] = RivalsEmotes.BuildEquippedEmoteData(emoteName)
                            changed = true
                        end
                    end
                end

                if changed and type(currentData.Replicate) == 'function' then
                    pcall(function()
                        currentData:Replicate('EquippedEmotes')
                    end)
                end
                return changed
            end

            function RivalsEmotes.SetEquippedEmote(slotKey, emoteName)
                local currentData = RivalsEmotes.ResolveCurrentData()
                local equippedEmotes = RivalsEmotes.ResolveEquippedEmotes(currentData)
                local numericSlot = tonumber(slotKey)
                if not currentData or type(equippedEmotes) ~= 'table' or not numericSlot then
                    return false
                end

                numericSlot = math.floor(numericSlot)
                if numericSlot < 1 or numericSlot > RivalsEmotes.ResolveEmoteSlotCount() then
                    return false
                end

                if not RivalsCosmeticsState.OriginalEquippedEmotes then
                    RivalsCosmeticsState.OriginalEquippedEmotes = RivalsEmotes.CloneEquippedEmotes(equippedEmotes)
                end

                local normalizedSlotKey = tostring(numericSlot)
                local nextData = nil
                if RivalsCosmetics.IsCosmeticValueSelected(emoteName) then
                    nextData = RivalsEmotes.BuildEquippedEmoteData(emoteName)
                end

                equippedEmotes[numericSlot] = nil
                equippedEmotes[normalizedSlotKey] = nextData
                if type(currentData.Replicate) == 'function' then
                    pcall(function()
                        currentData:Replicate('EquippedEmotes')
                    end)
                end
                if type(RivalsCosmetics.QueueCosmeticPresetAutoSave) == 'function' then
                    RivalsCosmetics.QueueCosmeticPresetAutoSave()
                end
                return true
            end

            function RivalsEmotes.RestoreEquippedEmotes()
                local originalEquippedEmotes = RivalsCosmeticsState.OriginalEquippedEmotes
                if type(originalEquippedEmotes) ~= 'table' then
                    return false
                end

                local currentData = RivalsEmotes.ResolveCurrentData()
                local equippedEmotes = RivalsEmotes.ResolveEquippedEmotes(currentData)
                if not currentData or type(equippedEmotes) ~= 'table' then
                    RivalsCosmeticsState.OriginalEquippedEmotes = nil
                    return false
                end

                for key in pairs(equippedEmotes) do
                    equippedEmotes[key] = nil
                end
                for key, value in pairs(originalEquippedEmotes) do
                    equippedEmotes[key] = value
                end

                RivalsCosmeticsState.OriginalEquippedEmotes = nil
                if type(currentData.Replicate) == 'function' then
                    pcall(function()
                        currentData:Replicate('EquippedEmotes')
                    end)
                end
                return true
            end

            function RivalsEmotes.ResolveLocalEntity()
                local fighter = ResolveLocalFighter()
                return fighter and fighter.Entity or nil
            end

            function RivalsEmotes.ShouldUseLocalPlayback(emoteName)
                return RivalsEmotes.IsEnabled()
                    and RivalsEmotes.IsCatalogEmoteName(emoteName)
                    and not RivalsEmotes.IsNaturallyOwnedEmote(emoteName)
            end

            function RivalsEmotes.PlayLocalEmoteByName(emoteName)
                if not RivalsEmotes.IsCatalogEmoteName(emoteName) then
                    return false
                end

                local entity = RivalsEmotes.ResolveLocalEntity()
                if type(entity) ~= 'table' or type(entity.PlayEmote) ~= 'function' then
                    return false
                end

                local emoteData = RivalsEmotes.BuildEquippedEmoteData(emoteName)
                if type(emoteData) ~= 'table' then
                    return false
                end

                local ok = pcall(function()
                    entity:PlayEmote(emoteData)
                end)
                return ok == true
            end

            function RivalsEmotes.EnsureEmoteControllerHook()
                if RivalsCosmeticsState.EmoteControllerHooked then
                    return true
                end

                local emoteController = RivalsEmotes.ResolveEmoteController()
                if type(emoteController) ~= 'table' or type(emoteController.EquipEmote) ~= 'function' or type(emoteController.UseEmoteByName) ~= 'function' then
                    return false
                end

                local originalEquipEmote = emoteController.EquipEmote
                local originalUseEmoteByName = emoteController.UseEmoteByName
                emoteController.EquipEmote = function(self, slotKey, emoteName, ...)
                    if RivalsEmotes.IsEnabled() and not RivalsEmotes.IsNaturallyOwnedEmote(emoteName) then
                        if RivalsEmotes.SetEquippedEmote(slotKey, emoteName) then
                            return
                        end
                    end

                    return originalEquipEmote(self, slotKey, emoteName, ...)
                end
                emoteController.UseEmoteByName = function(self, emoteName, ...)
                    if RivalsEmotes.ShouldUseLocalPlayback(emoteName) and RivalsEmotes.PlayLocalEmoteByName(emoteName) then
                        return
                    end

                    return originalUseEmoteByName(self, emoteName, ...)
                end

                RivalsCosmeticsState.HookedEmoteController = emoteController
                RivalsCosmeticsState.OriginalEmoteControllerEquipEmote = originalEquipEmote
                RivalsCosmeticsState.OriginalEmoteControllerUseEmoteByName = originalUseEmoteByName
                RivalsCosmeticsState.EmoteControllerHooked = true
                return true
            end

            function RivalsEmotes.RestoreEmoteControllerHook()
                local emoteController = RivalsCosmeticsState.HookedEmoteController
                local originalEquipEmote = RivalsCosmeticsState.OriginalEmoteControllerEquipEmote
                local originalUseEmoteByName = RivalsCosmeticsState.OriginalEmoteControllerUseEmoteByName
                if type(emoteController) == 'table' and type(originalEquipEmote) == 'function' then
                    emoteController.EquipEmote = originalEquipEmote
                end
                if type(emoteController) == 'table' and type(originalUseEmoteByName) == 'function' then
                    emoteController.UseEmoteByName = originalUseEmoteByName
                end

                RivalsCosmeticsState.HookedEmoteController = nil
                RivalsCosmeticsState.OriginalEmoteControllerEquipEmote = nil
                RivalsCosmeticsState.OriginalEmoteControllerUseEmoteByName = nil
                RivalsCosmeticsState.EmoteControllerHooked = false
                return true
            end

            function RivalsEmotes.ShouldUseRuntime()
                if RivalsCosmeticsState.CosmeticsUiLoaded ~= true then
                    return false
                end
                if not RivalsEmotes.IsEnabled() then
                    return false
                end
                if not ReplicatedStateReady then
                    RivalsCosmetics.QueueRuntimeApplyWhenReady()
                    return false
                end
                return true
            end

            function RivalsEmotes.ApplyAll()
                if not RivalsEmotes.ShouldUseRuntime() then
                    return false
                end

                pcall(RivalsCosmetics.EnsurePlayerDataHook)
                pcall(RivalsEmotes.EnsureEmoteControllerHook)
                pcall(RivalsEmotes.ApplyConfiguredEmoteSlots)
                return true
            end

            function RivalsEmotes.RestoreAll()
                pcall(RivalsEmotes.RestoreEquippedEmotes)
                pcall(RivalsEmotes.RestoreEmoteControllerHook)
                if not RivalsCosmetics.IsEnabled() then
                    pcall(RivalsCosmetics.RestorePlayerDataHook)
                end
                return true
            end

            function RivalsCosmetics.LoadSavedSelectionsFromConfig()
                local configPath = ScriptPaths.config_path(RivalsCosmeticsState.CosmeticsConfigName or 'RIVALS Default')
                if not isfile(configPath) then
                    return false
                end

                local readOk, rawConfig = pcall(readfile, configPath)
                if not readOk or type(rawConfig) ~= 'string' then
                    return false
                end

                local decodeOk, decoded = pcall(function()
                    return HttpService:JSONDecode(rawConfig)
                end)
                local objects = decodeOk and type(decoded) == 'table' and decoded.objects or nil
                if type(objects) ~= 'table' then
                    return false
                end

                local loadedAny = false
                local loadedPreviewWeaponName = nil
                local hasNativeCosmeticState = false
                for _, object in ipairs(objects) do
                    if object and object.idx == RIVALS_FAVORITES_STATE_OPTION_ID
                        and type(object.value) == 'table'
                        and object.value.nativeVersion == 1 then
                        hasNativeCosmeticState = true
                        break
                    end
                end
                RivalsCosmetics.RestoreAppliedCosmetics()
                RivalsCosmeticsState.SelectedSkinByWeapon = {}
                RivalsCosmeticsState.SelectedWrapByWeapon = {}
                RivalsCosmeticsState.SelectedCharmByWeapon = {}
                RivalsCosmeticsState.SelectedFinisherByWeapon = {}
                RivalsCosmeticsState.SelectedWrapInvertedByWeapon = {}
                RivalsCosmeticsState.StableRandomSelectionByWeapon = {}
                RivalsCosmeticsState.FavoritedCosmeticsByWeapon = {}
                RivalsCosmeticsState.OnlyUseFavoritesByWeapon = {}
                RivalsCosmeticsState.NativeFavoritesSeeded = false
                RivalsCosmeticsState.RankCharmOverridesBySeason = {}
                RivalsCosmeticsState.RefreshingDropdownValues = RivalsCosmeticsState.RefreshingDropdownValues + 1
                for _, object in ipairs(objects) do
                    local optionId = object and object.idx or nil
                    local optionInfo = RivalsCosmetics.ResolveCosmeticOptionInfo(optionId)
                    if optionInfo and hasNativeCosmeticState then
                        loadedPreviewWeaponName = loadedPreviewWeaponName or optionInfo.weaponName
                        if optionInfo.type == 'Toggle' then
                            RivalsCosmetics.SetStoredSelection(optionInfo.weaponName, optionInfo.kind, object.value == true)
                        else
                            RivalsCosmetics.SetStoredSelection(optionInfo.weaponName, optionInfo.kind, object.value)
                        end
                        loadedAny = true
                    elseif optionId == RIVALS_FAVORITES_STATE_OPTION_ID and hasNativeCosmeticState then
                        local favoritesState = RivalsCosmetics.NormalizeFavoritesState(object.value)
                        RivalsCosmeticsState.FavoritedCosmeticsByWeapon = favoritesState.favorites
                        RivalsCosmeticsState.OnlyUseFavoritesByWeapon = favoritesState.onlyUse
                        RivalsCosmeticsState.NativeFavoritesSeeded = type(object.value) == 'table'
                            and object.value.nativeVersion == 1
                            or next(favoritesState.favorites) ~= nil
                            or next(favoritesState.onlyUse) ~= nil
                        loadedAny = true
                    elseif optionId == RivalsCosmetics.ResolveEditorOptionId('Weapon') then
                        RivalsCosmetics.SetSelectedEditorWeapon(object.value)
                    end
                end
                if loadedPreviewWeaponName then
                    RivalsCosmeticsState.SelectedEditorWeaponName = loadedPreviewWeaponName
                    RivalsCosmetics.SetPreviewWeaponName(loadedPreviewWeaponName)
                end
                RivalsCosmetics.SyncActiveWeaponEditorFromState()
                RivalsCosmetics.SyncFavoriteEditorFromState()
                RivalsCosmetics.SyncRankCharmEditorFromState()
                RivalsCosmeticsState.RefreshingDropdownValues = math.max(RivalsCosmeticsState.RefreshingDropdownValues - 1, 0)

                return loadedAny
            end

            function RivalsCosmetics.CaptureSavedSelectionsBeforeConfigSave()
                RivalsCosmeticsState.SavedConfigCosmeticObjects = {}
                return false
            end

            function RivalsCosmetics.ResolveSelectionConfigObjectsById()
                local objectsById = {}
                for _, weaponName in ipairs(RivalsCosmetics.ResolveWeaponNames()) do
                    local skinValue = RivalsCosmetics.ResolveStoredSelectionValue(weaponName, 'Skin')
                    if skinValue ~= nil then
                        local skinOptionId = RivalsCosmetics.ResolveSkinOptionId(weaponName)
                        objectsById[skinOptionId] = {
                            idx = skinOptionId,
                            type = 'Dropdown',
                            value = skinValue,
                        }
                    end

                    local wrapValue = RivalsCosmetics.ResolveStoredSelectionValue(weaponName, 'Wrap')
                    if wrapValue ~= nil then
                        local wrapOptionId = RivalsCosmetics.ResolveWrapOptionId(weaponName)
                        objectsById[wrapOptionId] = {
                            idx = wrapOptionId,
                            type = 'Dropdown',
                            value = wrapValue,
                        }
                    end

                    local charmValue = RivalsCosmetics.ResolveStoredSelectionValue(weaponName, 'Charm')
                    if charmValue ~= nil then
                        local charmOptionId = RivalsCosmetics.ResolveCharmOptionId(weaponName)
                        objectsById[charmOptionId] = {
                            idx = charmOptionId,
                            type = 'Dropdown',
                            value = charmValue,
                        }
                    end

                    local finisherValue = RivalsCosmetics.ResolveStoredSelectionValue(weaponName, 'Finisher')
                    if finisherValue ~= nil then
                        local finisherOptionId = RivalsCosmetics.ResolveFinisherOptionId(weaponName)
                        objectsById[finisherOptionId] = {
                            idx = finisherOptionId,
                            type = 'Dropdown',
                            value = finisherValue,
                        }
                    end

                    local invertedValue = RivalsCosmetics.ResolveStoredSelectionValue(weaponName, 'WrapInverted')
                    if invertedValue ~= nil then
                        local invertedOptionId = RivalsCosmetics.ResolveWrapInvertedOptionId(weaponName)
                        objectsById[invertedOptionId] = {
                            idx = invertedOptionId,
                            type = 'Toggle',
                            value = invertedValue == true,
                        }
                    end
                end
                local nativeFavoritesState = RivalsCosmetics.ResolveFavoritesState()
                nativeFavoritesState.nativeVersion = 1
                objectsById[RIVALS_FAVORITES_STATE_OPTION_ID] = {
                    idx = RIVALS_FAVORITES_STATE_OPTION_ID,
                    type = 'CosmeticFavorites',
                    value = nativeFavoritesState,
                }
                return objectsById
            end

            function RivalsCosmetics.SaveSelectionsToConfig()
                local configPath = ScriptPaths.config_path(RivalsCosmeticsState.CosmeticsConfigName or 'RIVALS Default')
                if not isfile(configPath) then
                    RivalsCosmeticsState.SavedConfigCosmeticObjects = nil
                    return false
                end

                local readOk, rawConfig = pcall(readfile, configPath)
                if not readOk or type(rawConfig) ~= 'string' then
                    RivalsCosmeticsState.SavedConfigCosmeticObjects = nil
                    return false
                end

                local decodeOk, decoded = pcall(function()
                    return HttpService:JSONDecode(rawConfig)
                end)
                if not decodeOk or type(decoded) ~= 'table' then
                    RivalsCosmeticsState.SavedConfigCosmeticObjects = nil
                    return false
                end

                local existingObjects = type(decoded.objects) == 'table' and decoded.objects or {}
                local cosmeticObjectsById = {}
                for optionId, object in pairs(RivalsCosmeticsState.SavedConfigCosmeticObjects or {}) do
                    cosmeticObjectsById[optionId] = RivalsCosmetics.CloneConfigObject(object)
                end

                local selectedObjectsById = RivalsCosmetics.ResolveSelectionConfigObjectsById()
                for optionId, object in pairs(selectedObjectsById) do
                    cosmeticObjectsById[optionId] = object
                end

                local mergedObjects = {}
                for _, object in ipairs(existingObjects) do
                    local optionId = object and object.idx or nil
                    if not RivalsCosmetics.IsCosmeticOptionId(optionId) then
                        mergedObjects[#mergedObjects + 1] = object
                    end
                end

                local cosmeticOptionIds = {}
                for optionId in pairs(cosmeticObjectsById) do
                    cosmeticOptionIds[#cosmeticOptionIds + 1] = optionId
                end
                table.sort(cosmeticOptionIds)

                for _, optionId in ipairs(cosmeticOptionIds) do
                    local object = cosmeticObjectsById[optionId]
                    if object then
                        mergedObjects[#mergedObjects + 1] = object
                    end
                end

                decoded.objects = mergedObjects
                RivalsCosmeticsState.SavedConfigCosmeticObjects = nil
                return pcall(function()
                    writefile(configPath, HttpService:JSONEncode(decoded))
                end)
            end

            function RivalsCosmetics.CloneSerializable(value, seen)
                if type(value) ~= 'table' then
                    return value
                end
                seen = seen or {}
                if seen[value] then
                    return nil
                end
                local clone = {}
                seen[value] = clone
                for key, child in pairs(value) do
                    local clonedChild = RivalsCosmetics.CloneSerializable(child, seen)
                    if clonedChild ~= nil then
                        clone[key] = clonedChild
                    end
                end
                return clone
            end

            function RivalsCosmetics.ResolveCosmeticPresetSettings(value)
                value = type(value) == 'table' and value or {}
                return {
                    selectedName = type(value.selectedName) == 'string' and value.selectedName or '',
                    autoLoad = value.autoLoad == true,
                    autoLoadName = type(value.autoLoadName) == 'string' and value.autoLoadName or '',
                    autoSave = value.autoSave == true,
                    autoSaveName = type(value.autoSaveName) == 'string' and value.autoSaveName or '',
                }
            end

            function RivalsCosmetics.NormalizePresetSelectionTable(value, kind)
                local normalized = {}
                if type(value) ~= 'table' then
                    return normalized
                end
                for weaponName, selection in pairs(value) do
                    if RivalsCosmetics.IsKnownWeaponName(weaponName) then
                        if kind == 'WrapInverted' then
                            normalized[weaponName] = selection == true
                        else
                            selection = RivalsCosmetics.NormalizeSelectionValue(selection)
                            local values = RivalsCosmetics.ResolveBaseSelectionValues(weaponName, kind)
                            if RivalsCosmetics.ResolveValidDropdownValue(selection, values) == selection then
                                normalized[weaponName] = selection
                            end
                        end
                    end
                end
                return normalized
            end

            function RivalsCosmetics.ResolveCosmeticPresetEmotes()
                local emotes = {}
                for slotIndex = 1, RivalsEmotes.ResolveEmoteSlotCount() do
                    local option = Options[RivalsEmotes.ResolveSlotOptionId(slotIndex)]
                    emotes[tostring(slotIndex)] = option and option.Value or DEFAULT_RIVALS_COSMETIC_VALUE
                end
                return emotes
            end

            function RivalsCosmetics.NormalizeCosmeticPresetEmotes(value)
                local normalized = {}
                local available = RivalsEmotes.ResolveEmoteValues()
                value = type(value) == 'table' and value or {}
                for slotIndex = 1, RivalsEmotes.ResolveEmoteSlotCount() do
                    local slotKey = tostring(slotIndex)
                    local emoteName = value[slotKey] or value[slotIndex] or DEFAULT_RIVALS_COSMETIC_VALUE
                    if RivalsCosmetics.ResolveValidDropdownValue(emoteName, available) ~= emoteName then
                        emoteName = DEFAULT_RIVALS_COSMETIC_VALUE
                    end
                    normalized[slotKey] = emoteName
                end
                return normalized
            end

            function RivalsCosmetics.BuildDefaultCosmeticPresetSnapshot()
                local emotes = {}
                for slotIndex = 1, RivalsEmotes.ResolveEmoteSlotCount() do
                    emotes[tostring(slotIndex)] = DEFAULT_RIVALS_COSMETIC_VALUE
                end
                return {
                    version = 1,
                    weaponCosmeticsEnabled = false,
                    emotesEnabled = false,
                    selectedWeapon = RIVALS_COSMETIC_ALL_WEAPONS,
                    skins = {},
                    wraps = {},
                    charms = {},
                    finishers = {},
                    wrapInverted = {},
                    favorites = { favorites = {}, onlyUse = {} },
                    rankCharmOverrides = {},
                    emotes = emotes,
                }
            end

            function RivalsCosmetics.BuildCurrentCosmeticPresetSnapshot()
                return {
                    version = 1,
                    weaponCosmeticsEnabled = RivalsCosmetics.IsEnabled(),
                    emotesEnabled = RivalsEmotes.IsEnabled(),
                    selectedWeapon = RivalsCosmetics.ResolveSelectedEditorWeaponName(),
                    skins = RivalsCosmetics.CloneSerializable(RivalsCosmeticsState.SelectedSkinByWeapon),
                    wraps = RivalsCosmetics.CloneSerializable(RivalsCosmeticsState.SelectedWrapByWeapon),
                    charms = RivalsCosmetics.CloneSerializable(RivalsCosmeticsState.SelectedCharmByWeapon),
                    finishers = RivalsCosmetics.CloneSerializable(RivalsCosmeticsState.SelectedFinisherByWeapon),
                    wrapInverted = RivalsCosmetics.CloneSerializable(RivalsCosmeticsState.SelectedWrapInvertedByWeapon),
                    favorites = RivalsCosmetics.ResolveFavoritesState(),
                    rankCharmOverrides = RivalsCosmetics.NormalizeRankCharmOverrides(RivalsCosmeticsState.RankCharmOverridesBySeason),
                    emotes = RivalsCosmetics.ResolveCosmeticPresetEmotes(),
                }
            end

            function RivalsCosmetics.NormalizeCosmeticPresetSnapshot(value)
                value = type(value) == 'table' and value or {}
                local favorites = RivalsCosmetics.NormalizeFavoritesState(value.favorites)
                local selectedWeapon = RivalsCosmetics.IsKnownEditorWeaponName(value.selectedWeapon)
                    and value.selectedWeapon or RIVALS_COSMETIC_ALL_WEAPONS
                return {
                    version = 1,
                    weaponCosmeticsEnabled = value.weaponCosmeticsEnabled == true,
                    emotesEnabled = value.emotesEnabled == true,
                    selectedWeapon = selectedWeapon,
                    skins = RivalsCosmetics.NormalizePresetSelectionTable(value.skins, 'Skin'),
                    wraps = RivalsCosmetics.NormalizePresetSelectionTable(value.wraps, 'Wrap'),
                    charms = RivalsCosmetics.NormalizePresetSelectionTable(value.charms, 'Charm'),
                    finishers = RivalsCosmetics.NormalizePresetSelectionTable(value.finishers, 'Finisher'),
                    wrapInverted = RivalsCosmetics.NormalizePresetSelectionTable(value.wrapInverted, 'WrapInverted'),
                    favorites = favorites,
                    rankCharmOverrides = RivalsCosmetics.NormalizeRankCharmOverrides(value.rankCharmOverrides),
                    emotes = RivalsCosmetics.NormalizeCosmeticPresetEmotes(value.emotes),
                }
            end

            function RivalsCosmetics.LoadCosmeticPresetStore()
                if RivalsCosmeticsState.CosmeticPresetsLoaded then
                    return true
                end
                RivalsCosmeticsState.CosmeticPresetsLoaded = true
                RivalsCosmeticsState.CosmeticPresets = {}
                RivalsCosmeticsState.CosmeticPresetSettings = RivalsCosmetics.ResolveCosmeticPresetSettings(nil)
                if not isfile(RivalsCosmetics.CosmeticPresetPath) then
                    return true
                end
                local readOk, raw = pcall(readfile, RivalsCosmetics.CosmeticPresetPath)
                local decodeOk, decoded = pcall(function()
                    return HttpService:JSONDecode(raw)
                end)
                if not readOk or not decodeOk or type(decoded) ~= 'table' then
                    return false
                end
                for name, snapshot in pairs(type(decoded.presets) == 'table' and decoded.presets or {}) do
                    if type(name) == 'string' and name ~= '' and type(snapshot) == 'table' then
                        RivalsCosmeticsState.CosmeticPresets[name] = RivalsCosmetics.NormalizeCosmeticPresetSnapshot(snapshot)
                    end
                end
                local settings = RivalsCosmetics.ResolveCosmeticPresetSettings(decoded.settings)
                for _, key in ipairs({'selectedName', 'autoLoadName', 'autoSaveName'}) do
                    if RivalsCosmeticsState.CosmeticPresets[settings[key]] == nil then
                        settings[key] = ''
                    end
                end
                RivalsCosmeticsState.CosmeticPresetSettings = settings
                return true
            end

            function RivalsCosmetics.SaveCosmeticPresetStore()
                RivalsCosmetics.LoadCosmeticPresetStore()
                local payload = {
                    version = 1,
                    presets = RivalsCosmeticsState.CosmeticPresets,
                    settings = RivalsCosmeticsState.CosmeticPresetSettings,
                }
                return pcall(function()
                    if not isfolder('evilrollerplayersHail') then
                        makefolder('evilrollerplayersHail')
                    end
                    writefile(RivalsCosmetics.CosmeticPresetPath, HttpService:JSONEncode(payload))
                end)
            end

            function RivalsCosmetics.ResolveCosmeticPresetNames()
                RivalsCosmetics.LoadCosmeticPresetStore()
                local names = {}
                for name in pairs(RivalsCosmeticsState.CosmeticPresets) do
                    names[#names + 1] = name
                end
                table.sort(names)
                return names
            end

            function RivalsCosmetics.RefreshCosmeticPresetControls()
                local names = RivalsCosmetics.ResolveCosmeticPresetNames()
                local settings = RivalsCosmeticsState.CosmeticPresetSettings
                RivalsCosmeticsState.RefreshingDropdownValues = RivalsCosmeticsState.RefreshingDropdownValues + 1
                for _, optionId in ipairs({'P5PRESET_SELECTED', 'P5PRESET_AUTOLOAD_NAME', 'P5PRESET_AUTOSAVE_NAME'}) do
                    local option = Options[optionId]
                    if option and type(option.SetValues) == 'function' then
                        option:SetValues(names)
                    end
                end
                local selectedOption = Options.P5PRESET_SELECTED
                if selectedOption and type(selectedOption.SetValue) == 'function' then
                    selectedOption:SetValue(settings.selectedName ~= '' and settings.selectedName or nil)
                end
                local autoLoadNameOption = Options.P5PRESET_AUTOLOAD_NAME
                if autoLoadNameOption and type(autoLoadNameOption.SetValue) == 'function' then
                    autoLoadNameOption:SetValue(settings.autoLoadName ~= '' and settings.autoLoadName or nil)
                end
                local autoSaveNameOption = Options.P5PRESET_AUTOSAVE_NAME
                if autoSaveNameOption and type(autoSaveNameOption.SetValue) == 'function' then
                    autoSaveNameOption:SetValue(settings.autoSaveName ~= '' and settings.autoSaveName or nil)
                end
                local autoLoadToggle = Toggles.P5PRESET_AUTOLOAD
                if autoLoadToggle and type(autoLoadToggle.SetValue) == 'function' then
                    autoLoadToggle:SetValue(settings.autoLoad)
                end
                local autoSaveToggle = Toggles.P5PRESET_AUTOSAVE
                if autoSaveToggle and type(autoSaveToggle.SetValue) == 'function' then
                    autoSaveToggle:SetValue(settings.autoSave)
                end
                RivalsCosmeticsState.RefreshingDropdownValues = math.max(RivalsCosmeticsState.RefreshingDropdownValues - 1, 0)
                return names
            end

            function RivalsCosmetics.SanitizeCosmeticPresetName(value)
                return type(value) == 'string' and (value:gsub('%s+', '')) or ''
            end

            function RivalsCosmetics.CreateCosmeticPreset(name)
                RivalsCosmetics.LoadCosmeticPresetStore()
                name = RivalsCosmetics.SanitizeCosmeticPresetName(name)
                if name == '' or RivalsCosmeticsState.CosmeticPresets[name] ~= nil then
                    return false
                end
                local settings = RivalsCosmeticsState.CosmeticPresetSettings
                RivalsCosmeticsState.CosmeticPresets[name] = RivalsCosmetics.BuildDefaultCosmeticPresetSnapshot()
                local previousSelected = settings.selectedName
                settings.selectedName = name
                if not RivalsCosmetics.SaveCosmeticPresetStore() then
                    RivalsCosmeticsState.CosmeticPresets[name] = nil
                    settings.selectedName = previousSelected
                    return false
                end
                RivalsCosmetics.RefreshCosmeticPresetControls()
                return true
            end

            function RivalsCosmetics.SetSelectedCosmeticPreset(name)
                RivalsCosmetics.LoadCosmeticPresetStore()
                if type(name) ~= 'string' or RivalsCosmeticsState.CosmeticPresets[name] == nil then
                    return false
                end
                local settings = RivalsCosmeticsState.CosmeticPresetSettings
                local previous = settings.selectedName
                settings.selectedName = name
                if not RivalsCosmetics.SaveCosmeticPresetStore() then
                    settings.selectedName = previous
                    RivalsCosmetics.RefreshCosmeticPresetControls()
                    return false
                end
                return true
            end

            function RivalsCosmetics.SaveSelectedCosmeticPreset()
                RivalsCosmetics.LoadCosmeticPresetStore()
                local settings = RivalsCosmeticsState.CosmeticPresetSettings
                local name = settings.selectedName
                if RivalsCosmeticsState.CosmeticPresets[name] == nil then
                    return false
                end
                local previous = RivalsCosmeticsState.CosmeticPresets[name]
                RivalsCosmeticsState.CosmeticPresets[name] = RivalsCosmetics.BuildCurrentCosmeticPresetSnapshot()
                if not RivalsCosmetics.SaveCosmeticPresetStore() then
                    RivalsCosmeticsState.CosmeticPresets[name] = previous
                    return false
                end
                return true
            end

            function RivalsCosmetics.ApplyCosmeticPresetSnapshot(snapshot)
                snapshot = RivalsCosmetics.NormalizeCosmeticPresetSnapshot(snapshot)
                local previousRefreshing = RivalsCosmeticsState.RefreshingDropdownValues
                RivalsCosmeticsState.ApplyingCosmeticPreset = true
                local ok, result = xpcall(function()
                    local cosmeticsToggle = Toggles.P5S1T2
                    local emotesToggle = Toggles.P5S1T3
                    if cosmeticsToggle and type(cosmeticsToggle.SetValue) == 'function' then
                        cosmeticsToggle:SetValue(false)
                    end
                    if emotesToggle and type(emotesToggle.SetValue) == 'function' then
                        emotesToggle:SetValue(false)
                    end
                    RivalsCosmetics.RestoreAppliedCosmetics()
                    RivalsCosmeticsState.SelectedSkinByWeapon = snapshot.skins
                    RivalsCosmeticsState.SelectedWrapByWeapon = snapshot.wraps
                    RivalsCosmeticsState.SelectedCharmByWeapon = snapshot.charms
                    RivalsCosmeticsState.SelectedFinisherByWeapon = snapshot.finishers
                    RivalsCosmeticsState.SelectedWrapInvertedByWeapon = snapshot.wrapInverted
                    RivalsCosmeticsState.FavoritedCosmeticsByWeapon = snapshot.favorites.favorites
                    RivalsCosmeticsState.OnlyUseFavoritesByWeapon = snapshot.favorites.onlyUse
                    RivalsCosmeticsState.RankCharmOverridesBySeason = snapshot.rankCharmOverrides
                    RivalsCosmeticsState.StableRandomSelectionByWeapon = {}
                    RivalsCosmeticsState.SelectedEditorWeaponName = snapshot.selectedWeapon

                    RivalsCosmeticsState.RefreshingDropdownValues = RivalsCosmeticsState.RefreshingDropdownValues + 1
                    for slotIndex = 1, RivalsEmotes.ResolveEmoteSlotCount() do
                        local option = Options[RivalsEmotes.ResolveSlotOptionId(slotIndex)]
                        if option and type(option.SetValue) == 'function' then
                            option:SetValue(snapshot.emotes[tostring(slotIndex)])
                        end
                    end
                    RivalsCosmeticsState.RefreshingDropdownValues = math.max(RivalsCosmeticsState.RefreshingDropdownValues - 1, 0)
                    RivalsCosmetics.SyncActiveWeaponEditorFromState()
                    RivalsCosmetics.SyncFavoriteEditorFromState()
                    RivalsCosmetics.SyncRankCharmEditorFromState()
                    pcall(RivalsCosmetics.UpdatePreviewViewport)
                    if cosmeticsToggle and type(cosmeticsToggle.SetValue) == 'function' then
                        cosmeticsToggle:SetValue(snapshot.weaponCosmeticsEnabled)
                    end
                    if emotesToggle and type(emotesToggle.SetValue) == 'function' then
                        emotesToggle:SetValue(snapshot.emotesEnabled)
                    end
                    RivalsCosmetics.ApplyAll()
                    RivalsEmotes.ApplyAll()
                    return true
                end, function(err)
                    return debug.traceback(string.format('[Cosmetics_ApplyPreset] %s', tostring(err)), 2)
                end)
                RivalsCosmeticsState.ApplyingCosmeticPreset = false
                RivalsCosmeticsState.RefreshingDropdownValues = previousRefreshing
                if not ok then
                    error(result, 0)
                end
                return result == true
            end

            function RivalsCosmetics.LoadSelectedCosmeticPreset()
                RivalsCosmetics.LoadCosmeticPresetStore()
                local settings = RivalsCosmeticsState.CosmeticPresetSettings
                local snapshot = RivalsCosmeticsState.CosmeticPresets[settings.selectedName]
                if not snapshot then
                    return false
                end
                return RivalsCosmetics.ApplyCosmeticPresetSnapshot(snapshot)
            end

            function RivalsCosmetics.DeleteSelectedCosmeticPreset()
                RivalsCosmetics.LoadCosmeticPresetStore()
                local settings = RivalsCosmeticsState.CosmeticPresetSettings
                local name = settings.selectedName
                local snapshot = RivalsCosmeticsState.CosmeticPresets[name]
                if not snapshot then
                    return false
                end
                local previousSettings = RivalsCosmetics.CloneSerializable(settings)
                RivalsCosmeticsState.CosmeticPresets[name] = nil
                settings.selectedName = ''
                if settings.autoLoadName == name then
                    settings.autoLoadName = ''
                end
                if settings.autoSaveName == name then
                    settings.autoSaveName = ''
                end
                if not RivalsCosmetics.SaveCosmeticPresetStore() then
                    RivalsCosmeticsState.CosmeticPresets[name] = snapshot
                    RivalsCosmeticsState.CosmeticPresetSettings = previousSettings
                    return false
                end
                RivalsCosmetics.RefreshCosmeticPresetControls()
                return true
            end

            function RivalsCosmetics.SetCosmeticPresetSetting(key, value)
                RivalsCosmetics.LoadCosmeticPresetStore()
                local settings = RivalsCosmeticsState.CosmeticPresetSettings
                local previous = settings[key]
                if key == 'autoLoad' or key == 'autoSave' then
                    settings[key] = value == true
                elseif key == 'autoLoadName' or key == 'autoSaveName' then
                    if type(value) ~= 'string' or RivalsCosmeticsState.CosmeticPresets[value] == nil then
                        return false
                    end
                    settings[key] = value
                else
                    return false
                end
                if not RivalsCosmetics.SaveCosmeticPresetStore() then
                    settings[key] = previous
                    RivalsCosmetics.RefreshCosmeticPresetControls()
                    return false
                end
                return true
            end

            function RivalsCosmetics.ApplyCosmeticPresetAutoLoad()
                RivalsCosmetics.LoadCosmeticPresetStore()
                if RivalsCosmeticsState.CosmeticPresetAutoLoadApplied then
                    return false
                end
                RivalsCosmeticsState.CosmeticPresetAutoLoadApplied = true
                local settings = RivalsCosmeticsState.CosmeticPresetSettings
                local snapshot = settings.autoLoad and RivalsCosmeticsState.CosmeticPresets[settings.autoLoadName] or nil
                if not snapshot then
                    return false
                end
                settings.selectedName = settings.autoLoadName
                RivalsCosmetics.RefreshCosmeticPresetControls()
                return RivalsCosmetics.ApplyCosmeticPresetSnapshot(snapshot)
            end

            function RivalsCosmetics.QueueCosmeticPresetAutoSave()
                if RivalsCosmeticsState.ApplyingCosmeticPreset
                    or RivalsCosmeticsState.CosmeticsUiLoaded ~= true then
                    return false
                end
                RivalsCosmeticsState.CosmeticPresetSaveToken = RivalsCosmeticsState.CosmeticPresetSaveToken + 1
                local token = RivalsCosmeticsState.CosmeticPresetSaveToken
                task.defer(GuardRivalsCallback('Cosmetics_PresetAutoSave', function()
                    if token ~= RivalsCosmeticsState.CosmeticPresetSaveToken
                        or RivalsCosmeticsState.ApplyingCosmeticPreset then
                        return
                    end
                    RivalsCosmetics.LoadCosmeticPresetStore()
                    local settings = RivalsCosmeticsState.CosmeticPresetSettings
                    local name = settings.autoSave and settings.autoSaveName or ''
                    if RivalsCosmeticsState.CosmeticPresets[name] == nil then
                        return
                    end
                    local previous = RivalsCosmeticsState.CosmeticPresets[name]
                    RivalsCosmeticsState.CosmeticPresets[name] = RivalsCosmetics.BuildCurrentCosmeticPresetSnapshot()
                    if not RivalsCosmetics.SaveCosmeticPresetStore() then
                        RivalsCosmeticsState.CosmeticPresets[name] = previous
                    end
                end))
                return true
            end

            function RivalsCosmetics.ResolveSkinSourceModel(weaponName, skinName)
                if type(weaponName) ~= 'string' or weaponName == '' or not RivalsCosmetics.IsCosmeticValueSelected(skinName) then
                    return nil
                end

                local cacheKey = string.format('SkinSource_%s_%s', weaponName, skinName)
                local cachedSkinSource = RivalsCosmetics.Catalog[cacheKey]
                if cachedSkinSource and cachedSkinSource.Parent then
                    return cachedSkinSource
                end

                local cosmeticLibrary = RivalsCosmetics.ResolveCosmeticLibrary()
                local cosmetics = cosmeticLibrary and cosmeticLibrary.Cosmetics or nil
                local cosmeticData = type(cosmetics) == 'table' and cosmetics[skinName] or nil
                if not cosmeticData or cosmeticData.Type ~= 'Skin' or cosmeticData.ItemName ~= weaponName then
                    return nil
                end

                local viewModelsRoot = RivalsCosmetics.ResolveViewModelsRoot()
                if not viewModelsRoot then
                    return nil
                end

                local folderName = cosmeticData.Folder
                if type(folderName) == 'string' and folderName ~= '' then
                    local folder = viewModelsRoot:FindFirstChild(folderName)
                    local folderSource = folder and folder:FindFirstChild(skinName, true)
                    if folderSource and RivalsCosmetics.IsModelContainer(folderSource) then
                        RivalsCosmetics.Catalog[cacheKey] = folderSource
                        return folderSource
                    end
                end

                local sourceModel = viewModelsRoot:FindFirstChild(skinName, true)
                if sourceModel and RivalsCosmetics.IsModelContainer(sourceModel) then
                    RivalsCosmetics.Catalog[cacheKey] = sourceModel
                    return sourceModel
                end

                return nil
            end

            function RivalsCosmetics.ClonePreviewObject(instance, previewName)
                if not instance then
                    return nil
                end

                if instance:IsA('Model') or instance:IsA('BasePart') then
                    local clone = RivalsCosmetics.SafeClone(instance)
                    if not clone then
                        return nil
                    end
                    clone.Name = previewName or clone.Name
                    RivalsCosmetics.AnchorPreviewDescendants(clone)
                    if not RivalsCosmetics.HasRenderableDescendant(clone) then
                        clone:Destroy()
                        return nil
                    end
                    return clone
                end

                if instance:IsA('Folder') then
                    local previewModel = Instance.new('Model')
                    previewModel.Name = previewName or instance.Name
                    for _, child in ipairs(instance:GetChildren()) do
                        local childClone = RivalsCosmetics.SafeClone(child)
                        if childClone then
                            childClone.Parent = previewModel
                        end
                    end

                    if #previewModel:GetChildren() > 0 and RivalsCosmetics.HasRenderableDescendant(previewModel) then
                        RivalsCosmetics.AnchorPreviewDescendants(previewModel)
                        return previewModel
                    end

                    previewModel:Destroy()
                end

                return nil
            end

            function RivalsCosmetics.BuildPreviewModel(weaponName)
                local previewWeaponName = type(weaponName) == 'string' and weaponName ~= '' and weaponName or RivalsCosmetics.ResolvePreviewWeaponName()
                local selectedSkinName = previewWeaponName and RivalsCosmetics.ResolveSelectedSkinName(previewWeaponName) or nil
                local skinSelectionValue = previewWeaponName and RivalsCosmetics.ResolveSkinSelectionValue(previewWeaponName) or nil
                local previewSource = nil
                if selectedSkinName then
                    previewSource = RivalsCosmetics.ResolveSkinSourceModel(previewWeaponName, selectedSkinName)
                elseif skinSelectionValue == RIVALS_COSMETIC_NONE then
                    previewSource = RivalsCosmetics.ResolveDefaultWeaponTemplate(previewWeaponName)
                end
                previewSource = previewSource or (previewWeaponName and RivalsCosmetics.ResolveWeaponTemplate(previewWeaponName) or nil)
                local previewModel = RivalsCosmetics.ClonePreviewObject(previewSource, previewWeaponName and string.format('Preview_%s', previewWeaponName) or 'Preview')
                if not previewModel then
                    previewModel = Instance.new('Part')
                    previewModel.Name = 'PreviewPlaceholder'
                    previewModel.Anchored = true
                    previewModel.CanCollide = false
                    previewModel.Transparency = 1
                    previewModel.Size = Vector3.new(1, 1, 1)
                end

                return previewModel
            end

            function RivalsCosmetics.ResolvePreviewViewportModel()
                local viewportModel = RivalsCosmeticsState.PreviewViewportModel
                if viewportModel and viewportModel:IsA('Model') then
                    return viewportModel
                end

                viewportModel = Instance.new('Model')
                viewportModel.Name = 'RIVALS_CosmeticsPreview'
                RivalsCosmeticsState.PreviewViewportModel = viewportModel
                return viewportModel
            end

            function RivalsCosmetics.CopyPreviewModelIntoViewportModel(targetModel, sourceModel)
                if not targetModel or not targetModel:IsA('Model') or not sourceModel then
                    return false
                end

                local stagedModel = Instance.new('Model')
                stagedModel.Name = sourceModel.Name

                if sourceModel:IsA('BasePart') then
                    local childClone = RivalsCosmetics.SafeClone(sourceModel)
                    if childClone then
                        childClone.Parent = stagedModel
                    end
                elseif sourceModel:IsA('Model') or sourceModel:IsA('Folder') then
                    for _, child in ipairs(sourceModel:GetChildren()) do
                        local childClone = RivalsCosmetics.SafeClone(child)
                        if childClone then
                            childClone.Parent = stagedModel
                        end
                    end
                end

                RivalsCosmetics.AnchorPreviewDescendants(stagedModel)
                if not RivalsCosmetics.HasVisibleRenderableDescendant(stagedModel) then
                    stagedModel:Destroy()
                    return false
                end

                targetModel.Name = stagedModel.Name
                for _, child in ipairs(targetModel:GetChildren()) do
                    pcall(function()
                        child:Destroy()
                    end)
                end

                for _, child in ipairs(stagedModel:GetChildren()) do
                    child.Parent = targetModel
                end
                stagedModel:Destroy()

                RivalsCosmetics.AnchorPreviewDescendants(targetModel)
                return true
            end

            function RivalsCosmetics.BuildPreviewViewportModel()
                local viewportModel = RivalsCosmetics.ResolvePreviewViewportModel()
                local previewModel = RivalsCosmetics.BuildPreviewModel(RivalsCosmetics.ResolvePreviewWeaponName())
                if previewModel and RivalsCosmetics.HasVisibleRenderableDescendant(previewModel) then
                    RivalsCosmetics.CopyPreviewModelIntoViewportModel(viewportModel, previewModel)
                end
                if previewModel then
                    pcall(function()
                        previewModel:Destroy()
                    end)
                end
                return viewportModel
            end

            function RivalsCosmetics.ResolveFirstPersonFolder()
                local viewModels = Workspace:FindFirstChild('ViewModels')
                return viewModels and viewModels:FindFirstChild('FirstPerson') or nil
            end

            function RivalsCosmetics.ResolveFirstPersonModels(weaponName)
                local models = {}
                local firstPerson = RivalsCosmetics.ResolveFirstPersonFolder()
                if not firstPerson then
                    return models
                end

                local nameNeedle = type(weaponName) == 'string' and weaponName ~= '' and string.format(' - %s - ', weaponName) or nil
                for _, child in ipairs(firstPerson:GetChildren()) do
                    if child:IsA('Model') and (not nameNeedle or child.Name:find(nameNeedle, 1, true)) then
                        models[#models + 1] = child
                    end
                end

                return models
            end

            function RivalsCosmetics.ResolveWrapProperties(model)
                local originalWrapProperties = RivalsCosmeticsState.OriginalWrapProperties[model]
                if originalWrapProperties then
                    return originalWrapProperties
                end

                local wrapController = RivalsCosmetics.ResolveWrapController()
                if not wrapController then
                    return nil
                end

                originalWrapProperties = wrapController:RecordOriginalWrapProperties(model)
                RivalsCosmeticsState.OriginalWrapProperties[model] = originalWrapProperties
                return originalWrapProperties
            end

            function RivalsCosmetics.ApplyWrapToModel(model, wrapName, inverted)
                local wrapController = RivalsCosmetics.ResolveWrapController()
                if not wrapController or not model then
                    return false
                end

                local originalWrapProperties = RivalsCosmetics.ResolveWrapProperties(model)
                if not originalWrapProperties then
                    return false
                end

                if RivalsCosmetics.IsCosmeticValueSelected(wrapName) then
                    wrapController:ApplyWrap(originalWrapProperties, {
                        Name = wrapName,
                        Inverted = inverted == true,
                    })
                else
                    wrapController:ResetWrap(originalWrapProperties)
                end

                return true
            end

            function RivalsCosmetics.ResolveWorldItemOwnerAndName(instance)
                if not instance then
                    return nil, nil
                end

                local attributeOwner = nil
                local placedByUserId = instance:GetAttribute('PlacedByUserID')
                if type(placedByUserId) == 'number' then
                    attributeOwner = Players:GetPlayerByUserId(placedByUserId)
                end

                local objectId = instance:GetAttribute('ObjectID')
                if type(objectId) ~= 'string' then
                    return attributeOwner, nil
                end

                local fighterController = ResolveFighterController()
                local objects = fighterController and fighterController.Objects or nil
                if type(objects) ~= 'table' then
                    return attributeOwner, nil
                end

                local ok, objectOwner, itemName = pcall(function()
                    for _, fighter in pairs(objects) do
                        local items = fighter and fighter.Items or nil
                        if type(items) == 'table' then
                            for _, item in pairs(items) do
                                local data = item and item.Data or nil
                                local itemObjectId = data and data.ObjectID or ReadItemValue(item, 'ObjectID')
                                if itemObjectId == objectId then
                                    local itemName = (data and data.Name)
                                        or item.Name
                                        or ReadItemValue(item, 'Name')
                                    return fighter.Player, itemName
                                end
                            end
                        end
                    end
                    return nil, nil
                end)
                if not ok then
                    return attributeOwner, nil
                end
                return attributeOwner or objectOwner, itemName
            end

            function RivalsCosmetics.ResolveSpawnedCosmeticAssetFolder(folderName)
                local playerScripts = LP:FindFirstChild('PlayerScripts')
                if not playerScripts then
                    return nil
                end
                if folderName == 'SmokeClouds' then
                    local modules = playerScripts:FindFirstChild('Modules')
                    return modules and modules:FindFirstChild('SmokeClouds') or nil
                end
                local assets = playerScripts:FindFirstChild('Assets')
                local misc = assets and assets:FindFirstChild('Misc') or nil
                return misc and misc:FindFirstChild(folderName) or nil
            end

            function RivalsCosmetics.HasSpawnedCosmeticAsset(folderName, skinName)
                if not RivalsCosmetics.IsCosmeticValueSelected(skinName) then
                    return false
                end
                local folder = RivalsCosmetics.ResolveSpawnedCosmeticAssetFolder(folderName)
                return folder ~= nil and folder:FindFirstChild(skinName) ~= nil
            end

            function RivalsCosmetics.RefreshSpawnedCosmeticTag(instance, tagName)
                local collectionService = game:GetService('CollectionService')
                if not instance or not instance.Parent or not collectionService:HasTag(instance, tagName) then
                    return false
                end

                local retagToken = {}
                RivalsCosmeticsState.SpawnedWorldCosmeticRetagging[instance] = retagToken
                collectionService:RemoveTag(instance, tagName)
                local readdDelay = tagName == 'FireHitbox' and 1.8 or 0
                local function readdTag()
                    if instance.Parent and not collectionService:HasTag(instance, tagName) then
                        collectionService:AddTag(instance, tagName)
                    end
                end
                if readdDelay > 0 then
                    task.delay(readdDelay, readdTag)
                else
                    readdTag()
                end
                task.delay(readdDelay + 0.5, function()
                    if RivalsCosmeticsState.SpawnedWorldCosmeticRetagging[instance] == retagToken then
                        RivalsCosmeticsState.SpawnedWorldCosmeticRetagging[instance] = nil
                    end
                end)
                return true
            end

            function RivalsCosmetics.CaptureJumpPadOriginalProperty(entry, descendant)
                if not descendant or entry.OriginalProperties[descendant] ~= nil then
                    return
                end

                local properties = nil
                if descendant:IsA('BasePart') then
                    properties = {
                        Transparency = descendant.Transparency,
                        CastShadow = descendant.CastShadow,
                    }
                    descendant.Transparency = 1
                    descendant.CastShadow = false
                elseif descendant:IsA('Decal') or descendant:IsA('Texture') then
                    properties = { Transparency = descendant.Transparency }
                    descendant.Transparency = 1
                elseif descendant:IsA('ParticleEmitter') or descendant:IsA('Trail') or descendant:IsA('Beam') then
                    properties = { Enabled = descendant.Enabled }
                    descendant.Enabled = false
                elseif descendant:IsA('Sound') then
                    properties = { Volume = descendant.Volume }
                    descendant.Volume = 0
                end
                if properties then
                    entry.OriginalProperties[descendant] = properties
                end
            end

            function RivalsCosmetics.RestoreSpawnedWorldCosmetic(instance)
                local entry = RivalsCosmeticsState.SpawnedWorldCosmeticEntries[instance]
                if not entry then
                    return
                end

                if entry.ChildAdded then
                    pcall(function()
                        entry.ChildAdded:Disconnect()
                    end)
                end
                for _, model in ipairs(entry.WrapTargets or {}) do
                    pcall(RivalsCosmetics.ApplyWrapToModel, model, nil)
                end

                if entry.Kind == 'FireHitbox' then
                    pcall(function()
                        instance:SetAttribute('ViewModelName', entry.OriginalViewModelName)
                    end)
                    RivalsCosmetics.RefreshSpawnedCosmeticTag(instance, 'FireHitbox')
                elseif entry.Kind == 'SmokeCloud' then
                    pcall(function()
                        instance.Name = entry.OriginalName
                    end)
                    RivalsCosmetics.RefreshSpawnedCosmeticTag(instance, 'SmokeCloud')
                elseif entry.Kind == 'JumpPadHitbox' then
                    for child in pairs(entry.CustomChildren or {}) do
                        pcall(function()
                            child:Destroy()
                        end)
                    end
                    for descendant, properties in pairs(entry.OriginalProperties or {}) do
                        pcall(function()
                            for propertyName, value in pairs(properties) do
                                descendant[propertyName] = value
                            end
                        end)
                    end
                    pcall(function()
                        instance:SetAttribute('ViewModelName', entry.OriginalViewModelName)
                        instance:SetAttribute('SoundID', entry.OriginalSoundID)
                        instance:SetAttribute('SoundVolume', entry.OriginalSoundVolume)
                    end)
                end

                RivalsCosmeticsState.SpawnedWorldCosmeticEntries[instance] = nil
            end

            function RivalsCosmetics.WaitForLocalWorldItem(instance, requireItemName, token)
                local expiresAt = os.clock() + 3
                repeat
                    if not instance.Parent
                        or RivalsCosmeticsState.SpawnedWorldCosmeticApplyTokens[instance] ~= token then
                        return nil
                    end
                    local owner, itemName = RivalsCosmetics.ResolveWorldItemOwnerAndName(instance)
                    if owner then
                        if owner ~= LP then
                            return nil
                        end
                        if not requireItemName or type(itemName) == 'string' then
                            return itemName or true
                        end
                    end
                    task.wait(0.1)
                until os.clock() >= expiresAt
                return nil
            end

            function RivalsCosmetics.ApplyFireHitboxCosmetic(instance)
                if not instance or RivalsCosmeticsState.SpawnedWorldCosmeticRetagging[instance] then
                    return
                end
                RivalsCosmetics.RestoreSpawnedWorldCosmetic(instance)
                RivalsCosmeticsState.SpawnedWorldCosmeticApplyTokens[instance] = (RivalsCosmeticsState.SpawnedWorldCosmeticApplyTokens[instance] or 0) + 1
                local token = RivalsCosmeticsState.SpawnedWorldCosmeticApplyTokens[instance]
                task.spawn(GuardRivalsCallback('Cosmetics_ApplyFireHitbox', function()
                    local itemName = RivalsCosmetics.WaitForLocalWorldItem(instance, true, token)
                    if type(itemName) ~= 'string' or not RivalsCosmetics.IsEnabled() then
                        return
                    end
                    local skinName = RivalsCosmetics.ResolveSelectedSkinName(itemName)
                    local wrapName = RivalsCosmetics.ResolveSelectedWrapName(itemName)
                    local hasSkin = RivalsCosmetics.HasSpawnedCosmeticAsset('FireHitboxes', skinName)
                    if not hasSkin and not wrapName then
                        return
                    end

                    local entry = {
                        Kind = 'FireHitbox',
                        OriginalViewModelName = instance:GetAttribute('ViewModelName'),
                        WrapTargets = {},
                    }
                    RivalsCosmeticsState.SpawnedWorldCosmeticEntries[instance] = entry
                    if hasSkin then
                        instance:SetAttribute('ViewModelName', skinName)
                    end

                    if wrapName then
                        local expectedVisualName = hasSkin and skinName or (entry.OriginalViewModelName or 'Default')
                        local inverted = RivalsCosmetics.ResolveWrapInvertedValue(itemName)
                        entry.ChildAdded = Workspace.ChildAdded:Connect(GuardRivalsCallback('Cosmetics_FireHitboxVisualAdded', function(child)
                            if RivalsCosmeticsState.SpawnedWorldCosmeticEntries[instance] ~= entry
                                or RivalsCosmeticsState.SpawnedWorldCosmeticApplyTokens[instance] ~= token
                                or not child:IsA('Model')
                                or child.Name ~= expectedVisualName then
                                return
                            end

                            local primary = child:FindFirstChild('Primary')
                            local pivotOk, pivot = pcall(child.GetPivot, child)
                            if not primary or not primary:IsA('BasePart') or not pivotOk
                                or (pivot.Position - instance.Position).Magnitude > 0.5
                                or (primary.Size - instance.Size).Magnitude > 0.01 then
                                return
                            end

                            if RivalsCosmetics.ApplyWrapToModel(child, wrapName, inverted) then
                                entry.WrapTargets[#entry.WrapTargets + 1] = child
                                if entry.ChildAdded then
                                    entry.ChildAdded:Disconnect()
                                    entry.ChildAdded = nil
                                end
                            end
                        end))
                        task.delay(2.5, function()
                            if RivalsCosmeticsState.SpawnedWorldCosmeticEntries[instance] == entry and entry.ChildAdded then
                                entry.ChildAdded:Disconnect()
                                entry.ChildAdded = nil
                            end
                        end)
                    end
                    RivalsCosmetics.RefreshSpawnedCosmeticTag(instance, 'FireHitbox')
                end))
            end

            function RivalsCosmetics.ApplySmokeCloudCosmetic(instance)
                if not instance or RivalsCosmeticsState.SpawnedWorldCosmeticRetagging[instance] then
                    return
                end
                RivalsCosmetics.RestoreSpawnedWorldCosmetic(instance)
                RivalsCosmeticsState.SpawnedWorldCosmeticApplyTokens[instance] = (RivalsCosmeticsState.SpawnedWorldCosmeticApplyTokens[instance] or 0) + 1
                local token = RivalsCosmeticsState.SpawnedWorldCosmeticApplyTokens[instance]
                local skinName = RivalsCosmetics.ResolveSelectedSkinName('Smoke Grenade')
                if not RivalsCosmetics.HasSpawnedCosmeticAsset('SmokeClouds', skinName) then
                    return
                end
                task.spawn(GuardRivalsCallback('Cosmetics_ApplySmokeCloud', function()
                    if not RivalsCosmetics.WaitForLocalWorldItem(instance, false, token)
                        or not RivalsCosmetics.IsEnabled() then
                        return
                    end
                    local entry = {
                        Kind = 'SmokeCloud',
                        OriginalName = instance.Name,
                        WrapTargets = {},
                    }
                    RivalsCosmeticsState.SpawnedWorldCosmeticEntries[instance] = entry
                    instance.Name = skinName
                    RivalsCosmetics.RefreshSpawnedCosmeticTag(instance, 'SmokeCloud')
                end))
            end

            function RivalsCosmetics.ApplyJumpPadCosmetic(instance)
                if not instance or RivalsCosmeticsState.SpawnedWorldCosmeticRetagging[instance] then
                    return
                end
                RivalsCosmetics.RestoreSpawnedWorldCosmetic(instance)
                RivalsCosmeticsState.SpawnedWorldCosmeticApplyTokens[instance] = (RivalsCosmeticsState.SpawnedWorldCosmeticApplyTokens[instance] or 0) + 1
                local token = RivalsCosmeticsState.SpawnedWorldCosmeticApplyTokens[instance]
                local skinName = RivalsCosmetics.ResolveSelectedSkinName('Jump Pad')
                local wrapName = RivalsCosmetics.ResolveSelectedWrapName('Jump Pad')
                local hasSkin = RivalsCosmetics.HasSpawnedCosmeticAsset('JumpPads', skinName)
                if not hasSkin and not wrapName then
                    return
                end

                task.spawn(GuardRivalsCallback('Cosmetics_ApplyJumpPad', function()
                    if not RivalsCosmetics.WaitForLocalWorldItem(instance, false, token)
                        or not RivalsCosmetics.IsEnabled() then
                        return
                    end
                    task.wait(0.35)
                    if not instance.Parent
                        or RivalsCosmeticsState.SpawnedWorldCosmeticApplyTokens[instance] ~= token then
                        return
                    end

                    local entry = {
                        Kind = 'JumpPadHitbox',
                        OriginalViewModelName = instance:GetAttribute('ViewModelName'),
                        OriginalSoundID = instance:GetAttribute('SoundID'),
                        OriginalSoundVolume = instance:GetAttribute('SoundVolume'),
                        OriginalChildren = setmetatable({}, { __mode = 'k' }),
                        OriginalProperties = setmetatable({}, { __mode = 'k' }),
                        CustomChildren = setmetatable({}, { __mode = 'k' }),
                        WrapTargets = {},
                        CaptureCustomChildren = false,
                        ChildAdded = nil,
                    }
                    RivalsCosmeticsState.SpawnedWorldCosmeticEntries[instance] = entry

                    for _, child in ipairs(instance:GetChildren()) do
                        entry.OriginalChildren[child] = true
                        if child:IsA('Model') then
                            if hasSkin then
                                for _, descendant in ipairs(child:GetDescendants()) do
                                    RivalsCosmetics.CaptureJumpPadOriginalProperty(entry, descendant)
                                end
                            elseif wrapName then
                                entry.WrapTargets[#entry.WrapTargets + 1] = child
                                RivalsCosmetics.ApplyWrapToModel(child, wrapName, RivalsCosmetics.ResolveWrapInvertedValue('Jump Pad'))
                            end
                        elseif hasSkin and child:IsA('Sound') then
                            RivalsCosmetics.CaptureJumpPadOriginalProperty(entry, child)
                        end
                    end

                    if not hasSkin then
                        if #entry.WrapTargets == 0 then
                            RivalsCosmeticsState.SpawnedWorldCosmeticEntries[instance] = nil
                        end
                        return
                    end

                    entry.ChildAdded = instance.ChildAdded:Connect(GuardRivalsCallback('Cosmetics_JumpPadChildAdded', function(child)
                        if not entry.CaptureCustomChildren or entry.OriginalChildren[child] then
                            return
                        end
                        if child:IsA('Model') or child:IsA('Sound') then
                            entry.CustomChildren[child] = true
                            if child:IsA('Model') and wrapName then
                                entry.WrapTargets[#entry.WrapTargets + 1] = child
                                task.defer(RivalsCosmetics.ApplyWrapToModel, child, wrapName, RivalsCosmetics.ResolveWrapInvertedValue('Jump Pad'))
                            end
                        end
                    end))
                    entry.CaptureCustomChildren = true
                    instance:SetAttribute('ViewModelName', skinName)
                    RivalsCosmetics.RefreshSpawnedCosmeticTag(instance, 'JumpPadHitbox')
                    task.wait(0.35)
                    entry.CaptureCustomChildren = false
                end))
            end

            function RivalsCosmetics.BindSpawnedWorldCosmetics()
                if not Connections or not RivalsCosmetics.IsEnabled() then
                    return
                end
                local collectionService = game:GetService('CollectionService')
                local definitions = {
                    { Tag = 'FireHitbox', Apply = RivalsCosmetics.ApplyFireHitboxCosmetic },
                    { Tag = 'SmokeCloud', Apply = RivalsCosmetics.ApplySmokeCloudCosmetic },
                    { Tag = 'JumpPadHitbox', Apply = RivalsCosmetics.ApplyJumpPadCosmetic },
                }
                for _, definition in ipairs(definitions) do
                    local tagName = definition.Tag
                    local apply = definition.Apply
                    Connections:register('Cosmetics_' .. tagName .. 'Added', collectionService:GetInstanceAddedSignal(tagName):Connect(GuardRivalsCallback('Cosmetics_' .. tagName .. 'Added', apply)))
                    Connections:register('Cosmetics_' .. tagName .. 'Removed', collectionService:GetInstanceRemovedSignal(tagName):Connect(GuardRivalsCallback('Cosmetics_' .. tagName .. 'Removed', function(instance)
                        if RivalsCosmeticsState.SpawnedWorldCosmeticRetagging[instance] then
                            return
                        end
                        RivalsCosmeticsState.SpawnedWorldCosmeticApplyTokens[instance] = (RivalsCosmeticsState.SpawnedWorldCosmeticApplyTokens[instance] or 0) + 1
                        RivalsCosmetics.RestoreSpawnedWorldCosmetic(instance)
                    end)))
                    for _, instance in ipairs(collectionService:GetTagged(tagName)) do
                        apply(instance)
                    end
                end
            end

            function RivalsCosmetics.RestoreSpawnedWorldCosmetics()
                if Connections then
                    Connections:disconnect({
                        'Cosmetics_FireHitboxAdded',
                        'Cosmetics_FireHitboxRemoved',
                        'Cosmetics_SmokeCloudAdded',
                        'Cosmetics_SmokeCloudRemoved',
                        'Cosmetics_JumpPadHitboxAdded',
                        'Cosmetics_JumpPadHitboxRemoved',
                    })
                end
                for instance in pairs(RivalsCosmeticsState.SpawnedWorldCosmeticEntries) do
                    RivalsCosmeticsState.SpawnedWorldCosmeticApplyTokens[instance] = (RivalsCosmeticsState.SpawnedWorldCosmeticApplyTokens[instance] or 0) + 1
                    RivalsCosmetics.RestoreSpawnedWorldCosmetic(instance)
                end
            end

            function RivalsCosmetics.RestoreWorldTripmine(tripmine)
                local entry = RivalsCosmeticsState.WorldTripmineEntries[tripmine]
                if not entry then
                    return
                end
                if entry.DescendantAdded then
                    pcall(function()
                        entry.DescendantAdded:Disconnect()
                    end)
                end
                if entry.WrapTarget then
                    pcall(RivalsCosmetics.ApplyWrapToModel, entry.WrapTarget, nil)
                end
                for descendant, properties in pairs(entry.OriginalProperties) do
                    if descendant then
                        pcall(function()
                            for propertyName, value in pairs(properties) do
                                descendant[propertyName] = value
                            end
                        end)
                    end
                end
                if entry.Clone then
                    pcall(function()
                        entry.Clone:Destroy()
                    end)
                end
                RivalsCosmeticsState.WorldTripmineEntries[tripmine] = nil
            end

            function RivalsCosmetics.HideWorldTripmineDescendant(entry, descendant)
                if not descendant
                    or descendant == entry.Hitbox
                    or descendant:IsDescendantOf(entry.Hitbox)
                    or (entry.Clone and (descendant == entry.Clone or descendant:IsDescendantOf(entry.Clone))) then
                    return
                end

                local properties = nil
                if descendant:IsA('BasePart') then
                    properties = {
                        Transparency = descendant.Transparency,
                        CastShadow = descendant.CastShadow,
                    }
                    descendant.Transparency = 1
                    descendant.CastShadow = false
                elseif descendant:IsA('Decal') or descendant:IsA('Texture') then
                    properties = { Transparency = descendant.Transparency }
                    descendant.Transparency = 1
                elseif descendant:IsA('ParticleEmitter') or descendant:IsA('Trail') or descendant:IsA('Beam') then
                    properties = { Enabled = descendant.Enabled }
                    descendant.Enabled = false
                end
                if properties and entry.OriginalProperties[descendant] == nil then
                    entry.OriginalProperties[descendant] = properties
                end
            end

            function RivalsCosmetics.ApplyWorldTripmineNow(tripmine, hitbox, skinName, wrapName, inverted)
                if not tripmine.Parent
                    or tonumber(tripmine:GetAttribute('PlacedByUserID')) ~= LP.UserId
                    or not RivalsCosmetics.IsEnabled() then
                    return false
                end

                local entry = {
                    Clone = nil,
                    Hitbox = hitbox,
                    WrapTarget = tripmine,
                    OriginalProperties = setmetatable({}, { __mode = 'k' }),
                    DescendantAdded = nil,
                }
                RivalsCosmeticsState.WorldTripmineEntries[tripmine] = entry

                if skinName then
                    local sourceModel = RivalsCosmetics.ResolveSkinSourceModel('Subspace Tripmine', skinName)
                    local clone = RivalsCosmetics.ClonePreviewObject(sourceModel, '__evilrollerplayersHailTripmineSkin')
                    if clone then
                        entry.Clone = clone
                        entry.WrapTarget = clone
                        pcall(function()
                            clone:PivotTo(hitbox.CFrame)
                        end)
                        clone.Parent = tripmine
                        for _, descendant in ipairs(clone:GetDescendants()) do
                            if descendant:IsA('BasePart') then
                                descendant.Anchored = false
                                descendant.CanCollide = false
                                descendant.CanTouch = false
                                descendant.CanQuery = false
                                descendant.Massless = true
                                local weld = Instance.new('WeldConstraint')
                                weld.Part0 = hitbox
                                weld.Part1 = descendant
                                weld.Parent = descendant
                            end
                        end
                        for _, descendant in ipairs(tripmine:GetDescendants()) do
                            RivalsCosmetics.HideWorldTripmineDescendant(entry, descendant)
                        end
                        entry.DescendantAdded = tripmine.DescendantAdded:Connect(GuardRivalsCallback('Cosmetics_TripmineDescendantAdded', function(descendant)
                            RivalsCosmetics.HideWorldTripmineDescendant(entry, descendant)
                        end))
                    end
                end

                if wrapName then
                    RivalsCosmetics.ApplyWrapToModel(entry.WrapTarget, wrapName, inverted)
                end
                return entry.Clone ~= nil or wrapName ~= nil
            end

            function RivalsCosmetics.ApplyWorldTripmine(tripmine)
                if not tripmine then
                    return
                end
                RivalsCosmetics.RestoreWorldTripmine(tripmine)
                RivalsCosmeticsState.WorldTripmineApplyTokens[tripmine] = (RivalsCosmeticsState.WorldTripmineApplyTokens[tripmine] or 0) + 1
                local token = RivalsCosmeticsState.WorldTripmineApplyTokens[tripmine]
                local skinName = RivalsCosmetics.ResolveSelectedSkinName('Subspace Tripmine')
                local wrapName = RivalsCosmetics.ResolveSelectedWrapName('Subspace Tripmine')
                if not skinName and not wrapName then
                    return
                end
                local inverted = RivalsCosmetics.ResolveWrapInvertedValue('Subspace Tripmine')
                task.spawn(GuardRivalsCallback('Cosmetics_ApplyWorldTripmine', function()
                    local hitbox = tripmine:WaitForChild('Hitbox', 5)
                    if not hitbox
                        or RivalsCosmeticsState.WorldTripmineApplyTokens[tripmine] ~= token then
                        return
                    end
                    RivalsCosmetics.ApplyWorldTripmineNow(tripmine, hitbox, skinName, wrapName, inverted)
                end))
            end

            function RivalsCosmetics.BindWorldTripmines()
                if not Connections or not RivalsCosmetics.IsEnabled() then
                    return
                end
                local collectionService = game:GetService('CollectionService')
                Connections:register('Cosmetics_SubspaceTripmineAdded', collectionService:GetInstanceAddedSignal('SubspaceTripmine'):Connect(GuardRivalsCallback('Cosmetics_SubspaceTripmineAdded', RivalsCosmetics.ApplyWorldTripmine)))
                Connections:register('Cosmetics_SubspaceTripmineRemoved', collectionService:GetInstanceRemovedSignal('SubspaceTripmine'):Connect(GuardRivalsCallback('Cosmetics_SubspaceTripmineRemoved', function(tripmine)
                    RivalsCosmeticsState.WorldTripmineApplyTokens[tripmine] = (RivalsCosmeticsState.WorldTripmineApplyTokens[tripmine] or 0) + 1
                    RivalsCosmetics.RestoreWorldTripmine(tripmine)
                end)))
                for _, tripmine in ipairs(collectionService:GetTagged('SubspaceTripmine')) do
                    RivalsCosmetics.ApplyWorldTripmine(tripmine)
                end
            end

            function RivalsCosmetics.RestoreWorldTripmines()
                if Connections then
                    Connections:disconnect({
                        'Cosmetics_SubspaceTripmineAdded',
                        'Cosmetics_SubspaceTripmineRemoved',
                    })
                end
                for tripmine in pairs(RivalsCosmeticsState.WorldTripmineEntries) do
                    RivalsCosmeticsState.WorldTripmineApplyTokens[tripmine] = (RivalsCosmeticsState.WorldTripmineApplyTokens[tripmine] or 0) + 1
                    RivalsCosmetics.RestoreWorldTripmine(tripmine)
                end
            end

            function RivalsCosmetics.ResolveWrapTargetsForWeapon(weaponName)
                local targets = {}
                local seenTargets = {}
                for _, model in ipairs(RivalsCosmetics.ResolveFirstPersonModels(weaponName)) do
                    if seenTargets[model] ~= true then
                        seenTargets[model] = true
                        targets[#targets + 1] = model
                    end
                end

                return targets
            end

            function RivalsCosmetics.CaptureOriginalItemCosmetics(item)
                if type(item) ~= 'table' or RivalsCosmeticsState.OriginalInjectedItemCosmetics[item] then
                    return
                end

                RivalsCosmeticsState.OriginalInjectedItemCosmetics[item] = {
                    Skin = item.Skin ~= nil and item.Skin or ReadItemValue(item, 'Skin'),
                    Wrap = item.Wrap ~= nil and item.Wrap or ReadItemValue(item, 'Wrap'),
                    Charm = item.Charm ~= nil and item.Charm or ReadItemValue(item, 'Charm'),
                    Finisher = item.Finisher ~= nil and item.Finisher or ReadItemValue(item, 'Finisher'),
                }
            end

            function RivalsCosmetics.ResolveSelectedCosmeticApplyData(weaponName, kind, existingData)
                local selectionValue = nil
                if kind == 'Skin' then
                    selectionValue = RivalsCosmetics.ResolveSkinSelectionValue(weaponName)
                elseif kind == 'Wrap' then
                    selectionValue = RivalsCosmetics.ResolveWrapSelectionValue(weaponName)
                elseif kind == 'Charm' then
                    selectionValue = RivalsCosmetics.ResolveCharmSelectionValue(weaponName)
                elseif kind == 'Finisher' then
                    selectionValue = RivalsCosmetics.ResolveFinisherSelectionValue(weaponName)
                else
                    return nil, false
                end

                if RivalsCosmetics.IsCosmeticValueSelected(selectionValue) then
                    local data = RivalsCosmetics.BuildCosmeticData(existingData, selectionValue, kind)
                    if kind == 'Wrap' then
                        data.Inverted = RivalsCosmetics.ResolveWrapInvertedValue(weaponName) == true
                    elseif kind == 'Charm' then
                        data = RivalsCosmetics.PatchRankCharmPayload(data) or data
                    end
                    return data, true
                end

                if selectionValue == RIVALS_COSMETIC_NONE then
                    return nil, true
                end

                if kind == 'Charm' then
                    local patchedCharm = RivalsCosmetics.PatchRankCharmPayload(existingData)
                    if patchedCharm then
                        return patchedCharm, true
                    end
                end

                return nil, false
            end

            function RivalsCosmetics.InjectWeaponData(weaponName)
                local playerDataController = RivalsCosmetics.ResolvePlayerDataController()
                local currentData = playerDataController and playerDataController.CurrentData or nil
                if type(weaponName) ~= 'string' or weaponName == '' or not currentData or type(currentData.Get) ~= 'function' then
                    return false
                end

                local ok, inventory = pcall(function()
                    return currentData:Get('WeaponInventory')
                end)
                if not ok or type(inventory) ~= 'table' then
                    return false
                end

                for _, item in pairs(inventory) do
                    if type(item) == 'table' and item.Name == weaponName then
                        local changed = false
                        local skinData, shouldSetSkin = RivalsCosmetics.ResolveSelectedCosmeticApplyData(weaponName, 'Skin', item.Skin)
                        if shouldSetSkin then
                            RivalsCosmetics.CaptureOriginalItemCosmetics(item)
                            item.Skin = skinData
                            changed = true
                        end

                        local wrapData, shouldSetWrap = RivalsCosmetics.ResolveSelectedCosmeticApplyData(weaponName, 'Wrap', item.Wrap)
                        if shouldSetWrap then
                            RivalsCosmetics.CaptureOriginalItemCosmetics(item)
                            item.Wrap = wrapData
                            changed = true
                        end

                        local charmData, shouldSetCharm = RivalsCosmetics.ResolveSelectedCosmeticApplyData(weaponName, 'Charm', item.Charm)
                        if shouldSetCharm then
                            RivalsCosmetics.CaptureOriginalItemCosmetics(item)
                            item.Charm = charmData
                            changed = true
                        end

                        local finisherData, shouldSetFinisher = RivalsCosmetics.ResolveSelectedCosmeticApplyData(weaponName, 'Finisher', item.Finisher)
                        if shouldSetFinisher then
                            RivalsCosmetics.CaptureOriginalItemCosmetics(item)
                            item.Finisher = finisherData
                            changed = true
                        end

                        if changed and type(currentData.Replicate) == 'function' then
                            pcall(function()
                                currentData:Replicate('WeaponInventory')
                            end)
                        end
                        return changed
                    end
                end

                return false
            end

            function RivalsCosmetics.InjectAllWeaponData()
                local injected = false
                for _, weaponName in ipairs(RivalsCosmetics.ResolveWeaponNames()) do
                    injected = RivalsCosmetics.InjectWeaponData(weaponName) or injected
                end
                return injected
            end

            function RivalsCosmetics.EncodeGameTable(value)
                local encoded = {}
                for key, entry in pairs(value) do
                    local encodedKey = type(key) == 'string' and RivalsCosmetics.EncodeGameKey(key) or key
                    encoded[encodedKey] = entry
                end
                return encoded
            end

            function RivalsCosmetics.ResolveClientItemForWeapon(weaponName)
                local fighter = ResolveLocalFighter()
                if type(fighter) ~= 'table' then
                    return nil, nil
                end

                local equippedItem = rawget(fighter, 'EquippedItem')
                if type(equippedItem) == 'table' and rawget(equippedItem, 'Name') == weaponName then
                    return equippedItem, fighter
                end
                for _, fieldName in ipairs({'Loadout', 'Slots', 'Items', 'EquippedItems'}) do
                    local items = rawget(fighter, fieldName)
                    if type(items) == 'table' then
                        for _, item in pairs(items) do
                            if type(item) == 'table' and rawget(item, 'Name') == weaponName then
                                return item, fighter
                            end
                        end
                    end
                end
                return nil, fighter
            end

            function RivalsCosmetics.RunAtIdentity2(callback)
                local previousIdentity = type(getthreadidentity) == 'function' and getthreadidentity() or nil
                if type(setthreadidentity) == 'function' then
                    setthreadidentity(2)
                end
                local results = table.pack(pcall(callback))
                if previousIdentity ~= nil and type(setthreadidentity) == 'function' then
                    setthreadidentity(previousIdentity)
                end
                if not results[1] then
                    return false, results[2]
                end
                return true, unpack(results, 2, results.n)
            end

            function RivalsCosmetics.BuildViewModelSelectionSignature(weaponName, selection)
                if type(selection) ~= 'table' then
                    return weaponName .. '|restore'
                end
                local wrap = selection.wrap
                return table.concat({
                    weaponName,
                    tostring(selection.skin),
                    tostring(type(wrap) == 'table' and wrap.name or nil),
                    tostring(type(wrap) == 'table' and wrap.inverted == true or false),
                    tostring(selection.charm),
                }, '|')
            end

            function RivalsCosmetics.ReloadWeaponViewModel(weaponName, force, restoreOnly)
                local item, fighter = RivalsCosmetics.ResolveClientItemForWeapon(weaponName)
                local viewModel = type(item) == 'table' and rawget(item, 'ViewModel') or nil
                local viewModelData = type(viewModel) == 'table' and rawget(viewModel, 'Data') or nil
                if type(item) ~= 'table' or type(viewModel) ~= 'table' or type(viewModelData) ~= 'table' then
                    return false
                end

                local selection = restoreOnly == true and nil or RivalsCosmetics.BuildevilrollerplayersItemSelection(weaponName)
                local signature = RivalsCosmetics.BuildViewModelSelectionSignature(weaponName, selection)
                local appliedSelection = RivalsCosmeticsState.ViewModelSelectionSignatureByItem[item]
                if force ~= true and type(appliedSelection) == 'table'
                    and appliedSelection.Signature == signature
                    and appliedSelection.ViewModel == viewModel then
                    return true
                end

                if type(selection) == 'table' then
                    RivalsCosmetics.EnsureClientItemRestoreData(LP, weaponName, viewModelData)
                end
                local restoreData = RivalsCosmetics.GetClientItemRestoreData(LP, weaponName)
                local nextData
                if type(selection) == 'table' then
                    nextData = RivalsCosmetics.ApplyevilrollerplayersViewModelSelection(
                        weaponName,
                        { Name = weaponName },
                        selection
                    )
                else
                    nextData = type(restoreData) == 'table' and table.clone(restoreData) or table.clone(viewModelData)
                end

                local clientViewModel = RivalsCosmetics.ResolveClientViewModelClass()
                local destroy = type(clientViewModel) == 'table' and clientViewModel.Destroy or nil
                if type(destroy) ~= 'function' then
                    return false
                end
                RivalsCosmetics.RunAtIdentity2(function()
                    destroy(viewModel)
                end)

                local createViewModel = item._CreateViewModel
                if type(createViewModel) ~= 'function' then
                    return false
                end
                local info = RivalsCosmetics.EncodeGameTable({
                    Data = RivalsCosmetics.EncodeGameTable(nextData),
                })
                local created, newViewModel = RivalsCosmetics.RunAtIdentity2(function()
                    return createViewModel(item, info)
                end)
                if not created or type(newViewModel) ~= 'table' then
                    return false
                end
                rawset(item, 'ViewModel', newViewModel)

                local getArmsData = type(fighter) == 'table' and fighter.GetArmsData or nil
                local setArmsData = newViewModel.SetArmsData
                local equip = newViewModel.Equip
                local armsData = nil
                if type(getArmsData) == 'function' then
                    armsData = table.pack(getArmsData(fighter))
                end
                RivalsCosmetics.RunAtIdentity2(function()
                    if type(setArmsData) == 'function' and armsData ~= nil then
                        setArmsData(newViewModel, unpack(armsData, 1, armsData.n))
                    end
                    if type(equip) == 'function' then
                        equip(newViewModel, true)
                    end
                end)

                local spring = rawget(newViewModel, '_equip_spring')
                if type(spring) == 'table' then
                    rawset(spring, '_position0', 0)
                    rawset(spring, '_velocity0', 0)
                end
                RivalsCosmeticsState.ViewModelSelectionSignatureByItem[item] = {
                    Signature = signature,
                    ViewModel = newViewModel,
                }
                return true
            end

            function RivalsCosmetics.RestoreWeaponViewModels()
                local byWeapon = RivalsCosmeticsState.ClientItemRestoreData[LP]
                if type(byWeapon) == 'table' then
                    for weaponName in pairs(byWeapon) do
                        RivalsCosmetics.ReloadWeaponViewModel(weaponName, true, true)
                    end
                end
                RivalsCosmeticsState.ClientItemRestoreData = {}
                RivalsCosmeticsState.ViewModelSelectionSignatureByItem = setmetatable({}, { __mode = 'k' })
                return true
            end

            function RivalsCosmetics.ApplyActiveWeaponCosmetics()
                local fighter = ResolveLocalFighter()
                local item = fighter and fighter.EquippedItem or nil
                local weaponName = item and item.Name or nil
                if type(weaponName) ~= 'string' or weaponName == '' then
                    return false
                end
                return RivalsCosmetics.ReloadWeaponViewModel(weaponName)
            end

            function RivalsCosmetics.ApplySelectedWeaponCosmetics()
                local applied = false
                for _, weaponName in ipairs(RivalsCosmetics.ResolveWeaponNames()) do
                    if RivalsCosmetics.BuildevilrollerplayersItemSelection(weaponName) ~= nil then
                        applied = RivalsCosmetics.ReloadWeaponViewModel(weaponName) or applied
                    end
                end
                return applied
            end

            function RivalsCosmetics.RestoreInjectedWeaponData()
                local restored = false
                for item, original in pairs(RivalsCosmeticsState.OriginalInjectedItemCosmetics) do
                    if type(item) == 'table' and type(original) == 'table' then
                        item.Skin = original.Skin
                        item.Wrap = original.Wrap
                        item.Charm = original.Charm
                        item.Finisher = original.Finisher

                        if type(item.Set) == 'function' then
                            pcall(item.Set, item, 'Skin', original.Skin)
                            pcall(item.Set, item, 'Wrap', original.Wrap)
                            pcall(item.Set, item, 'Charm', original.Charm)
                            pcall(item.Set, item, 'Finisher', original.Finisher)
                        end

                        local viewModel = rawget(item, 'ViewModel')
                        if type(viewModel) == 'table' then
                            if type(viewModel.SetSkin) == 'function' then
                                pcall(viewModel.SetSkin, viewModel, original.Skin)
                            end
                            if type(viewModel.SetWrap) == 'function' then
                                pcall(viewModel.SetWrap, viewModel, original.Wrap)
                            end
                            if type(viewModel.SetCharm) == 'function' then
                                pcall(viewModel.SetCharm, viewModel, original.Charm)
                            end
                            if type(viewModel._UpdateSkin) == 'function' then
                                pcall(viewModel._UpdateSkin, viewModel)
                            end
                            if type(viewModel._UpdateWrap) == 'function' then
                                pcall(viewModel._UpdateWrap, viewModel)
                            end
                            if type(viewModel._UpdateCharm) == 'function' then
                                pcall(viewModel._UpdateCharm, viewModel)
                            end
                        end

                        restored = true
                    end
                end

                RivalsCosmeticsState.OriginalInjectedItemCosmetics = setmetatable({}, { __mode = 'k' })
                if restored then
                    local playerDataController = RivalsCosmetics.ResolvePlayerDataController()
                    local currentData = playerDataController and playerDataController.CurrentData or nil
                    if currentData and type(currentData.Replicate) == 'function' then
                        pcall(function()
                            currentData:Replicate('WeaponInventory')
                        end)
                    end
                end
                return restored
            end

            function RivalsCosmetics.ApplyWraps()
                for _, weaponName in ipairs(RivalsCosmetics.ResolveWeaponNames()) do
                    local selectedWrapName = RivalsCosmetics.ResolveSelectedWrapName(weaponName)
                    local inverted = RivalsCosmetics.ResolveWrapInvertedValue(weaponName)
                    for _, target in ipairs(RivalsCosmetics.ResolveWrapTargetsForWeapon(weaponName)) do
                        pcall(function()
                            RivalsCosmetics.ApplyWrapToModel(target, selectedWrapName, inverted)
                        end)
                    end
                end
            end

            function RivalsCosmetics.UpdatePreviewViewport()
                local previewViewport = Options.P5S3V1
                if not previewViewport or type(previewViewport.SetObject) ~= 'function' then
                    return false
                end

                local previewWeaponName = RivalsCosmetics.ResolvePreviewWeaponName()
                local previewModel = RivalsCosmetics.BuildPreviewModel(previewWeaponName)
                if not previewModel then
                    return false
                end

                if not RivalsCosmetics.HasVisibleRenderableDescendant(previewModel) then
                    pcall(function()
                        previewModel:Destroy()
                    end)
                    return false
                end

                local viewportModel = RivalsCosmetics.ResolvePreviewViewportModel()
                local copiedPreview = RivalsCosmetics.CopyPreviewModelIntoViewportModel(viewportModel, previewModel)
                pcall(function()
                    previewModel:Destroy()
                end)
                if not copiedPreview then
                    return false
                end

                if previewViewport.Object ~= viewportModel then
                    local previousObject = previewViewport.Object
                    local viewportParent = nil
                    pcall(function()
                        viewportParent = previousObject and previousObject.Parent or nil
                    end)

                    if viewportParent and viewportModel.Parent ~= viewportParent then
                        pcall(function()
                            viewportModel.Parent = viewportParent
                        end)
                    end
                    if previousObject and previousObject ~= viewportModel then
                        pcall(function()
                            previousObject.Parent = nil
                        end)
                    end
                    previewViewport.Object = viewportModel
                end

                if type(previewViewport.Focus) == 'function' then
                    pcall(function()
                        previewViewport:Focus()
                    end)
                end

                return true
            end

            function RivalsCosmetics.RefreshDropdownOptions()
                if RivalsCosmeticsState.CosmeticsUiLoaded ~= true then
                    return false
                end

                local ok, result = xpcall(function()
                    local synced = RivalsCosmetics.SyncActiveWeaponEditorFromState()
                    RivalsCosmetics.SyncFavoriteEditorFromState()
                    RivalsCosmetics.SyncRankCharmEditorFromState()
                    RivalsCosmetics.RefreshCosmeticPresetControls()
                    return synced
                end, function(err)
                    return debug.traceback(string.format('[Cosmetics_RefreshDropdownOptions] %s', tostring(err)), 2)
                end)

                if not ok then
                    error(result, 0)
                end
                return result == true
            end

            function RivalsCosmetics.BindFirstPersonModels()
                if RivalsCosmeticsState.BoundFirstPersonModels then
                    return
                end

                RivalsCosmeticsState.BoundFirstPersonModels = true
                task.spawn(GuardRivalsCallback('Cosmetics_BindFirstPersonModels', function()
                    local viewModels = Workspace:WaitForChild('ViewModels')
                    local firstPerson = viewModels:WaitForChild('FirstPerson')

                    Connections:register('Cosmetics_FirstPersonChildAdded', firstPerson.ChildAdded:Connect(GuardRivalsCallback('Cosmetics_FirstPersonChildAdded', function(child)
                        if not child or not child:IsA('Model') then
                            return
                        end

                        task.defer(function()
                            RivalsCosmetics.ApplyAll()
                        end)
                    end)))

                    if #firstPerson:GetChildren() > 0 then
                        task.defer(function()
                            RivalsCosmetics.ApplyAll()
                        end)
                    end
                end))
            end

            function RivalsCosmetics.RestoreAppliedCosmetics()
                RivalsCosmeticsState.PendingApplyToken = RivalsCosmeticsState.PendingApplyToken + 1
                RivalsCosmeticsState.RuntimeApplyRetryPending = false

                RivalsCosmetics.RestoreSpawnedWorldCosmetics()
                RivalsCosmetics.RestoreWorldTripmines()
                for model in pairs(RivalsCosmeticsState.OriginalWrapProperties) do
                    RivalsCosmetics.ApplyWrapToModel(model, nil)
                end

                RivalsCosmeticsState.OriginalWrapProperties = setmetatable({}, { __mode = 'k' })
                if not RivalsEmotes.IsEnabled() then
                    RivalsEmotes.RestoreEquippedEmotes()
                end
                RivalsCosmetics.RestoreWeaponViewModels()
                RivalsCosmetics.RestoreInjectedWeaponData()
                RivalsCosmeticsState.PendingSkinSelectionByWeapon = {}
                RivalsCosmeticsState.PendingWrapSelectionByWeapon = {}
                RivalsCosmeticsState.PendingCharmSelectionByWeapon = {}
                RivalsCosmeticsState.PendingFinisherSelectionByWeapon = {}
                RivalsCosmeticsState.WorldTripmineEntries = setmetatable({}, { __mode = 'k' })
                RivalsCosmeticsState.WorldTripmineApplyTokens = setmetatable({}, { __mode = 'k' })
                RivalsCosmeticsState.SpawnedWorldCosmeticEntries = setmetatable({}, { __mode = 'k' })
                RivalsCosmeticsState.SpawnedWorldCosmeticApplyTokens = setmetatable({}, { __mode = 'k' })
                RivalsCosmeticsState.SpawnedWorldCosmeticRetagging = setmetatable({}, { __mode = 'k' })
                if not RivalsEmotes.IsEnabled() then
                    RivalsCosmetics.RestorePlayerDataHook()
                    RivalsCosmetics.RestoreNativeUiBindings()
                end
                RivalsCosmetics.RestoreClientViewModelHook()
                RivalsCosmetics.RestoreFinisherHook()
                if not RivalsEmotes.IsEnabled() then
                    RivalsEmotes.RestoreEmoteControllerHook()
                end
                pcall(RivalsCosmetics.RefreshNativeCosmeticsScene)
                return true
            end

            function RivalsCosmetics.ResetState()
                RivalsCosmetics.RestoreAppliedCosmetics()
                RivalsCosmeticsState.PreviewWeaponName = nil
                RivalsCosmeticsState.SelectedEditorWeaponName = nil
                RivalsCosmeticsState.SelectedSkinByWeapon = {}
                RivalsCosmeticsState.SelectedWrapByWeapon = {}
                RivalsCosmeticsState.SelectedCharmByWeapon = {}
                RivalsCosmeticsState.SelectedFinisherByWeapon = {}
                RivalsCosmeticsState.SelectedWrapInvertedByWeapon = {}
                RivalsCosmeticsState.StableRandomSelectionByWeapon = {}
                RivalsCosmeticsState.FavoritedCosmeticsByWeapon = {}
                RivalsCosmeticsState.OnlyUseFavoritesByWeapon = {}
                RivalsCosmeticsState.RankCharmOverridesBySeason = {}
                RivalsCosmeticsState.SelectedRankCharmSeason = nil
                RivalsCosmeticsState.PendingApplyToken = 0
                RivalsCosmeticsState.RuntimeApplyRetryPending = false
                RivalsCosmeticsState.SavedConfigCosmeticObjects = nil
                RivalsCosmeticsState.CosmeticPresetsLoaded = false
                RivalsCosmeticsState.CosmeticPresets = {}
                RivalsCosmeticsState.CosmeticPresetSettings = {}
                RivalsCosmeticsState.CosmeticPresetAutoLoadApplied = false
                RivalsCosmeticsState.CosmeticPresetSaveToken = RivalsCosmeticsState.CosmeticPresetSaveToken + 1
                RivalsCosmeticsState.ApplyingCosmeticPreset = false
                RivalsCosmeticsState.CosmeticsUiLoaded = false
                RivalsCosmeticsState.CosmeticsUiLoading = false
                RivalsCosmeticsState.CosmeticsConfigName = 'RIVALS Default'
                RivalsCosmeticsState.NativeUnlockedInventory = nil
                RivalsCosmeticsState.NativeFavoritesSeeded = false
                RivalsCosmeticsState.NativeSaveToken = RivalsCosmeticsState.NativeSaveToken + 1
                if RivalsCosmeticsState.PreviewViewportModel then
                    pcall(function()
                        RivalsCosmeticsState.PreviewViewportModel:Destroy()
                    end)
                end
                RivalsCosmeticsState.PreviewViewportModel = nil
                RivalsCosmeticsState.BoundFirstPersonModels = false
            end

            function RivalsCosmetics.ApplyAll()
                if not RivalsCosmetics.ShouldUseCosmeticsRuntime() then
                    return false
                end

                pcall(RivalsCosmetics.EnsurePlayerDataHook)
                pcall(RivalsCosmetics.BuildNativeUnlockedInventory)
                pcall(RivalsCosmetics.EnsureNativeUiBindings)
                pcall(RivalsCosmetics.EnsureClientViewModelHook)
                pcall(RivalsCosmetics.BindFirstPersonModels)
                pcall(RivalsCosmetics.ApplySelectedWeaponCosmetics)
                pcall(RivalsCosmetics.ApplyActiveWeaponCosmetics)
                pcall(RivalsCosmetics.EnsureFinisherHook)
                pcall(RivalsEmotes.ApplyAll)
                pcall(RivalsCosmetics.ApplyWraps)
                pcall(RivalsCosmetics.BindSpawnedWorldCosmetics)
                pcall(RivalsCosmetics.BindWorldTripmines)
                pcall(RivalsCosmetics.UpdatePreviewViewport)
                return true
            end

            function RivalsCosmetics.ApplyPendingSelection(previewWeaponName, skinName, wrapName, charmName, finisherName)
                local previousSkinName = nil
                local previousWrapName = nil
                local previousCharmName = nil
                local previousFinisherName = nil
                local hasWeapon = type(previewWeaponName) == 'string' and previewWeaponName ~= ''
                if hasWeapon then
                    previousSkinName = RivalsCosmeticsState.PendingSkinSelectionByWeapon[previewWeaponName]
                    previousWrapName = RivalsCosmeticsState.PendingWrapSelectionByWeapon[previewWeaponName]
                    previousCharmName = RivalsCosmeticsState.PendingCharmSelectionByWeapon[previewWeaponName]
                    previousFinisherName = RivalsCosmeticsState.PendingFinisherSelectionByWeapon[previewWeaponName]
                    if skinName ~= nil then
                        RivalsCosmeticsState.PendingSkinSelectionByWeapon[previewWeaponName] = skinName
                    end
                    if wrapName ~= nil then
                        RivalsCosmeticsState.PendingWrapSelectionByWeapon[previewWeaponName] = wrapName
                    end
                    if charmName ~= nil then
                        RivalsCosmeticsState.PendingCharmSelectionByWeapon[previewWeaponName] = charmName
                    end
                    if finisherName ~= nil then
                        RivalsCosmeticsState.PendingFinisherSelectionByWeapon[previewWeaponName] = finisherName
                    end
                    RivalsCosmetics.SetPreviewWeaponName(previewWeaponName)
                end

                local previewOk, previewResult = pcall(RivalsCosmetics.UpdatePreviewViewport)

                if hasWeapon then
                    RivalsCosmeticsState.PendingSkinSelectionByWeapon[previewWeaponName] = previousSkinName
                    RivalsCosmeticsState.PendingWrapSelectionByWeapon[previewWeaponName] = previousWrapName
                    RivalsCosmeticsState.PendingCharmSelectionByWeapon[previewWeaponName] = previousCharmName
                    RivalsCosmeticsState.PendingFinisherSelectionByWeapon[previewWeaponName] = previousFinisherName
                end

                RivalsCosmeticsState.PendingApplyToken = RivalsCosmeticsState.PendingApplyToken + 1
                local pendingApplyToken = RivalsCosmeticsState.PendingApplyToken
                task.defer(GuardRivalsCallback('Cosmetics_ApplyPendingSelection_ApplyAll', function()
                    if RivalsCosmeticsState.PendingApplyToken ~= pendingApplyToken then
                        return nil
                    end

                    if hasWeapon then
                        if skinName ~= nil then
                            RivalsCosmeticsState.PendingSkinSelectionByWeapon[previewWeaponName] = skinName
                        end
                        if wrapName ~= nil then
                            RivalsCosmeticsState.PendingWrapSelectionByWeapon[previewWeaponName] = wrapName
                        end
                        if charmName ~= nil then
                            RivalsCosmeticsState.PendingCharmSelectionByWeapon[previewWeaponName] = charmName
                        end
                        if finisherName ~= nil then
                            RivalsCosmeticsState.PendingFinisherSelectionByWeapon[previewWeaponName] = finisherName
                        end
                    end

                    local applyResult = RivalsCosmetics.ApplyAll()
                    if hasWeapon then
                        RivalsCosmeticsState.PendingSkinSelectionByWeapon[previewWeaponName] = previousSkinName
                        RivalsCosmeticsState.PendingWrapSelectionByWeapon[previewWeaponName] = previousWrapName
                        RivalsCosmeticsState.PendingCharmSelectionByWeapon[previewWeaponName] = previousCharmName
                        RivalsCosmeticsState.PendingFinisherSelectionByWeapon[previewWeaponName] = previousFinisherName
                    end
                    return applyResult
                end))

                if not previewOk then
                    error(previewResult, 0)
                end

                return previewOk
            end

