                local function AddChamControls(group, prefix, label, stripDefault)
                    BindViewmodelVisualOption(group:AddToggle(prefix .. 'T1', {
                        Text = label,
                        Default = false,
                    }))
                    local settings = group:AddDependencyBox()
                    BindViewmodelVisualOption(settings:AddDropdown(prefix .. 'D1', {
                        Values = RivalsRuntimeBridge.ViewmodelVisuals.MaterialNames,
                        Default = 'Ghost',
                        Multi = false,
                        Text = 'Material',
                    }))
                    BindViewmodelVisualOption(settings:AddLabel('Color'):AddColorPicker(prefix .. 'C1', {
                        Default = Color3.new(1, 1, 1),
                        Title = label .. ' Color',
                    }))
                    BindViewmodelVisualOption(settings:AddSlider(prefix .. 'S1', {
                        Text = 'Transparency', Default = 0, Min = 0, Max = 1, Rounding = 2, Compact = true,
                    }))
                    BindViewmodelVisualOption(settings:AddToggle(prefix .. 'T2', {
                        Text = 'Strip Textures', Default = stripDefault == true,
                    }))
                    settings:SetupDependencies({{ Toggles[prefix .. 'T1'], true }})
                end

