            BuildRivalsMiscUi = function(Window)
                local MovementTab = Window:AddTab('Movement', 'move')
                local P10 = Window:AddTab('Misc', 'package')
                local RIVALS_REWARD_CLAIM_DELAY = 0.2
                -- Opening a capsule can spawn more unclaimed rewards (nested drops) that replicate a
                -- moment later. After the list looks empty we wait this long and re-check, a few times,
                -- so one Claim All drains everything instead of leaving leftovers for a second click.
                local RIVALS_REWARD_SETTLE_DELAY = 0.6
                local RIVALS_REWARD_EMPTY_CONFIRMATIONS = 3

                local function ClaimAllRivalsBundle()
                    local pdc = ResolvePlayerDataController()
                    if not pdc or not IsPlayerDataControllerReady() then
                        Library:Notify({ Title = 'RIVALS', Description = 'Player data not ready yet, try again in a moment.', Time = 3 })
                        return
                    end

                    local DAILY_REWARDS = {
                        { remote = 'ClaimLikeReward',          flag = 'ClaimedLikeReward' },
                        { remote = 'ClaimFavoriteReward',      flag = 'ClaimedFavoriteReward' },
                        { remote = 'ClaimNotificationsReward', flag = 'ClaimedNotificationsReward' },
                    }
                    local dailyClaimed, dailySkippedAlready = 0, 0
                    for _, info in ipairs(DAILY_REWARDS) do
                        if pdc:Get(info.flag) then
                            dailySkippedAlready = dailySkippedAlready + 1
                        else
                            local r = ResolveRivalsDataRemote(info.remote, 'RemoteEvent')
                            if r then
                                local ok = pcall(r.FireServer, r)
                                if ok then
                                    dailyClaimed = dailyClaimed + 1
                                    task.wait(RIVALS_REWARD_CLAIM_DELAY)
                                end
                            end
                        end
                    end

                    local passClaimed = 0
                    local passNotActive, passNoProgress = false, false
                    do
                        local passRemote = ResolveRivalsDataRemote('ClaimBattlePassReward', 'RemoteEvent')
                        if passRemote then
                            local modulesFolder = ReplicatedStorage:FindFirstChild('Modules')
                            local seasonLibraryModule = modulesFolder and modulesFolder:FindFirstChild('SeasonLibrary')
                            if seasonLibraryModule then
                                local okSeason, seasonLibrary = pcall(require, seasonLibraryModule)
                                if okSeason and type(seasonLibrary) == 'table' and type(seasonLibrary.CurrentSeason) == 'table' then
                                    local currentSeason = seasonLibrary.CurrentSeason
                                    if not currentSeason.BattlePassActive then
                                        passNotActive = true
                                    else
                                        local seasons = pdc:Get('Seasons')
                                        local seasonData = type(seasons) == 'table' and currentSeason.Name and seasons[currentSeason.Name] or nil
                                        local battlePass = type(seasonData) == 'table' and seasonData.BattlePass or nil
                                        if type(battlePass) ~= 'table' then
                                            passNoProgress = true
                                        else
                                            local passLevel = tonumber(battlePass.PassLevel) or 0
                                            local maxTrack = tonumber(battlePass.MaxPassTrackNum) or 0
                                            local rewardsClaimed = type(battlePass.RewardsClaimed) == 'table' and battlePass.RewardsClaimed or {}
                                            local rewardsCatalog = type(currentSeason.BattlePassRewards) == 'table' and currentSeason.BattlePassRewards or {}
                                            for tier = 1, passLevel do
                                                local tierCatalog = rewardsCatalog[tier]
                                                if type(tierCatalog) == 'table' then
                                                    local claimedTier = rewardsClaimed[tostring(tier)]
                                                    for track = 1, maxTrack do
                                                        if tierCatalog[track] ~= nil then
                                                            local already = type(claimedTier) == 'table' and claimedTier[tostring(track)]
                                                            if not already then
                                                                local ok = pcall(passRemote.FireServer, passRemote, tier, track)
                                                                if ok then
                                                                    passClaimed = passClaimed + 1
                                                                    task.wait(RIVALS_REWARD_CLAIM_DELAY)
                                                                end
                                                            end
                                                        end
                                                    end
                                                end
                                            end
                                        end
                                    end
                                end
                            end
                        end
                    end

                    local capsuleClaimed = 0
                    local capsuleSkippedDuel = false
                    local duelState = FighterDataCache.LocalDuel
                    if duelState and (duelState.IsInDuel or duelState.IsInShootingRange) then
                        capsuleSkippedDuel = true
                    else
                        local capsuleRemote = ResolveRivalsDataRemote('UseUnclaimedReward', 'RemoteFunction')
                        if capsuleRemote then
                            local maxQty = 99
                            local modulesFolder = ReplicatedStorage:FindFirstChild('Modules')
                            local constantsModule = modulesFolder and modulesFolder:FindFirstChild('CONSTANTS')
                            if constantsModule then
                                local okC, constants = pcall(require, constantsModule)
                                if okC and type(constants) == 'table' and type(constants.MAX_BACKPACK_USE_QUANTITY) == 'number' then
                                    maxQty = constants.MAX_BACKPACK_USE_QUANTITY
                                end
                            end

                            local emptyStreak = 0
                            local failureStreak = 0
                            for _ = 1, 400 do
                                local rewards = pdc:Get('UnclaimedRewards')
                                if type(rewards) ~= 'table' or rewards[1] == nil then
                                    -- The list can read empty for a moment while rewards spawned by the
                                    -- last capsule are still replicating. Only finish once it stays empty
                                    -- across a settle window, so a second Claim All finds nothing left.
                                    emptyStreak = emptyStreak + 1
                                    if emptyStreak >= RIVALS_REWARD_EMPTY_CONFIRMATIONS then break end
                                    task.wait(RIVALS_REWARD_SETTLE_DELAY)
                                else
                                    emptyStreak = 0
                                    local entry = rewards[1]
                                    local startQty = type(entry) == 'table' and tonumber(entry.Quantity) or 1
                                    if not startQty or startQty < 1 then startQty = 1 end
                                    local useQty = math.min(startQty, maxQty)

                                    local ok, result = pcall(capsuleRemote.InvokeServer, capsuleRemote, 1, useQty)
                                    if ok and result == 'Success' then
                                        capsuleClaimed = capsuleClaimed + 1
                                        failureStreak = 0
                                    else
                                        -- Server refused this open (rate limit / transient). Stop only if
                                        -- it keeps refusing so we never spin forever on a stuck item.
                                        failureStreak = failureStreak + 1
                                        if failureStreak >= 5 then break end
                                    end

                                    task.wait(RIVALS_REWARD_CLAIM_DELAY)
                                end
                            end
                        end
                    end

                    local parts = {}
                    if dailyClaimed > 0 then table.insert(parts, string.format('%d daily', dailyClaimed)) end
                    if capsuleClaimed > 0 then table.insert(parts, string.format('%d capsule%s', capsuleClaimed, capsuleClaimed == 1 and '' or 's')) end
                    if passClaimed > 0 then table.insert(parts, string.format('%d pass tier%s', passClaimed, passClaimed == 1 and '' or 's')) end

                    local desc
                    if #parts > 0 then
                        desc = 'Claimed ' .. table.concat(parts, ', ') .. '.'
                        if capsuleSkippedDuel then desc = desc .. ' Capsules skipped (in duel/range).' end
                    elseif capsuleSkippedDuel then
                        desc = 'Capsules skipped (in duel/range). Nothing else to claim.'
                    elseif dailySkippedAlready == 3 and not passNotActive and not passNoProgress then
                        desc = 'Already up to date - nothing to claim.'
                    elseif dailySkippedAlready == 3 then
                        desc = 'Daily rewards already claimed - nothing else to claim right now.'
                    else
                        desc = 'Nothing to claim.'
                    end

                    Library:Notify({ Title = 'RIVALS', Description = desc, Time = 4 })
                end

                local playerSpooferLabels = {
                    Winstreak = 'Win Streak',
                    Level = 'Level',
                    RankedElo = 'Ranked ELO',
                    NametagStatus = 'Nametag Status',
                    Influencer = 'Influencer',
                    RobloxEmployee = 'Roblox Employee',
                    NosniyTeam = "Nosniy's Team",
                }
                local playerSpooferScopes = {
                    { suffix = 'You', title = 'Player Spoofer (You)', side = 'Left' },
                    { suffix = 'Oth', title = 'Player Spoofer (Others)', side = 'Right' },
                }
                for _, scope in ipairs(playerSpooferScopes) do
