            BuildRivalsUi = function(Window)
                local originalAddTab = Window.AddTab
                local tabs = {}
                for _, name in ipairs({'Combat', 'World', 'ESP', 'Visuals', 'Character', 'Misc', 'Settings'}) do
                    tabs[name] = originalAddTab(Window, name)
                end
                local aliases = {
                    ['Client Effects'] = 'Visuals', Crosshair = 'Visuals',
                    Automation = 'Character', Movement = 'Character',
                    Debug = 'Misc', ['UI Settings'] = 'Settings',
                }
                function Window:AddTab(name, ...)
                    local target = aliases[name] or name
                    if tabs[target] then return tabs[target] end
                    tabs[target] = originalAddTab(self, target, ...)
                    return tabs[target]
                end
                BuildRivalsEspUi(Window)
                local CombatTab = BuildRivalsAimbotUi(Window)
                BuildRivalsModsUi(CombatTab)
                local AutomationTab = BuildRivalsPickupUi(Window)
                BuildRivalsRagebotUi(CombatTab)
                BuildRivalsVisualsUi(Window)
                local MiscTab = BuildRivalsMiscUi(Window)
                BuildRivalsCosmeticsUi(MiscTab)
                BuildRivalsDebugUi(Window)
            end

            local RivalsRuntime = {}

            function RivalsRuntime.ResetState()
                RivalsRuntimeBridge.WorldVisuals.Destroy()
                RivalsRuntimeBridge.ViewmodelVisuals.Destroy()
                RivalsRuntimeBridge.NativeRemovals.Destroy()
                RivalsRagebotState.RespawnBinding = nil
                RivalsRuntimeBridge.Movement.Destroy()
                RivalsRuntimeBridge.DeviceSpoof.Destroy()
                RivalsRuntimeBridge.PlayerSpoofer.Destroy()
                RivalsRuntimeBridge.AnimationPlayer.Destroy()
                RivalsRuntimeBridge.MovementRecorder.Destroy()
                if RivalsRuntimeBridge.DestroyevilrollerplayersHailRagebot then
                    RivalsRuntimeBridge.DestroyevilrollerplayersHailRagebot()
                end
                RivalsRuntimeBridge.CombatFeedback.Destroy()
                RivalsRuntimeBridge.ResetRivalsCosmetics()
                RivalsModsState.RestoreHooks()
                AimbotBridge.ResetAimbotRuntimeState()
                AimbotBridge.ResetTriggerbotReactionState()
                AimbotBridge.ResetCameraAimRandomState()
                RivalsRuntimeBridge.ResetFlickbot()
                RivalsRagebotState.Target = nil
                RivalsRagebotState.HoldCFrame = nil
                RivalsRagebotState.LastHoldUpdateAt = 0
                RivalsRagebotState.LastRespawnRequestAt = 0
                RivalsRagebotState.PhaseClockSec = 0
                RivalsRuntimeBridge.ResetAutoLoadoutState()
                RivalsRuntimeBridge.ResetAutoBanState()
                RivalsRuntimeBridge.ResetTripmineAutomation()
                LocalPickupObserver.ResetDropTracking()
                AimbotTriggerbotLastShotAt = 0
                MeleeFastFire.LastShotAt = 0
                RivalsRuntimeBridge.DestroyAimbotStatusNotification()
                AimbotInputState.LeftMouse = false
                AimbotInputState.RightMouse = false
                AimbotInputState.TouchCount = 0
                AimbotFovCircle.Visible = false
                pcall(function() AimbotFovCircle:Remove() end)
                CameraFovCircle.Visible = false
                pcall(function() CameraFovCircle:Remove() end)
                DestroyAllESP()
                WorldESPState.DestroyAllThrowable()
                WorldESPState.DestroyAllHazard()
                WorldESPState.DestroyAllSoundVisualizer()
                DestroyRuntimeIssueNotification()
            end

            function RivalsRuntime.RegisterPlayerLifecycle()
                RivalsRuntimeBridge.NextESPReconcileAt = 0
                if EspRenderSettings.Enabled then
                    ReconcileESPPlayers()
                end

                Library:GiveSignal(Players.PlayerRemoving:Connect(GuardRivalsCallback('Player_Removing', function(player)
                    DestroyESP(player)
                end)))

                EnsureWeaponInfoTracking()
            end

            function RivalsRuntime.RegisterWorldLifecycle()
                for _, child in ipairs(Workspace:GetChildren()) do
                    WorldESPState.RegisterThrowable(child)
                    LocalPickupObserver.ObserveDrop(child)
                end
                Connections:register('Throwable_Added', Workspace.ChildAdded:Connect(GuardRivalsCallback('Throwable_Added', WorldESPState.RegisterThrowable)))
                Connections:register('Throwable_Removed', Workspace.ChildRemoved:Connect(GuardRivalsCallback('Throwable_Removed', WorldESPState.DestroyThrowable)))
                Connections:register('PickupDrop_Added', Workspace.ChildAdded:Connect(GuardRivalsCallback('PickupDrop_Added', LocalPickupObserver.ObserveDrop)))
                Connections:register('PickupDrop_Removed', Workspace.ChildRemoved:Connect(GuardRivalsCallback('PickupDrop_Removed', LocalPickupObserver.UnobserveDrop)))

                for _, descendant in ipairs(Workspace:GetDescendants()) do
                    WorldESPState.RegisterHazard(descendant)
                end
                Connections:register('Hazard_Added', Workspace.DescendantAdded:Connect(GuardRivalsCallback('Hazard_Added', WorldESPState.RegisterHazard)))
                Connections:register('Hazard_Removed', Workspace.DescendantRemoving:Connect(GuardRivalsCallback('Hazard_Removed', WorldESPState.DestroyHazard)))
                WorldESPState.SetSoundVisualizerEnabled(Toggles.P1S3T1 and Toggles.P1S3T1.Value == true)
                RivalsRuntimeBridge.BindTripmineAutomation()
            end

            function RivalsRuntime.RegisterInputLifecycle()
                Connections:register('Aimbot_InputBegan', UserInputService.InputBegan:Connect(GuardRivalsCallback('Aimbot_InputBegan', function(input, gameProcessed)
                    if gameProcessed then
                        return
                    end

                    if input.UserInputType == Enum.UserInputType.MouseButton1 then
                        AimbotInputState.LeftMouse = true
                    elseif input.UserInputType == Enum.UserInputType.MouseButton2 then
                        AimbotInputState.RightMouse = true
                    end
                end)))

                Connections:register('Aimbot_InputEnded', UserInputService.InputEnded:Connect(GuardRivalsCallback('Aimbot_InputEnded', function(input)
                    if input.UserInputType == Enum.UserInputType.MouseButton1 then
                        AimbotInputState.LeftMouse = false
                    elseif input.UserInputType == Enum.UserInputType.MouseButton2 then
                        AimbotInputState.RightMouse = false
                    end
                end)))

                Connections:register('Aimbot_TouchStarted', UserInputService.TouchStarted:Connect(GuardRivalsCallback('Aimbot_TouchStarted', function(touch, gameProcessed)
                    if gameProcessed then
                        return
                    end

                    AimbotInputState.TouchCount = AimbotInputState.TouchCount + 1
                end)))

                Connections:register('Aimbot_TouchEnded', UserInputService.TouchEnded:Connect(GuardRivalsCallback('Aimbot_TouchEnded', function()
                    AimbotInputState.TouchCount = math.max(AimbotInputState.TouchCount - 1, 0)
                end)))
            end

            function RivalsRuntime.WaitForInitialLoadInSettle()
                -- Wait for the spawn-shield readiness signal before any
                -- character/camera setup. In lobby (no fighter, no shield)
                -- the readiness check stays false forever, so the timeout
                -- is the deliberate exit path; 10s is a generous ceiling
                -- that real spawn shields beat by orders of magnitude and
                -- a safety net if the shield system ever regresses.
                RivalsRuntimeBridge.WaitForLocalReady(10)
                InitCharacter()

                if RivalsRuntimeBridge.IsAutoQueueLobby and RivalsRuntimeBridge.IsAutoQueueLobby() then
                    if type(RivalsRuntimeBridge.RefreshAutoQueueDropdownValues) == 'function' then
                        pcall(RivalsRuntimeBridge.RefreshAutoQueueDropdownValues)
                    end
                    -- The toggle's OnChanged fired during SaveManager autoload (in prepare_setup) and
                    -- already issued JoinQueue if the saved toggle was true. Only fire here as a
                    -- fallback when belief is still 'idle' (i.e., the earlier attempt was rejected
                    -- with not_in_lobby because the lobby hadn't settled yet).
                    if Toggles and Toggles.P8S6T1 and Toggles.P8S6T1.Value == true
                        and type(RivalsRuntimeBridge.FireAutoQueueJoin) == 'function' then
                        local belief = type(RivalsRuntimeBridge.GetAutoQueueBelief) == 'function'
                            and RivalsRuntimeBridge.GetAutoQueueBelief() or 'idle'
                        if belief == 'idle' then
                            pcall(RivalsRuntimeBridge.FireAutoQueueJoin)
                        end
                    end
                end
            end

            function RivalsRuntime.StartLoops()
                Connections:register('ESP_Render', RunService.RenderStepped:Connect(GuardRivalsCallback('ESP_Render', RivalsRuntimeBridge.UpdateESP)))
                Connections:register('Throwable_Render', RunService.RenderStepped:Connect(GuardRivalsCallback('Throwable_Render', WorldESPState.UpdateThrowable)))
                Connections:register('Hazard_Render', RunService.RenderStepped:Connect(GuardRivalsCallback('Hazard_Render', WorldESPState.UpdateHazard)))
                Connections:register('CombatFeedback_Render', RunService.RenderStepped:Connect(GuardRivalsCallback('CombatFeedback_Render', RivalsRuntimeBridge.CombatFeedback.Update)))
                Connections:register('ViewmodelVisuals_Render', RunService.RenderStepped:Connect(GuardRivalsCallback('ViewmodelVisuals_Render', RivalsRuntimeBridge.ViewmodelVisuals.Update)))
                Connections:register('Movement_PreSimulation', RunService.PreSimulation:Connect(GuardRivalsCallback('Movement_PreSimulation', RivalsRuntimeBridge.Movement.Update)))
                Connections:register('MovementRecorder_PreSimulation', RunService.PreSimulation:Connect(GuardRivalsCallback('MovementRecorder_PreSimulation', RivalsRuntimeBridge.MovementRecorder.Update)))
                Connections:register('Movement_BlankFlight', RunService.RenderStepped:Connect(GuardRivalsCallback('Movement_BlankFlight', RivalsRuntimeBridge.Movement.BlankFlightVelocity)))
                Connections:register('AnimationPlayer_Render', RunService.RenderStepped:Connect(GuardRivalsCallback('AnimationPlayer_Render', RivalsRuntimeBridge.AnimationPlayer.Update)))
                Connections:register('CameraModifiers_Render', RunService.RenderStepped:Connect(GuardRivalsCallback('CameraModifiers_Render', RivalsModsState.UpdateCameraModifiers)))
                Connections:register('MovementRecorder_Render', RunService.RenderStepped:Connect(GuardRivalsCallback('MovementRecorder_Render', RivalsRuntimeBridge.MovementRecorder.UpdateRender)))
                Connections:register('Flickbot_Render', RunService.RenderStepped:Connect(GuardRivalsCallback('Flickbot_Render', RivalsRuntimeBridge.UpdateFlickbot)))
                Connections:register('CameraAim_Render', RunService.RenderStepped:Connect(GuardRivalsCallback('CameraAim_Render', RivalsRuntimeBridge.UpdateCameraAim)))
                Connections:register('Aimbot_Render', RunService.Heartbeat:Connect(GuardRivalsCallback('Aimbot_Render', RivalsRuntimeBridge.UpdateAimbot)))
                Connections:register('Ragebot_Heartbeat', RunService.Heartbeat:Connect(GuardRivalsCallback('Ragebot_Heartbeat', RivalsRuntimeBridge.UpdateRagebot)))
                Connections:register('TripmineAutomation_Heartbeat', RunService.Heartbeat:Connect(GuardRivalsCallback('TripmineAutomation_Heartbeat', RivalsRuntimeBridge.UpdateTripmineAutomation)))

                local AutoQueueRemotes = ReplicatedStorage:FindFirstChild('Remotes')
                local AutoQueueMatchmaking = AutoQueueRemotes and AutoQueueRemotes:FindFirstChild('Matchmaking')
                local AutoQueueStatus = AutoQueueMatchmaking and AutoQueueMatchmaking:FindFirstChild('UpdateQueueStatus')
                if AutoQueueStatus and AutoQueueStatus:IsA('RemoteEvent') then
                    Connections:register('AutoQueue_StatusUpdate',
                        AutoQueueStatus.OnClientEvent:Connect(GuardRivalsCallback(
                            'AutoQueue_StatusUpdate', RivalsRuntimeBridge.HandleAutoQueueStatusUpdate)))
                end
                Connections:register('AutoQueue_MatchmadeGameOver',
                    workspace:GetAttributeChangedSignal('MatchmadeGameOver'):Connect(GuardRivalsCallback(
                        'AutoQueue_MatchmadeGameOver', RivalsRuntimeBridge.OnAutoQueueMatchmadeGameOverChanged)))
                Connections:register('AutoQueue_LobbyReturn_Teleport',
                    game:GetService('TeleportService').LocalPlayerArrivedFromTeleport:Connect(GuardRivalsCallback(
                        'AutoQueue_LobbyReturn_Teleport', RivalsRuntimeBridge.OnAutoQueueLobbyReturn)))
                RivalsRuntimeBridge.CombatFeedback.RefreshBinding()
                RivalsRuntimeBridge.MovementRecorder.BindRoundSignal()
            end

            function RivalsRuntime.RegisterCharacterLifecycle()
                RefreshLocalPickupHealthObserver()
                AttachWeaponInfoObservers(LP)
                RivalsModsState.EnsureHooks()
                RivalsRuntimeBridge.ApplyRivalsCosmetics()
                RivalsRuntimeBridge.RegisterAutoRespawnSignals()
                RivalsRuntimeBridge.RegisterAutoBanSignals()
                RivalsRuntimeBridge.RegisterAutoQueuePlayAgainSignals()

                RivalsRuntimeBridge.RunPickupSpawnSetup = function()
                    task.defer(function()
                        -- Wait for the spawn-shield readiness signal before any
                        -- per-spawn setup. Replaces the legacy fixed-time
                        -- fighter wait -- the shield-driven wait stays
                        -- patient until the character is actually loaded and
                        -- the round is live, then proceeds. 30s safety ceiling
                        -- covers lobby spawns (no shield + no fighter ever) so
                        -- the deferred coroutine doesn't leak on lobby cycles.
                        if not RivalsRuntimeBridge.WaitForLocalReady(30) then
                            RivalsRuntimeBridge.LogDiagnosticEvent('Spawn', 'WaitForLocalReady timed out; per-spawn setup aborted')
                            return
                        end

                        local fighter = ResolveLocalFighter()
                        if not fighter then
                            RivalsRuntimeBridge.LogDiagnosticEvent('Spawn', 'Local fighter unavailable after readiness; per-spawn setup aborted')
                            return
                        end

                        FighterDataCache.AttachLocalDuelWatchers(fighter)
                        RivalsRuntimeBridge.RegisterAutoRespawnSignals()
                        RivalsRuntimeBridge.RegisterAutoBanSignals()
                        RivalsRuntimeBridge.RegisterAutoQueuePlayAgainSignals()
                        if not InitCharacter() then
                            RivalsRuntimeBridge.LogDiagnosticEvent('Spawn', 'InitCharacter failed after fighter ready; per-spawn setup aborted')
                            return
                        end

                        if not Humanoid or Humanoid.Health <= 0 then
                            RivalsRuntimeBridge.LogDiagnosticEvent('Spawn', 'Humanoid missing or dead at per-spawn; setup aborted')
                            return
                        end

                        RefreshLocalPickupHealthObserver()
                        AttachWeaponInfoObservers(LP)
                        RivalsModsState.EnsureHooks()
                        UpdateRivalsPickupFeatures()
                        RivalsRuntimeBridge.ApplyRivalsCosmetics()
                    end)
                end

                if LP.Character then
                    RivalsRuntimeBridge.RunPickupSpawnSetup()
                end

                Library:GiveSignal(LP.CharacterAdded:Connect(GuardRivalsCallback('Pickup_CharacterAdded', function(newChar)
                    RivalsRuntimeBridge.LogDiagnosticEvent(
                        'CharAdded',
                        'LP.CharacterAdded fired (new: ' .. tostring(newChar and newChar.Name or '<nil>') .. ')'
                    )
                    RivalsRuntimeBridge.ResetLocalShieldLatch()
                    RivalsRuntimeBridge.RunPickupSpawnSetup()
                end)))
            end

