                }
                local ConfigProfileDefaults = {
                    Legit = {
                        { idx = 'P2S1T7', type = 'Toggle', value = false },
                        { idx = 'P8S4T1', type = 'Toggle', value = false },
                        { idx = 'P8S4T2', type = 'Toggle', value = false },
                        { idx = 'P8S5T1', type = 'Toggle', value = false },
                        { idx = 'P8S6T1', type = 'Toggle', value = false },
