                        { idx = 'P4S1T4', type = 'Toggle', value = false },
                        { idx = 'P8S4T4', type = 'Toggle', value = false },
                    },
                    Rage = {
                        { idx = 'P2S1T7', type = 'Toggle', value = true },
                        { idx = 'P8S4T1', type = 'Toggle', value = true },
                        { idx = 'P8S4T2', type = 'Toggle', value = true },
                        { idx = 'P8S5T1', type = 'Toggle', value = true },
                        { idx = 'P8S6T1', type = 'Toggle', value = true },
                        { idx = 'P4S1T3', type = 'Toggle', value = true },
                        { idx = 'P4S1T4', type = 'Toggle', value = true },
                        { idx = 'P8S4T4', type = 'Toggle', value = true },
                    },
                }

                local function CloneRivalsConfigProfileValue(value)
                    if type(value) ~= 'table' then
                        return value
                    end

                    local copy = {}
                    for key, child in pairs(value) do
                        copy[key] = CloneRivalsConfigProfileValue(child)
                    end
                    return copy
                end

                local function CloneRivalsConfigProfileObject(object)
                    local copy = {}
                    for key, value in pairs(object) do
                        copy[key] = CloneRivalsConfigProfileValue(value)
                    end
                    return copy
                end

                local function BuildRivalsConfigProfileDefaultObjects(config_name)
                    local profile_defaults = ConfigProfileDefaults[config_name]
                    if type(profile_defaults) ~= 'table' then
                        return nil
                    end

                    local objects = {}
                    local indexes_by_id = {}
                    local function upsert(object)
                        if type(object) ~= 'table' or type(object.idx) ~= 'string' then
                            return
                        end

                        local cloned = CloneRivalsConfigProfileObject(object)
                        local existing_index = indexes_by_id[cloned.idx]
                        if existing_index then
                            objects[existing_index] = cloned
                        else
                            indexes_by_id[cloned.idx] = #objects + 1
                            objects[#objects + 1] = cloned
                        end
                    end

                    for _, object in ipairs(SharedConfigDefaultObjects) do
                        upsert(object)
                    end
                    for _, object in ipairs(profile_defaults) do
                        upsert(object)
                    end

                    return objects
                end

                local function WriteRivalsConfigProfileDefault(config_name)
                    local objects = BuildRivalsConfigProfileDefaultObjects(config_name)
                    if not objects then
                        return false, 'unknown RIVALS config profile: ' .. tostring(config_name)
                    end

                    local settings_folder = ScriptPaths.storage_root() .. '/settings'
                    if not isfolder(settings_folder) then
                        makefolder(settings_folder)
                    end

                    local ok, err = pcall(function()
                        writefile(ScriptPaths.config_path(config_name), HttpService:JSONEncode({ objects = objects }))
                    end)
                    if not ok then
                        return false, err
                    end
                    return true
                end
                RivalsConfigProfiles.WriteDefault = WriteRivalsConfigProfileDefault

                -- Preset pickers are one-shot actions; configs save the values they set,
                -- so re-loading a config must not replay the preset over saved tweaks.
                SaveManager:SetIgnoreIndexes({ 'P1S32D1', 'P1S26D6', 'P1S14D1',
                    'P5EDITOR_WEAPON', 'P5EDITOR_SKIN', 'P5EDITOR_CHARM', 'P5EDITOR_WRAP',
                    'P5EDITOR_FINISHER', 'P5EDITOR_WRAPINV', 'evilrollerplayersCosmeticsEmote' })

                local SharedUI = GameBootstrap.create_standard_shared_ui({
                    ui_settings = UISettings,
                    window = Window,
                    library = Library,
                    theme_manager = ThemeManager,
                    script_paths = ScriptPaths,
                    save_manager = SaveManager,
                    current_config_name = 'RIVALS',
                    default_config_name = 'RIVALS Default',
                    config_names = RivalsConfigProfiles.Names,
                    use_global_config_names = true,
                    toggles = Toggles,
                    options = Options,
                    local_player = LP,
                    defaults = {
                        auto_show = false,
                        show_notification = true,
                        show_keybind_states = true,
                        auto_execute_on_teleport = true,
                        auto_load_config = true,
                        auto_save_config = true,
                        load_config_name = 'Legit',
                        menu_keybind = 'RightShift',
                    },
                    persist_menu_keybind = false,
                    queue_on_teleport = queue_on_teleport,
                    before_save = function(shared_ui, config_name)
                        local saveName = config_name or (shared_ui and shared_ui:resolve_save_config_name()) or 'Legit'
                        RivalsRuntimeBridge.SetRivalsCosmeticsConfigName(saveName)
                        RivalsRuntimeBridge.SetAutoLoadoutConfigName(saveName)
                        RivalsRuntimeBridge.CaptureSavedRivalsCosmeticsSelections()
                    end,
                    on_save = function(shared_ui, config_name)
                        local saveName = config_name or (shared_ui and shared_ui:resolve_save_config_name()) or 'Legit'
                        RivalsRuntimeBridge.SetRivalsCosmeticsConfigName(saveName)
                        RivalsRuntimeBridge.SetAutoLoadoutConfigName(saveName)
                        RivalsRuntimeBridge.SaveRivalsCosmeticsSelections()
                        RivalsRuntimeBridge.SaveAutoLoadoutProfiles()
                    end,
                    on_load_saved = function(shared_ui, config_name)
                        local loadName = config_name or (shared_ui and shared_ui:resolve_load_config_name()) or 'Legit'
                        RivalsRuntimeBridge.SetRivalsCosmeticsConfigName(loadName)
                        RivalsRuntimeBridge.SetAutoLoadoutConfigName(loadName)
                        task.defer(GuardRivalsCallback('Cosmetics_LoadSavedSelections', function()
                            RivalsRuntimeBridge.LoadSavedRivalsCosmeticsSelections()
                            RivalsRuntimeBridge.RefreshRivalsCosmetics()
                            RivalsRuntimeBridge.ApplyRivalsCosmetics()
                        end))
                        task.defer(GuardRivalsCallback('AutoLoadout_LoadSavedProfiles', RivalsRuntimeBridge.LoadAutoLoadoutProfiles))
                    end,
                    on_load_default = function(shared_ui, config_name)
                        local loadName = config_name or (shared_ui and shared_ui:resolve_save_config_name()) or 'Legit'
                        RivalsRuntimeBridge.SetRivalsCosmeticsConfigName(loadName)
                        RivalsRuntimeBridge.SetAutoLoadoutConfigName(loadName)
                        task.defer(GuardRivalsCallback('Cosmetics_LoadDefaultSelections', function()
                            RivalsRuntimeBridge.LoadSavedRivalsCosmeticsSelections()
                            RivalsRuntimeBridge.RefreshRivalsCosmetics()
                            RivalsRuntimeBridge.ApplyRivalsCosmetics()
                        end))
                        task.defer(GuardRivalsCallback('AutoLoadout_LoadDefaultProfiles', RivalsRuntimeBridge.LoadAutoLoadoutProfiles))
                    end,
                    reset_config_to_default = function(shared_ui, config_name)
                        return RivalsConfigProfiles.WriteDefault(config_name)
                    end,
                    reconcile_loaded_state = function()
                        if ReconcileLoadedState then
                            ReconcileLoadedState()
                        end
                    end,
                })
                local initialRivalsConfigName = (SharedUI:should_auto_load_config() and SharedUI:resolve_load_config_name()) or 'RIVALS Default'
                RivalsRuntimeBridge.SetRivalsCosmeticsConfigName(initialRivalsConfigName)
                RivalsRuntimeBridge.SetAutoLoadoutConfigName(initialRivalsConfigName)
                ReconcileLoadedState = function()
                    RefreshEspRenderSettings()
                    RivalsModsState.EnsureHooks()
                    RivalsRuntimeBridge.WorldVisuals.RefreshAll()
                    RivalsRuntimeBridge.ViewmodelVisuals.RefreshAll()
                    RivalsRuntimeBridge.NativeRemovals.RefreshAll()
                    RivalsRuntimeBridge.Movement.RefreshAll()
                    RivalsRuntimeBridge.DeviceSpoof.RefreshAll()
                    RivalsRuntimeBridge.PlayerSpoofer.RefreshAll()
                    RivalsRuntimeBridge.AnimationPlayer.RefreshAll()
                    RivalsRuntimeBridge.RefreshRivalsCosmetics()
                    RivalsRuntimeBridge.ApplyRivalsCosmetics()
                end

                GameBootstrap.prepare_setup({
                    save_manager = SaveManager,
                    script_paths = ScriptPaths,
                    current_config_name = 'RIVALS',
                    default_config_name = 'RIVALS Default',
                    shared_ui = SharedUI,
                    toggles = Toggles,
                    options = Options,
                    reset_config_to_default = function(shared_ui, config_name)
                        return RivalsConfigProfiles.WriteDefault(config_name)
                    end,
                })
                RivalsRuntimeBridge.LoadSavedRivalsCosmeticsSelections()
                task.defer(GuardRivalsCallback('AutoLoadout_LoadInitialProfiles', RivalsRuntimeBridge.LoadAutoLoadoutProfiles))
                EnsureEspRenderSettingsTracking()
                RefreshEspRenderSettings()
                RivalsRuntimeBridge.WorldVisuals.RefreshAll()
                RivalsRuntimeBridge.ViewmodelVisuals.RefreshAll()
                RivalsRuntimeBridge.NativeRemovals.RefreshAll()
                RivalsRuntimeBridge.Movement.RefreshAll()
                RivalsRuntimeBridge.DeviceSpoof.RefreshAll()
                RivalsRuntimeBridge.PlayerSpoofer.RefreshAll()
                RivalsRuntimeBridge.AnimationPlayer.RefreshAll()

                -- =============================================
                -- Lifecycle
                -- =============================================

                Library:OnUnload(GuardRivalsCallback('Runtime_Unload', function()
                    RivalsRuntime.ResetState()
                    Connections:disconnect_all()
                end))

                RivalsRuntime.WaitForInitialLoadInSettle()
                RivalsRuntime.RegisterPlayerLifecycle()
                RivalsRuntime.RegisterWorldLifecycle()
                RivalsRuntime.RegisterInputLifecycle()
                RivalsRuntime.RegisterCharacterLifecycle()
                RivalsRuntime.StartLoops()
                RivalsRuntimeBridge.EnsureMatchBoundaryDetection()
                RivalsRuntimeBridge.BindRivalsCosmetics()
                RivalsRuntimeBridge.BindAutoLoadoutControllers()
                RivalsRuntimeBridge.ApplyRivalsCosmetics()
                RivalsRuntimeBridge.QueueAutoLoadoutSubmission()

                SharedUI:notify_loaded(5)
            end

            if GuardRivalsCallback('EnumLibrary_StartupBarrier', function()
                local enumLibrary = ResolveEnumLibrary()
                if not enumLibrary then
                    error('EnumLibrary is unavailable')
                end

                if enumLibrary._enum_builder_complete ~= true then
                    local builderDeadline = os.clock() + 30
                    while os.clock() < builderDeadline and enumLibrary._enum_builder_complete ~= true do
                        task.wait(0.1)
                    end
                end

                if enumLibrary._enum_builder_complete ~= true then
                    -- Empty _from_enum after the deadline = require() handed us a
                    -- fresh sandbox copy the game's enum builder can never touch
                    -- (Solara-tier require emulation). Support notice, not an error.
                    local fromEnum = rawget(enumLibrary, '_from_enum')
                    if type(fromEnum) ~= 'table' or next(fromEnum) == nil then
                        local executorName = 'this executor'
                        if type(identifyexecutor) == 'function' then
                            local ok, name = pcall(identifyexecutor)
                            if ok and type(name) == 'string' and name ~= '' then
                                executorName = name
                            end
                        end
                        TryShowRivalsRuntimeIssueNotification('RIVALS isn\'t supported on ' .. executorName .. '.')
                        return false
                    end

                    error('EnumLibrary builder did not complete')
                end

                if type(enumLibrary.WaitForEnumBuilder) == 'function' then
                    enumLibrary:WaitForEnumBuilder()
                end

                return true
            end)() ~= true then
                return
            end

            BuildRivalsUi(Window)
            RivalsRuntime.Initialize(Window)
            end

-- =============================================================================
--  Footer - closes the bootstrap
-- =============================================================================
--  Closes the experience check opened by the feature module, the xpcall that
--  wraps it, and the outer function. Any error thrown anywhere inside the
--  feature module lands here with a full traceback rather than killing the
--  script silently.
-- =============================================================================

    else
        if Library and type(Library.Notify) == 'function' then
            Library:Notify({ Title = 'evilrollerplayersHail', Description = 'This script only supports RIVALS.', Time = 5 })
        end
    end

    end, function(e)
        return debug.traceback(tostring(e), 2)
    end)

    if not __game_ok then
        if ErrorReporter and type(ErrorReporter.report) == 'function' then
            ErrorReporter.report(__game_err, nil, 'game_init')
        end
        if Library and type(Library.Notify) == 'function' then
            Library:Notify({ Title = 'evilrollerplayersHail', Description = 'Fatal error: ' .. tostring(__game_err), Time = 8 })
        end
    end

end)()
